def scenario_activation_events(scenario: dict[str, Any]) -> list[str]:
    return [str(item) for item in scenario.get("activationEvents", []) if isinstance(item, str) and item]


def scenario_activation_command_entries(scenario: dict[str, Any]) -> list[dict[str, Any]]:
    commands: list[dict[str, Any]] = []
    seen: set[tuple[str, str]] = set()
    seen_commands: set[str] = set()
    for item in scenario.get("activationCommands", []):
        entry: dict[str, Any] | None = None
        if isinstance(item, str) and item:
            entry = {"command": item, "args": []}
        elif isinstance(item, dict):
            command = str(item.get("command") or "").strip()
            if command:
                args = item.get("args") if isinstance(item.get("args"), list) else []
                settle_ms = item.get("settleMs")
                entry = {"command": command, "args": copy.deepcopy(args)}
                if isinstance(item.get("allowDisabled"), bool):
                    entry["allowDisabled"] = bool(item.get("allowDisabled"))
                if isinstance(settle_ms, (int, float)) and settle_ms >= 0:
                    entry["settleMs"] = int(settle_ms)
        if not entry:
            continue
        command = str(entry.get("command") or "")
        args_key = json.dumps(entry.get("args", []), sort_keys=True)
        key = (command, args_key)
        if key in seen:
            continue
        commands.append(entry)
        seen.add(key)
        seen_commands.add(command)
    for event in scenario_activation_events(scenario):
        if event.startswith("onCommand:"):
            command = event.split(":", 1)[1]
            key = (command, "[]")
            if command and command not in seen_commands and key not in seen:
                commands.append({"command": command, "args": []})
                seen.add(key)
    return commands


def scenario_activation_commands(scenario: dict[str, Any]) -> list[str]:
    commands: list[str] = []
    seen: set[str] = set()
    for entry in scenario_activation_command_entries(scenario):
        command = str(entry.get("command") or "").strip()
        if not command or command in seen:
            continue
        commands.append(command)
        seen.add(command)
    return commands


def pick_generic_fixture_file(fixture_dir: Path, scenario: dict[str, Any]) -> str:
    files = [
        item
        for item in fixture_dir.rglob("*")
        if item.is_file() and ".vscode" not in item.relative_to(fixture_dir).parts and item.name != "README.md"
    ]
    if not files:
        raise AssertionError(f"fixture has no runnable file candidates: {fixture_dir}")
    by_rel = {item.relative_to(fixture_dir).as_posix(): item for item in files}
    explicit_probe_file = str(scenario.get("probeFile") or "").strip()
    if explicit_probe_file:
        explicit = by_rel.get(explicit_probe_file)
        if explicit is not None:
            return explicit_probe_file
    ranked_matches = lambda language_id: sorted(
        (
            (item.relative_to(fixture_dir).as_posix(), item)
            for item in files
            if infer_language_id_from_path(item) == language_id
        ),
        key=lambda entry: (
            0 if entry[1].suffix else 1,
            0 if any(part in {"src", "lib"} for part in entry[1].relative_to(fixture_dir).parts) else 1,
            entry[0],
        ),
    )
    activation_events = scenario_activation_events(scenario)
    for event in activation_events:
        if not event.startswith("onLanguage:"):
            continue
        language_id = event.split(":", 1)[1]
        matches = ranked_matches(language_id)
        if matches:
            return matches[0][0]
    for preferred in GENERIC_PROBE_FILE_PREFERENCES:
        if preferred in by_rel:
            return preferred
    return sorted(by_rel)[0]


def infer_language_id_from_path(path: Path) -> str:
    lower_name = path.name.lower()
    if lower_name in LANGUAGE_ID_BY_BASENAME:
        return LANGUAGE_ID_BY_BASENAME[lower_name]
    if path.suffix.lower() in LANGUAGE_ID_BY_SUFFIX:
        return LANGUAGE_ID_BY_SUFFIX[path.suffix.lower()]
    return "plaintext"


def infer_generic_language_id(scenario: dict[str, Any], fixture_file: str) -> str:
    for event in scenario_activation_events(scenario):
        if event.startswith("onLanguage:"):
            return event.split(":", 1)[1]
    return infer_language_id_from_path(Path(fixture_file))


def scenario_lane_groups(scenario: dict[str, Any]) -> list[str]:
    kind = str(scenario.get("kind") or "")
    expected = {str(item) for item in scenario.get("expectedEvidence", []) if isinstance(item, str)}
    runtime_modes = {str(item) for item in scenario.get("runtimeModes", []) if isinstance(item, str)}
    groups = {"runtime", "performance"}
    if kind in {"command", "environment"}:
        groups.add("command")
    if kind in {"language-provider", "valid-runtime"} or bool(expected & PROVIDER_EVIDENCE_KEYS):
        groups.add("provider")
    if kind in {"tree-view", "custom-editor", "scm-view", "ai-offline", "network-auth"} or bool(expected & VIEW_EVIDENCE_KEYS):
        groups.add("view")
    if kind in {"debug", "debug-config", "debug-test", "test", "tasks-tree", "lifecycle"} or bool(expected & DEBUG_TASK_EVIDENCE_KEYS):
        groups.add("debug")
    if kind in {"ai-network", "network-auth", "ai-offline"} or {"offline", "opt-in-network"} & runtime_modes:
        groups.add("network")
    return sorted(groups)


def matching_workspace_activation_events(baseline_row: dict[str, Any], fixture_dir: Path) -> list[str]:
    manifest_json = read_vsix_package_json(baseline_row.get("vsix", {}) if isinstance(baseline_row, dict) else {})
    activation_events = manifest_json.get("activationEvents") if isinstance(manifest_json.get("activationEvents"), list) else []
    fixture_paths = sorted(path.relative_to(fixture_dir).as_posix() for path in fixture_dir.rglob("*") if path.is_file())
    matched: list[str] = []
    for item in activation_events:
        if not isinstance(item, str) or not item.startswith("workspaceContains:"):
            continue
        pattern = item.split(":", 1)[1]
        if any(fnmatch.fnmatch(path, pattern) for path in fixture_paths):
            matched.append(item)
    return matched


def _append_unique_activation_events(target: dict[str, Any], extra_events: list[str]) -> dict[str, Any]:
    activation_events = target.setdefault("activationEvents", [])
    if not isinstance(activation_events, list):
        return target
    existing = {str(value) for value in activation_events}
    for event in extra_events:
        if event not in existing:
            activation_events.append(event)
            existing.add(event)
    return target


def _java_workspace_activation_events() -> list[str]:
    return [
        "workspaceContains:pom.xml",
        "workspaceContains:*/pom.xml",
        "workspaceContains:build.gradle",
        "workspaceContains:*/build.gradle",
        "workspaceContains:build.gradle.kts",
        "workspaceContains:*/build.gradle.kts",
        "workspaceContains:.classpath",
        "workspaceContains:*/.classpath",
    ]


def _local_valid_jdk_home() -> str | None:
    candidates: list[Path] = []
    for value in (
        os.environ.get("WIZP_REDHAT_JAVA_VALID_JDK_HOME"),
        os.environ.get("JAVA_HOME"),
        "/opt/android-studio/jbr",
        "/usr/lib/jvm/java-26-openjdk",
    ):
        if value:
            candidates.append(Path(value))
    java_bin = shutil.which("java")
    javac_bin = shutil.which("javac")
    if java_bin and javac_bin:
        candidates.append(Path(java_bin).resolve().parents[1])
    seen: set[str] = set()
    for candidate in candidates:
        key = str(candidate)
        if key in seen:
            continue
        seen.add(key)
        if (candidate / "bin" / "java").exists() and (candidate / "bin" / "javac").exists():
            return key
    return None


def _redhat_java_initial_configuration(jdk_home: str) -> dict[str, Any]:
    return {
        "java": {
            "home": jdk_home,
            "server": {"launchMode": "Hybrid"},
            "jdt": {"ls": {"java": {"home": jdk_home}}},
            "transport": "stdio",
            "imports": {"maven": {"enabled": True}, "gradle": {"enabled": False}},
            "autobuild": {"enabled": False},
            "configuration": {"updateBuildConfiguration": "disabled"},
        },
        "redhat": {"telemetry": {"enabled": False}},
    }


def _enrich_redhat_java_target(target: dict[str, Any]) -> None:
    if str(target.get("extensionId") or "") != "redhat.java":
        return
    runtime_modes = {str(item) for item in target.get("runtimeModes", []) if isinstance(item, str)}
    if "valid-jdk" not in runtime_modes:
        return
    jdk_home = _local_valid_jdk_home()
    if not jdk_home:
        return
    settings = dict(target.get("settings", {})) if isinstance(target.get("settings"), dict) else {}
    settings.update(
        {
            "java.home": jdk_home,
            "java.jdt.ls.java.home": jdk_home,
            "java.server.launchMode": "Hybrid",
            "java.transport": "stdio",
            "java.imports.maven.enabled": True,
            "java.imports.gradle.enabled": False,
            "java.autobuild.enabled": False,
            "java.configuration.updateBuildConfiguration": "disabled",
        }
    )
    target["settings"] = settings
    env = dict(target.get("env", {})) if isinstance(target.get("env"), dict) else {}
    env["JAVA_HOME"] = jdk_home
    env["WIZP_EXTENSION_ACTIVATION_TIMEOUT_MS"] = str(max(int(env.get("WIZP_EXTENSION_ACTIVATION_TIMEOUT_MS") or 0), 45000))
    target["env"] = env
    target["initialConfiguration"] = _redhat_java_initial_configuration(jdk_home)
    path_prepend = [str(Path(jdk_home) / "bin")]
    for entry in target.get("pathPrepend", []):
        if isinstance(entry, str) and entry and entry not in path_prepend:
            path_prepend.append(entry)
    target["pathPrepend"] = path_prepend
    target["activationSettleMs"] = max(int(target.get("activationSettleMs") or 1000), 15000)
    target["probeTimeoutMs"] = max(int(target.get("probeTimeoutMs") or 6000), 30000)
    target["providerRegistrationWaitMs"] = max(int(target.get("providerRegistrationWaitMs") or 0), 15000)
    target["providerRpcTimeoutMs"] = max(int(target.get("providerRpcTimeoutMs") or 0), 15000)


def _enrich_phptools_target(target: dict[str, Any]) -> None:
    if str(target.get("extensionId") or "") != "devsense.phptools-vscode":
        return
    runtime_modes = {str(item) for item in target.get("runtimeModes", []) if isinstance(item, str)}
    if "valid-runtime" not in runtime_modes:
        return
    phptools_pack_ids = [
        "devsense.intelli-php-vscode",
        "devsense.composer-php-vscode",
        "devsense.profiler-php-vscode",
    ]
    for key in ("wizpExtraExtensionIds", "referenceExtraExtensionIds"):
        existing = [str(item) for item in target.get(key, []) if isinstance(item, str) and item]
        target[key] = list(dict.fromkeys([*existing, *phptools_pack_ids]))
    env = dict(target.get("env", {})) if isinstance(target.get("env"), dict) else {}
    env["WIZP_EXTENSION_BACKGROUND_ACTIVATION_ALLOWLIST"] = ",".join(
        sorted(
            {
                str(part).strip()
                for part in [
                    env.get("WIZP_EXTENSION_BACKGROUND_ACTIVATION_ALLOWLIST"),
                    "devsense.phptools-vscode",
                ]
                if isinstance(part, str) and part.strip()
            }
        )
    )
    env["WIZP_EXTENSION_ACTIVATION_TIMEOUT_MS"] = str(max(int(env.get("WIZP_EXTENSION_ACTIVATION_TIMEOUT_MS") or 0), 60000))
    target["env"] = env
    target["activationEventTimeoutMs"] = max(int(target.get("activationEventTimeoutMs") or 15000), 45000)
    target["activationSettleMs"] = max(int(target.get("activationSettleMs") or 1000), 15000)
    target["probeTimeoutMs"] = max(int(target.get("probeTimeoutMs") or 6000), 30000)
    target["providerRegistrationWaitMs"] = max(int(target.get("providerRegistrationWaitMs") or 0), 15000)
    target["providerRpcTimeoutMs"] = max(int(target.get("providerRpcTimeoutMs") or 0), 10000)


def _enrich_java_pack_target(target: dict[str, Any], baseline_row: dict[str, Any] | None) -> None:
    if str(target.get("extensionId") or "") != "vscjava.vscode-java-pack":
        return
    if str(target.get("scenarioId") or "") != "java-pack-child-rollup":
        return
    manifest_json = read_vsix_package_json(baseline_row.get("vsix", {}) if isinstance(baseline_row, dict) else {})
    package = package_summary(manifest_json)
    children = extension_pack_children(package)
    if children:
        existing = [str(item) for item in target.get("wizpExtraExtensionIds", []) if isinstance(item, str) and item]
        target["wizpExtraExtensionIds"] = list(dict.fromkeys([*existing, *children]))
    env = dict(target.get("env", {})) if isinstance(target.get("env"), dict) else {}
    env["WIZP_EXTENSION_BACKGROUND_ACTIVATION_ALLOWLIST"] = ",".join(
        sorted(
            {
                str(part).strip()
                for part in [
                    env.get("WIZP_EXTENSION_BACKGROUND_ACTIVATION_ALLOWLIST"),
                    "vscjava.vscode-java-test",
                ]
                if isinstance(part, str) and part.strip()
            }
        )
    )
    env["WIZP_EXTENSION_ACTIVATION_TIMEOUT_MS"] = str(max(int(env.get("WIZP_EXTENSION_ACTIVATION_TIMEOUT_MS") or 0), 60000))
    target["env"] = env
    _append_unique_activation_events(
        target,
        [
            "workspaceContains:pom.xml",
            "workspaceContains:*/pom.xml",
            "workspaceContains:**/pom.xml",
            "onLanguage:java",
        ],
    )
    jdk_home = _local_valid_jdk_home()
    if jdk_home:
        settings = dict(target.get("settings", {})) if isinstance(target.get("settings"), dict) else {}
        settings.update(
            {
                "java.home": jdk_home,
                "java.jdt.ls.java.home": jdk_home,
                "java.server.launchMode": "Hybrid",
                "java.transport": "stdio",
                "java.imports.maven.enabled": True,
                "java.imports.gradle.enabled": False,
                "java.autobuild.enabled": False,
                "java.configuration.updateBuildConfiguration": "disabled",
            }
        )
        target["settings"] = settings
        env["JAVA_HOME"] = jdk_home
        target["env"] = env
        target["initialConfiguration"] = _redhat_java_initial_configuration(jdk_home)
        path_prepend = [str(Path(jdk_home) / "bin")]
        for entry in target.get("pathPrepend", []):
            if isinstance(entry, str) and entry and entry not in path_prepend:
                path_prepend.append(entry)
        target["pathPrepend"] = path_prepend
    target["activationEventTimeoutMs"] = max(int(target.get("activationEventTimeoutMs") or 15000), 60000)
    target["activationSettleMs"] = max(int(target.get("activationSettleMs") or 1000), 15000)
    target["probeTimeoutMs"] = max(int(target.get("probeTimeoutMs") or 4000), 30000)
    target["providerRegistrationWaitMs"] = max(int(target.get("providerRegistrationWaitMs") or 0), 10000)


def _enrich_ms_python_target(target: dict[str, Any]) -> None:
    if str(target.get("extensionId") or "") != "ms-python.python":
        return
    if str(target.get("scenarioId") or "") != "python-interpreter-workflow":
        return
    activation_events = [
        str(item)
        for item in target.get("activationEvents", [])
        if isinstance(item, str) and not str(item).startswith("workspaceContains:")
    ]
    if activation_events:
        target["activationEvents"] = activation_events
        target["activationEvent"] = activation_events[0]
    target["activeDocumentTimeoutMs"] = max(int(target.get("activeDocumentTimeoutMs") or 0), 30000)
    target["activationEventTimeoutMs"] = max(int(target.get("activationEventTimeoutMs") or 15000), 45000)
    target["activationSettleMs"] = max(int(target.get("activationSettleMs") or 1000), 15000)
    target["probeTimeoutMs"] = max(int(target.get("probeTimeoutMs") or 6000), 30000)
    target["referenceRunnerTimeoutSeconds"] = max(int(target.get("referenceRunnerTimeoutSeconds") or 90), 180)
    settings = dict(target.get("settings", {})) if isinstance(target.get("settings"), dict) else {}
    settings.setdefault("python.defaultInterpreterPath", "${fixtureWorkspace}/.venv/bin/python")
    target["settings"] = settings
    env = dict(target.get("env", {})) if isinstance(target.get("env"), dict) else {}
    env["WIZP_EXTENSION_ACTIVATION_TIMEOUT_MS"] = str(max(int(env.get("WIZP_EXTENSION_ACTIVATION_TIMEOUT_MS") or 0), 60000))
    target["env"] = env
    target["workspaceSetup"] = "python-envs-venv"
    target["installPythonEnvToolsShim"] = True
    target["wizpEnablePythonExtensionApiShim"] = True


def _enrich_composer_target(target: dict[str, Any]) -> None:
    if str(target.get("extensionId") or "") != "devsense.composer-php-vscode":
        return
    scenario_id = str(target.get("scenarioId") or "")
    command_entries: list[dict[str, Any]] = []
    if scenario_id == "composer-valid-commands":
        command_entries = [
            {"command": "composer.about", "args": [], "settleMs": 500},
            {"command": "composer.install", "args": [], "settleMs": 1000},
            {"command": "composer.update", "args": [], "settleMs": 1000},
        ]
    elif scenario_id == "composer-missing-tools":
        command_entries = [{"command": "composer.install", "args": [], "settleMs": 1000}]
    if not command_entries:
        return
    target["activationCommandEntries"] = command_entries
    target["activationCommands"] = [str(item["command"]) for item in command_entries]
    target["commandSettleMs"] = max(int(target.get("commandSettleMs") or 750), 1500)
    target["probeTimeoutMs"] = max(int(target.get("probeTimeoutMs") or 4000), 10000)
    target["autoSelectQuickPick"] = True


def build_generic_scenario_target(
    manifest: dict[str, Any],
    scenario: dict[str, Any],
    baseline_row: dict[str, Any] | None = None,
) -> dict[str, Any]:
    fixture_dir = safe_fixture_dir(str(scenario["fixture"]))
    fixture_file = pick_generic_fixture_file(fixture_dir, scenario)
    budget = scenario_budget(str(scenario.get("kind", "")), [str(item) for item in scenario.get("runtimeModes", [])])
    activation_events = scenario_activation_events(scenario)
    if baseline_row:
        activation_events = list(dict.fromkeys([*activation_events, *matching_workspace_activation_events(baseline_row, fixture_dir)]))
    activation_command_entries = scenario_activation_command_entries(scenario)
    activation_commands = scenario_activation_commands(scenario)
    target = {
        "extensionId": str(manifest["extensionId"]),
        "scenarioId": str(scenario["id"]),
        "title": str(scenario.get("title") or ""),
        "kind": str(scenario.get("kind") or ""),
        "workspaceFixtureDir": fixture_dir,
        "fixtureFile": fixture_file,
        "languageId": infer_generic_language_id(scenario, fixture_file),
        "activationEvents": activation_events,
        "activationEvent": activation_events[0] if activation_events else "onStartupFinished",
        "activationCommandEntries": activation_command_entries,
        "activationCommands": activation_commands,
        "settings": scenario.get("settings", {}),
        "expectedEvidence": scenario.get("expectedEvidence", []),
        "runtimeModes": scenario.get("runtimeModes", []),
        "laneGroups": scenario_lane_groups(scenario),
        "captureStatusBarSideEffects": "statusItem" in set(scenario.get("expectedEvidence", [])),
        "autoSelectQuickPick": kind in {"environment", "command", "ai-network"} if (kind := str(scenario.get("kind") or "")) else False,
        "activationSettleMs": max(1000, min(int(budget["activationTimeoutMs"]) // 2, 4000)),
        "commandSettleMs": max(750, min(int(budget["firstResultTimeoutMs"]) // 2, 2500)),
        "probeTimeoutMs": max(4000, int(budget["firstResultTimeoutMs"]) + 2000),
        "scenarioBudget": budget,
        "acceptedProcessNote": "Generic paired survey captures activation/runtime/process/network surfaces and timings without claiming deeper scenario-specific payload parity.",
    }
    for key in (
        "env",
        "pathPrepend",
        "initialConfiguration",
        "extraExtensionIds",
        "wizpExtraExtensionIds",
        "referenceExtraExtensionIds",
        "wizpExtraBuiltinExtensionIds",
        "wizpEnablePythonExtensionApiShim",
        "installPythonEnvToolsShim",
        "frontendProbeRequired",
        "viewProbeIds",
    ):
        if key in scenario:
            target[key] = copy.deepcopy(scenario[key])
    for key in (
        "activationEventTimeoutMs",
        "activationSettleMs",
        "activeDocumentTimeoutMs",
        "commandSettleMs",
        "probeTimeoutMs",
        "providerRegistrationWaitMs",
        "providerRpcTimeoutMs",
        "referenceRunnerTimeoutSeconds",
    ):
        if key in scenario and scenario.get(key) is not None:
            target[key] = int(scenario[key])
    if str(target.get("scenarioId") or "").strip() == "redhat-java-jdt-language":
        _append_unique_activation_events(target, _java_workspace_activation_events())
    _enrich_redhat_java_target(target)
    _enrich_phptools_target(target)
    _enrich_java_pack_target(target, baseline_row)
    _enrich_ms_python_target(target)
    _enrich_composer_target(target)
    return target


PROVIDER_ANCHOR_PATTERNS: dict[str, list[str]] = {
    "python": [r"\badd\s*\("],
    "php": [r"\badd\s*\("],
    "go": [r"\badd\s*\("],
    "cpp": [r"\badd\s*\("],
    "c": [r"\badd\s*\("],
    "java": [r"\badd\s*\("],
    "ruby": [r"\badd\s*\("],
    "dockerfile": [r"\bLABEL\b", r"\bFROM\b"],
    "yaml": [r"\bfixture\b", r"\bimage\b", r"\bservices\b"],
}


def offset_to_line_character(text: str, offset: int) -> tuple[int, int]:
    clamped = max(0, min(offset, len(text)))
    line = text.count("\n", 0, clamped)
    line_start = text.rfind("\n", 0, clamped)
    return line, clamped if line_start < 0 else clamped - line_start - 1


def provider_probe_for_text(text: str, language_id: str) -> dict[str, Any]:
    patterns = PROVIDER_ANCHOR_PATTERNS.get(language_id, []) + [r"\badd\s*\(", r"\bmain\b", r"\bfixture\b", r"\b[A-Za-z_][A-Za-z0-9_]*\b"]
    anchor_offset = 0
    for pattern in patterns:
        matches = list(re.finditer(pattern, text, re.MULTILINE))
        if matches:
            anchor_offset = matches[-1].start()
            break
    line, _character = offset_to_line_character(text, anchor_offset)
    lines = text.splitlines() or [text]
    line_text = lines[min(line, len(lines) - 1)] if lines else ""
    identifier_match = None
    for match in re.finditer(r"[A-Za-z_][A-Za-z0-9_]*", line_text):
        absolute_start = sum(len(item) + 1 for item in lines[:line]) + match.start()
        absolute_end = sum(len(item) + 1 for item in lines[:line]) + match.end()
        if absolute_start <= anchor_offset < absolute_end:
            identifier_match = match
            break
    if identifier_match is None:
        identifier_match = next(iter(re.finditer(r"[A-Za-z_][A-Za-z0-9_]*", line_text)), None)
    if identifier_match is None:
        start_char = 0
        end_char = max(1, len(line_text))
        cursor_char = 0
        symbol = line_text[:1]
    else:
        start_char = identifier_match.start()
        end_char = identifier_match.end()
        cursor_char = min(end_char - 1, start_char + 1)
        symbol = identifier_match.group(0)
    return {
        "line": line,
        "character": cursor_char,
        "rangeStartLine": line,
        "rangeStartCharacter": 0,
        "rangeEndLine": line,
        "rangeEndCharacter": max(end_char, len(line_text)),
        "newName": "wizpRenamedSymbol",
        "options": {"tabSize": 2, "insertSpaces": True},
        "symbol": symbol,
        "lineText": line_text,
        "itemResolveCount": 20,
        "triggerCharacter": None,
        "ch": None,
    }


PROVIDER_POINT_RESULT_FIELDS: dict[str, list[str]] = {
    "diagnostics": ["diagnostics"],
    "completion": ["completion"],
    "hover": ["hover"],
    "definition": ["definition"],
    "references": ["references"],
    "rename": ["prepareRename", "rename"],
    "codeActions": ["codeActions"],
    "formatting": ["documentFormatting", "documentFormattingAppliedText", "rangeFormatting", "rangeFormattingAppliedText"],
    "symbols": ["documentSymbols"],
}

PROVIDER_POINT_RESOLUTION_FIELDS: dict[str, list[str]] = {
    "completion": ["completion", "completionErrors", "completionFallback", "completionSamples", "completionIsIncomplete", "completionInvalidCount"],
    "hover": ["hover", "hoverErrors"],
    "definition": ["definition", "definitionErrors"],
    "references": ["references", "referenceErrors"],
    "rename": ["rename", "renameErrors"],
    "codeActions": ["codeActions", "codeActionErrors"],
    "formatting": ["documentFormatting", "documentFormattingErrors", "rangeFormatting", "rangeFormattingErrors", "onTypeFormatting", "onTypeFormattingErrors"],
    "symbols": ["documentSymbols", "documentSymbolErrors"],
}


def merge_captured_provider_point(
    result: dict[str, Any],
    point: str,
    point_result: dict[str, Any],
    point_request: dict[str, Any],
) -> None:
    if not isinstance(result, dict) or not isinstance(point_result, dict):
        return
    point_requests = result.get("pointRequests")
    if not isinstance(point_requests, dict):
        point_requests = {}
        result["pointRequests"] = point_requests
    point_requests[point] = copy.deepcopy(point_request)
    for field in PROVIDER_POINT_RESULT_FIELDS.get(point, []):
        if field in point_result:
            result[field] = copy.deepcopy(point_result[field])
    resolution_keys = PROVIDER_POINT_RESOLUTION_FIELDS.get(point, [])
    if not resolution_keys:
        return
    point_resolution = point_result.get("providerResolution")
    if not isinstance(point_resolution, dict):
        return
    provider_resolution = result.get("providerResolution")
    if not isinstance(provider_resolution, dict):
        provider_resolution = {}
        result["providerResolution"] = provider_resolution
    for field in resolution_keys:
        if field in point_resolution:
            provider_resolution[field] = copy.deepcopy(point_resolution[field])


def build_provider_probe_target(manifest: dict[str, Any], scenario: dict[str, Any], baseline_row: dict[str, Any] | None = None) -> dict[str, Any]:
    target = build_generic_scenario_target(manifest, scenario, baseline_row)
    fixture_path = safe_fixture_dir(str(scenario["fixture"])) / str(target["fixtureFile"])
    provider_points = [
        str(item)
        for item in scenario.get("expectedEvidence", [])
        if isinstance(item, str) and item in PROVIDER_EVIDENCE_KEYS
    ]
    target["providerProbePoints"] = provider_points
    target["providerProbe"] = provider_probe_for_text(fixture_path.read_text(encoding="utf-8"), str(target["languageId"]))
    scenario_provider_probe = scenario.get("providerProbe")
    if isinstance(scenario_provider_probe, dict):
        target["providerProbe"].update(copy.deepcopy(scenario_provider_probe))
    point_overrides = scenario.get("providerPointOverrides")
    if isinstance(point_overrides, dict):
        target["providerPointOverrides"] = copy.deepcopy(point_overrides)
        target["providerProbe"]["pointOverrides"] = copy.deepcopy(point_overrides)
    env = dict(target.get("env", {})) if isinstance(target.get("env"), dict) else {}
    env.setdefault("WIZP_EXTENSION_NATIVE_FORK", "1")
    target["env"] = env
    return target


def write_fixture_common(path: Path, extension_id: str, scenario: dict[str, Any]) -> None:
    settings = scenario.get("settings") if isinstance(scenario.get("settings"), dict) else {}
    write_text_if_missing(
        path / "README.md",
        "\n".join(
            [
                f"# {extension_id} / {scenario['id']}",
                "",
                "Generated starter fixture for WIZP top-20 behavior parity.",
                "",
                f"- Scenario: {scenario['title']}",
                f"- Kind: {scenario['kind']}",
                f"- Runtime modes: {', '.join(scenario.get('runtimeModes', []))}",
                "",
                "This fixture is intentionally small and hermetic; scenario runners may add",
                "temporary runtime/tool shims outside the checked-in fixture directory.",
                "",
            ]
        ),
    )
    write_text_if_missing(path / ".vscode" / "settings.json", json.dumps(settings, indent=2, sort_keys=True) + "\n")


def write_python_fixture(path: Path, scenario: dict[str, Any]) -> None:
    write_text_if_missing(
        path / "src" / "sample.py",
        'def add(left: int, right: int) -> int:\n    return left + right\n\n\nprint(add(2, 3))\n',
    )
    if "venv" in str(path) or "env" in str(path):
        write_text_if_missing(path / "pyproject.toml", '[project]\nname = "wizp-top20-python-fixture"\nversion = "0.0.0"\n')
    if "debug" in str(path):
        write_text_if_missing(
            path / ".vscode" / "launch.json",
            '{\n  "version": "0.2.0",\n  "configurations": [\n    {\n      "name": "Python: Fixture",\n      "type": "debugpy",\n      "request": "launch",\n      "program": "${workspaceFolder}/src/sample.py"\n    }\n  ]\n}\n',
        )


