def command_execution_targets(command_diff: dict[str, Any]) -> list[dict[str, Any]]:
    targets: list[dict[str, Any]] = []
    for row in command_diff.get("results", []):
        if not isinstance(row, dict):
            continue
        extension_id = str(row.get("id") or "")
        profile = COMMAND_EXECUTION_PROFILES.get(extension_id)
        if not profile:
            continue
        for command_entry in row.get("commands", []):
            if not isinstance(command_entry, dict) or command_entry.get("executionClass") != "safe-candidate":
                continue
            command = str(command_entry.get("command") or "")
            if not command:
                continue
            title = str(command_entry.get("title") or "")
            target = {
                **profile,
                "extensionId": extension_id,
                "command": command,
                "title": title,
                "expectedResult": profile.get("expectedResult"),
                "executionClass": command_entry.get("executionClass", ""),
                "classificationReason": command_entry.get("classificationReason", ""),
            }
            command_timeout_ms = COMMAND_EXECUTION_TIMEOUT_OVERRIDES.get((extension_id, command))
            if command_timeout_ms:
                target["commandTimeoutMs"] = command_timeout_ms
            targets.append(target)
    return targets


def normalize_paired_command_result(
    target: dict[str, Any],
    baseline: dict[str, Any],
    wizp_result: dict[str, Any],
    reference_result: dict[str, Any],
    blockers: list[str],
    safe_candidate_commands: int = 0,
) -> dict[str, Any]:
    wizp_ok = wizp_result.get("status") == "wizp-command-executed"
    reference_ok = reference_result.get("status") == "reference-command-executed"
    wizp_return_value = wizp_result.get("executeResult")
    reference_return_value = reference_result.get("commandResult", {}).get("executeResult") if isinstance(reference_result.get("commandResult"), dict) else None
    return_values_match = wizp_ok and reference_ok and wizp_return_value == reference_return_value
    wizp_side_effects = (
        wizp_result.get("sideEffects")
        if isinstance(wizp_result.get("sideEffects"), dict)
        else normalize_wizp_command_side_effects(
            wizp_result.get("uiEvents", []) if isinstance(wizp_result.get("uiEvents"), list) else [],
            wizp_result.get("runtimeProcesses", {}) if isinstance(wizp_result.get("runtimeProcesses"), dict) else {},
            wizp_result.get("activationErrors", {}) if isinstance(wizp_result.get("activationErrors"), dict) else {},
        )
    )
    reference_side_effects = normalize_reference_command_side_effects(
        (reference_result.get("commandResult") or {}).get("sideEffects")
        if isinstance(reference_result.get("commandResult"), dict)
        else {}
    )
    wizp_side_effects, reference_side_effects = normalize_target_specific_side_effects(
        target,
        wizp_side_effects,
        reference_side_effects,
    )
    side_effect_drift = side_effect_drift_fields(wizp_side_effects, reference_side_effects) if wizp_ok and reference_ok else []
    side_effects_match = wizp_ok and reference_ok and not side_effect_drift
    result_blockers = list(blockers)
    if wizp_ok and reference_ok:
        status = "paired-command-execution-verified" if return_values_match and side_effects_match else "paired-command-execution-drift"
        if not return_values_match:
            normalized_status = "return-value-drift"
        elif not side_effects_match:
            normalized_status = "side-effect-drift"
        else:
            normalized_status = "matched-return-value-and-side-effects"
    elif wizp_ok:
        status = "partial-wizp-command-executed-reference-blocked"
        normalized_status = "blocked-reference-command-execution"
    else:
        status = "blocked-command-execution"
        normalized_status = "not-run"
    if not reference_ok and reference_result.get("status"):
        result_blockers.append(str(reference_result["status"]))
    if not wizp_ok and wizp_result.get("status"):
        result_blockers.append(str(wizp_result["status"]))

    runtime_processes = wizp_result.get("runtimeProcesses") if isinstance(wizp_result.get("runtimeProcesses"), dict) else {}
    network_count = runtime_processes.get("networkAuditCount") if isinstance(runtime_processes, dict) else None
    reference_log_audit_result = reference_result.get("logAudit") if isinstance(reference_result.get("logAudit"), dict) else {}
    return {
        "status": status,
        "blockers": sorted(set(result_blockers)),
        "target": target,
        "safeCandidateCommands": safe_candidate_commands,
        "wizpExecutedSafeCommands": 1 if wizp_ok else 0,
        "referenceExecutedSafeCommands": 1 if reference_ok else 0,
        "referenceHost": baseline.get("referenceHost", {}),
        "wizpResult": wizp_result,
        "referenceResult": reference_result,
        "normalizedDiff": {
            "status": normalized_status,
            "unexpectedDrift": bool(wizp_ok and reference_ok and (not return_values_match or not side_effects_match)),
            "acceptedDifferences": sorted(set(result_blockers)),
            "returnValueComparable": wizp_ok and reference_ok,
            "returnValuesMatch": return_values_match,
            "wizpReturnValue": wizp_return_value,
            "referenceReturnValue": reference_return_value,
            "sideEffectsComparable": wizp_ok and reference_ok,
            "sideEffectsMatch": side_effects_match,
            "sideEffectDriftFields": side_effect_drift,
            "wizpSideEffects": wizp_side_effects,
            "referenceSideEffects": reference_side_effects,
            "processAuditSummary": {
                "wizpSpawnedProcessCount": runtime_processes.get("spawnedProcessCount") if isinstance(runtime_processes, dict) else None,
                "wizpForkedProcessCount": runtime_processes.get("forkedProcessCount") if isinstance(runtime_processes, dict) else None,
                "wizpNetworkAuditCount": network_count,
                "referenceNetworkLogLineCount": reference_log_audit_result.get("networkLogLineCount"),
                "referenceLogErrorLineCount": reference_log_audit_result.get("errorLineCount"),
                "acceptedBoundedHelperProcesses": bool(wizp_ok and network_count == 0),
            },
            "notes": "This per-command result records paired WIZP/MrCode command execution, return-value comparison, and normalized state/message/output/terminal/task/process/network side-effect comparison.",
        },
    }


def execute_paired_command_target(
    target: dict[str, Any],
    baseline: dict[str, Any],
    baseline_row: dict[str, Any],
    safe_candidate_commands: int = 0,
) -> dict[str, Any]:
    blockers: list[str] = []
    if not baseline_row:
        blockers.append("target-extension-missing-from-baseline")
    if blockers:
        wizp_result = {"status": "not-run", "reason": ", ".join(blockers)}
        reference_result = {"status": "not-run", "reason": ", ".join(blockers)}
    else:
        wizp_result = run_wizp_command_execution(target, baseline, baseline_row)
        reference_result = run_reference_command_execution(target, baseline, baseline_row)
    return normalize_paired_command_result(target, baseline, wizp_result, reference_result, blockers, safe_candidate_commands)


def build_single_command_execution_result(
    target: dict[str, Any],
    baseline: dict[str, Any],
    command_diff: dict[str, Any],
) -> dict[str, Any]:
    extension_id = str(target["extensionId"])
    command = str(target["command"])
    baseline_row = baseline_extension(baseline, extension_id)
    command_row = next((row for row in command_diff.get("results", []) if row.get("id") == extension_id), {})
    command_entry = next((item for item in command_row.get("commands", []) if item.get("command") == command), {})
    blockers: list[str] = []
    if not baseline_row:
        blockers.append("target-extension-missing-from-baseline")
    if not command_entry:
        blockers.append("target-command-missing-from-command-diff")
    elif command_entry.get("executionClass") != "safe-candidate":
        blockers.append("target-command-not-safe-candidate")

    if blockers:
        wizp_result = {"status": "not-run", "reason": ", ".join(blockers)}
        reference_result = {"status": "not-run", "reason": ", ".join(blockers)}
    else:
        wizp_result = run_wizp_command_execution(target, baseline, baseline_row)
        reference_result = run_reference_command_execution(target, baseline, baseline_row)
    command_title = str(command_entry.get("title") or "")
    if command_title.startswith("%") and command_title.endswith("%"):
        command_title = str(target.get("title") or command_title)
    normalized_target = {
        **target,
        "executionClass": command_entry.get("executionClass", ""),
        "classificationReason": command_entry.get("classificationReason", ""),
        "title": command_title or target.get("title", ""),
    }
    return normalize_paired_command_result(
        normalized_target,
        baseline,
        wizp_result,
        reference_result,
        blockers,
        command_diff.get("safeCandidateCommands", 0),
    )


def build_command_execution_report(baseline: dict[str, Any], command_diff: dict[str, Any], generated_at: str) -> dict[str, Any]:
    targets = command_execution_targets(command_diff)
    if not targets:
        blockers = ["no-safe-command-targets-with-execution-profile"]
        return {
            "schema": "wizp.top20-behavior-command-execution.v1",
            "generatedAt": generated_at,
            "sourceCommandDiff": rel(COMMAND_DIFF_JSON),
            "status": "blocked-command-execution",
            "blockers": blockers,
            "target": {},
            "targets": [],
            "commandResults": [],
            "safeCandidateCommands": command_diff.get("safeCandidateCommands", 0),
            "targetedSafeCommands": 0,
            "wizpExecutedSafeCommands": 0,
            "referenceExecutedSafeCommands": 0,
            "pairedReturnValueMatches": 0,
            "pairedReturnValueDrifts": 0,
            "pairedSideEffectMatches": 0,
            "pairedSideEffectDrifts": 0,
            "referenceHost": baseline.get("referenceHost", {}),
            "wizpResult": {"status": "not-run", "reason": ", ".join(blockers)},
            "referenceResult": {"status": "not-run", "reason": ", ".join(blockers)},
            "normalizedDiff": {
                "status": "not-run",
                "unexpectedDrift": False,
                "acceptedDifferences": blockers,
                "returnValueComparable": False,
                "returnValuesMatch": False,
                "sideEffectsComparable": False,
                "sideEffectsMatch": False,
                "notes": "No command execution profiles were available for the classified safe candidates.",
            },
        }

    command_results = [build_single_command_execution_result(target, baseline, command_diff) for target in targets]
    primary = next(
        (
            result
            for result in command_results
            if (result.get("target") or {}).get("command") == "python-envs.searchSettings"
        ),
        command_results[0],
    )
    wizp_executed = sum(1 for result in command_results if (result.get("wizpResult") or {}).get("status") == "wizp-command-executed")
    reference_executed = sum(1 for result in command_results if (result.get("referenceResult") or {}).get("status") == "reference-command-executed")
    paired_matches = sum(1 for result in command_results if (result.get("normalizedDiff") or {}).get("returnValuesMatch") is True)
    paired_drifts = sum(1 for result in command_results if (result.get("normalizedDiff") or {}).get("returnValueComparable") is True and (result.get("normalizedDiff") or {}).get("returnValuesMatch") is not True)
    paired_side_effect_matches = sum(1 for result in command_results if (result.get("normalizedDiff") or {}).get("sideEffectsMatch") is True)
    paired_side_effect_drifts = sum(1 for result in command_results if (result.get("normalizedDiff") or {}).get("sideEffectsComparable") is True and (result.get("normalizedDiff") or {}).get("sideEffectsMatch") is not True)
    all_blockers = sorted({str(blocker) for result in command_results for blocker in result.get("blockers", []) if blocker})
    reference_log_errors = sum(
        int(((result.get("referenceResult") or {}).get("logAudit") or {}).get("errorLineCount") or 0)
        for result in command_results
    )
    reference_network_lines = sum(
        int(((result.get("referenceResult") or {}).get("logAudit") or {}).get("networkLogLineCount") or 0)
        for result in command_results
    )
    wizp_network_count = sum(
        int((((result.get("wizpResult") or {}).get("runtimeProcesses") or {}).get("networkAuditCount")) or 0)
        for result in command_results
    )
    wizp_spawned_count = sum(
        int((((result.get("wizpResult") or {}).get("runtimeProcesses") or {}).get("spawnedProcessCount")) or 0)
        for result in command_results
    )
    if paired_matches == len(targets) and paired_drifts == 0 and paired_side_effect_matches == len(targets) and paired_side_effect_drifts == 0:
        status = "paired-command-execution-safe-subset-side-effects-verified"
        normalized_status = "matched-safe-subset-return-values-and-side-effects"
    elif paired_matches == len(targets) and paired_drifts == 0:
        status = "paired-command-execution-safe-subset-return-values-verified"
        normalized_status = "matched-safe-subset-return-values"
    elif paired_matches:
        status = "paired-command-execution-expanded-partial"
        normalized_status = "partial-return-value-matches"
    elif wizp_executed:
        status = "partial-wizp-command-executed-reference-blocked"
        normalized_status = "blocked-reference-command-execution"
    else:
        status = "blocked-command-execution"
        normalized_status = "not-run"

    return {
        "schema": "wizp.top20-behavior-command-execution.v1",
        "generatedAt": generated_at,
        "sourceCommandDiff": rel(COMMAND_DIFF_JSON),
        "status": status,
        "blockers": all_blockers,
        "target": primary.get("target", {}),
        "targets": [result.get("target", {}) for result in command_results],
        "commandResults": command_results,
        "safeCandidateCommands": command_diff.get("safeCandidateCommands", 0),
        "targetedSafeCommands": len(targets),
        "wizpExecutedSafeCommands": wizp_executed,
        "referenceExecutedSafeCommands": reference_executed,
        "pairedReturnValueMatches": paired_matches,
        "pairedReturnValueDrifts": paired_drifts,
        "pairedSideEffectMatches": paired_side_effect_matches,
        "pairedSideEffectDrifts": paired_side_effect_drifts,
        "referenceHost": baseline.get("referenceHost", {}),
        "wizpResult": primary.get("wizpResult", {}),
        "referenceResult": primary.get("referenceResult", {}),
        "normalizedDiff": {
            "status": normalized_status,
            "unexpectedDrift": bool(paired_drifts or paired_side_effect_drifts),
            "acceptedDifferences": all_blockers,
            "returnValueComparable": bool(reference_executed),
            "returnValuesMatch": paired_matches == len(targets) and paired_drifts == 0,
            "matchedReturnCommandCount": paired_matches,
            "driftCommandCount": paired_drifts,
            "sideEffectsComparable": bool(reference_executed),
            "sideEffectsMatch": paired_side_effect_matches == len(targets) and paired_side_effect_drifts == 0,
            "matchedSideEffectCommandCount": paired_side_effect_matches,
            "sideEffectDriftCommandCount": paired_side_effect_drifts,
            "targetedSafeCommandCount": len(targets),
            "wizpExecutedSafeCommandCount": wizp_executed,
            "referenceExecutedSafeCommandCount": reference_executed,
            "processAuditSummary": {
                "wizpSpawnedProcessCount": wizp_spawned_count,
                "wizpNetworkAuditCount": wizp_network_count,
                "referenceNetworkLogLineCount": reference_network_lines,
                "referenceLogErrorLineCount": reference_log_errors,
                "acceptedBoundedHelperProcesses": bool(wizp_executed and wizp_network_count == 0),
            },
            "notes": "This artifact compares return values and normalized state/message/output/terminal/task/process/network side effects for the classified safe command subset.",
        },
    }


def attach_command_execution(command_diff: dict[str, Any], command_execution: dict[str, Any]) -> dict[str, Any]:
    command_results = command_execution.get("commandResults") if isinstance(command_execution.get("commandResults"), list) else []
    if not command_results:
        command_results = [command_execution]
    result_by_key: dict[tuple[str, str], dict[str, Any]] = {}
    for result in command_results:
        if not isinstance(result, dict):
            continue
        target = result.get("target", {}) if isinstance(result.get("target"), dict) else {}
        extension_id = str(target.get("extensionId") or "")
        command = str(target.get("command") or "")
        if extension_id and command:
            result_by_key[(extension_id, command)] = result
    if not result_by_key:
        return command_diff
    for row in command_diff.get("results", []):
        row_id = str(row.get("id") or "")
        for item in row.get("commands", []):
            result = result_by_key.get((row_id, str(item.get("command") or "")))
            if not result:
                continue
            item["executionStatus"] = result.get("status", "")
            item["wizpResult"] = {
                "status": (result.get("wizpResult") or {}).get("status", ""),
                "artifact": rel(COMMAND_EXECUTION_JSON),
            }
            item["referenceResult"] = {
                "status": (result.get("referenceResult") or {}).get("status", ""),
                "artifact": rel(COMMAND_EXECUTION_JSON),
            }
            item["normalizedDiff"] = result.get("normalizedDiff", {})
        row["executedSafeCandidateCount"] = sum(
            1
            for item in row.get("commands", [])
            if item.get("executionStatus")
            in {
                "paired-command-execution-verified",
                "paired-command-execution-drift",
                "partial-wizp-command-executed-reference-blocked",
                "paired-command-execution-expanded-partial",
                "paired-command-execution-safe-subset-return-values-verified",
                "paired-command-execution-safe-subset-side-effects-verified",
            }
        )
    command_diff["executionArtifact"] = rel(COMMAND_EXECUTION_JSON)
    command_diff["wizpExecutedSafeCommands"] = command_execution.get("wizpExecutedSafeCommands", 0)
    command_diff["referenceExecutedSafeCommands"] = command_execution.get("referenceExecutedSafeCommands", 0)
    command_diff["pairedReturnValueMatches"] = command_execution.get("pairedReturnValueMatches", 0)
    command_diff["pairedReturnValueDrifts"] = command_execution.get("pairedReturnValueDrifts", 0)
    command_diff["pairedSideEffectMatches"] = command_execution.get("pairedSideEffectMatches", 0)
    command_diff["pairedSideEffectDrifts"] = command_execution.get("pairedSideEffectDrifts", 0)
    command_diff["targetedSafeCommands"] = command_execution.get("targetedSafeCommands", 0)
    if command_execution.get("status") == "paired-command-execution-safe-subset-side-effects-verified":
        command_diff["note"] = (
            f"Static command inventory and safety classification cover {command_diff.get('totalCommands', 0)} commands. "
            f"The command execution artifact now targets {command_execution.get('targetedSafeCommands', 0)} safe candidate(s), runs {command_execution.get('referenceExecutedSafeCommands', 0)} in both WIZP and the pinned MrCode reference host, and records {command_execution.get('pairedReturnValueMatches', 0)} matching return value(s) plus {command_execution.get('pairedSideEffectMatches', 0)} matching normalized side-effect profile(s)."
        )
    elif command_execution.get("referenceExecutedSafeCommands", 0):
        command_diff["note"] = (
            f"Static command inventory and safety classification cover {command_diff.get('totalCommands', 0)} commands. "
            f"The command execution artifact now targets {command_execution.get('targetedSafeCommands', 0)} safe candidate(s), runs {command_execution.get('referenceExecutedSafeCommands', 0)} in both WIZP and the pinned MrCode reference host, and records {command_execution.get('pairedReturnValueMatches', 0)} matching return value(s) plus {command_execution.get('pairedSideEffectMatches', 0)} matching normalized side-effect profile(s); side-effect diffs stay open for the remaining drift fields."
        )
    else:
        command_diff["note"] = (
            f"Static command inventory and safety classification cover {command_diff.get('totalCommands', 0)} commands. "
            "The command execution artifact has not yet produced paired reference-host executions."
        )
    return command_diff


def extension_scenario_ledger(manifests: dict[str, dict[str, Any]], baseline: dict[str, Any], extension_id: str) -> list[dict[str, Any]]:
    manifest = manifests.get(extension_id.lower(), {})
    rows: list[dict[str, Any]] = []
    for scenario in manifest.get("scenarios", []):
        if not isinstance(scenario, dict):
            continue
        ownership = scenario_ownership(extension_id, scenario, baseline)
        rows.append(ownership)
    return rows


def command_execution_index(command_execution: dict[str, Any]) -> dict[tuple[str, str], dict[str, Any]]:
    result: dict[tuple[str, str], dict[str, Any]] = {}
    entries = command_execution.get("commandResults") if isinstance(command_execution.get("commandResults"), list) else []
    if not entries and isinstance(command_execution.get("target"), dict):
        entries = [command_execution]
    for item in entries:
        if not isinstance(item, dict):
            continue
        target = item.get("target") if isinstance(item.get("target"), dict) else {}
        extension_id = str(target.get("extensionId") or "")
        command = str(target.get("command") or "")
        if extension_id and command:
            result[(extension_id, command)] = item
    return result


def command_ownership(
    extension_id: str,
    command_entry: dict[str, Any],
    scenario_rows: list[dict[str, Any]],
    executed: dict[str, Any] | None,
) -> dict[str, Any]:
    command = str(command_entry.get("command") or "")
    execution_class = str(command_entry.get("executionClass") or "")
    classification_reason = str(command_entry.get("classificationReason") or "")
    scenario_ids = [str(item.get("scenarioIds", [""])[0]) for item in scenario_rows if item.get("scenarioIds")]
    backlog_ids = [backlog for item in scenario_rows for backlog in item.get("backlogIds", []) if isinstance(backlog, str)]
    blocked_host_rows = [
        item
        for item in scenario_rows
        if item.get("owner") == "wizp-host-runtime-api" and item.get("scenarioStatus") == "blocked"
    ]
    unsupported_rows = [item for item in scenario_rows if item.get("owner") == "unsupported-dependency"]
    policy_rows = [item for item in scenario_rows if item.get("owner") == "policy-bound-feature"]
    verified_or_partial = any(item.get("scenarioStatus") in {"verified", "partial"} for item in scenario_rows)
    if executed and str(executed.get("status") or "") in SAFE_COMMAND_EXECUTION_STATUSES:
        return ownership_payload(
            "extension-owned-behavior",
            "This contributed command is already covered by the paired H05 safe-subset execution artifact.",
            bucket="paired-safe-executed",
            backlog_ids=["T20V-H05"],
            scenario_ids=[],
        )
    if execution_class == "requires-consent":
        refs = policy_rows or scenario_rows
        return ownership_payload(
            "policy-bound-feature",
            classification_reason or "This command requires explicit consent, network, or auth policy review before it should run automatically.",
            bucket="manual-only",
            backlog_ids=[backlog for item in refs for backlog in item.get("backlogIds", []) if isinstance(backlog, str)] or ["T20V-H10"],
            scenario_ids=[sid for item in refs for sid in item.get("scenarioIds", []) if isinstance(sid, str)],
        )
    if unsupported_rows and not scenario_rows:
        primary = unsupported_rows[0]
        return ownership_payload(
            "unsupported-dependency",
            str(primary.get("reason") or "The supporting dependency remains unavailable in the pinned reference stack."),
            bucket="unsupported",
        )
    if blocked_host_rows and execution_class == "requires-runtime-or-side-effect-review" and not verified_or_partial:
        primary = blocked_host_rows[0]
        return ownership_payload(
            "wizp-host-runtime-api",
            f"{classification_reason or 'This command needs real runtime plumbing before it can be compared.'} Current blocker owner: {primary.get('reason', '')}".strip(),
            bucket="runtime-blocked",
            backlog_ids=[backlog for item in blocked_host_rows for backlog in item.get("backlogIds", []) if isinstance(backlog, str)],
            scenario_ids=[sid for item in blocked_host_rows for sid in item.get("scenarioIds", []) if isinstance(sid, str)],
            blockers=[blocker for item in blocked_host_rows for blocker in item.get("blockers", []) if isinstance(blocker, str)],
        )
    if execution_class == "manual-review-required" and not scenario_rows:
        return ownership_payload(
            "extension-owned-behavior",
            classification_reason or "This command still needs an explicit scenario before we can compare it safely.",
            bucket="manual-only",
        )
    bucket = "scenario-owned" if scenario_rows else "manual-only"
    reason = (
        "This command should close through the extension's paired scenario rows rather than new WIZP core feature logic."
        if scenario_rows
        else (classification_reason or "This command still needs an explicit paired scenario.")
    )
    return ownership_payload(
        "extension-owned-behavior",
        reason,
        bucket=bucket,
        backlog_ids=backlog_ids,
        scenario_ids=scenario_ids,
    )


def annotate_command_ownership(
    command_diff: dict[str, Any],
    manifests: dict[str, dict[str, Any]],
    baseline: dict[str, Any],
    command_execution: dict[str, Any],
) -> dict[str, Any]:
    executed_index = command_execution_index(command_execution)
    bucket_counts: dict[str, int] = {}
    owner_counts: dict[str, int] = {}
    unowned_commands = 0
    for row in command_diff.get("results", []):
        if not isinstance(row, dict):
            continue
        extension_id = str(row.get("id") or "")
        scenario_rows = extension_scenario_ledger(manifests, baseline, extension_id)
        row_bucket_counts: dict[str, int] = {}
        row_owner_counts: dict[str, int] = {}
        for command_entry in row.get("commands", []):
            if not isinstance(command_entry, dict):
                continue
            executed = executed_index.get((extension_id, str(command_entry.get("command") or "")))
            ownership = command_ownership(extension_id, command_entry, scenario_rows, executed)
            command_entry["ownership"] = ownership
            bucket = str(ownership.get("bucket") or "")
            owner = str(ownership.get("owner") or "")
            if not bucket or not owner:
                unowned_commands += 1
                continue
            bucket_counts[bucket] = bucket_counts.get(bucket, 0) + 1
            owner_counts[owner] = owner_counts.get(owner, 0) + 1
            row_bucket_counts[bucket] = row_bucket_counts.get(bucket, 0) + 1
            row_owner_counts[owner] = row_owner_counts.get(owner, 0) + 1
        row["ownershipBucketCounts"] = dict(sorted(row_bucket_counts.items()))
        row["ownershipOwnerCounts"] = dict(sorted(row_owner_counts.items()))
    command_diff["ownershipBucketCounts"] = dict(sorted(bucket_counts.items()))
    command_diff["ownershipOwnerCounts"] = dict(sorted(owner_counts.items()))
    command_diff["unownedCommandCount"] = unowned_commands
    command_diff["ownershipCoverage"] = {
        "ownedCommands": int(command_diff.get("totalCommands", 0)) - unowned_commands,
        "totalCommands": int(command_diff.get("totalCommands", 0)),
        "status": "complete" if unowned_commands == 0 else "partial",
    }
    command_diff["note"] = (
        f"{command_diff.get('note', '')} Ownership ledger covers {int(command_diff.get('totalCommands', 0)) - unowned_commands}/{command_diff.get('totalCommands', 0)} commands."
    ).strip()
    return command_diff


def annotate_contribution_ownership(contribution_diff: dict[str, Any], baseline: dict[str, Any]) -> dict[str, Any]:
    owner_counts: dict[str, int] = {}
    for row in contribution_diff.get("results", []):
        if not isinstance(row, dict):
            continue
        extension_id = str(row.get("id") or "")
        unsupported = unsupported_dependencies_for(baseline, extension_id)
        if unsupported:
            primary = unsupported[0]
            ownership = ownership_payload(
                "unsupported-dependency",
                str(primary.get("policy") or primary.get("classification") or "A required dependency remains unsupported in the pinned set."),
            )
        elif row.get("driftFamilies") or str(row.get("status") or "").startswith("missing-"):
            ownership = ownership_payload(
                "wizp-host-runtime-api",
                "Contribution drift here is a host/runtime/API normalization problem, not extension feature logic that WIZP should reimplement.",
            )
        else:
            ownership = ownership_payload(
                "extension-owned-behavior",
                "The contribution surface already matches; remaining work stays with other behavior lanes rather than core feature replacement.",
            )
        row["ownership"] = ownership
        owner = str(ownership.get("owner") or "")
        owner_counts[owner] = owner_counts.get(owner, 0) + 1
    contribution_diff["ownershipOwnerCounts"] = dict(sorted(owner_counts.items()))
    return contribution_diff


def annotate_lane_scenario_ownership(artifact: dict[str, Any], manifests: dict[str, dict[str, Any]], baseline: dict[str, Any]) -> dict[str, Any]:
    owner_counts: dict[str, int] = {}
    for row in artifact.get("results", []):
        if not isinstance(row, dict):
            continue
        extension_id = str(row.get("id") or "")
        for scenario_entry in row.get("scenarios", []):
            if not isinstance(scenario_entry, dict):
                continue
            scenario_id = str(scenario_entry.get("scenarioId") or "")
            manifest_scenario = scenario_manifest_entry(manifests, extension_id, scenario_id, scenario_entry)
            ownership = scenario_ownership(extension_id, manifest_scenario, baseline)
            scenario_entry["ownership"] = ownership
            owner = str(ownership.get("owner") or "")
            owner_counts[owner] = owner_counts.get(owner, 0) + 1
    artifact["ownershipOwnerCounts"] = dict(sorted(owner_counts.items()))
    return artifact


def baseline_extension(baseline: dict[str, Any], extension_id: str) -> dict[str, Any]:
    return next((item for item in baseline.get("extensions", []) if item.get("id") == extension_id), {})


def package_summary(manifest_json: dict[str, Any]) -> dict[str, Any]:
    contributes = manifest_json.get("contributes") if isinstance(manifest_json.get("contributes"), dict) else {}
    return {
        "id": f"{manifest_json.get('publisher', '')}.{manifest_json.get('name', '')}".strip("."),
        "name": manifest_json.get("name", ""),
        "displayName": manifest_json.get("displayName", ""),
        "publisher": manifest_json.get("publisher", ""),
        "version": manifest_json.get("version", ""),
        "engines": manifest_json.get("engines", {}),
        "activationEvents": manifest_json.get("activationEvents", []),
        "main": manifest_json.get("main", ""),
        "browser": manifest_json.get("browser", ""),
        "extensionPack": manifest_json.get("extensionPack", []) if isinstance(manifest_json.get("extensionPack"), list) else [],
        "extensionDependencies": manifest_json.get("extensionDependencies", []) if isinstance(manifest_json.get("extensionDependencies"), list) else [],
        "contributionKeys": sorted(str(key) for key in contributes.keys()),
    }


def load_real_extension_report() -> dict[str, Any]:
    if not REAL_EXTENSION_REPORT_JSON.exists():
        return {}
    try:
        return json.loads(REAL_EXTENSION_REPORT_JSON.read_text(encoding="utf-8"))
    except json.JSONDecodeError:
        return {}


def load_top20_runtime_evidence(key: str) -> dict[str, Any]:
    report = load_real_extension_report()
    top20 = report.get("topOpenVSXTop20Runtime") if isinstance(report.get("topOpenVSXTop20Runtime"), dict) else {}
    value = top20.get(key)
    return value if isinstance(value, dict) else {}


def scrub_runtime_paths(value: Any) -> Any:
    replacements = {
        str(REPO_ROOT): "${repo}",
        str(ROOT): "${wizpRoot}",
    }
    return scrub_strings(value, replacements)


def load_wizp_pyrefly_evidence() -> dict[str, Any]:
    if not REAL_EXTENSION_REPORT_JSON.exists():
        return {"status": "missing-runtime-report", "artifact": rel(REAL_EXTENSION_REPORT_JSON)}
    report = load_real_extension_report()
    if not report:
        return {"status": "invalid-runtime-report", "artifact": rel(REAL_EXTENSION_REPORT_JSON)}
    pyrefly = (report.get("topOpenVSXLanguageRuntime") or {}).get("pyrefly") if isinstance(report.get("topOpenVSXLanguageRuntime"), dict) else None
    if not isinstance(pyrefly, dict):
        return {"status": "missing-pyrefly-runtime-evidence", "artifact": rel(REAL_EXTENSION_REPORT_JSON)}
    binary = pyrefly.get("bundledBinary") if isinstance(pyrefly.get("bundledBinary"), dict) else {}
    replacements: dict[str, str] = {}
    binary_path = str(binary.get("path") or "")
    if binary_path:
        replacements[binary_path] = "${wizpExtensionInstallDir}/bin/pyrefly"
        install_root = binary_path.removesuffix("/bin/pyrefly")
        replacements[install_root] = "${wizpExtensionInstallDir}"
    source_file = str(pyrefly.get("sourceFile") or "")
    if source_file:
        replacements[source_file] = "${fixtureWorkspace}/pyrefly_smoke.py"
        replacements[str(Path(source_file).parent)] = "${fixtureWorkspace}"
    ui_events = pyrefly.get("uiEvents") if isinstance(pyrefly.get("uiEvents"), list) else []
    messages = []
    for event in ui_events:
        if not isinstance(event, dict):
            continue
        text = event.get("message") or event.get("text")
        if isinstance(text, str) and text:
            messages.append(scrub_strings(text, replacements))
    runtime_processes = pyrefly.get("runtimeProcesses") if isinstance(pyrefly.get("runtimeProcesses"), dict) else {}
    activation_errors = pyrefly.get("activationErrors") if isinstance(pyrefly.get("activationErrors"), dict) else {}
    health = pyrefly.get("health") if isinstance(pyrefly.get("health"), dict) else {}
    return {
        "status": pyrefly.get("status", ""),
        "artifact": rel(REAL_EXTENSION_REPORT_JSON),
        "bundledBinary": scrub_strings(binary, replacements),
        "activationErrors": scrub_strings(activation_errors, replacements),
        "runtimeProcesses": scrub_strings(runtime_processes, replacements),
        "userFacingMessages": messages[-5:],
        "hostResponsiveAfterFailure": bool(health.get("activeTextEditor") or health.get("providerCounts")),
    }


def load_wizp_ruby_lsp_evidence() -> dict[str, Any]:
    if not REAL_EXTENSION_REPORT_JSON.exists():
        return {"status": "missing-runtime-report", "artifact": rel(REAL_EXTENSION_REPORT_JSON)}
    report = load_real_extension_report()
    if not report:
        return {"status": "invalid-runtime-report", "artifact": rel(REAL_EXTENSION_REPORT_JSON)}
    ruby_lsp = (report.get("topOpenVSXLanguageRuntime") or {}).get("rubyLsp") if isinstance(report.get("topOpenVSXLanguageRuntime"), dict) else None
    if not isinstance(ruby_lsp, dict):
        return {"status": "missing-ruby-lsp-runtime-evidence", "artifact": rel(REAL_EXTENSION_REPORT_JSON)}
    return scrub_runtime_paths({"artifact": rel(REAL_EXTENSION_REPORT_JSON), **ruby_lsp})


def contribution_keys(manifest: dict[str, Any]) -> list[str]:
    contributes = manifest.get("contributes")
    if not isinstance(contributes, dict):
        return []
    return sorted(str(key) for key in contributes.keys())


def command_entries(manifest: dict[str, Any]) -> list[dict[str, Any]]:
    contributes = manifest.get("contributes")
    if not isinstance(contributes, dict):
        return []
    commands = contributes.get("commands")
    if not isinstance(commands, list):
        return []
    entries: list[dict[str, Any]] = []
    for command in commands:
        if not isinstance(command, dict) or not isinstance(command.get("command"), str):
            continue
        entries.append(
            {
                "command": command.get("command", ""),
                "title": command.get("title", ""),
                "category": command.get("category", ""),
                "enablement": command.get("enablement", ""),
                "icon": bool(command.get("icon")),
            }
        )
    return sorted(entries, key=lambda item: str(item["command"]))


def command_execution_class(command_id: str, title: str) -> tuple[str, str]:
    text = f"{command_id} {title}".lower()
    deny_tokens = (
        "install",
        "uninstall",
        "update",
        "delete",
        "remove",
        "create",
        "new ",
        "generate",
        "build",
        "run",
        "start",
        "stop",
        "restart",
        "debug",
        "test",
        "deploy",
        "publish",
        "login",
        "signin",
        "sign in",
        "connect",
        "download",
        "upload",
        "push",
        "pull",
        "sync",
        "clone",
        "commit",
        "checkout",
        "switch",
        "terminal",
        "shell",
        "docker",
        "container",
        "compose",
        "maven",
        "gradle",
        "composer",
        "java.",
        "python.",
        "go.",
        "ruby",
        "php",
        "claude",
        "gitlens",
    )
    consent_tokens = (
        "auth",
        "account",
        "cloud",
        "remote",
        "network",
        "telemetry",
        "assistant",
        "ai",
        "copilot",
    )
    safe_tokens = (
        "show",
        "open",
        "display",
        "view",
        "reveal",
        "refresh",
        "list",
        "status",
        "info",
        "help",
        "about",
        "settings",
        "configuration",
        "copy",
        "clear output",
    )
    if any(token in text for token in consent_tokens):
        return "requires-consent", "auth/network/cloud semantics require an explicit user-consent scenario"
    if any(token in text for token in deny_tokens):
        return "requires-runtime-or-side-effect-review", "command may mutate state, spawn tools, open terminals, or require external runtime"
    if any(token in text for token in safe_tokens):
        return "safe-candidate", "read-only or UI-only command candidate for paired execution"
    return "manual-review-required", "needs explicit scenario classification before execution"


def command_execution_override(
    extension_id: str,
    command_id: str,
    execution_class: str,
    reason: str,
) -> tuple[str, str]:
    if extension_id == "llvm-vs-code-extensions.vscode-clangd" and execution_class == "safe-candidate":
        return (
            "requires-runtime-or-side-effect-review",
            (
                f"{command_id} is contributed statically, but the pinned MrCode host does not register clangd commands "
                "in the missing-clangd fixture; run this under the valid-clangd provider/runtime scenario with a live client"
            ),
        )
    return execution_class, reason


def reference_host() -> dict[str, Any]:
    git_head = ""
    stable_release = ""
    stable_commit = ""
    git_dir = MRCODE_DIR / ".git"
    head = git_dir / "HEAD"
    if head.exists():
        raw = head.read_text(encoding="utf-8", errors="replace").strip()
        if raw.startswith("ref: "):
            ref_path = git_dir / raw.removeprefix("ref: ").strip()
            if ref_path.exists():
                git_head = ref_path.read_text(encoding="utf-8", errors="replace").strip()
        else:
            git_head = raw
    stable_json = MRCODE_DIR / "upstream" / "stable.json"
    if stable_json.exists():
        try:
            stable = json.loads(stable_json.read_text(encoding="utf-8"))
            stable_release = str(stable.get("release") or "")
            stable_commit = str(stable.get("commit") or "")
        except json.JSONDecodeError:
            stable_release = ""
            stable_commit = ""
    executable_source = ""
    configured = os.environ.get("WIZP_TOP20_REFERENCE_HOST", "").strip()
    executable = configured or shutil.which("mrcode") or ""
    if configured:
        executable_source = "WIZP_TOP20_REFERENCE_HOST"
    elif executable:
        executable_source = "PATH:mrcode"
    resolved_executable = ""
    version_lines: list[str] = []
    version = ""
    executable_commit = ""
    arch = ""
    executable_status = "source-present-executable-unpinned" if MRCODE_DIR.exists() else "missing"
    if executable:
        executable_path = Path(executable)
        if executable_path.exists() and os.access(executable_path, os.X_OK):
            resolved_executable = str(executable_path.resolve())
            try:
                completed = subprocess.run(
                    [str(executable_path), "--version"],
                    cwd=str(REPO_ROOT),
                    check=False,
                    text=True,
                    stdout=subprocess.PIPE,
                    stderr=subprocess.PIPE,
                    timeout=10,
                )
                version_lines = [line.strip() for line in completed.stdout.splitlines() if line.strip()]
                if len(version_lines) >= 1:
                    version = version_lines[0]
                if len(version_lines) >= 2:
                    executable_commit = version_lines[1]
                if len(version_lines) >= 3:
                    arch = version_lines[2]
                executable_status = "runnable-pinned" if completed.returncode == 0 and version else "version-probe-failed"
            except (OSError, subprocess.TimeoutExpired):
                executable_status = "version-probe-failed"
        else:
            executable_status = "configured-executable-missing"
    return {
        "preferred": "MrCode",
        "path": rel(MRCODE_DIR) if MRCODE_DIR.exists() else "",
        "exists": MRCODE_DIR.exists(),
        "gitHead": git_head,
        "upstreamStableRelease": stable_release,
        "upstreamStableCommit": stable_commit,
        "executable": executable,
        "resolvedExecutable": resolved_executable,
        "executableSource": executable_source,
        "version": version,
        "versionLines": version_lines,
        "executableCommit": executable_commit,
        "arch": arch,
        "invocationContract": {
            "versionProbe": [executable, "--version"] if executable else [],
            "scenarioArgs": [
                "--user-data-dir",
                "${isolatedUserDataDir}",
                "--extensions-dir",
                "${isolatedExtensionsDir}",
                "--disable-workspace-trust",
                "${fixtureWorkspace}",
            ] if executable else [],
            "profileIsolation": "required",
            "networkAudit": "external wrapper required before behavior evidence",
        },
        "status": executable_status,
    }


def write_default_scenarios(rows: list[dict[str, Any]], overwrite: bool) -> None:
    SCENARIO_DIR.mkdir(parents=True, exist_ok=True)
    write_json(SCENARIO_SCHEMA, SCENARIO_SCHEMA_DOC)
    by_id = {str(row["id"]): row for row in rows}
    for extension_id, scenarios in DEFAULT_SCENARIOS.items():
        row = by_id.get(extension_id)
        if not row:
            continue
        path = SCENARIO_DIR / scenario_filename(extension_id)
        if path.exists() and not overwrite:
            continue
        manifest = {
            "schema": "wizp.top20-behavior-scenario.v1",
            "extensionId": extension_id,
            "rank": int(row["rank"]),
            "lane": str(row["lane"]),
            "version": str(row.get("version") or ""),
            "referenceHost": "MrCode",
            "scenarios": scenarios,
        }
        write_json(path, manifest)


def validate_scenario(manifest: dict[str, Any], row_by_id: dict[str, dict[str, Any]]) -> list[str]:
    errors: list[str] = []
    if manifest.get("schema") != "wizp.top20-behavior-scenario.v1":
        errors.append("schema must be wizp.top20-behavior-scenario.v1")
    extension_id = manifest.get("extensionId")
    if not isinstance(extension_id, str) or not extension_id:
        errors.append("extensionId must be a string")
        return errors
    row = row_by_id.get(extension_id.lower())
    if not row:
        errors.append(f"{extension_id} is not in current top 20")
        return errors
    if manifest.get("rank") != row.get("rank"):
        errors.append(f"rank mismatch for {extension_id}: {manifest.get('rank')} != {row.get('rank')}")
    if manifest.get("lane") != row.get("lane"):
        errors.append(f"lane mismatch for {extension_id}: {manifest.get('lane')} != {row.get('lane')}")
    scenarios = manifest.get("scenarios")
    if not isinstance(scenarios, list) or not scenarios:
        errors.append("scenarios must be a non-empty array")
        return errors
    seen: set[str] = set()
    required = ["id", "title", "backlogIds", "kind", "currentStatus", "fixture", "activationEvents", "actions", "expectedEvidence"]
    for index, scenario in enumerate(scenarios):
        if not isinstance(scenario, dict):
            errors.append(f"scenario {index} must be an object")
            continue
        for key in required:
            if key not in scenario:
                errors.append(f"scenario {index} missing {key}")
        scenario_id = scenario.get("id")
        if not isinstance(scenario_id, str) or not scenario_id:
            errors.append(f"scenario {index} id must be a string")
        elif scenario_id in seen:
            errors.append(f"duplicate scenario id {scenario_id}")
        else:
            seen.add(scenario_id)
        if scenario.get("currentStatus") not in {"planned", "partial", "verified", "unsupported", "blocked"}:
            errors.append(f"scenario {scenario_id or index} has invalid currentStatus")
        for list_key in ["backlogIds", "activationEvents", "actions", "expectedEvidence"]:
            if not isinstance(scenario.get(list_key), list) or not scenario.get(list_key):
                errors.append(f"scenario {scenario_id or index} {list_key} must be a non-empty array")
    return errors


def load_scenarios(rows: list[dict[str, Any]]) -> tuple[dict[str, dict[str, Any]], list[str]]:
    row_by_id = {str(row["id"]).lower(): row for row in rows}
    manifests: dict[str, dict[str, Any]] = {}
    errors: list[str] = []
    for row in rows:
        path = SCENARIO_DIR / scenario_filename(str(row["id"]))
        if not path.exists():
            errors.append(f"missing scenario manifest for {row['id']}: {rel(path)}")
            continue
        try:
            manifest = json.loads(path.read_text(encoding="utf-8"))
        except json.JSONDecodeError as exc:
            errors.append(f"{rel(path)} invalid JSON: {exc}")
            continue
        manifest_errors = validate_scenario(manifest, row_by_id)
        errors.extend(f"{rel(path)}: {message}" for message in manifest_errors)
        manifests[str(row["id"]).lower()] = manifest
    return manifests, errors


def build_baseline(rows: list[dict[str, Any]], manifests: dict[str, dict[str, Any]], generated_at: str) -> dict[str, Any]:
    extensions: list[dict[str, Any]] = []
    unsupported_dependencies = [
        {
            "extensionId": "ms-python.python",
            "dependency": "ms-python.vscode-pylance",
            "classification": "OpenVSX HTTP 404 unsupported child",
            "policy": "unsupported-or-user-supplied-before-full-python-parity-claim",
        }
    ]
    for row in rows:
        extension_id = str(row["id"])
        scenario_path = SCENARIO_DIR / scenario_filename(extension_id)
        scenario_hash = sha256_file(scenario_path) if scenario_path.exists() else ""
        manifest = manifests.get(extension_id.lower(), {})
        fixture_hashes = []
        for scenario in manifest.get("scenarios", []):
            if not isinstance(scenario, dict) or not isinstance(scenario.get("fixture"), str):
                continue
            fixture_path = safe_fixture_dir(str(scenario["fixture"]))
            if fixture_path.exists():
                fixture_hashes.append(
                    {
                        "scenarioId": scenario.get("id", ""),
                        "path": rel(fixture_path),
                        "sha256": sha256_directory(fixture_path),
                        "fileCount": file_count(fixture_path),
                        "status": "pinned",
                    }
                )
            else:
                fixture_hashes.append(
                    {
                        "scenarioId": scenario.get("id", ""),
                        "path": rel(fixture_path),
                        "sha256": "",
                        "fileCount": 0,
                        "status": "missing",
                    }
                )
        extensions.append(
            {
                "rank": row["rank"],
                "id": extension_id,
                "displayName": row.get("displayName", extension_id),
                "version": str(row.get("version") or ""),
                "lane": row.get("lane", ""),
                "runtimeEvidence": row.get("smokeStatus", ""),
                "runtimeArtifact": row.get("artifact", ""),
                "topReportContributionKeys": row.get("contributes", []),
                "vsix": choose_vsix(extension_id, str(row.get("version") or "")),
                "scenarioManifest": rel(scenario_path),
                "scenarioManifestSha256": scenario_hash,
                "scenarioCount": len(manifest.get("scenarios", [])) if isinstance(manifest.get("scenarios"), list) else 0,
                "fixtureWorkspaceHashes": fixture_hashes,
                "fixtureWorkspaceStatus": "pinned" if fixture_hashes and all(item["status"] == "pinned" for item in fixture_hashes) else "pending-real-fixtures",
            }
        )
    return {
        "schema": "wizp.top20-behavior-baseline.v1",
        "generatedAt": generated_at,
        "sourceTopReport": rel(TOP_REPORT_JSON),
        "sourceRuntimeCoverage": rel(RUNTIME_JSON),
        "referenceHost": reference_host(),
        "total": len(extensions),
        "pinnedVsixCount": sum(1 for item in extensions if item["vsix"]["status"] == "pinned"),
        "scenarioManifestCount": sum(1 for item in extensions if item["scenarioCount"] > 0),
        "fixtureWorkspaceHashCount": sum(len(item["fixtureWorkspaceHashes"]) for item in extensions),
        "pinnedFixtureWorkspaceHashCount": sum(1 for item in extensions for fixture in item["fixtureWorkspaceHashes"] if fixture["status"] == "pinned"),
        "unsupportedDependencies": unsupported_dependencies,
        "extensions": extensions,
    }


