def host_keybinding_platform() -> str:
    if sys.platform.startswith("linux"):
        return "linux"
    if sys.platform == "darwin":
        return "mac"
    if sys.platform in {"win32", "cygwin"}:
        return "win"
    return "linux"


def manifest_contributes(manifest: dict[str, Any]) -> dict[str, Any]:
    contributes = manifest.get("contributes")
    return contributes if isinstance(contributes, dict) else {}


def manifest_array_contribution(manifest: dict[str, Any], key: str) -> list[Any]:
    contributes = manifest_contributes(manifest)
    value = contributes.get(key)
    return value if isinstance(value, list) else []


def manifest_object_contribution(manifest: dict[str, Any], key: str) -> dict[str, Any]:
    contributes = manifest_contributes(manifest)
    value = contributes.get(key)
    return value if isinstance(value, dict) else {}


def manifest_configuration_properties(manifest: dict[str, Any]) -> dict[str, Any]:
    contributes = manifest_contributes(manifest)
    value = contributes.get("configuration")
    entries = value if isinstance(value, list) else [value]
    properties: dict[str, Any] = {}
    for entry in entries:
        if not isinstance(entry, dict):
            continue
        entry_properties = entry.get("properties")
        if isinstance(entry_properties, dict):
            properties.update(entry_properties)
    return properties


def manifest_string_array(value: Any) -> list[str]:
    if not isinstance(value, list):
        return []
    return [str(item) for item in value if isinstance(item, str)]


def select_manifest_keybinding(item: dict[str, Any], platform: str) -> str:
    preferred_key = ""
    if platform == "linux":
        preferred_key = str(item.get("linux") or "")
    elif platform == "mac":
        preferred_key = str(item.get("mac") or "")
    elif platform == "win":
        preferred_key = str(item.get("win") or "")
    if preferred_key:
        return preferred_key
    key = item.get("key")
    return str(key) if isinstance(key, str) else ""


def raw_contribution_entries_from_manifest(manifest: dict[str, Any], key: str) -> list[dict[str, Any]]:
    contributes = manifest_contributes(manifest)
    value = contributes.get(key)
    if isinstance(value, list):
        entries = []
        for item in value:
            entry: dict[str, Any] = {"value": item}
            if isinstance(item, dict):
                for candidate in ("id", "name", "type"):
                    candidate_value = item.get(candidate)
                    if isinstance(candidate_value, str) and candidate_value:
                        entry["key"] = candidate_value
                        break
            entries.append(entry)
        return entries
    if isinstance(value, dict):
        return [{"key": str(entry_key), "value": entry_value} for entry_key, entry_value in value.items()]
    if value is None:
        return []
    return [{"value": value}]


def manifest_debugger_snapshot(manifest: dict[str, Any]) -> list[dict[str, Any]]:
    debugger_items = []
    for item in manifest_array_contribution(manifest, "debuggers"):
        if not isinstance(item, dict):
            continue
        type_name = str(item.get("type") or "")
        if not type_name:
            continue
        entry = {str(key): value for key, value in item.items()}
        entry["type"] = type_name
        debugger_items.append(entry)
    return debugger_items


def manifest_contribution_snapshot(manifest: dict[str, Any], platform: str) -> dict[str, Any]:
    contributes = manifest_contributes(manifest)
    command_items = []
    command_title_by_id: dict[str, str] = {}
    for item in manifest_array_contribution(manifest, "commands"):
        if not isinstance(item, dict):
            continue
        command = str(item.get("command") or "")
        if not command:
            continue
        title = str(item.get("title") or "")
        if title:
            command_title_by_id[command] = title
        entry = {"command": command, "title": title or command}
        enablement = item.get("enablement")
        if isinstance(enablement, str) and enablement:
            entry["enablement"] = enablement
        command_items.append(entry)

    menu_items = []
    for menu_name, entries in manifest_object_contribution(manifest, "menus").items():
        if not isinstance(entries, list):
            continue
        for item in entries:
            if not isinstance(item, dict):
                continue
            command = str(item.get("command") or "")
            if not command:
                continue
            entry = {
                "menu": str(menu_name),
                "command": command,
                "title": command_title_by_id.get(command, command),
            }
            for optional_key in ("when", "group", "alt"):
                optional_value = item.get(optional_key)
                if isinstance(optional_value, str) and optional_value:
                    entry[optional_key] = optional_value
            if "args" in item:
                entry["args"] = item.get("args")
            menu_items.append(entry)

    keybinding_items = []
    for item in manifest_array_contribution(manifest, "keybindings"):
        if not isinstance(item, dict):
            continue
        command = str(item.get("command") or "")
        key = select_manifest_keybinding(item, platform)
        if not command or not key:
            continue
        entry = {"command": command, "key": key}
        when = item.get("when")
        if isinstance(when, str) and when:
            entry["when"] = when
        keybinding_items.append(entry)

    configuration_items = []
    configuration = manifest_object_contribution(manifest, "configuration")
    config_title = str(configuration.get("title") or "Extension")
    properties = configuration.get("properties")
    if isinstance(properties, dict):
        for config_key, item in properties.items():
            if not isinstance(item, dict):
                continue
            entry = {
                "key": str(config_key),
                "title": config_title,
                "type": item.get("type", "string"),
                "default": item.get("default"),
            }
            description = item.get("description")
            if isinstance(description, str) and description:
                entry["description"] = description
            configuration_items.append(entry)

    language_items = []
    for item in manifest_array_contribution(manifest, "languages"):
        if not isinstance(item, dict):
            continue
        language_id = str(item.get("id") or "")
        if not language_id:
            continue
        language_items.append(
            {
                "id": language_id,
                "aliases": manifest_string_array(item.get("aliases")),
                "extensions": manifest_string_array(item.get("extensions")),
                "configuration": str(item.get("configuration")) if isinstance(item.get("configuration"), str) else None,
            }
        )

    grammar_items = []
    for item in manifest_array_contribution(manifest, "grammars"):
        if not isinstance(item, dict):
            continue
        language_id = str(item.get("language") or "")
        scope_name = str(item.get("scopeName") or "")
        path = str(item.get("path") or "")
        if not scope_name or not path:
            continue
        grammar_items.append({"language": language_id, "scopeName": scope_name, "path": path})

    theme_items = []
    for item in manifest_array_contribution(manifest, "themes"):
        if not isinstance(item, dict):
            continue
        theme_id = str(item.get("id") or "")
        path = str(item.get("path") or "")
        if not theme_id or not path:
            continue
        entry = {"id": theme_id, "label": str(item.get("label") or theme_id), "path": path}
        ui_theme = item.get("uiTheme")
        if isinstance(ui_theme, str) and ui_theme:
            entry["uiTheme"] = ui_theme
        theme_items.append(entry)

    snippet_items = []
    for item in manifest_array_contribution(manifest, "snippets"):
        if not isinstance(item, dict):
            continue
        language_id = str(item.get("language") or "")
        path = str(item.get("path") or "")
        if not language_id or not path:
            continue
        snippet_items.append({"language": language_id, "path": path})

    view_container_items = []
    for location, entries in manifest_object_contribution(manifest, "viewsContainers").items():
        if not isinstance(entries, list):
            continue
        for item in entries:
            if not isinstance(item, dict):
                continue
            container_id = str(item.get("id") or "")
            if not container_id:
                continue
            entry = {
                "location": str(location),
                "id": container_id,
                "title": str(item.get("title") or container_id),
            }
            icon = item.get("icon")
            if isinstance(icon, str) and icon:
                entry["icon"] = icon
            view_container_items.append(entry)

    view_items = []
    for location, entries in manifest_object_contribution(manifest, "views").items():
        if not isinstance(entries, list):
            continue
        for item in entries:
            if not isinstance(item, dict):
                continue
            view_id = str(item.get("id") or "")
            if not view_id:
                continue
            entry = {
                "location": str(location),
                "container": str(location),
                "id": view_id,
                "name": str(item.get("name") or view_id),
            }
            when = item.get("when")
            if isinstance(when, str) and when:
                entry["when"] = when
            view_items.append(entry)

    view_welcome_items = []
    for item in manifest_array_contribution(manifest, "viewsWelcome"):
        if not isinstance(item, dict):
            continue
        view_id = str(item.get("view") or "")
        contents = str(item.get("contents") or "")
        if not view_id or not contents:
            continue
        entry = {"view": view_id, "contents": contents}
        when = item.get("when")
        if isinstance(when, str) and when:
            entry["when"] = when
        view_welcome_items.append(entry)

    breakpoint_items = []
    for item in manifest_array_contribution(manifest, "breakpoints"):
        if not isinstance(item, dict):
            continue
        language_id = str(item.get("language") or "")
        if language_id:
            breakpoint_items.append({"language": language_id})

    json_validation_items = []
    for item in manifest_array_contribution(manifest, "jsonValidation"):
        if not isinstance(item, dict):
            continue
        url = str(item.get("url") or "")
        if not url:
            continue
        json_validation_items.append(
            {
                "fileMatch": manifest_string_array(item.get("fileMatch")),
                "url": url,
            }
        )

    resource_label_items = []
    for item in manifest_array_contribution(manifest, "resourceLabelFormatters"):
        if not isinstance(item, dict):
            continue
        scheme = str(item.get("scheme") or "")
        formatting = item.get("formatting")
        if not scheme or formatting is None:
            continue
        resource_label_items.append({"scheme": scheme, "formatting": formatting})

    problem_matcher_items = []
    for item in manifest_array_contribution(manifest, "problemMatchers"):
        if not isinstance(item, dict):
            continue
        name = str(item.get("name") or "")
        if not name:
            continue
        entry = {"name": name}
        for optional_key in ("label", "owner", "source"):
            optional_value = item.get(optional_key)
            if isinstance(optional_value, str) and optional_value:
                entry[optional_key] = optional_value
        if "pattern" in item:
            entry["pattern"] = item.get("pattern")
        problem_matcher_items.append(entry)

    task_definition_items = []
    for item in manifest_array_contribution(manifest, "taskDefinitions"):
        if not isinstance(item, dict):
            continue
        type_name = str(item.get("type") or "")
        if not type_name:
            continue
        entry = {"type": type_name, "required": manifest_string_array(item.get("required"))}
        if "properties" in item:
            entry["properties"] = item.get("properties")
        task_definition_items.append(entry)

    debugger_items = manifest_debugger_snapshot(manifest)

    icon_theme_items = []
    for item in manifest_array_contribution(manifest, "iconThemes"):
        if not isinstance(item, dict):
            continue
        theme_id = str(item.get("id") or "")
        path = str(item.get("path") or "")
        if not theme_id or not path:
            continue
        icon_theme_items.append({"id": theme_id, "label": str(item.get("label") or theme_id), "path": path})

    walkthrough_items = []
    for walkthrough_id, item in manifest_object_contribution(manifest, "walkthroughs").items():
        if not isinstance(item, dict):
            continue
        entry = {"id": str(walkthrough_id), "title": str(item.get("title") or walkthrough_id)}
        description = item.get("description")
        if isinstance(description, str) and description:
            entry["description"] = description
        if "steps" in item:
            entry["steps"] = item.get("steps")
        walkthrough_items.append(entry)

    snapshot = {
        "commands": command_items,
        "menus": menu_items,
        "keybindings": keybinding_items,
        "configuration": configuration_items,
        "languages": language_items,
        "grammars": grammar_items,
        "themes": theme_items,
        "snippets": snippet_items,
        "viewsContainers": view_container_items,
        "views": view_items,
        "viewsWelcome": view_welcome_items,
        "breakpoints": breakpoint_items,
        "jsonValidation": json_validation_items,
        "resourceLabelFormatters": resource_label_items,
        "problemMatchers": problem_matcher_items,
        "taskDefinitions": task_definition_items,
        "debuggers": debugger_items,
        "iconThemes": icon_theme_items,
        "walkthroughs": walkthrough_items,
    }
    for family in CONTRIBUTION_SNAPSHOT_FAMILIES:
        if family in snapshot:
            continue
        snapshot[family] = raw_contribution_entries_from_manifest(manifest, family)
    return snapshot


def read_vsix_package_nls(vsix: dict[str, Any]) -> dict[str, str]:
    path = vsix.get("path")
    if not isinstance(path, str) or not path:
        return {}
    vsix_path = REPO_ROOT / path
    if not vsix_path.exists():
        return {}
    try:
        with zipfile.ZipFile(vsix_path) as archive:
            for candidate in ("extension/package.nls.json", "extension/package.nls.en.json"):
                try:
                    with archive.open(candidate) as handle:
                        payload = json.loads(handle.read().decode("utf-8"))
                        if isinstance(payload, dict):
                            return {str(key): str(value) for key, value in payload.items() if isinstance(value, str)}
                except KeyError:
                    continue
    except (zipfile.BadZipFile, json.JSONDecodeError, UnicodeDecodeError):
        return {}
    return {}


def resolve_localized_value(value: Any, localization: dict[str, str]) -> Any:
    if isinstance(value, str) and value.startswith("%") and value.endswith("%") and len(value) > 2:
        return localization.get(value[1:-1], value)
    if isinstance(value, list):
        return [resolve_localized_value(item, localization) for item in value]
    if isinstance(value, dict):
        return {key: resolve_localized_value(item, localization) for key, item in value.items()}
    return value


def normalize_contribution_value(value: Any) -> Any:
    if isinstance(value, dict):
        return {str(key): normalize_contribution_value(item) for key, item in sorted(value.items(), key=lambda entry: str(entry[0]))}
    if isinstance(value, list):
        return [normalize_contribution_value(item) for item in value]
    if isinstance(value, tuple):
        return [normalize_contribution_value(item) for item in value]
    return value


def normalize_contribution_item(family: str, item: Any) -> Any:
    if isinstance(item, dict):
        filtered = {
            key: normalize_contribution_value(value)
            for key, value in item.items()
            if key not in CONTRIBUTION_DYNAMIC_FIELDS.get(family, set())
        }
        return dict(sorted(filtered.items(), key=lambda entry: str(entry[0])))
    return normalize_contribution_value(item)


def normalize_contribution_snapshot(snapshot: dict[str, Any]) -> dict[str, list[Any]]:
    normalized: dict[str, list[Any]] = {}
    for family in CONTRIBUTION_SNAPSHOT_FAMILIES:
        items = snapshot.get(family)
        if not isinstance(items, list):
            items = []
        normalized_items = [normalize_contribution_item(family, item) for item in items]
        normalized[family] = unique_json_items(sorted(normalized_items, key=json_signature))
    return normalized


def contribution_snapshot_counts(snapshot: dict[str, list[Any]]) -> dict[str, int]:
    return {family: len(snapshot.get(family, [])) for family in CONTRIBUTION_SNAPSHOT_FAMILIES if snapshot.get(family)}


def raw_debugger_schema_signature(value: Any) -> str:
    return json.dumps(normalize_contribution_value(value), sort_keys=True, separators=(",", ":"), ensure_ascii=False)


def raw_debugger_schema_summary(reference_debuggers: list[Any], wizp_debuggers: list[Any]) -> dict[str, Any]:
    reference_items = [item for item in reference_debuggers if isinstance(item, dict) and item.get("type")]
    wizp_items = [item for item in wizp_debuggers if isinstance(item, dict) and item.get("type")]
    reference_by_type = {str(item.get("type")): item for item in reference_items}
    wizp_by_type = {str(item.get("type")): item for item in wizp_items}
    types = sorted(set(reference_by_type) | set(wizp_by_type))
    missing_in_wizp = sorted(set(reference_by_type) - set(wizp_by_type))
    extra_in_wizp = sorted(set(wizp_by_type) - set(reference_by_type))
    drift_types = sorted(
        type_name
        for type_name in (set(reference_by_type) & set(wizp_by_type))
        if raw_debugger_schema_signature(reference_by_type[type_name]) != raw_debugger_schema_signature(wizp_by_type[type_name])
    )
    matched_types = sorted(type_name for type_name in types if type_name not in missing_in_wizp and type_name not in extra_in_wizp and type_name not in drift_types)
    configuration_attribute_types = sorted(
        {
            type_name
            for type_name in types
            if (
                isinstance(reference_by_type.get(type_name), dict)
                and "configurationAttributes" in reference_by_type[type_name]
            )
            or (
                isinstance(wizp_by_type.get(type_name), dict)
                and "configurationAttributes" in wizp_by_type[type_name]
            )
        }
    )
    if not types:
        status = "no-debugger-contributions"
        note = "This extension contributes no debuggers, so raw debugger-schema parity does not apply."
    elif not missing_in_wizp and not extra_in_wizp and not drift_types:
        status = "raw-debugger-schema-match"
        note = "Raw debugger contribution schemas match, including configurationAttributes payloads."
    else:
        status = "raw-debugger-schema-drift"
        note = "Raw debugger contribution schemas still drift and remain explicit H08-owned follow-up."
    return {
        "status": status,
        "ownedBy": "T20V-H08",
        "referenceDebuggerCount": len(reference_items),
        "wizpDebuggerCount": len(wizp_items),
        "debuggerTypeCount": len(types),
        "configurationAttributeDebuggerTypes": configuration_attribute_types,
        "matchedDebuggerTypes": matched_types,
        "driftDebuggerTypes": drift_types,
        "missingInWizpDebuggerTypes": missing_in_wizp,
        "extraInWizpDebuggerTypes": extra_in_wizp,
        "note": note,
    }


def contribution_family_diff(left: list[Any], right: list[Any], limit: int = 8) -> dict[str, Any]:
    left_by_sig = {json_signature(item): item for item in left}
    right_by_sig = {json_signature(item): item for item in right}
    left_only_keys = sorted(set(left_by_sig) - set(right_by_sig))
    right_only_keys = sorted(set(right_by_sig) - set(left_by_sig))
    return {
        "wizpOnlyCount": len(left_only_keys),
        "referenceOnlyCount": len(right_only_keys),
        "wizpOnlyPreview": [left_by_sig[key] for key in left_only_keys[:limit]],
        "referenceOnlyPreview": [right_by_sig[key] for key in right_only_keys[:limit]],
    }


def write_reference_contribution_probe(dev_extension_dir: Path, result_path: Path) -> Path:
    dev_extension_dir.mkdir(parents=True, exist_ok=True)
    package_json = {
        "name": "wizp-top20-reference-contribution-probe",
        "displayName": "WIZP Top20 Reference Contribution Probe",
        "publisher": "wizp",
        "version": "0.0.1",
        "engines": {"vscode": "^1.110.0"},
        "main": "./extension.js",
    }
    (dev_extension_dir / "package.json").write_text(json.dumps(package_json, indent=2) + "\n", encoding="utf-8")
    extension_js = dev_extension_dir / "extension.js"
    extension_js.write_text(
        """
const vscode = require('vscode');
const fs = require('fs');

function findExtension(extensionId) {
  const exact = vscode.extensions.getExtension(extensionId);
  if (exact) return exact;
  const lower = String(extensionId || '').toLowerCase();
  return vscode.extensions.all.find((item) => String(item.id || '').toLowerCase() === lower) || null;
}

exports.run = async function run(_testsRoot, callback) {
  const extensionId = process.env.WIZP_REF_EXTENSION_ID || '';
  const resultPath = process.env.WIZP_REF_RESULT || '';
  const result = { status: 'reference-contribution-probe-started', extensionId };
  try {
    const extension = findExtension(extensionId);
    if (!extension) {
      result.status = 'extension-not-found';
      result.installedExtensionIds = vscode.extensions.all.map((item) => item.id);
    } else {
      result.status = 'ok';
      result.extension = {
        id: extension.id,
        extensionPath: extension.extensionPath,
        isActive: !!extension.isActive,
      };
      result.packageJSON = extension.packageJSON || {};
    }
    fs.writeFileSync(resultPath, JSON.stringify(result, null, 2));
    callback(null, 0);
  } catch (error) {
    result.status = 'reference-contribution-probe-error';
    result.error = String(error);
    result.stack = error && error.stack ? String(error.stack) : '';
    fs.writeFileSync(resultPath, JSON.stringify(result, null, 2));
    callback(error, 1);
  }
};
""".lstrip(),
        encoding="utf-8",
    )
    return extension_js


def run_reference_contribution_probe(
    extension_id: str,
    baseline: dict[str, Any],
    baseline_row: dict[str, Any],
    platform: str,
) -> dict[str, Any]:
    reference = baseline.get("referenceHost", {}) if isinstance(baseline.get("referenceHost"), dict) else {}
    vsix = baseline_row.get("vsix", {}) if isinstance(baseline_row.get("vsix"), dict) else {}
    vsix_path = REPO_ROOT / str(vsix.get("path", ""))
    executable = str(reference.get("executable") or "")
    if not executable:
        return {"status": "blocked-reference-host-executable-unpinned", "extensionId": extension_id}
    if not vsix_path.exists():
        return {"status": "blocked-missing-vsix", "extensionId": extension_id, "vsix": rel(vsix_path)}

    with tempfile.TemporaryDirectory(prefix="wizp-top20-reference-contribution-") as tmp:
        tmp_root = Path(tmp)
        user_data = tmp_root / "user-data"
        extensions_dir = tmp_root / "extensions"
        workspace = tmp_root / "workspace"
        dev_extension = tmp_root / "dev-test-extension"
        logs_dir = tmp_root / "logs"
        result_path = tmp_root / "result.json"
        workspace.mkdir(parents=True)
        logs_dir.mkdir(parents=True)
        probe_module = write_reference_contribution_probe(dev_extension, result_path)
        replacements = {
            str(tmp_root): "${tmp}",
            str(user_data): "${isolatedUserDataDir}",
            str(extensions_dir): "${isolatedExtensionsDir}",
            str(workspace): "${fixtureWorkspace}",
            str(dev_extension): "${testExtensionDir}",
            str(probe_module): "${testModule}",
            str(result_path): "${resultJson}",
            str(vsix_path): "${pinnedVsix}",
            str(REPO_ROOT): "${repo}",
            str(ROOT): "${wizpRoot}",
        }
        install_evidence = install_reference_vsix_into(
            reference,
            vsix_path,
            extension_id,
            str(baseline_row.get("version") or ""),
            user_data,
            extensions_dir,
            replacements,
        )
        if install_evidence.get("status") != "installed-and-listed":
            return {
                "status": "blocked-reference-install-or-list-failed",
                "extensionId": extension_id,
                "installEvidence": install_evidence,
            }

        env = os.environ.copy()
        env.update(
            {
                "DONT_PROMPT_WSL_INSTALL": "1",
                "VSCODE_DISABLE_CRASH_REPORTER": "1",
                "WIZP_REF_EXTENSION_ID": extension_id,
                "WIZP_REF_RESULT": str(result_path),
                "WIZP_REF_PLATFORM": platform,
            }
        )
        run_template = [
            "${referenceHost}",
            "--new-window",
            "--wait",
            "--user-data-dir",
            "${isolatedUserDataDir}",
            "--extensions-dir",
            "${isolatedExtensionsDir}",
            "--logsPath",
            "${referenceLogsDir}",
            "--disable-workspace-trust",
            "--disable-telemetry",
            "--disable-experiments",
            "--disable-updates",
            "--skip-welcome",
            "--skip-release-notes",
            "--skip-add-to-recently-opened",
            "--password-store=basic",
            "--extensionDevelopmentPath=${testExtensionDir}",
            "--extensionTestsPath=${testModule}",
            "${fixtureWorkspace}",
        ]
        replacements[str(logs_dir)] = "${referenceLogsDir}"
        runner = command_capture_result(
            [
                executable,
                "--new-window",
                "--wait",
                "--user-data-dir",
                str(user_data),
                "--extensions-dir",
                str(extensions_dir),
                "--logsPath",
                str(logs_dir),
                "--disable-workspace-trust",
                "--disable-telemetry",
                "--disable-experiments",
                "--disable-updates",
                "--skip-welcome",
                "--skip-release-notes",
                "--skip-add-to-recently-opened",
                "--password-store=basic",
                f"--extensionDevelopmentPath={dev_extension}",
                f"--extensionTestsPath={probe_module}",
                str(workspace),
            ],
            90,
            run_template,
            replacements,
            env=env,
        )
        probe_result = json.loads(result_path.read_text(encoding="utf-8")) if result_path.exists() else {}
        log_audit = reference_log_audit(logs_dir, extension_id, replacements)
        status = "reference-contribution-snapshot-captured"
        if runner.get("returnCode") != 0 or probe_result.get("status") != "ok":
            status = "reference-contribution-snapshot-failed"
        return scrub_strings(
            {
                "status": status,
                "extensionId": extension_id,
                "vsix": rel(vsix_path),
                "installEvidence": install_evidence,
                "runner": runner,
                "probeResult": probe_result,
                "logAudit": log_audit,
            },
            replacements,
        )


def run_wizp_contribution_probe(extension_id: str, baseline_row: dict[str, Any], platform: str) -> dict[str, Any]:
    vsix = baseline_row.get("vsix", {}) if isinstance(baseline_row.get("vsix"), dict) else {}
    vsix_path = REPO_ROOT / str(vsix.get("path", ""))
    manifest = read_vsix_package_json(vsix)
    if not WIZP_BIN.exists():
        return {"status": "blocked-missing-wizp-binary", "binary": rel(WIZP_BIN), "extensionId": extension_id}
    if not vsix_path.exists():
        return {"status": "blocked-missing-vsix", "extensionId": extension_id, "vsix": rel(vsix_path)}
    if not manifest:
        return {"status": "blocked-missing-vsix-manifest", "extensionId": extension_id, "vsix": rel(vsix_path)}

    with tempfile.TemporaryDirectory(prefix="wizp-top20-contribution-") as tmp:
        tmp_root = Path(tmp)
        home = tmp_root / "home"
        workspace = tmp_root / "workspace"
        ext_root = home / ".wizp" / "extensions"
        ext_root.mkdir(parents=True)
        workspace.mkdir()
        install_path = install_vsix_for_wizp(vsix_path, ext_root, manifest)
        port = free_tcp_port()
        rpc_url = f"http://127.0.0.1:{port}/api/rpc"
        stdout_path = tmp_root / "wizp.stdout.log"
        stderr_path = tmp_root / "wizp.stderr.log"
        replacements = {
            str(tmp_root): "${tmp}",
            str(home): "${isolatedHome}",
            str(workspace): "${fixtureWorkspace}",
            str(ext_root): "${isolatedExtensionsDir}",
            str(install_path): "${wizpExtensionInstallDir}",
            str(vsix_path): "${pinnedVsix}",
            str(REPO_ROOT): "${repo}",
            str(ROOT): "${wizpRoot}",
        }
        env = os.environ.copy()
        env.update(
            {
                "HOME": str(home),
                "WIZP_EXTENSION_DIR": str(ext_root),
                "WIZP_PORT": str(port),
                "WIZP_NO_BROWSER": "1",
                "WIZP_WEBVIEW": "false",
                "WIZP_DEFER_STARTUP_EXTENSIONS": "1",
            }
        )
        with stdout_path.open("w", encoding="utf-8") as stdout, stderr_path.open("w", encoding="utf-8") as stderr:
            proc = subprocess.Popen([str(WIZP_BIN)], cwd=str(workspace), env=env, stdout=stdout, stderr=stderr)
            try:
                manifest_name = str(manifest.get("name") or "")
                required_commands = {
                    str(item.get("command") or "")
                    for item in command_entries(manifest)[:1]
                    if isinstance(item, dict) and isinstance(item.get("command"), str) and item.get("command")
                }
                wait_for_wizp_server(
                    rpc_url,
                    required_commands=required_commands or None,
                    timeout=30.0,
                )
                snapshot = wait_for_wizp_contribution_snapshot(
                    rpc_url,
                    [extension_id, manifest_name],
                    platform,
                    timeout=20.0,
                    request_id=341,
                )
                status = "wizp-contribution-snapshot-captured"
                if not isinstance(snapshot, dict) or snapshot.get("status") != "ok":
                    status = "wizp-contribution-snapshot-failed"
                return scrub_strings(
                    {
                        "status": status,
                        "extensionId": extension_id,
                        "port": port,
                        "vsix": rel(vsix_path),
                        "installDirName": install_path.name,
                        "snapshot": snapshot,
                        "stdoutTail": stdout_path.read_text(encoding="utf-8", errors="replace")[-2000:],
                        "stderrTail": stderr_path.read_text(encoding="utf-8", errors="replace")[-4000:],
                    },
                    replacements,
                )
            except Exception as exc:
                stdout.flush()
                stderr.flush()
                return scrub_strings(
                    {
                        "status": "wizp-contribution-snapshot-failed",
                        "extensionId": extension_id,
                        "port": port,
                        "vsix": rel(vsix_path),
                        "error": str(exc),
                        "stdoutTail": stdout_path.read_text(encoding="utf-8", errors="replace")[-2000:],
                        "stderrTail": stderr_path.read_text(encoding="utf-8", errors="replace")[-4000:],
                    },
                    replacements,
                )
            finally:
                proc.terminate()
                try:
                    proc.wait(timeout=5)
                except subprocess.TimeoutExpired:
                    proc.kill()
                    proc.wait(timeout=5)


def build_contribution_diff(rows: list[dict[str, Any]], baseline: dict[str, Any], generated_at: str) -> dict[str, Any]:
    baseline_by_id = {str(item["id"]): item for item in baseline.get("extensions", [])}
    platform = host_keybinding_platform()
    results: list[dict[str, Any]] = []
    static_matched = 0
    normalized_matched = 0
    drifted = 0
    blocked = 0

    for row in rows:
        extension_id = str(row["id"])
        baseline_row = baseline_by_id.get(extension_id, {})
        manifest = read_vsix_package_json(baseline_row.get("vsix", {}))
        localization = read_vsix_package_nls(baseline_row.get("vsix", {}))
        vsix_keys = contribution_keys(manifest)
        report_keys = sorted(str(key) for key in row.get("contributes", []))
        missing = sorted(set(report_keys) - set(vsix_keys))
        extra = sorted(set(vsix_keys) - set(report_keys))
        static_status = "static-contribution-keys-match" if not missing and not extra and vsix_keys else "static-contribution-drift"
        if not manifest:
            static_status = "missing-vsix-manifest"
        if static_status == "static-contribution-keys-match":
            static_matched += 1

        reference_probe = run_reference_contribution_probe(extension_id, baseline, baseline_row, platform) if manifest else {"status": "missing-vsix-manifest"}
        wizp_probe = run_wizp_contribution_probe(extension_id, baseline_row, platform) if manifest else {"status": "missing-vsix-manifest"}

        reference_manifest = (
            reference_probe.get("probeResult", {}).get("packageJSON", {})
            if isinstance(reference_probe.get("probeResult"), dict)
            else {}
        )
        reference_manifest = resolve_localized_value(reference_manifest, localization) if isinstance(reference_manifest, dict) else {}
        raw_manifest = resolve_localized_value(manifest, localization) if isinstance(manifest, dict) else {}
        reference_snapshot = manifest_contribution_snapshot(reference_manifest, platform) if isinstance(reference_manifest, dict) else {}
        wizp_snapshot_raw = wizp_probe.get("snapshot", {}) if isinstance(wizp_probe.get("snapshot"), dict) else {}
        wizp_snapshot_raw = resolve_localized_value(wizp_snapshot_raw, localization) if isinstance(wizp_snapshot_raw, dict) else wizp_snapshot_raw
        raw_debugger_evidence = raw_debugger_schema_summary(
            manifest_debugger_snapshot(raw_manifest) if isinstance(raw_manifest, dict) else [],
            wizp_snapshot_raw.get("debuggers") if isinstance(wizp_snapshot_raw.get("debuggers"), list) else [],
        )

        normalized_reference = normalize_contribution_snapshot(reference_snapshot) if reference_snapshot else {family: [] for family in CONTRIBUTION_SNAPSHOT_FAMILIES}
        normalized_wizp = normalize_contribution_snapshot(wizp_snapshot_raw) if wizp_snapshot_raw else {family: [] for family in CONTRIBUTION_SNAPSHOT_FAMILIES}

        families = [
            family
            for family in CONTRIBUTION_SNAPSHOT_FAMILIES
            if normalized_reference.get(family) or normalized_wizp.get(family)
        ]
        matched_families = [family for family in families if normalized_wizp.get(family, []) == normalized_reference.get(family, [])]
        drift_families = [
            {
                "family": family,
                "wizpCount": len(normalized_wizp.get(family, [])),
                "referenceCount": len(normalized_reference.get(family, [])),
                **contribution_family_diff(normalized_wizp.get(family, []), normalized_reference.get(family, [])),
            }
            for family in families
            if normalized_wizp.get(family, []) != normalized_reference.get(family, [])
        ]

        blocked_reason = ""
        if static_status == "missing-vsix-manifest":
            status = "missing-vsix-manifest"
        elif wizp_probe.get("status") != "wizp-contribution-snapshot-captured":
            status = "blocked-wizp-contribution-snapshot"
            blocked_reason = str(wizp_probe.get("status") or "wizp-probe-failed")
        elif reference_probe.get("status") != "reference-contribution-snapshot-captured":
            status = "blocked-reference-contribution-snapshot"
            blocked_reason = str(reference_probe.get("status") or "reference-probe-failed")
        elif static_status != "static-contribution-keys-match" or drift_families:
            status = "reference-normalized-contribution-drift"
        else:
            status = "reference-normalized-contribution-match"

        if status == "reference-normalized-contribution-match":
            normalized_matched += 1
        elif status.startswith("blocked-"):
            blocked += 1
        elif status != "missing-vsix-manifest":
            drifted += 1

        note = "WIZP and the pinned MrCode host expose matching normalized contribution families."
        if status == "reference-normalized-contribution-drift":
            note = f"Normalized contribution drift remains in {len(drift_families)} family(s)."
        elif status.startswith("blocked-"):
            note = f"Contribution normalization probe is blocked: {blocked_reason}."
        elif status == "missing-vsix-manifest":
            note = "Pinned VSIX manifest is missing, so contribution normalization could not run."

        results.append(
            {
                "rank": row["rank"],
                "id": extension_id,
                "version": row.get("version", ""),
                "status": status,
                "vsix": baseline_row.get("vsix", {}),
                "displayName": manifest.get("displayName") or row.get("displayName", extension_id),
                "publisher": manifest.get("publisher", ""),
                "manifestVersion": manifest.get("version", ""),
                "platform": platform,
                "topReportContributionKeys": report_keys,
                "vsixContributionKeys": vsix_keys,
                "missingInVsixManifest": missing,
                "extraInVsixManifest": extra,
                "staticStatus": static_status,
                "comparedFamilies": families,
                "matchedFamilies": matched_families,
                "driftFamilies": drift_families,
                "wizpFamilyCounts": contribution_snapshot_counts(normalized_wizp),
                "referenceFamilyCounts": contribution_snapshot_counts(normalized_reference),
                "wizpProbe": wizp_probe,
                "referenceProbe": reference_probe,
                "wizpNormalizedSnapshot": normalized_wizp,
                "referenceNormalizedSnapshot": normalized_reference,
                "rawDebuggerSchemaEvidence": raw_debugger_evidence,
                "note": note,
            }
        )
    return {
        "schema": "wizp.top20-behavior-contribution-diff.v2",
        "generatedAt": generated_at,
        "sourceBaseline": rel(BASELINE_JSON),
        "referenceHost": baseline.get("referenceHost", {}),
        "platform": platform,
        "total": len(results),
        "staticContributionKeysMatch": static_matched,
        "remainingStaticDrift": len(results) - static_matched,
        "referenceNormalizedMatch": normalized_matched,
        "remainingReferenceDrift": drifted,
        "blockedReferenceNormalization": blocked,
        "normalizedDynamicFields": {family: sorted(fields) for family, fields in sorted(CONTRIBUTION_DYNAMIC_FIELDS.items())},
        "normalizedDynamicFieldOwnership": CONTRIBUTION_DYNAMIC_FIELD_OWNERSHIP,
        "results": results,
    }


def build_command_diff(rows: list[dict[str, Any]], baseline: dict[str, Any], generated_at: str) -> dict[str, Any]:
    baseline_by_id = {str(item["id"]): item for item in baseline.get("extensions", [])}
    reference = baseline.get("referenceHost", {})
    reference_ready = bool(reference.get("executable") and reference.get("version"))
    results: list[dict[str, Any]] = []
    total_commands = 0
    safe_candidates = 0
    by_class: dict[str, int] = {}
    for row in rows:
        extension_id = str(row["id"])
        baseline_row = baseline_by_id.get(extension_id, {})
        manifest = read_vsix_package_json(baseline_row.get("vsix", {}))
        commands: list[dict[str, Any]] = []
        for command in command_entries(manifest):
            execution_class, reason = command_execution_class(str(command["command"]), str(command.get("title", "")))
            execution_class, reason = command_execution_override(extension_id, str(command["command"]), execution_class, reason)
            by_class[execution_class] = by_class.get(execution_class, 0) + 1
            total_commands += 1
            if execution_class == "safe-candidate":
                safe_candidates += 1
            commands.append(
                {
                    **command,
                    "executionClass": execution_class,
                    "classificationReason": reason,
                    "executionStatus": "blocked-reference-host-executable-unpinned" if not reference_ready else "planned",
                    "wizpResult": {"status": "not-run", "artifact": ""},
                    "referenceResult": {"status": "not-run", "artifact": ""},
                    "normalizedDiff": {"status": "not-run", "unexpectedDrift": False},
                }
            )
        results.append(
            {
                "rank": row["rank"],
                "id": extension_id,
                "version": row.get("version", ""),
                "vsix": baseline_row.get("vsix", {}),
                "commandCount": len(commands),
                "safeCandidateCount": sum(1 for item in commands if item["executionClass"] == "safe-candidate"),
                "executionGate": "reference-host-executable-unpinned" if not reference_ready else "ready-for-paired-execution",
                "commands": commands,
            }
        )
    return {
        "schema": "wizp.top20-behavior-command-diff.v1",
        "generatedAt": generated_at,
        "sourceBaseline": rel(BASELINE_JSON),
        "totalExtensions": len(results),
        "totalCommands": total_commands,
        "safeCandidateCommands": safe_candidates,
        "classificationCounts": dict(sorted(by_class.items())),
        "executionGate": "reference-host-executable-unpinned" if not reference_ready else "ready-for-paired-execution",
        "results": results,
        "note": "Static command inventory and safety classification only; real WIZP/reference execution remains gated by T20V-H02.",
    }


