def manifest_language_summary(manifest: dict[str, Any]) -> dict[str, Any]:
    contributes = manifest.get("contributes")
    if not isinstance(contributes, dict):
        contributes = {}
    languages = contributes.get("languages") if isinstance(contributes.get("languages"), list) else []
    grammars = contributes.get("grammars") if isinstance(contributes.get("grammars"), list) else []
    semantic_scopes = contributes.get("semanticTokenScopes") if isinstance(contributes.get("semanticTokenScopes"), list) else []
    return {
        "languageIds": sorted(str(item.get("id")) for item in languages if isinstance(item, dict) and item.get("id")),
        "grammarScopes": sorted(str(item.get("scopeName")) for item in grammars if isinstance(item, dict) and item.get("scopeName")),
        "semanticTokenScopeCount": len(semantic_scopes),
    }


def provider_probe_artifact_path(extension_id: str, scenario_id: str) -> Path:
    return PROVIDER_PROBE_DIR / extension_id / f"{scenario_id}.json"


def normalize_provider_markdown(value: Any) -> Any:
    if value is None:
        return None
    if isinstance(value, str):
        if "\\" in value and any(token in value for token in ("\\n", "\\r", "\\t", '\\"')):
            try:
                value = json.loads(f'"{value}"')
            except json.JSONDecodeError:
                value = value.replace("\\n", "\n").replace("\\r", "\r").replace("\\t", "\t").replace('\\"', '"')
        return value.rstrip()
    if isinstance(value, list):
        return [normalize_provider_markdown(item) for item in value]
    if isinstance(value, dict):
        if isinstance(value.get("value"), str):
            return value["value"]
        return {key: normalize_provider_markdown(item) for key, item in sorted(value.items())}
    return str(value)


def normalize_provider_range(value: Any) -> Any:
    if not isinstance(value, dict):
        return None
    start = value.get("start") if isinstance(value.get("start"), dict) else {}
    end = value.get("end") if isinstance(value.get("end"), dict) else {}
    return {
        "start": {
            "line": int(start.get("line") or 0),
            "character": int(start.get("character") or 0),
        },
        "end": {
            "line": int(end.get("line") or 0),
            "character": int(end.get("character") or 0),
        },
    }


def normalize_provider_uri(value: Any) -> str:
    uri = str(value or "")
    if uri.startswith("file://${fixtureWorkspace}/"):
        return uri[len("file://") :]
    if not uri or "${fixtureWorkspace}" in uri:
        return uri
    marker = "/workspace/"
    if uri.startswith("file://") and marker in uri:
        return "file://${fixtureWorkspace}/" + uri.split(marker, 1)[1]
    if marker in uri:
        return "${fixtureWorkspace}/" + uri.split(marker, 1)[1]
    return uri


def normalize_provider_location(value: Any) -> Any:
    if not isinstance(value, dict):
        return None
    return {
        "uri": normalize_provider_uri(value.get("uri")),
        "range": normalize_provider_range(value.get("range")),
    }


def normalize_provider_workspace_edit(value: Any) -> Any:
    if not isinstance(value, dict):
        return None
    changes = value.get("changes") if isinstance(value.get("changes"), dict) else {}
    normalized_changes: dict[str, list[str]] = {}
    for uri, edits in sorted(changes.items()):
        if not isinstance(edits, list):
            continue
        normalized_changes[normalize_provider_uri(uri)] = unique_json_items(
            sorted(
                (str(item.get("newText") or "") for item in edits if isinstance(item, dict)),
                key=json_signature,
            )
        )
    return {"changes": normalized_changes}


def normalize_provider_completion(value: Any) -> dict[str, Any]:
    items = value.get("items") if isinstance(value, dict) and isinstance(value.get("items"), list) else []
    normalized = []
    for item in items:
        if not isinstance(item, dict):
            continue
        normalized.append(
            {
                "label": str(item.get("label") or ""),
                "kind": item.get("kind"),
                "insertText": str(item.get("insertText") or ""),
                "detail": str(item.get("detail") or ""),
                "documentation": normalize_provider_markdown(item.get("documentation")),
                "commitCharacters": [str(entry) for entry in item.get("commitCharacters", []) if isinstance(entry, str)],
            }
        )
    return {"items": unique_json_items(sorted(normalized, key=json_signature))}


def completion_labels_from_normalized(value: Any) -> list[str]:
    items = value.get("items") if isinstance(value, dict) and isinstance(value.get("items"), list) else []
    return [str(item.get("label") or "") for item in items if isinstance(item, dict) and str(item.get("label") or "")]


def completion_label_text(value: Any) -> str:
    if not isinstance(value, dict):
        return ""
    label = value.get("label")
    if isinstance(label, dict):
        return str(label.get("label") or "")
    return str(label or "")


def stable_completion_prefix(sequences: list[list[str]]) -> list[str]:
    if not sequences:
        return []
    prefix: list[str] = []
    for entries in zip(*sequences):
        if len(set(entries)) != 1:
            break
        prefix.append(entries[0])
    return prefix


def stable_completion_label_set(label_sets: list[set[str]]) -> set[str]:
    if not label_sets:
        return set()
    return set.intersection(*label_sets)


def completion_stability_run_summary(bundle: dict[str, Any]) -> dict[str, Any]:
    provider = bundle.get("provider") if isinstance(bundle.get("provider"), dict) else {}
    raw_completion = provider.get("completion") if isinstance(provider.get("completion"), dict) else {}
    raw_items = raw_completion.get("items") if isinstance(raw_completion.get("items"), list) else []
    labels = [label for label in (completion_label_text(item) for item in raw_items) if label]
    label_set = set(labels)
    return {
        "status": str(bundle.get("status") or "not-run"),
        "isIncomplete": bool(raw_completion.get("isIncomplete") or raw_completion.get("incomplete")),
        "count": len(labels),
        "labels": labels,
        "labelSet": label_set,
    }


def normalize_provider_hover(value: Any) -> Any:
    if not isinstance(value, dict):
        return None
    contents = value.get("contents")
    if isinstance(contents, list):
        normalized_contents = [normalize_provider_markdown(item) for item in contents]
    elif contents is None:
        normalized_contents = []
    else:
        normalized_contents = [normalize_provider_markdown(contents)]
    return {"contents": normalized_contents}


def normalize_provider_locations(value: Any) -> list[dict[str, Any]]:
    if not isinstance(value, list):
        return []
    normalized = [{"uri": normalize_provider_uri(item.get("uri"))} for item in value if isinstance(item, dict) and str(item.get("uri") or "")]
    return unique_json_items(sorted((item for item in normalized if item), key=json_signature))


def normalize_provider_code_actions(value: Any) -> list[dict[str, Any]]:
    if not isinstance(value, list):
        return []
    normalized = []
    for item in value:
        if not isinstance(item, dict):
            continue
        command = item.get("command") if isinstance(item.get("command"), dict) else {}
        normalized.append(
            {
                "title": str(item.get("title") or ""),
                "kind": str(item.get("kind") or "") or None,
                "isPreferred": bool(item.get("isPreferred")),
                "command": {
                    "title": str(command.get("title") or ""),
                    "command": str(command.get("command") or ""),
                    "hasArguments": bool(command.get("arguments")),
                }
                if command
                else None,
            }
        )
    return unique_json_items(sorted(normalized, key=json_signature))


def normalize_provider_text_edits(value: Any) -> list[dict[str, Any]]:
    if isinstance(value, dict) and "appliedText" in value:
        return [{"appliedText": normalize_provider_markdown(value.get("appliedText"))}]
    if not isinstance(value, list):
        return []
    normalized = []
    for item in value:
        if not isinstance(item, dict):
            continue
        normalized.append({"newText": str(item.get("newText") or "")})
    return unique_json_items(sorted(normalized, key=json_signature))


def normalize_provider_symbol_item(value: Any) -> Any:
    if not isinstance(value, dict):
        return None
    normalized = {
        "name": str(value.get("name") or ""),
        "kind": value.get("kind"),
    }
    if value.get("containerName"):
        normalized["containerName"] = str(value.get("containerName") or "")
    return normalized


def normalize_provider_symbols(value: Any) -> list[dict[str, Any]]:
    if not isinstance(value, list):
        return []
    normalized = [normalize_provider_symbol_item(item) for item in value if isinstance(item, dict)]
    return unique_json_items(sorted((item for item in normalized if item), key=json_signature))


def normalize_prepare_rename(value: Any) -> Any:
    if value is None:
        return None
    if isinstance(value, dict):
        if isinstance(value.get("range"), dict):
            placeholder = str(value.get("placeholder") or "") or None
            if placeholder is not None:
                return {"placeholder": placeholder}
            return {"range": normalize_provider_range(value.get("range"))}
        if "start" in value and "end" in value:
            return normalize_provider_range(value)
    return normalize_provider_markdown(value)


def normalize_provider_diagnostics(bundle: dict[str, Any]) -> list[dict[str, Any]]:
    active_uri = normalize_provider_uri(bundle.get("activeUri"))
    diagnostics = bundle.get("diagnostics")
    rows: list[dict[str, Any]] = []
    if isinstance(diagnostics, dict):
        collections = diagnostics.get("collections") if isinstance(diagnostics.get("collections"), list) else []
        for collection in collections:
            if not isinstance(collection, dict):
                continue
            for entry in collection.get("entries", []):
                if not isinstance(entry, dict):
                    continue
                uri = normalize_provider_uri(entry.get("uri"))
                if active_uri and uri != active_uri:
                    continue
                for item in entry.get("diagnostics", []):
                    if isinstance(item, dict):
                        rows.append(
                            {
                                "uri": uri,
                                "message": str(item.get("message") or ""),
                                "severity": item.get("severity"),
                                "source": str(item.get("source") or ""),
                                "code": item.get("code"),
                            }
                        )
    elif isinstance(diagnostics, list):
        for entry in diagnostics:
            if not isinstance(entry, dict):
                continue
            uri = normalize_provider_uri(entry.get("uri"))
            if active_uri and uri != active_uri:
                continue
            for item in entry.get("diagnostics", []):
                if isinstance(item, dict):
                    rows.append(
                        {
                            "uri": uri,
                            "message": str(item.get("message") or ""),
                            "severity": item.get("severity"),
                            "source": str(item.get("source") or ""),
                            "code": item.get("code"),
                        }
                    )
    return unique_json_items(sorted(rows, key=json_signature))


def provider_bundle_from_wizp(wizp_result: dict[str, Any]) -> dict[str, Any]:
    provider_payload = wizp_result.get("providerPayload") if isinstance(wizp_result.get("providerPayload"), dict) else {}
    active_document = wizp_result.get("activeDocument") if isinstance(wizp_result.get("activeDocument"), dict) else {}
    debug_state = wizp_result.get("debugState") if isinstance(wizp_result.get("debugState"), dict) else {}
    activation_errors = wizp_result.get("activationErrors") if isinstance(wizp_result.get("activationErrors"), dict) else {}
    error_entries = activation_errors.get("errors") if isinstance(activation_errors.get("errors"), list) else []
    return {
        "status": str(provider_payload.get("status") or "not-run"),
        "activeUri": str(active_document.get("uri") or ""),
        "provider": provider_payload.get("result") if isinstance(provider_payload.get("result"), dict) else {},
        "diagnostics": wizp_result.get("diagnostics"),
        "request": provider_payload.get("request", {}),
        "error": str(provider_payload.get("error") or ""),
        "providerCounts": debug_state.get("providerCounts", {}) if isinstance(debug_state.get("providerCounts"), dict) else {},
        "activationErrorNames": [
            str(item.get("name") or "")
            for item in error_entries
            if isinstance(item, dict) and str(item.get("name") or "")
        ],
    }


def provider_bundle_from_reference(reference_result: dict[str, Any]) -> dict[str, Any]:
    probe = reference_result.get("probeResult") if isinstance(reference_result.get("probeResult"), dict) else {}
    provider_payload = probe.get("providerPayload") if isinstance(probe.get("providerPayload"), dict) else {}
    return {
        "status": str(provider_payload.get("status") or "not-run"),
        "activeUri": str(probe.get("openedDocumentUri") or ""),
        "provider": provider_payload,
        "diagnostics": probe.get("diagnostics"),
        "request": provider_payload.get("request", {}),
        "error": str(provider_payload.get("error") or ""),
    }


def wizp_provider_point_available(bundle: dict[str, Any], point: str) -> bool:
    provider = bundle.get("provider") if isinstance(bundle.get("provider"), dict) else {}
    provider_resolution = provider.get("providerResolution") if isinstance(provider.get("providerResolution"), dict) else {}
    provider_counts = bundle.get("providerCounts") if isinstance(bundle.get("providerCounts"), dict) else {}
    if point == "diagnostics":
        return bool(provider_counts.get("diagnostics"))
    if point == "completion":
        return bool(provider_resolution.get("completion")) or provider.get("completion") is not None or bool(provider_counts.get("completions"))
    if point == "hover":
        return bool(provider_resolution.get("hover")) or provider.get("hover") is not None
    if point == "definition":
        return bool(provider_resolution.get("definition")) or provider.get("definition") is not None
    if point == "references":
        return bool(provider_resolution.get("references")) or provider.get("references") is not None
    if point == "rename":
        return bool(provider_resolution.get("rename")) or provider.get("prepareRename") is not None or provider.get("rename") is not None
    if point == "codeActions":
        return bool(provider_resolution.get("codeActions")) or provider.get("codeActions") is not None or bool(provider_counts.get("codeActions"))
    if point == "formatting":
        return (
            bool(provider_resolution.get("documentFormatting"))
            or bool(provider_resolution.get("rangeFormatting"))
            or provider.get("documentFormatting") is not None
            or provider.get("rangeFormatting") is not None
            or bool(provider_counts.get("documentFormatting"))
            or bool(provider_counts.get("rangeFormatting"))
        )
    if point == "symbols":
        return bool(provider_resolution.get("documentSymbols")) or provider.get("documentSymbols") is not None or bool(provider_counts.get("documentSymbols"))
    return False


def wizp_provider_runtime_blocker(bundle: dict[str, Any], point: str) -> str | None:
    activation_error_names = {str(item) for item in bundle.get("activationErrorNames", []) if isinstance(item, str)}
    if "ActivationHostTimeout" not in activation_error_names:
        return None
    if wizp_provider_point_available(bundle, point):
        return None
    return "activation-host-timeout-no-provider"


def organize_import_action(action: dict[str, Any]) -> bool:
    kind = str(action.get("kind") or "")
    title = str(action.get("title") or "").lower()
    return "organizeimports" in kind.replace(".", "").lower() or "organize import" in title


def snippet_completion(item: dict[str, Any]) -> bool:
    kind = item.get("kind")
    detail = str(item.get("detail") or "").lower()
    insert_text = str(item.get("insertText") or "")
    return kind in {15, 27} or "snippet" in detail or "\n" in insert_text


def normalized_provider_point(bundle: dict[str, Any], point: str) -> Any:
    provider = bundle.get("provider") if isinstance(bundle.get("provider"), dict) else {}
    if point == "diagnostics":
        return normalize_provider_diagnostics(bundle)
    if point == "completion":
        return normalize_provider_completion(provider.get("completion"))
    if point == "snippets":
        completion = normalize_provider_completion(provider.get("completion"))
        return {"items": [item for item in completion["items"] if snippet_completion(item)]}
    if point == "hover":
        return normalize_provider_hover(provider.get("hover"))
    if point == "definition":
        return normalize_provider_locations(provider.get("definition"))
    if point == "references":
        return normalize_provider_locations(provider.get("references"))
    if point == "rename":
        return {
            "prepareRename": normalize_prepare_rename(provider.get("prepareRename")),
            "rename": normalize_provider_workspace_edit(provider.get("rename")),
        }
    if point == "codeActions":
        return normalize_provider_code_actions(provider.get("codeActions"))
    if point == "formatting":
        applied_text = provider.get("documentFormattingAppliedText") or provider.get("rangeFormattingAppliedText")
        if applied_text is not None:
            return normalize_provider_text_edits({"appliedText": applied_text})
        return normalize_provider_text_edits(provider.get("documentFormatting") or provider.get("rangeFormatting"))
    if point == "symbols":
        return normalize_provider_symbols(provider.get("documentSymbols"))
    if point == "organizeImports":
        return [item for item in normalize_provider_code_actions(provider.get("codeActions")) if organize_import_action(item)]
    return None


def provider_point_cardinality(value: Any) -> int:
    if value is None:
        return 0
    if isinstance(value, list):
        return len(value)
    if isinstance(value, dict):
        if isinstance(value.get("items"), list):
            return len(value["items"])
        if isinstance(value.get("changes"), dict):
            return sum(len(item) for item in value["changes"].values() if isinstance(item, list))
        return len(value)
    return 1


def build_provider_normalized_diff(
    provider_points: list[str],
    wizp_bundle: dict[str, Any],
    reference_bundle: dict[str, Any],
) -> dict[str, Any]:
    wizp_captured = wizp_bundle.get("status") == "captured"
    reference_captured = reference_bundle.get("status") == "captured"
    point_results: list[dict[str, Any]] = []
    matched_points: list[str] = []
    drift_points: list[str] = []
    blocked_points: list[str] = []
    for point in provider_points:
        if not wizp_captured or not reference_captured:
            blocked_points.append(point)
            point_results.append(
                {
                    "point": point,
                    "status": "blocked-host-capture",
                    "wizpStatus": wizp_bundle.get("status"),
                    "referenceStatus": reference_bundle.get("status"),
                }
            )
            continue
        wizp_value = normalized_provider_point(wizp_bundle, point)
        reference_value = normalized_provider_point(reference_bundle, point)
        runtime_blocker = wizp_provider_runtime_blocker(wizp_bundle, point)
        if runtime_blocker and json_signature(wizp_value) != json_signature(reference_value):
            blocked_points.append(point)
            point_results.append(
                {
                    "point": point,
                    "status": "blocked-runtime-activation-timeout",
                    "blocker": runtime_blocker,
                    "wizpCount": provider_point_cardinality(wizp_value),
                    "referenceCount": provider_point_cardinality(reference_value),
                    "wizpValue": wizp_value,
                    "referenceValue": reference_value,
                }
            )
            continue
        point_status = "matched" if json_signature(wizp_value) == json_signature(reference_value) else "drift"
        if point_status == "matched":
            matched_points.append(point)
        else:
            drift_points.append(point)
        point_results.append(
            {
                "point": point,
                "status": point_status,
                "wizpCount": provider_point_cardinality(wizp_value),
                "referenceCount": provider_point_cardinality(reference_value),
                "wizpValue": wizp_value,
                "referenceValue": reference_value,
            }
        )
    return {
        "status": "paired-provider-diff-captured" if wizp_captured and reference_captured else "blocked-provider-host-capture",
        "unexpectedDrift": bool(drift_points or blocked_points),
        "comparablePointCount": len(provider_points) - len(blocked_points),
        "matchedPointCount": len(matched_points),
        "driftPointCount": len(drift_points),
        "blockedPointCount": len(blocked_points),
        "matchedPoints": matched_points,
        "driftPoints": drift_points,
        "blockedPoints": blocked_points,
        "pointResults": point_results,
    }


def completion_stability_config(scenario: dict[str, Any]) -> dict[str, int]:
    provider_probe = scenario.get("providerProbe") if isinstance(scenario.get("providerProbe"), dict) else {}
    configured_runs = provider_probe.get("completionStabilityRuns")
    min_prefix = provider_probe.get("completionStabilityMinPrefix")
    min_reference_labels = provider_probe.get("completionStabilityMinReferenceLabels")
    min_shared_labels = provider_probe.get("completionStabilityMinSharedLabels")
    min_shared_ratio = provider_probe.get("completionStabilityMinSharedRatio")
    return {
        "runs": max(1, int(configured_runs)) if isinstance(configured_runs, (int, float)) else 1,
        "minPrefix": max(1, int(min_prefix)) if isinstance(min_prefix, (int, float)) else 10,
        "minReferenceLabels": max(1, int(min_reference_labels)) if isinstance(min_reference_labels, (int, float)) else 25,
        "minSharedLabels": max(1, int(min_shared_labels)) if isinstance(min_shared_labels, (int, float)) else 25,
        "minSharedRatioPercent": max(1, int(round(float(min_shared_ratio) * 100))) if isinstance(min_shared_ratio, (int, float)) else 90,
    }


def build_completion_stability_audit(
    scenario: dict[str, Any],
    baseline: dict[str, Any],
    baseline_row: dict[str, Any],
    target: dict[str, Any],
    initial_wizp_result: dict[str, Any],
    initial_reference_result: dict[str, Any],
) -> dict[str, Any] | None:
    config = completion_stability_config(scenario)
    if config["runs"] <= 1:
        return None

    run_pairs: list[tuple[dict[str, Any], dict[str, Any]]] = [(initial_wizp_result, initial_reference_result)]
    for _ in range(1, config["runs"]):
        run_pairs.append(
            (
                run_wizp_scenario_probe(target, baseline, baseline_row, capture_provider_payload=True),
                run_reference_scenario_probe(target, baseline, baseline_row, capture_provider_payload=True),
            )
        )

    wizp_sequences: list[list[str]] = []
    reference_sequences: list[list[str]] = []
    wizp_sets: list[set[str]] = []
    reference_sets: list[set[str]] = []
    runs: list[dict[str, Any]] = []

    for run_index, (wizp_result, reference_result) in enumerate(run_pairs, start=1):
        wizp_bundle = provider_bundle_from_wizp(wizp_result) if isinstance(wizp_result, dict) else {"status": "not-run"}
        reference_bundle = provider_bundle_from_reference(reference_result) if isinstance(reference_result, dict) else {"status": "not-run"}
        wizp_summary = completion_stability_run_summary(wizp_bundle)
        reference_summary = completion_stability_run_summary(reference_bundle)
        wizp_sequences.append(wizp_summary["labels"])
        reference_sequences.append(reference_summary["labels"])
        wizp_sets.append(set(wizp_summary["labelSet"]))
        reference_sets.append(set(reference_summary["labelSet"]))
        shared_labels = sorted(wizp_summary["labelSet"] & reference_summary["labelSet"])
        wizp_only_labels = sorted(wizp_summary["labelSet"] - reference_summary["labelSet"])
        reference_only_labels = sorted(reference_summary["labelSet"] - wizp_summary["labelSet"])
        runs.append(
            {
                "runIndex": run_index,
                "wizp": {
                    "status": wizp_summary["status"],
                    "isIncomplete": wizp_summary["isIncomplete"],
                    "count": wizp_summary["count"],
                    "labelsHead": wizp_summary["labels"][:20],
                },
                "reference": {
                    "status": reference_summary["status"],
                    "isIncomplete": reference_summary["isIncomplete"],
                    "count": reference_summary["count"],
                    "labelsHead": reference_summary["labels"][:20],
                },
                "sharedLabelCount": len(shared_labels),
                "wizpOnlyLabels": wizp_only_labels[:20],
                "referenceOnlyLabels": reference_only_labels[:20],
            }
        )

    wizp_stable_prefix = stable_completion_prefix(wizp_sequences)
    reference_stable_prefix = stable_completion_prefix(reference_sequences)
    wizp_stable_labels = stable_completion_label_set(wizp_sets)
    reference_stable_labels = stable_completion_label_set(reference_sets)
    wizp_union_labels = set().union(*wizp_sets) if wizp_sets else set()
    reference_union_labels = set().union(*reference_sets) if reference_sets else set()
    shared_stable_labels = sorted(wizp_stable_labels & reference_stable_labels)
    missing_reference_stable = sorted(reference_stable_labels - wizp_stable_labels)
    wizp_stable_outside_reference_union = sorted(wizp_stable_labels - reference_union_labels)
    shared_stable_ratio_percent = (
        int(round((len(shared_stable_labels) / len(reference_stable_labels)) * 100))
        if reference_stable_labels
        else 0
    )
    all_captured = all(
        run["wizp"]["status"] == "captured" and run["reference"]["status"] == "captured"
        for run in runs
    )
    all_incomplete = all(run["wizp"]["isIncomplete"] and run["reference"]["isIncomplete"] for run in runs)
    stable_prefix_match = wizp_stable_prefix == reference_stable_prefix
    status = (
        "matched-stable-core"
        if all_captured
        and all_incomplete
        and stable_prefix_match
        and len(reference_stable_labels) >= config["minReferenceLabels"]
        and len(reference_stable_prefix) >= config["minPrefix"]
        and len(shared_stable_labels) >= config["minSharedLabels"]
        and shared_stable_ratio_percent >= config["minSharedRatioPercent"]
        and not wizp_stable_outside_reference_union
        else ("blocked-host-capture" if not all_captured else "drift-unstable-core")
    )

    return {
        "status": status,
        "configuredRuns": config["runs"],
        "minStablePrefix": config["minPrefix"],
        "minStableReferenceLabels": config["minReferenceLabels"],
        "minSharedStableLabels": config["minSharedLabels"],
        "minSharedStableRatioPercent": config["minSharedRatioPercent"],
        "runs": runs,
        "checks": {
            "allCaptured": all_captured,
            "allIncomplete": all_incomplete,
            "stablePrefixMatch": stable_prefix_match,
            "stablePrefixThresholdMet": len(reference_stable_prefix) >= config["minPrefix"],
            "stableReferenceLabelThresholdMet": len(reference_stable_labels) >= config["minReferenceLabels"],
            "sharedStableLabelThresholdMet": len(shared_stable_labels) >= config["minSharedLabels"],
            "sharedStableRatioThresholdMet": shared_stable_ratio_percent >= config["minSharedRatioPercent"],
            "sharedStableRatioPercent": shared_stable_ratio_percent,
            "missingReferenceStableLabels": missing_reference_stable,
            "wizpStableOutsideReferenceObserved": wizp_stable_outside_reference_union,
        },
        "wizpStablePrefix": wizp_stable_prefix,
        "referenceStablePrefix": reference_stable_prefix,
        "wizpStableLabelCount": len(wizp_stable_labels),
        "referenceStableLabelCount": len(reference_stable_labels),
        "sharedStableLabelCount": len(shared_stable_labels),
        "sharedStableLabels": shared_stable_labels,
        "wizpStableOnlyLabels": sorted(wizp_stable_labels - reference_stable_labels)[:20],
        "referenceStableOnlyLabels": sorted(reference_stable_labels - wizp_stable_labels)[:20],
        "wizpObservedUnionCount": len(wizp_union_labels),
        "referenceObservedUnionCount": len(reference_union_labels),
    }


def apply_completion_stability_audit(normalized_diff: dict[str, Any], audit: dict[str, Any] | None) -> dict[str, Any]:
    if not isinstance(audit, dict) or str(audit.get("status") or "") != "matched-stable-core":
        return normalized_diff
    result = copy.deepcopy(normalized_diff)
    drift_points = [str(item) for item in result.get("driftPoints", []) if isinstance(item, str)]
    matched_points = [str(item) for item in result.get("matchedPoints", []) if isinstance(item, str)]
    blocked_points = [str(item) for item in result.get("blockedPoints", []) if isinstance(item, str)]
    if "completion" in drift_points:
        drift_points = [item for item in drift_points if item != "completion"]
    if "completion" not in matched_points:
        matched_points.append("completion")
    point_results = result.get("pointResults") if isinstance(result.get("pointResults"), list) else []
    for point_result in point_results:
        if not isinstance(point_result, dict) or point_result.get("point") != "completion":
            continue
        point_result["rawStatus"] = point_result.get("status")
        point_result["status"] = "matched-incomplete-stable-core"
        point_result["stabilityAudit"] = {
            "status": audit.get("status"),
            "sharedStableLabelCount": audit.get("sharedStableLabelCount"),
            "referenceStableLabelCount": audit.get("referenceStableLabelCount"),
            "wizpStableLabelCount": audit.get("wizpStableLabelCount"),
            "stablePrefixLength": len(audit.get("referenceStablePrefix", [])) if isinstance(audit.get("referenceStablePrefix"), list) else 0,
        }
        break
    result["matchedPoints"] = matched_points
    result["driftPoints"] = drift_points
    result["blockedPoints"] = blocked_points
    result["matchedPointCount"] = len(matched_points)
    result["driftPointCount"] = len(drift_points)
    result["blockedPointCount"] = len(blocked_points)
    result["comparablePointCount"] = len(matched_points) + len(drift_points)
    result["unexpectedDrift"] = bool(drift_points or blocked_points)
    return result


def run_provider_probe_artifact(
    manifest: dict[str, Any],
    scenario: dict[str, Any],
    baseline: dict[str, Any],
    generated_at: str,
    *,
    reuse_cached_reference: bool = False,
) -> dict[str, Any]:
    extension_id = str(manifest["extensionId"])
    scenario_id = str(scenario["id"])
    baseline_row = baseline_extension(baseline, extension_id)
    target = build_provider_probe_target(manifest, scenario, baseline_row)
    provider_points = [str(item) for item in target.get("providerProbePoints", []) if isinstance(item, str)]
    blockers: list[str] = []
    if not baseline_row:
        blockers.append("target-extension-missing-from-baseline")
    if blockers:
        wizp_result = {"status": "not-run", "reason": ", ".join(blockers)}
        reference_result = {"status": "not-run", "reason": ", ".join(blockers)}
        reference_reuse: dict[str, Any] | None = None
    else:
        wizp_result = run_wizp_scenario_probe(target, baseline, baseline_row, capture_provider_payload=True)
        cached_reference_result, cached_reference_artifact = (None, None)
        if reuse_cached_reference:
            cached_reference_result, cached_reference_artifact = load_cached_provider_reference_result(extension_id, scenario_id, target, baseline)
        if cached_reference_result is not None:
            reference_result = cached_reference_result
            reference_reuse = {
                "status": "reused-cached-reference-provider-probe",
                "artifact": cached_reference_artifact,
            }
        else:
            reference_result = run_reference_scenario_probe(target, baseline, baseline_row, capture_provider_payload=True)
            reference_reuse = None
    wizp_bundle = provider_bundle_from_wizp(wizp_result) if isinstance(wizp_result, dict) else {"status": "not-run"}
    reference_bundle = provider_bundle_from_reference(reference_result) if isinstance(reference_result, dict) else {"status": "not-run"}
    normalized_diff = build_provider_normalized_diff(provider_points, wizp_bundle, reference_bundle)
    completion_stability_audit = build_completion_stability_audit(
        scenario,
        baseline,
        baseline_row,
        target,
        wizp_result,
        reference_result,
    )
    normalized_diff = apply_completion_stability_audit(normalized_diff, completion_stability_audit)
    wizp_ok = wizp_bundle.get("status") == "captured"
    reference_ok = reference_bundle.get("status") == "captured"
    if wizp_ok and reference_ok:
        status = "paired-provider-payload-verified" if not normalized_diff.get("unexpectedDrift") else "paired-provider-payload-captured"
    elif wizp_ok:
        status = "partial-wizp-provider-payload-captured-reference-blocked"
    else:
        status = "blocked-provider-probe"
    artifact = {
        "schema": "wizp.top20-behavior-provider-probe.v1",
        "generatedAt": generated_at,
        "extensionId": extension_id,
        "scenarioId": scenario_id,
        "backlogIds": scenario.get("backlogIds", []),
        "title": scenario.get("title", ""),
        "fixture": scenario.get("fixture", ""),
        "fixtureHash": fixture_hash_for_scenario(baseline, extension_id, scenario_id),
        "scenarioCacheKey": scenario_cache_key(target),
        "scenarioCacheContract": scenario_cache_contract(target),
        "providerProbePoints": provider_points,
        "status": status,
        "referenceHost": baseline.get("referenceHost", {}),
        "target": {
            "fixtureFile": target.get("fixtureFile"),
            "languageId": target.get("languageId"),
            "activationEvents": target.get("activationEvents", []),
            "probe": target.get("providerProbe", {}),
        },
        "wizp": wizp_result,
        "reference": reference_result,
        "normalizedDiff": normalized_diff,
    }
    if completion_stability_audit:
        artifact["completionStabilityAudit"] = completion_stability_audit
    if reference_reuse:
        artifact["referenceReuse"] = reference_reuse
    return artifact


def provider_payload_scenario_evidence(
    scenario: dict[str, Any],
    provider_artifact: dict[str, Any],
) -> tuple[dict[str, Any], list[str], list[str], dict[str, Any]]:
    expected = [str(item) for item in scenario.get("expectedEvidence", []) if isinstance(item, str)]
    provider_points = [item for item in expected if item in PROVIDER_EVIDENCE_KEYS]
    residual_expected = [item for item in expected if item not in PROVIDER_EVIDENCE_KEYS]
    normalized = provider_artifact.get("normalizedDiff") if isinstance(provider_artifact.get("normalizedDiff"), dict) else {}
    matched_points = {str(item) for item in normalized.get("matchedPoints", []) if isinstance(item, str)}
    drift_points = {str(item) for item in normalized.get("driftPoints", []) if isinstance(item, str)}
    blocked_points = {str(item) for item in normalized.get("blockedPoints", []) if isinstance(item, str)}
    point_results = normalized.get("pointResults") if isinstance(normalized.get("pointResults"), list) else []
    point_results_by_name = {
        str(item.get("point")): item
        for item in point_results
        if isinstance(item, dict) and item.get("point")
    }
    evidence: dict[str, Any] = {}
    pending: list[str] = []
    for point in provider_points:
        point_result = point_results_by_name.get(point, {})
        if point in matched_points:
            evidence[point] = {
                "status": "matched-provider-payload",
                "artifact": rel(provider_probe_artifact_path(str(provider_artifact.get("extensionId") or ""), str(provider_artifact.get("scenarioId") or ""))),
                "wizpCount": point_result.get("wizpCount"),
                "referenceCount": point_result.get("referenceCount"),
            }
        elif point in drift_points:
            pending.append(point)
            evidence[point] = {
                "status": "provider-payload-drift",
                "artifact": rel(provider_probe_artifact_path(str(provider_artifact.get("extensionId") or ""), str(provider_artifact.get("scenarioId") or ""))),
                "wizpCount": point_result.get("wizpCount"),
                "referenceCount": point_result.get("referenceCount"),
            }
        elif point in blocked_points:
            pending.append(point)
            evidence[point] = {
                "status": "provider-payload-blocked",
                "artifact": rel(provider_probe_artifact_path(str(provider_artifact.get("extensionId") or ""), str(provider_artifact.get("scenarioId") or ""))),
                "wizpCount": point_result.get("wizpCount"),
                "referenceCount": point_result.get("referenceCount"),
            }
        else:
            pending.append(point)
            evidence[point] = {
                "status": "provider-payload-missing",
                "artifact": rel(provider_probe_artifact_path(str(provider_artifact.get("extensionId") or ""), str(provider_artifact.get("scenarioId") or ""))),
            }
    pending.extend(residual_expected)
    summary = {
        "providerProbePoints": provider_points,
        "matchedProviderPoints": sorted(matched_points & set(provider_points)),
        "driftProviderPoints": sorted(drift_points & set(provider_points)),
        "blockedProviderPoints": sorted(blocked_points & set(provider_points)),
        "residualExpectedEvidence": residual_expected,
        "providerPayloadMatched": bool(provider_points) and not any(point in pending for point in provider_points),
    }
    return evidence, pending, residual_expected, summary


