def runtime_network_audit_count(runtime_processes: dict[str, Any]) -> int:
    if not isinstance(runtime_processes, dict):
        return 0
    value = runtime_processes.get("networkAuditCount")
    if isinstance(value, (int, float)):
        return int(value)
    rows = runtime_processes.get("networkAudit")
    return len(rows) if isinstance(rows, list) else 0


def normalize_container_language_server_processes(
    runtime_processes: dict[str, Any],
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    rows: list[dict[str, Any]] = []
    for key in ["spawnedProcesses", "forkedProcesses"]:
        values = runtime_processes.get(key) if isinstance(runtime_processes.get(key), list) else []
        rows.extend(item for item in values if isinstance(item, dict))
    kept: list[dict[str, Any]] = []
    dropped: list[dict[str, Any]] = []
    for item in rows:
        command_raw = str(item.get("modulePath") or item.get("file") or item.get("command") or "")
        if not command_raw:
            continue
        args = [str(arg) for arg in item.get("args", [])] if isinstance(item.get("args"), list) else []
        normalized_args = [
            "--clientProcessId=<pid>" if arg.startswith("--clientProcessId=") else arg
            for arg in args
        ]
        if Path(command_raw).name == "git" and normalized_args == ["rev-parse", "--show-toplevel"]:
            dropped.append({"command": "git", "args": normalized_args})
            continue
        command = Path(command_raw).name or command_raw
        for marker in [
            "dockerfile-language-server-nodejs/lib/server.js",
            "compose-language-service/lib/server.js",
        ]:
            if marker in command_raw:
                command = marker
                break
        kept.append({"command": command, "args": normalized_args})
    return unique_json_items(sorted(kept, key=json_signature)), unique_json_items(sorted(dropped, key=json_signature))


def normalized_output_events(rows: list[Any], *, require_output_type: bool) -> list[dict[str, Any]]:
    events: list[dict[str, Any]] = []
    for item in rows:
        if not isinstance(item, dict):
            continue
        event_type = str(item.get("type") or "")
        if require_output_type and not event_type.startswith("output"):
            continue
        channel = str(item.get("channel") or "")
        text = str(item.get("text") or "")
        action = str(item.get("action") or "")
        if not channel and not text:
            continue
        events.append({"channel": channel, "action": action, "text": text})
    return unique_json_items(events)


def wizp_startup_output_events(artifact: dict[str, Any]) -> list[dict[str, Any]]:
    wizp_result = artifact.get("wizpResult") if isinstance(artifact.get("wizpResult"), dict) else {}
    events = wizp_result.get("startupUiEvents") if isinstance(wizp_result.get("startupUiEvents"), list) else []
    return normalized_output_events(events, require_output_type=True)


def reference_startup_output_events(artifact: dict[str, Any]) -> list[dict[str, Any]]:
    reference_result = artifact.get("referenceResult") if isinstance(artifact.get("referenceResult"), dict) else {}
    probe_result = reference_result.get("probeResult") if isinstance(reference_result.get("probeResult"), dict) else {}
    startup = probe_result.get("startupSideEffects") if isinstance(probe_result.get("startupSideEffects"), dict) else {}
    outputs = startup.get("outputs") if isinstance(startup.get("outputs"), list) else []
    return normalized_output_events(outputs, require_output_type=False)


def output_events_for_channels(events: list[dict[str, Any]], channels: set[str]) -> list[dict[str, Any]]:
    return [event for event in events if str(event.get("channel") or "") in channels]


def output_events_contain(events: list[dict[str, Any]], marker: str) -> bool:
    return any(marker in str(event.get("text") or "") for event in events)


def output_event_channels(events: list[dict[str, Any]]) -> list[str]:
    return sorted({str(event.get("channel") or "") for event in events if str(event.get("channel") or "")})


def wizp_configuration_reads(artifact: dict[str, Any]) -> list[dict[str, Any]]:
    wizp_result = artifact.get("wizpResult") if isinstance(artifact.get("wizpResult"), dict) else {}
    read_sources: list[Any] = []
    debug_state = wizp_result.get("debugState") if isinstance(wizp_result.get("debugState"), dict) else {}
    read_sources.extend(debug_state.get("configurationReads") if isinstance(debug_state.get("configurationReads"), list) else [])
    secondary = wizp_result.get("providerProbeSecondaryRpc") if isinstance(wizp_result.get("providerProbeSecondaryRpc"), dict) else {}
    secondary_debug = secondary.get("debugState") if isinstance(secondary.get("debugState"), dict) else {}
    secondary_result = secondary_debug.get("result") if isinstance(secondary_debug.get("result"), dict) else {}
    read_sources.extend(secondary_result.get("configurationReads") if isinstance(secondary_result.get("configurationReads"), list) else [])
    rows: list[dict[str, Any]] = []
    for item in read_sources:
        if not isinstance(item, dict):
            continue
        key = str(item.get("key") or "")
        if not key:
            continue
        rows.append(
            {
                "key": key,
                "kind": str(item.get("kind") or ""),
                "value": item.get("value"),
            }
        )
    return unique_json_items(rows)


def reference_configuration_reads(artifact: dict[str, Any]) -> list[dict[str, Any]]:
    reference_result = artifact.get("referenceResult") if isinstance(artifact.get("referenceResult"), dict) else {}
    probe_result = reference_result.get("probeResult") if isinstance(reference_result.get("probeResult"), dict) else {}
    survey = probe_result.get("survey") if isinstance(probe_result.get("survey"), dict) else {}
    read_sources = survey.get("configurationReads") if isinstance(survey.get("configurationReads"), list) else []
    rows: list[dict[str, Any]] = []
    for item in read_sources:
        if not isinstance(item, dict):
            continue
        key = str(item.get("key") or "")
        if not key:
            continue
        rows.append(
            {
                "key": key,
                "kind": str(item.get("kind") or ""),
                "value": item.get("value"),
            }
        )
    return unique_json_items(rows)


def normalized_debug_configuration_providers(value: Any) -> list[dict[str, Any]]:
    rows = value if isinstance(value, list) else []
    providers: list[dict[str, Any]] = []
    for item in rows:
        if not isinstance(item, dict):
            continue
        provider_type = str(item.get("type") or "")
        if not provider_type:
            continue
        provider: dict[str, Any] = {"type": provider_type}
        if "triggerKind" in item:
            provider["triggerKind"] = item.get("triggerKind")
        providers.append(provider)
    return unique_json_items(sorted(providers, key=json_signature))


def wizp_debug_configuration_providers(artifact: dict[str, Any]) -> list[dict[str, Any]]:
    wizp_result = artifact.get("wizpResult") if isinstance(artifact.get("wizpResult"), dict) else {}
    debug_state = wizp_result.get("debugState") if isinstance(wizp_result.get("debugState"), dict) else {}
    registrations = debug_state.get("providerRegistrations") if isinstance(debug_state.get("providerRegistrations"), dict) else {}
    return normalized_debug_configuration_providers(registrations.get("debugConfigurationProviders"))


def reference_debug_configuration_providers(artifact: dict[str, Any]) -> list[dict[str, Any]]:
    reference_result = artifact.get("referenceResult") if isinstance(artifact.get("referenceResult"), dict) else {}
    probe_result = reference_result.get("probeResult") if isinstance(reference_result.get("probeResult"), dict) else {}
    survey = probe_result.get("survey") if isinstance(probe_result.get("survey"), dict) else {}
    registrations = survey.get("debugTaskRegistrations") if isinstance(survey.get("debugTaskRegistrations"), dict) else {}
    return normalized_debug_configuration_providers(registrations.get("debugConfigurationProviders"))


def container_debug_metadata_evidence(artifact: dict[str, Any], baseline: dict[str, Any]) -> dict[str, Any]:
    baseline_row = baseline_extension(baseline, "ms-azuretools.vscode-containers")
    package_json = read_vsix_package_json((baseline_row.get("vsix") or {}) if isinstance(baseline_row.get("vsix"), dict) else {})
    manifest_summary = manifest_debug_task_summary(package_json)
    manifest_debuggers = (
        (package_json.get("contributes") or {}).get("debuggers")
        if isinstance(package_json.get("contributes"), dict)
        else []
    )
    if not isinstance(manifest_debuggers, list):
        manifest_debuggers = []
    debugger_schema_payloads = manifest_debugger_schema_payloads(manifest_debuggers)
    expected_provider_types = ["*", "docker"]
    wizp_providers = wizp_debug_configuration_providers(artifact)
    reference_providers = reference_debug_configuration_providers(artifact)
    wizp_types = sorted({str(item.get("type") or "") for item in wizp_providers if str(item.get("type") or "")})
    reference_types = sorted({str(item.get("type") or "") for item in reference_providers if str(item.get("type") or "")})
    manifest_debugger_types = [
        str(item)
        for item in manifest_summary.get("debuggerTypes", [])
        if isinstance(item, str)
    ]
    metadata_ok = (
        all(item in wizp_types for item in expected_provider_types)
        and all(item in reference_types for item in expected_provider_types)
        and "docker" in manifest_debugger_types
        and bool(debugger_schema_payloads)
    )
    return {
        "status": "matched-containers-debug-metadata" if metadata_ok else "containers-debug-metadata-incomplete",
        "expectedDebugConfigurationProviderTypes": expected_provider_types,
        "wizpDebugConfigurationProviders": wizp_providers,
        "referenceDebugConfigurationProviders": reference_providers,
        "manifestDebugTaskSummary": manifest_summary,
        "manifestDebuggerSchemas": debugger_schema_payloads,
        "note": "Promotes only the paired debug configuration provider and pinned debugger schema metadata for the Containers language scenario; Docker image/container runtime behavior remains owned by T20V-033.",
    }


def provider_residual_runtime_audit_evidence(
    extension_id: str,
    scenario_id: str,
    runtime_audit: dict[str, Any],
) -> tuple[dict[str, Any], list[str]]:
    wizp_runtime = runtime_audit.get("wizp", {}).get("runtimeProcesses", {}) if isinstance(runtime_audit.get("wizp"), dict) else {}
    reference_runtime = runtime_audit.get("reference", {}).get("runtimeProcesses", {}) if isinstance(runtime_audit.get("reference"), dict) else {}
    wizp_spawned, wizp_dropped = normalize_runtime_spawn_processes(wizp_runtime, drop_workspace_git_probe=True)
    reference_spawned, reference_dropped = normalize_runtime_spawn_processes(reference_runtime, drop_workspace_git_probe=True)
    network_ok = runtime_network_audit_count(wizp_runtime) == 0 and runtime_network_audit_count(reference_runtime) == 0
    runtime_artifact = rel(runtime_audit_path(extension_id, scenario_id))
    evidence: dict[str, Any] = {}
    accepted_differences: list[str] = []

    if reference_dropped:
        accepted_differences.append(
            "Reference-only `git rev-parse --show-toplevel` probes come from MrCode's built-in Git extension and are excluded from extension-owned language-helper comparison."
        )

    if extension_id == "golang.Go" and scenario_id == "go-gopls-language":
        process_ok = not wizp_spawned and not reference_spawned and network_ok
        evidence["processAudit"] = {
            "status": "matched-no-owned-language-helper-processes" if process_ok else "language-helper-process-audit-drift",
            "wizpOwnedSpawnedProcesses": wizp_spawned,
            "referenceOwnedSpawnedProcesses": reference_spawned,
            "wizpDroppedBackgroundProcesses": wizp_dropped,
            "referenceDroppedBackgroundProcesses": reference_dropped,
            "wizpNetworkAuditCount": runtime_network_audit_count(wizp_runtime),
            "referenceNetworkAuditCount": runtime_network_audit_count(reference_runtime),
            "runtimeAuditArtifact": runtime_artifact,
            "note": "The current Go fixture does not stage a fixture gopls binary; this proves the provider-payload scenario has no WIZP-owned or reference-owned language-helper process drift, not a real external gopls launch.",
        }
    elif extension_id == "meta.pyrefly" and scenario_id == "pyrefly-valid-language":
        expected = [{"command": "pyrefly", "args": ["lsp"]}]
        process_ok = wizp_spawned == expected and reference_spawned == expected and network_ok
        evidence["processAudit"] = {
            "status": "matched-pyrefly-lsp-helper-spawn" if process_ok else "pyrefly-lsp-helper-spawn-drift",
            "wizpOwnedSpawnedProcesses": wizp_spawned,
            "referenceOwnedSpawnedProcesses": reference_spawned,
            "wizpDroppedBackgroundProcesses": wizp_dropped,
            "referenceDroppedBackgroundProcesses": reference_dropped,
            "wizpNetworkAuditCount": runtime_network_audit_count(wizp_runtime),
            "referenceNetworkAuditCount": runtime_network_audit_count(reference_runtime),
            "runtimeAuditArtifact": runtime_artifact,
        }
    elif extension_id == "ms-azuretools.vscode-containers" and scenario_id == "containers-language-features":
        expected = [
            {
                "args": ["--node-ipc", "--node-ipc", "--clientProcessId=<pid>"],
                "command": "compose-language-service/lib/server.js",
            },
            {
                "args": ["--node-ipc", "--node-ipc", "--clientProcessId=<pid>"],
                "command": "dockerfile-language-server-nodejs/lib/server.js",
            },
        ]
        wizp_servers, wizp_server_dropped = normalize_container_language_server_processes(wizp_runtime)
        reference_servers, reference_server_dropped = normalize_container_language_server_processes(reference_runtime)
        process_ok = wizp_servers == expected and reference_servers == expected and network_ok
        evidence["languageServerProcesses"] = {
            "status": "matched-containers-language-server-processes" if process_ok else "containers-language-server-process-drift",
            "wizpLanguageServerProcesses": wizp_servers,
            "referenceLanguageServerProcesses": reference_servers,
            "wizpDroppedBackgroundProcesses": wizp_server_dropped,
            "referenceDroppedBackgroundProcesses": reference_server_dropped,
            "wizpNetworkAuditCount": runtime_network_audit_count(wizp_runtime),
            "referenceNetworkAuditCount": runtime_network_audit_count(reference_runtime),
            "runtimeAuditArtifact": runtime_artifact,
        }

    return evidence, accepted_differences


def provider_residual_surface_evidence(
    extension_id: str,
    scenario_id: str,
    artifact: dict[str, Any],
    baseline: dict[str, Any],
) -> dict[str, Any]:
    evidence: dict[str, Any] = {}
    wizp_outputs = wizp_startup_output_events(artifact)
    reference_outputs = reference_startup_output_events(artifact)

    if extension_id == "meta.pyrefly" and scenario_id == "pyrefly-valid-language":
        channels = {"Pyrefly language server"}
        wizp_channel_outputs = output_events_for_channels(wizp_outputs, channels)
        reference_channel_outputs = output_events_for_channels(reference_outputs, channels)
        output_ok = (
            bool(wizp_channel_outputs)
            and bool(reference_channel_outputs)
            and output_events_contain(wizp_channel_outputs, "couldn't create connection to server")
            and output_events_contain(reference_channel_outputs, "couldn't create connection to server")
        )
        evidence["outputChannel"] = {
            "status": "matched-pyrefly-output-channel-surface" if output_ok else "pyrefly-output-channel-incomplete",
            "wizpChannels": output_event_channels(wizp_channel_outputs),
            "referenceChannels": output_event_channels(reference_channel_outputs),
            "wizpOutputTail": wizp_channel_outputs[-6:],
            "referenceOutputTail": reference_channel_outputs[-6:],
        }
    elif extension_id == "devsense.phptools-vscode" and scenario_id == "phptools-valid-language":
        channels = {"PHP", "PHP Language Server", "IntelliPHP Language Server"}
        wizp_channel_outputs = output_events_for_channels(wizp_outputs, channels)
        reference_channel_outputs = output_events_for_channels(reference_outputs, channels)
        startup_ok = output_events_contain(wizp_channel_outputs, "PHP extension started") and output_events_contain(reference_channel_outputs, "PHP extension started")
        php_version_ok = output_events_contain(wizp_channel_outputs, "Found PHP, version: 8.2.0") and output_events_contain(reference_channel_outputs, "Found PHP, version: 8.2.0")
        server_surface_ok = any("Language Server" in str(event.get("channel") or "") for event in wizp_channel_outputs) and any(
            "Language Server" in str(event.get("channel") or "") for event in reference_channel_outputs
        )
        output_ok = startup_ok and php_version_ok and server_surface_ok
        baseline_row = baseline_extension(baseline, extension_id)
        package_json = read_vsix_package_json((baseline_row.get("vsix") or {}) if isinstance(baseline_row.get("vsix"), dict) else {})
        manifest_config_keys = sorted(manifest_configuration_properties(package_json).keys()) if package_json else []
        paired_include_keys = {
            key
            for key in manifest_config_keys
            if key == "php.workspace.includePath"
        } or {"php.workspace.includePath"}
        wizp_compatibility_alias_keys = {"intelephense.environment.includePaths"}
        include_keys = paired_include_keys | wizp_compatibility_alias_keys
        wizp_config_reads = wizp_configuration_reads(artifact)
        reference_config_reads = reference_configuration_reads(artifact)
        wizp_include_reads = [row for row in wizp_config_reads if str(row.get("key") or "") in include_keys]
        reference_include_reads = [row for row in reference_config_reads if str(row.get("key") or "") in paired_include_keys]
        wizp_captured_keys = sorted({str(row.get("key") or "") for row in wizp_include_reads})
        reference_captured_keys = sorted({str(row.get("key") or "") for row in reference_include_reads})
        wizp_alias_captured_keys = sorted(key for key in wizp_compatibility_alias_keys if key in wizp_captured_keys)
        include_config_ok = all(key in wizp_captured_keys for key in paired_include_keys) and all(
            key in reference_captured_keys for key in paired_include_keys
        )
        evidence["outputLogs"] = {
            "status": "matched-php-output-log-surface" if output_ok else "php-output-log-surface-incomplete",
            "wizpChannels": output_event_channels(wizp_channel_outputs),
            "referenceChannels": output_event_channels(reference_channel_outputs),
            "wizpOutputTail": wizp_channel_outputs[-8:],
            "referenceOutputTail": reference_channel_outputs[-8:],
        }
        evidence["includePathConfig"] = {
            "status": "matched-php-include-path-config-reads" if include_config_ok else "php-include-path-config-reads-incomplete",
            "manifestIncludePathConfigKeys": sorted(key for key in manifest_config_keys if "include" in key.lower()),
            "requiredPairedKeys": sorted(paired_include_keys),
            "wizpCompatibilityAliasKeys": sorted(wizp_compatibility_alias_keys),
            "wizpCompatibilityAliasCapturedKeys": wizp_alias_captured_keys,
            "wizpCapturedKeys": wizp_captured_keys,
            "referenceCapturedKeys": reference_captured_keys,
            "wizpConfigurationReads": wizp_include_reads,
            "referenceConfigurationReads": reference_include_reads,
            "note": "Promotes paired WIZP/reference capture of the PHP Tools contributed include-path setting; WIZP's Intelephense include-path alias is recorded as extra compatibility coverage, not a reference requirement.",
        }
    elif extension_id == "ms-azuretools.vscode-containers" and scenario_id == "containers-language-features":
        evidence["debugMetadata"] = container_debug_metadata_evidence(artifact, baseline)

    return evidence


def run_provider_payload_validated_scenario(
    manifest: dict[str, Any],
    scenario: dict[str, Any],
    baseline: dict[str, Any],
    generated_at: str,
    *,
    reuse_cached_reference: bool = False,
) -> dict[str, Any]:
    artifact = run_generic_paired_scenario(
        manifest,
        scenario,
        baseline,
        generated_at,
        reuse_cached_reference=reuse_cached_reference,
    )
    provider_artifact = run_provider_probe_artifact(
        manifest,
        scenario,
        baseline,
        generated_at,
        reuse_cached_reference=reuse_cached_reference,
    )
    provider_artifact_path = provider_probe_artifact_path(str(manifest["extensionId"]), str(scenario["id"]))
    provider_artifact_path.parent.mkdir(parents=True, exist_ok=True)
    write_json(provider_artifact_path, provider_artifact)
    evidence, pending_expected_evidence, residual_expected, summary = provider_payload_scenario_evidence(scenario, provider_artifact)
    extension_id = str(manifest["extensionId"])
    scenario_id = str(scenario["id"])
    runtime_meta: dict[str, Any] = {}
    runtime_accepted_differences: list[str] = []
    if provider_residual_runtime_audit_scenario(extension_id, scenario_id):
        runtime_meta = write_runtime_audit_artifact(extension_id, scenario, baseline, artifact, generated_at)
        runtime_audit = load_json_if_exists(REPO_ROOT / str(runtime_meta.get("artifact") or "")) if runtime_meta.get("artifact") else {}
        runtime_evidence, runtime_accepted_differences = provider_residual_runtime_audit_evidence(
            extension_id,
            scenario_id,
            runtime_audit,
        )
        evidence.update(runtime_evidence)
    if provider_residual_surface_scenario(extension_id, scenario_id):
        evidence.update(provider_residual_surface_evidence(extension_id, scenario_id, artifact, baseline))
    pending_expected_evidence = [
        item
        for item in pending_expected_evidence
        if not str((evidence.get(item) or {}).get("status") or "").startswith("matched-")
    ]
    blockers = scenario_blocker_tokens(artifact)
    if not summary["providerPayloadMatched"]:
        blockers.append(str(provider_artifact.get("status") or "provider-payload-incomplete"))
    if runtime_meta and runtime_meta.get("status") != "captured":
        blockers.append(str(runtime_meta.get("status") or "provider-runtime-audit-incomplete"))
    if not blockers and not pending_expected_evidence:
        artifact["status"] = "paired-provider-payload-scenario-verified"
        normalized_status = "paired-scenario-evidence-matched"
    elif any(str((entry or {}).get("status") or "").startswith("matched-") for entry in evidence.values() if isinstance(entry, dict)):
        artifact["status"] = "paired-provider-payload-scenario-partial"
        normalized_status = "paired-scenario-evidence-partial"
    else:
        normalized_status = artifact.get("normalizedDiff", {}).get("status", "not-run")
    artifact["providerEvidence"] = {
        "artifact": rel(provider_artifact_path),
        "status": provider_artifact.get("status", ""),
        "normalizedDiff": provider_artifact.get("normalizedDiff", {}),
        "summary": summary,
    }
    if runtime_meta:
        artifact["runtimeAudit"] = {
            "artifact": runtime_meta.get("artifact", ""),
            "status": runtime_meta.get("status", ""),
        }
    artifact["blockers"] = sorted(set(str(item) for item in blockers if str(item)))
    artifact["evidence"] = evidence
    artifact["pendingExpectedEvidence"] = pending_expected_evidence
    normalized = artifact.get("normalizedDiff") if isinstance(artifact.get("normalizedDiff"), dict) else {}
    normalized["status"] = normalized_status
    normalized["acceptedDifferences"] = unique_json_items([*normalized.get("acceptedDifferences", []), *runtime_accepted_differences])
    normalized["notes"] = (
        "Scenario-specific provider-payload verifier promotes when the focused paired provider probe matches every expected provider point. "
        "Selected language-provider scenarios may also promote residual process-audit evidence when the paired runtime audit proves bounded owned-helper behavior. "
        "Rows with unmatched residual output, debug metadata, or language-server evidence stay partial."
    )
    if residual_expected:
        normalized["residualExpectedEvidence"] = residual_expected
    artifact["normalizedDiff"] = normalized
    return artifact


def debug_task_check_aliases() -> dict[str, set[str]]:
    return {
        "dapTrace": {"dapTrace", "dapEvents", "dapSessionTrace"},
        "breakpointStop": {"breakpointStop", "breakpoints", "stoppedEvent", "stoppedEvents"},
        "stackScopesVariables": {"stackScopesVariables", "stack", "scopes", "variables", "stackFrames", "stackTrace"},
        "evaluate": {"evaluate", "evaluateResult", "evaluateResponse"},
        "continueTerminate": {"continueTerminate", "continue", "terminate", "termination"},
        "debugUiState": {"debugUiState", "debugUiSnapshot", "uiState"},
        "taskTreeState": {"taskTreeState", "taskTree", "taskTreeNodes"},
        "taskOutput": {"taskOutput", "taskOutputLines", "taskRunOutput", "terminalOutput", "output"},
        "problemMatcher": {"problemMatcher", "problemExtraction", "problemMatcherDiagnostics"},
        "cancellation": {"cancellation", "cancellationState", "cancelResult"},
        "terminalMetadata": {"terminalMetadata", "terminalState", "terminalCleanup"},
        "testTree": {"testTree", "testItems", "testTreeState"},
        "testResults": {"testResults", "testRunResults", "resultPayloads"},
        "testOutput": {"testOutput", "testRunOutput"},
        "passFailSkipped": {"passFailSkipped", "testCounts", "testStateCounts"},
        "rerunState": {"rerunState", "rerunResult"},
        "problemMapping": {"problemMapping", "testProblemMapping"},
        "launchSchema": {"launchSchema", "launchConfig"},
        "generatedConfigs": {"generatedConfigs", "generatedConfigurationPayload"},
        "selectorState": {"selectorState", "debugSelectorState"},
        "adapterPath": {"adapterPath", "adapterPathHandling"},
        "schemaDiagnostics": {"schemaDiagnostics", "launchSchemaDiagnostics"},
    }


def debug_task_check_for_expected_evidence(evidence_key: str, scenario: dict[str, Any] | None = None) -> str:
    if isinstance(scenario, dict):
        expected = {
            str(item)
            for item in scenario.get("expectedEvidence", [])
            if isinstance(item, str)
        }
        kind = str(scenario.get("kind") or "")
        is_test_scenario = kind == "test" or bool(expected & {"testTree", "testResults", "passFailSkipped", "rerunState", "problemMapping"})
        if evidence_key == "output" and is_test_scenario:
            return "testOutput"
        if evidence_key == "uiState" and is_test_scenario:
            return ""
    for check_key, aliases in debug_task_check_aliases().items():
        if evidence_key in aliases:
            return check_key
    return ""


def scenario_debug_task_probe_points(scenario: dict[str, Any]) -> list[str]:
    expected = [
        str(item)
        for item in scenario.get("expectedEvidence", [])
        if isinstance(item, str)
    ]
    return [
        item
        for item in expected
        if debug_task_check_for_expected_evidence(item, scenario)
    ]


def debug_task_payload_scenario_evidence(
    scenario: dict[str, Any],
    debug_task_artifact: dict[str, Any],
) -> tuple[dict[str, Any], list[str], list[str], dict[str, Any]]:
    expected = [
        str(item)
        for item in scenario.get("expectedEvidence", [])
        if isinstance(item, str)
    ]
    checks = debug_task_artifact.get("checks") if isinstance(debug_task_artifact.get("checks"), dict) else {}
    artifact_path = rel(
        debug_task_probe_path(
            str(debug_task_artifact.get("extensionId") or ""),
            str(debug_task_artifact.get("scenarioId") or ""),
        )
    )
    evidence: dict[str, Any] = {}
    pending: list[str] = []
    residual_expected: list[str] = []
    matched_expected: list[str] = []
    missing_expected: list[str] = []
    for item in expected:
        check_key = debug_task_check_for_expected_evidence(item, scenario)
        if not check_key:
            residual_expected.append(item)
            pending.append(item)
            continue
        check = checks.get(check_key) if isinstance(checks.get(check_key), dict) else {}
        if check.get("status") == "captured":
            matched_expected.append(item)
            evidence[item] = {
                "status": "matched-debug-task-payload",
                "artifact": artifact_path,
                "check": check_key,
                "note": check.get("note", ""),
            }
        else:
            missing_expected.append(item)
            pending.append(item)
            evidence[item] = {
                "status": "debug-task-payload-missing",
                "artifact": artifact_path,
                "check": check_key,
                "checkStatus": check.get("status", "missing"),
                "note": check.get("note", ""),
            }
    summary = {
        "debugTaskProbePoints": [
            str(item)
            for item in debug_task_artifact.get("debugTaskProbePoints", [])
            if isinstance(item, str)
        ],
        "scenarioRequiredPromotionEvidence": [
            str(item)
            for item in debug_task_artifact.get("scenarioRequiredPromotionEvidence", [])
            if isinstance(item, str)
        ],
        "matchedDebugTaskEvidence": sorted(matched_expected),
        "missingDebugTaskEvidence": sorted(missing_expected),
        "residualExpectedEvidence": residual_expected,
        "debugTaskPayloadMatched": bool(matched_expected) and not missing_expected,
    }
    return evidence, pending, residual_expected, summary


def normalized_message_entries(items: Any) -> list[dict[str, Any]]:
    rows = items if isinstance(items, list) else []
    normalized: list[dict[str, Any]] = []
    for item in rows:
        if not isinstance(item, dict):
            continue
        message = str(item.get("message") or item.get("text") or "").strip()
        if not message:
            continue
        normalized.append(
            {
                "severity": str(item.get("severity") or ""),
                "message": message,
                "items": normalize_message_items(item.get("items")),
            }
        )
    return unique_json_items(normalized)


def wizp_debug_config_messages(artifact: dict[str, Any]) -> list[dict[str, Any]]:
    wizp_result = artifact.get("wizpResult") if isinstance(artifact.get("wizpResult"), dict) else {}
    messages: list[dict[str, Any]] = []
    side_effects = wizp_result.get("sideEffects") if isinstance(wizp_result.get("sideEffects"), dict) else {}
    messages.extend(normalized_message_entries(side_effects.get("messages")))
    for key in ("startupUiEvents", "uiEvents"):
        for item in wizp_result.get(key, []) if isinstance(wizp_result.get(key), list) else []:
            if isinstance(item, dict) and item.get("type") == "message":
                messages.extend(normalized_message_entries([item]))
    return unique_json_items(messages)


def reference_debug_config_messages(artifact: dict[str, Any]) -> list[dict[str, Any]]:
    reference_result = artifact.get("referenceResult") if isinstance(artifact.get("referenceResult"), dict) else {}
    probe_result = reference_result.get("probeResult") if isinstance(reference_result.get("probeResult"), dict) else {}
    messages: list[dict[str, Any]] = []
    side_effects = probe_result.get("sideEffects") if isinstance(probe_result.get("sideEffects"), dict) else {}
    startup_side_effects = probe_result.get("startupSideEffects") if isinstance(probe_result.get("startupSideEffects"), dict) else {}
    messages.extend(normalized_message_entries(side_effects.get("messages")))
    messages.extend(normalized_message_entries(startup_side_effects.get("messages")))
    return unique_json_items(messages)


def normalized_activation_error_entries(value: Any) -> list[dict[str, str]]:
    if isinstance(value, dict):
        rows = value.get("errors") if isinstance(value.get("errors"), list) else []
    else:
        rows = value if isinstance(value, list) else []
    normalized: list[dict[str, str]] = []
    for item in rows:
        if not isinstance(item, dict):
            continue
        message = str(item.get("message") or "")
        name = str(item.get("name") or "")
        if not message and not name:
            continue
        normalized.append(
            {
                "id": str(item.get("id") or ""),
                "name": name,
                "message": message,
            }
        )
    return unique_json_items(normalized)


def wizp_debug_config_activation_errors(artifact: dict[str, Any]) -> list[dict[str, str]]:
    wizp_result = artifact.get("wizpResult") if isinstance(artifact.get("wizpResult"), dict) else {}
    errors: list[dict[str, str]] = []
    for key in ("activationErrors", "activationErrorsFinal", "startupActivationErrorsFinal", "commandScopedActivationErrors"):
        errors.extend(normalized_activation_error_entries(wizp_result.get(key)))
    side_effects = wizp_result.get("sideEffects") if isinstance(wizp_result.get("sideEffects"), dict) else {}
    errors.extend(normalized_activation_error_entries(side_effects.get("activationErrors")))
    return unique_json_items(errors)


def reference_debug_config_activation_errors(artifact: dict[str, Any]) -> list[dict[str, str]]:
    reference_result = artifact.get("referenceResult") if isinstance(artifact.get("referenceResult"), dict) else {}
    probe_result = reference_result.get("probeResult") if isinstance(reference_result.get("probeResult"), dict) else {}
    errors: list[dict[str, str]] = []
    for key in ("sideEffects", "startupSideEffects"):
        side_effects = probe_result.get(key) if isinstance(probe_result.get(key), dict) else {}
        errors.extend(normalized_activation_error_entries(side_effects.get("activationErrors")))
    return unique_json_items(errors)


def task_tree_residual_surface_scenario(extension_id: str, scenario_id: str) -> bool:
    return (extension_id, scenario_id) in {
        ("vscjava.vscode-maven", "maven-explorer-goals"),
        ("vscjava.vscode-gradle", "gradle-explorer-tasks"),
    }


def task_tree_refresh_commands(extension_id: str, scenario_id: str) -> list[str]:
    if extension_id == "vscjava.vscode-maven" and scenario_id == "maven-explorer-goals":
        return ["maven.explorer.refresh"]
    if extension_id == "vscjava.vscode-gradle" and scenario_id == "gradle-explorer-tasks":
        return ["gradle.refresh"]
    return []


def command_entries_for_ids(value: Any, command_ids: list[str]) -> list[dict[str, Any]]:
    if not isinstance(value, dict):
        return []
    wanted = set(command_ids)
    commands = value.get("commands") if isinstance(value.get("commands"), list) else []
    entries: list[dict[str, Any]] = []
    for item in commands:
        if not isinstance(item, dict):
            continue
        command = str(item.get("command") or "")
        if command not in wanted:
            continue
        entries.append(
            {
                "command": command,
                "title": str(item.get("title") or ""),
                "enabled": item.get("enabled") is not False,
            }
        )
    return unique_json_items(entries)


def task_tree_residual_surface_evidence(
    extension_id: str,
    scenario_id: str,
    artifact: dict[str, Any],
) -> dict[str, Any]:
    if not task_tree_residual_surface_scenario(extension_id, scenario_id):
        return {}
    evidence: dict[str, Any] = {}
    artifact_path = rel(scenario_artifact_path(extension_id, scenario_id))
    wizp_result = artifact.get("wizpResult") if isinstance(artifact.get("wizpResult"), dict) else {}
    wizp_messages = wizp_debug_config_messages(artifact)
    reference_messages = reference_debug_config_messages(artifact)
    wizp_runtime = extract_wizp_runtime_processes(artifact)
    reference_runtime = extract_reference_runtime_processes(artifact)
    wizp_spawned, wizp_dropped = normalize_runtime_spawn_processes(wizp_runtime, drop_workspace_git_probe=True)
    reference_spawned, reference_dropped = normalize_runtime_spawn_processes(reference_runtime, drop_workspace_git_probe=True)
    wizp_forked = wizp_runtime.get("forkedProcesses") if isinstance(wizp_runtime.get("forkedProcesses"), list) else []
    reference_forked = reference_runtime.get("forkedProcesses") if isinstance(reference_runtime.get("forkedProcesses"), list) else []
    network_ok = runtime_network_audit_count(wizp_runtime) == 0 and runtime_network_audit_count(reference_runtime) == 0
    process_ok = not wizp_spawned and not reference_spawned and not wizp_forked and not reference_forked and network_ok
    messages_ok = not wizp_messages and not reference_messages
    refresh_commands = task_tree_refresh_commands(extension_id, scenario_id)
    refresh_entries = command_entries_for_ids(wizp_result.get("commandsAfterOpen"), refresh_commands)
    task_runtime = wizp_result.get("taskRuntime") if isinstance(wizp_result.get("taskRuntime"), dict) else {}
    task_state = task_runtime_tree_state(task_runtime)
    task_output = task_runtime_output(task_runtime)
    refresh_ok = (
        bool(refresh_commands)
        and len(refresh_entries) == len(refresh_commands)
        and all(entry.get("enabled") is True for entry in refresh_entries)
        and bool(task_state)
        and bool(task_output)
    )
    evidence["refreshState"] = {
        "status": "matched-task-refresh-surface" if refresh_ok else "task-refresh-surface-incomplete",
        "artifact": artifact_path,
        "requiredCommands": refresh_commands,
        "wizpRefreshCommands": refresh_entries,
        "taskStateSource": task_state.get("source", ""),
        "taskOutputSource": task_output.get("source", ""),
        "note": "This verifies the bounded refresh surface: contributed refresh command availability plus captured task/tree runtime state. It does not claim an external Maven or Gradle daemon refresh completed.",
    }
    evidence["messages"] = {
        "status": "matched-no-task-runtime-messages" if messages_ok else "task-runtime-message-drift",
        "artifact": artifact_path,
        "wizpMessages": wizp_messages[-8:],
        "referenceMessages": reference_messages[-8:],
    }
    evidence["processAudit"] = {
        "status": "matched-bounded-task-runtime-process-audit" if process_ok else "task-runtime-process-audit-drift",
        "artifact": artifact_path,
        "wizpOwnedSpawnedProcesses": wizp_spawned,
        "referenceOwnedSpawnedProcesses": reference_spawned,
        "wizpForkedProcesses": wizp_forked,
        "referenceForkedProcesses": reference_forked,
        "wizpDroppedBackgroundProcesses": wizp_dropped,
        "referenceDroppedBackgroundProcesses": reference_dropped,
        "wizpNetworkAuditCount": runtime_network_audit_count(wizp_runtime),
        "referenceNetworkAuditCount": runtime_network_audit_count(reference_runtime),
    }
    return evidence


def debug_config_residual_surface_evidence(
    extension_id: str,
    scenario_id: str,
    artifact: dict[str, Any],
) -> dict[str, Any]:
    evidence: dict[str, Any] = {}
    artifact_path = rel(scenario_artifact_path(extension_id, scenario_id))
    wizp_messages = wizp_debug_config_messages(artifact)
    reference_messages = reference_debug_config_messages(artifact)
    wizp_activation_errors = wizp_debug_config_activation_errors(artifact)
    reference_activation_errors = reference_debug_config_activation_errors(artifact)

    if extension_id == "ms-python.debugpy" and scenario_id == "debugpy-config-schema":
        messages_ok = not wizp_messages and not reference_messages
        evidence["messages"] = {
            "status": "matched-no-user-facing-debug-config-messages" if messages_ok else "debug-config-message-surface-drift",
            "artifact": artifact_path,
            "wizpMessages": wizp_messages,
            "referenceMessages": reference_messages,
            "note": "The debugpy generated-config/schema scenario is expected to avoid user-facing error messages while selector/schema payloads are captured.",
        }
        return evidence

    if extension_id == "devsense.phptools-vscode" and scenario_id == "phptools-debug-degraded":
        wizp_runtime = extract_wizp_runtime_processes(artifact)
        reference_runtime = extract_reference_runtime_processes(artifact)
        wizp_spawned, wizp_dropped = normalize_runtime_spawn_processes(wizp_runtime, drop_workspace_git_probe=True)
        reference_spawned, reference_dropped = normalize_runtime_spawn_processes(reference_runtime, drop_workspace_git_probe=True)
        network_ok = runtime_network_audit_count(wizp_runtime) == 0 and runtime_network_audit_count(reference_runtime) == 0
        process_ok = not wizp_spawned and not reference_spawned and network_ok
        activation_ok = not wizp_activation_errors and not reference_activation_errors
        messages_ok = json_signature(wizp_messages) == json_signature(reference_messages) and bool(wizp_messages or reference_messages)
        evidence["messages"] = {
            "status": "matched-php-debug-degraded-messages" if messages_ok else "php-debug-degraded-message-drift",
            "artifact": artifact_path,
            "wizpMessages": wizp_messages[-8:],
            "referenceMessages": reference_messages[-8:],
            "wizpMessageCount": len(wizp_messages),
            "referenceMessageCount": len(reference_messages),
            "note": "PHP Tools degraded debug UX requires reference-compatible user-facing missing-runtime messages.",
        }
        evidence["processAudit"] = {
            "status": "matched-no-unrequested-debug-processes" if process_ok else "php-debug-degraded-process-audit-drift",
            "artifact": artifact_path,
            "wizpOwnedSpawnedProcesses": wizp_spawned,
            "referenceOwnedSpawnedProcesses": reference_spawned,
            "wizpDroppedBackgroundProcesses": wizp_dropped,
            "referenceDroppedBackgroundProcesses": reference_dropped,
            "wizpNetworkAuditCount": runtime_network_audit_count(wizp_runtime),
            "referenceNetworkAuditCount": runtime_network_audit_count(reference_runtime),
            "note": "This row stays open while WIZP performs unaccepted missing-runtime process or network work.",
        }
        evidence["activationErrors"] = {
            "status": "matched-no-debug-config-activation-errors" if activation_ok else "php-debug-degraded-activation-error-drift",
            "artifact": artifact_path,
            "wizpActivationErrors": wizp_activation_errors,
            "referenceActivationErrors": reference_activation_errors,
        }

    return evidence


def go_missing_tool_messages(messages: list[dict[str, Any]]) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for message in messages:
        text = str(message.get("message") or "")
        if "Failed to find the \"go\" binary" not in text:
            continue
        rows.append(
            {
                "severity": str(message.get("severity") or ""),
                "message": text,
                "actionLabels": [
                    str(item.get("label") or "")
                    for item in message.get("items", [])
                    if isinstance(item, dict) and str(item.get("label") or "")
                ],
            }
        )
    return unique_json_items(rows)


def go_debug_test_residual_surface_evidence(
    extension_id: str,
    scenario_id: str,
    artifact: dict[str, Any],
) -> dict[str, Any]:
    if (extension_id, scenario_id) != ("golang.Go", "go-debug-test-tools"):
        return {}
    artifact_path = rel(scenario_artifact_path(extension_id, scenario_id))
    wizp_result = artifact.get("wizpResult") if isinstance(artifact.get("wizpResult"), dict) else {}
    wizp_messages = wizp_debug_config_messages(artifact)
    reference_messages = reference_debug_config_messages(artifact)
    wizp_command_runtime = (
        wizp_result.get("commandScopedRuntimeProcesses")
        if isinstance(wizp_result.get("commandScopedRuntimeProcesses"), dict)
        else extract_wizp_runtime_processes(artifact)
    )
    reference_runtime = extract_reference_runtime_processes(artifact)
    wizp_spawned, wizp_dropped = normalize_runtime_spawn_processes(wizp_command_runtime, drop_workspace_git_probe=True)
    reference_spawned, reference_dropped = normalize_runtime_spawn_processes(reference_runtime, drop_workspace_git_probe=True)
    network_ok = runtime_network_audit_count(wizp_command_runtime) == 0 and runtime_network_audit_count(reference_runtime) == 0
    process_ok = not wizp_spawned and not reference_spawned and network_ok
    wizp_tool_prompts = go_missing_tool_messages(wizp_messages)
    reference_tool_prompts = go_missing_tool_messages(reference_messages)
    tool_prompt_ok = (
        bool(wizp_tool_prompts)
        and bool(reference_tool_prompts)
        and json_signature(wizp_tool_prompts) == json_signature(reference_tool_prompts)
    )
    return {
        "toolPrompt": {
            "status": "matched-go-missing-tool-prompt" if tool_prompt_ok else "go-missing-tool-prompt-drift",
            "artifact": artifact_path,
            "wizpMissingToolPrompts": wizp_tool_prompts,
            "referenceMissingToolPrompts": reference_tool_prompts,
            "note": "The Go row stays open until WIZP surfaces the same missing-Go tool prompt that the reference host emits.",
        },
        "networkAudit": {
            "status": "matched-zero-go-tool-network-audit" if network_ok else "go-tool-network-audit-drift",
            "artifact": artifact_path,
            "wizpNetworkAuditCount": runtime_network_audit_count(wizp_command_runtime),
            "referenceNetworkAuditCount": runtime_network_audit_count(reference_runtime),
        },
        "processAudit": {
            "status": "matched-bounded-go-tool-process-audit" if process_ok else "go-tool-process-audit-drift",
            "artifact": artifact_path,
            "wizpOwnedSpawnedProcesses": wizp_spawned,
            "referenceOwnedSpawnedProcesses": reference_spawned,
            "wizpDroppedBackgroundProcesses": wizp_dropped,
            "referenceDroppedBackgroundProcesses": reference_dropped,
            "note": "The reference host performs only the workspace Git discovery probe in this lane; no command-scoped Go tool subprocess or network passthrough is accepted as scenario evidence.",
        },
    }


def ruby_lsp_missing_runtime_process_audit(payload: dict[str, Any]) -> dict[str, Any]:
    if str(payload.get("extensionId") or "") != "Shopify.ruby-lsp" or str(payload.get("scenarioId") or "") != "ruby-lsp-bundler-degraded":
        return {}
    wizp_result = payload.get("wizpResult") if isinstance(payload.get("wizpResult"), dict) else {}
    runtime_processes = observed_wizp_runtime_processes(wizp_result)
    rows = runtime_processes.get("spawnedProcesses") if isinstance(runtime_processes.get("spawnedProcesses"), list) else []
    commands = [
        str(item.get("command") or item.get("file") or "")
        for item in rows
        if isinstance(item, dict) and str(item.get("command") or item.get("file") or "")
    ]
    manager_names = ["chruby", "rbenv", "rvm", "asdf", "rv"]
    manager_probe_ok = all(any(f"bash -i -c '{name} --version'" in command for command in commands) for name in manager_names)
    activation_probe_ok = any(
        "ruby -EUTF-8:UTF-8" in command
        and "activation.rb" in command
        and "/tmp/wizp-missing-ruby" not in command
        for command in commands
    )
    configured_missing_probe_ok = any(
        "/tmp/wizp-missing-ruby" in command
        and "activation.rb" in command
        for command in commands
    )
    network_ok = int(runtime_processes.get("networkAuditCount") or 0) == 0
    expected_count = len(manager_names) + 2
    status = (
        "accepted-bounded-ruby-lsp-missing-runtime-probes"
        if len(commands) == expected_count
        and manager_probe_ok
        and activation_probe_ok
        and configured_missing_probe_ok
        and network_ok
        else "ruby-lsp-missing-runtime-process-drift"
    )
    return {
        "status": status,
        "acceptedSpawnedProcessCount": expected_count,
        "observedSpawnedProcessCount": len(commands),
        "networkAuditCount": runtime_processes.get("networkAuditCount"),
        "managerProbeCommandsPresent": manager_probe_ok,
        "activationProbeCommandPresent": activation_probe_ok,
        "configuredMissingRubyProbePresent": configured_missing_probe_ok,
        "commands": commands,
        "note": (
            "Ruby LSP missing-runtime startup probes check five Ruby version managers, then try the default ruby activation path and the configured missing ruby executable. "
            "This bounded degraded-runtime pattern is accepted for T20V-011 only."
        ),
    }


def normalize_container_cli_processes(
    runtime_processes: dict[str, Any],
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    rows: list[dict[str, Any]] = []
    for key in ("spawnedProcesses", "forkedProcesses"):
        values = runtime_processes.get(key) if isinstance(runtime_processes.get(key), list) else []
        rows.extend(item for item in values if isinstance(item, dict))
    kept: list[dict[str, Any]] = []
    dropped: list[dict[str, Any]] = []
    for item in rows:
        command_raw = str(item.get("modulePath") or item.get("file") or item.get("command") or "")
        if not command_raw:
            continue
        args = [str(arg) for arg in item.get("args", [])] if isinstance(item.get("args"), list) else []
        normalized_args = [
            "--clientProcessId=<pid>" if arg.startswith("--clientProcessId=") else arg
            for arg in args
        ]
        command_name = Path(command_raw).name or command_raw
        normalized = {"command": command_name, "args": normalized_args}
        if command_name == "git" and normalized_args == ["rev-parse", "--show-toplevel"]:
            dropped.append(normalized)
            continue
        if any(
            marker in command_raw
            for marker in (
                "dockerfile-language-server-nodejs/lib/server.js",
                "compose-language-service/lib/server.js",
            )
        ):
            dropped.append({"command": command_raw, "args": normalized_args, "reason": "language-server-background-process"})
            continue
        if (
            command_name == "docker"
            and normalized_args
            and normalized_args[0] == "events"
            and "type=container" in normalized_args
            and "type=image" in normalized_args
            and "event=prune" in normalized_args
            and "{{json .}}" in normalized_args
        ):
            dropped.append(
                {
                    "command": command_name,
                    "args": normalized_args,
                    "reason": "bounded-missing-docker-event-watcher",
                }
            )
            continue
        kept.append(normalized)
    return unique_json_items(sorted(kept, key=json_signature)), unique_json_items(sorted(dropped, key=json_signature))


def container_runtime_residual_surface_evidence(
    extension_id: str,
    scenario_id: str,
    artifact: dict[str, Any],
) -> dict[str, Any]:
    if (extension_id, scenario_id) != ("ms-azuretools.vscode-containers", "containers-docker-cli"):
        return {}
    artifact_path = rel(scenario_artifact_path(extension_id, scenario_id))
    wizp_messages = wizp_debug_config_messages(artifact)
    reference_messages = reference_debug_config_messages(artifact)
    wizp_runtime = extract_wizp_runtime_processes(artifact)
    reference_runtime = extract_reference_runtime_processes(artifact)
    wizp_result = artifact.get("wizpResult") if isinstance(artifact.get("wizpResult"), dict) else {}
    reference_result = artifact.get("referenceResult") if isinstance(artifact.get("referenceResult"), dict) else {}
    reference_probe = reference_result.get("probeResult") if isinstance(reference_result.get("probeResult"), dict) else {}
    reference_survey = reference_probe.get("survey") if isinstance(reference_probe.get("survey"), dict) else {}
    wizp_spawned, wizp_dropped = normalize_container_cli_processes(wizp_runtime)
    reference_spawned, reference_dropped = normalize_container_cli_processes(reference_runtime)
    network_ok = runtime_network_audit_count(wizp_runtime) == 0 and runtime_network_audit_count(reference_runtime) == 0
    process_ok = not wizp_spawned and not reference_spawned and network_ok
    messages_ok = not wizp_messages and not reference_messages
    wizp_activation_errors = wizp_debug_config_activation_errors(artifact)
    reference_activation_errors = reference_debug_config_activation_errors(artifact)

    def container_view_ids(value: Any) -> list[str]:
        if isinstance(value, list):
            rows = value
        else:
            rows = None
        if not isinstance(value, dict):
            if rows is None:
                return []
        else:
            rows = value.get("views")
            if isinstance(rows, dict):
                rows = rows.get("views")
            elif isinstance(value.get("result"), dict):
                rows = value.get("result", {}).get("views")
        if not isinstance(rows, list):
            return []
        ids = [
            str(item.get("id") or "")
            for item in rows
            if isinstance(item, dict) and str(item.get("id") or "")
        ]
        return sorted(set(ids))

    def task_stdout(value: Any) -> str:
        if not isinstance(value, dict):
            return ""
        run_result = value.get("run") if isinstance(value.get("run"), dict) else {}
        result = run_result.get("result") if isinstance(run_result.get("result"), dict) else {}
        return str(result.get("stdout") or "")

    wizp_view_ids = container_view_ids(wizp_result.get("views"))
    reference_view_ids = container_view_ids(reference_survey.get("views"))
    reference_image_ok = (not reference_view_ids) or ("vscode-containers.views.images" in reference_view_ids)
    reference_container_ok = (not reference_view_ids) or ("vscode-containers.views.containers" in reference_view_ids)
    image_list_ok = "vscode-containers.views.images" in wizp_view_ids and reference_image_ok
    container_list_ok = "vscode-containers.views.containers" in wizp_view_ids and reference_container_ok
    wizp_task_stdout = task_stdout(wizp_result.get("taskRuntime"))
    reference_task_stdout = task_stdout(reference_survey.get("taskRuntime"))
    missing_docker_wizp = any('Executable not found in $PATH: "docker"' in str(item.get("message") or "") for item in wizp_activation_errors)
    missing_docker_reference = any('Executable not found in $PATH: "docker"' in str(item.get("message") or "") for item in reference_activation_errors)
    errors_ok = (
        missing_docker_wizp
        and (missing_docker_reference or not reference_activation_errors)
    )
    return {
        "imageList": {
            "status": "matched-container-image-view-surface" if image_list_ok else "container-image-view-surface-drift",
            "artifact": artifact_path,
            "wizpViewIds": wizp_view_ids,
            "referenceViewIds": reference_view_ids,
            "wizpTaskStdoutTail": wizp_task_stdout[-240:],
            "referenceTaskStdoutTail": reference_task_stdout[-240:],
            "note": "This scenario treats the Containers Images view plus the paired fixture task output as the bounded image-list surface for the missing-Docker workflow.",
        },
        "containerList": {
            "status": "matched-container-list-view-surface" if container_list_ok else "container-list-view-surface-drift",
            "artifact": artifact_path,
            "wizpViewIds": wizp_view_ids,
            "referenceViewIds": reference_view_ids,
            "wizpTaskStdoutTail": wizp_task_stdout[-240:],
            "referenceTaskStdoutTail": reference_task_stdout[-240:],
            "note": "This scenario treats the Containers view plus the paired fixture task output as the bounded container-list surface for the missing-Docker workflow.",
        },
        "errors": {
            "status": "matched-missing-docker-error-surface" if errors_ok else "missing-docker-error-surface-drift",
            "artifact": artifact_path,
            "wizpActivationErrors": wizp_activation_errors,
            "referenceActivationErrors": reference_activation_errors,
            "note": "The missing-Docker path is accepted when both hosts capture the same bounded `Executable not found in $PATH: \"docker\"` activation error surface.",
        },
        "messages": {
            "status": "matched-no-container-cli-messages" if messages_ok else "container-cli-message-drift",
            "artifact": artifact_path,
            "wizpMessages": wizp_messages[-8:],
            "referenceMessages": reference_messages[-8:],
        },
        "processAudit": {
            "status": "matched-bounded-container-cli-process-audit" if process_ok else "container-cli-process-audit-drift",
            "artifact": artifact_path,
            "wizpOwnedSpawnedProcesses": wizp_spawned,
            "referenceOwnedSpawnedProcesses": reference_spawned,
            "wizpDroppedBackgroundProcesses": wizp_dropped,
            "referenceDroppedBackgroundProcesses": reference_dropped,
            "wizpNetworkAuditCount": runtime_network_audit_count(wizp_runtime),
            "referenceNetworkAuditCount": runtime_network_audit_count(reference_runtime),
            "note": "This bounded audit drops workspace Git probes, Dockerfile/Compose language servers, and the Containers extension's repeated missing-Docker `docker events ...` watcher probes; Docker image/container payload evidence remains scenario-owned.",
        },
    }


def run_debug_task_payload_validated_scenario(
    manifest: dict[str, Any],
    scenario: dict[str, Any],
    baseline: dict[str, Any],
    generated_at: str,
    *,
    reuse_cached_reference: bool = False,
) -> dict[str, Any]:
    artifact = run_generic_paired_scenario(
        manifest,
        scenario,
        baseline,
        generated_at,
        reuse_cached_reference=reuse_cached_reference,
    )
    extension_id = str(manifest["extensionId"])
    scenario_id = str(scenario["id"])
    batch_id = DEBUG_TASK_PROBE_SCENARIO_BATCHES.get((extension_id.lower(), scenario_id), "")
    debug_task_artifact = write_debug_task_probe_artifact(
        batch_id,
        extension_id,
        scenario,
        baseline,
        artifact,
        generated_at,
    )
    debug_task_artifact_payload = load_json_if_exists(debug_task_probe_path(extension_id, scenario_id))
    evidence, pending_expected_evidence, residual_expected, summary = debug_task_payload_scenario_evidence(
        scenario,
        debug_task_artifact_payload,
    )
    residual_evidence: dict[str, Any] = {}
    residual_evidence.update(debug_config_residual_surface_evidence(extension_id, scenario_id, artifact))
    residual_evidence.update(task_tree_residual_surface_evidence(extension_id, scenario_id, artifact))
    residual_evidence.update(go_debug_test_residual_surface_evidence(extension_id, scenario_id, artifact))
    residual_evidence.update(container_runtime_residual_surface_evidence(extension_id, scenario_id, artifact))
    evidence.update(residual_evidence)
    pending_expected_evidence = [
        item
        for item in pending_expected_evidence
        if not evidence_entry_matched(evidence.get(item))
    ]
    residual_expected = [
        item
        for item in residual_expected
        if not evidence_entry_matched(evidence.get(item))
    ]
    summary["matchedResidualEvidence"] = sorted(
        item
        for item in residual_evidence
        if evidence_entry_matched(residual_evidence.get(item))
    )
    summary["residualExpectedEvidence"] = residual_expected
    blockers = scenario_blocker_tokens(artifact)
    if not debug_task_artifact.get("promotionReady"):
        blockers.extend(
            str(item)
            for item in debug_task_artifact.get("missingPromotionEvidence", [])
            if isinstance(item, str)
        )
        blockers.append(str(debug_task_artifact.get("status") or "debug-task-payload-incomplete"))
    if not blockers and not pending_expected_evidence:
        artifact["status"] = "paired-debug-task-payload-scenario-verified"
        normalized_status = "paired-scenario-evidence-matched"
    elif any(str((entry or {}).get("status") or "").startswith("matched-") for entry in evidence.values() if isinstance(entry, dict)):
        artifact["status"] = "paired-debug-task-payload-scenario-partial"
        normalized_status = "paired-scenario-evidence-partial"
    else:
        normalized_status = artifact.get("normalizedDiff", {}).get("status", "not-run")
    artifact["debugTaskEvidence"] = {
        "artifact": rel(debug_task_probe_path(extension_id, scenario_id)),
        "status": debug_task_artifact.get("status", ""),
        "promotionReady": debug_task_artifact.get("promotionReady"),
        "batchId": debug_task_artifact.get("batchId", ""),
        "summary": summary,
    }
    artifact["blockers"] = sorted(set(str(item) for item in blockers if str(item)))
    artifact["evidence"] = evidence
    artifact["pendingExpectedEvidence"] = pending_expected_evidence
    normalized = artifact.get("normalizedDiff") if isinstance(artifact.get("normalizedDiff"), dict) else {}
    normalized["status"] = normalized_status
    normalized["acceptedDifferences"] = unique_json_items(normalized.get("acceptedDifferences", []))
    normalized["notes"] = (
        "Scenario-specific debug/task verifier promotes only when the H08 focused probe is promotion-ready, every expected debug/task/test evidence key maps to a captured probe check, and no non-H08 expected evidence remains. "
        "Rows with matched debug/task payloads but residual process, message, tree, network, Docker, or UI evidence stay partial."
    )
    if residual_expected:
        normalized["residualExpectedEvidence"] = residual_expected
    artifact["normalizedDiff"] = normalized
    return artifact


def generic_lifecycle_payload_scenario(extension_id: str, scenario_id: str) -> bool:
    return (extension_id, scenario_id) == ("redhat.java", "redhat-java-lifecycle")


def java_lifecycle_event_commands(events: list[Any]) -> list[str]:
    commands: list[str] = []
    for event in events:
        if not isinstance(event, dict) or event.get("type") != "commandRegistered":
            continue
        command = str(event.get("command") or "")
        if command:
            commands.append(command)
    return sorted(set(commands))


def java_lifecycle_output_events(events: list[Any]) -> list[dict[str, Any]]:
    output_events: list[dict[str, Any]] = []
    for event in events:
        if not isinstance(event, dict) or event.get("type") not in {"output", "outputTrace"}:
            continue
        channel = str(event.get("channel") or "")
        if "Language Support for Java" not in channel:
            continue
        output_events.append(
            {
                "channel": channel,
                "action": str(event.get("action") or ""),
                "text": str(event.get("text") or "")[:240],
            }
        )
    return unique_json_items(output_events)


def java_lifecycle_setting_read(reads: list[Any], key: str, section: str = "") -> Any:
    for read in reads:
        if not isinstance(read, dict):
            continue
        read_key = str(read.get("key") or "")
        read_section = str(read.get("section") or "")
        if read_key != key:
            continue
        if section and read_section != section:
            continue
        value = read.get("value")
        if value is not None:
            return value
    return None


def java_lifecycle_setting_value(value: Any) -> Any:
    if not isinstance(value, dict):
        return value
    if "workspaceValue" in value:
        return value.get("workspaceValue")
    if "value" in value:
        return value.get("value")
    return value


def java_lifecycle_missing_jdk_messages(messages: list[Any]) -> list[dict[str, Any]]:
    matched: list[dict[str, Any]] = []
    for message in messages:
        if not isinstance(message, dict):
            continue
        text = str(message.get("message") or "")
        if "Invalid runtime for JavaSE-" not in text or "does not point to a JDK" not in text:
            continue
        items = message.get("items") if isinstance(message.get("items"), list) else []
        labels = [
            str(item.get("label") or "")
            for item in items
            if isinstance(item, dict) and str(item.get("label") or "")
        ]
        matched.append(
            {
                "message": text,
                "severity": str(message.get("severity") or ""),
                "actionLabels": labels,
            }
        )
    return unique_json_items(matched)


def java_lifecycle_jdt_processes(runtime_processes: dict[str, Any]) -> list[dict[str, Any]]:
    processes = runtime_processes.get("spawnedProcesses") if isinstance(runtime_processes.get("spawnedProcesses"), list) else []
    jdt_processes: list[dict[str, Any]] = []
    for process in processes:
        if not isinstance(process, dict):
            continue
        args = [str(item) for item in process.get("args", []) if isinstance(process.get("args"), list)]
        joined_args = " ".join(args)
        if "org.eclipse.equinox.launcher" not in joined_args and "jdt_ws" not in joined_args:
            continue
        jdt_processes.append(
            {
                "command": str(process.get("command") or ""),
                "hasGlobalConfigPath": ".wizp-context/global" in joined_args,
                "hasWorkspaceDataPath": ".wizp-context/workspace" in joined_args,
                "hasSharedArchivePath": "jdtls.jsa" in joined_args,
            }
        )
    return jdt_processes


def java_lifecycle_payload_evidence(
    extension_id: str,
    scenario_id: str,
    artifact: dict[str, Any],
) -> dict[str, Any]:
    if not generic_lifecycle_payload_scenario(extension_id, scenario_id):
        return {}
    artifact_path = rel(scenario_artifact_path(extension_id, scenario_id))
    wizp_result = artifact.get("wizpResult") if isinstance(artifact.get("wizpResult"), dict) else {}
    reference_result = artifact.get("referenceResult") if isinstance(artifact.get("referenceResult"), dict) else {}
    probe_result = reference_result.get("probeResult") if isinstance(reference_result.get("probeResult"), dict) else {}
    debug_state = wizp_result.get("debugState") if isinstance(wizp_result.get("debugState"), dict) else {}
    runtime_processes = extract_wizp_runtime_processes(artifact)
    activation_events = wizp_result.get("activationEvents") if isinstance(wizp_result.get("activationEvents"), list) else []
    startup_events = list(wizp_result.get("startupUiEvents") or []) if isinstance(wizp_result.get("startupUiEvents"), list) else []
    startup_tail = list(wizp_result.get("startupUiEventsTail") or []) if isinstance(wizp_result.get("startupUiEventsTail"), list) else []
    all_startup_events = startup_events + startup_tail
    command_registrations = java_lifecycle_event_commands(all_startup_events)
    output_events = java_lifecycle_output_events(all_startup_events)
    status_bar_events = [
        event
        for event in all_startup_events
        if isinstance(event, dict)
        and event.get("type") == "statusBar"
        and isinstance(event.get("item"), dict)
        and event["item"].get("alignment") == "java.serverStatus"
    ]
    progress_events = [
        event
        for event in all_startup_events
        if isinstance(event, dict)
        and str(event.get("title") or event.get("message") or "").startswith("Opening Java Projects")
    ]
    configuration_reads = debug_state.get("configurationReads") if isinstance(debug_state.get("configurationReads"), list) else []
    required_settings = {
        "java.jdt.ls.java.home": java_lifecycle_setting_read(configuration_reads, "java.jdt.ls.java.home"),
        "java.server.launchMode": java_lifecycle_setting_read(configuration_reads, "java.server.launchMode"),
        "java.transport": java_lifecycle_setting_read(configuration_reads, "transport", "java"),
        "redhat.telemetry.enabled": java_lifecycle_setting_read(configuration_reads, "redhat.telemetry.enabled"),
    }
    jdt_processes = java_lifecycle_jdt_processes(runtime_processes)
    clean_commands = [
        command
        for command in ("java.clean.workspace", "java.clean.sharedIndexes")
        if command in command_registrations
    ]
    wizp_messages = wizp_debug_config_messages(artifact)
    reference_messages = reference_debug_config_messages(artifact)
    wizp_activation_errors = wizp_debug_config_activation_errors(artifact)
    reference_activation_errors = reference_debug_config_activation_errors(artifact)
    missing_jdk_messages = java_lifecycle_missing_jdk_messages(wizp_messages)
    only_missing_jdk_messages = len(missing_jdk_messages) == len(wizp_messages)
    activated = any(isinstance(event, dict) and event.get("status") == "activated" for event in activation_events)
    active_extensions = [
        item
        for item in debug_state.get("extensions", [])
        if isinstance(debug_state.get("extensions"), list)
        and isinstance(item, dict)
        and str(item.get("id") or "").lower() == "redhat.java"
    ]
    activation_ok = (
        activated
        and bool(active_extensions)
        and all(item.get("isActive") is True for item in active_extensions)
        and not wizp_activation_errors
        and not reference_activation_errors
        and reference_result.get("status") == "reference-scenario-probed"
        and probe_result.get("status") == "reference-scenario-probed"
    )
    language_ok = (
        bool(status_bar_events)
        and "java.show.server.task.status" in command_registrations
        and "java.server.restart" in command_registrations
        and "java.server.mode.switch" in command_registrations
        and bool(progress_events)
    )
    settings_ok = (
        java_lifecycle_setting_value(required_settings.get("java.jdt.ls.java.home")) == "/opt/android-studio/jbr"
        and java_lifecycle_setting_value(required_settings.get("java.server.launchMode")) == "Hybrid"
        and java_lifecycle_setting_value(required_settings.get("java.transport")) == "stdio"
        and java_lifecycle_setting_value(required_settings.get("redhat.telemetry.enabled")) is False
    )
    cache_ok = (
        bool(jdt_processes)
        and all(item.get("hasGlobalConfigPath") and item.get("hasWorkspaceDataPath") for item in jdt_processes)
        and bool(clean_commands)
    )
    messages_ok = not reference_messages and not wizp_activation_errors and not reference_activation_errors and (
        not wizp_messages or (bool(missing_jdk_messages) and only_missing_jdk_messages)
    )
    message_status = (
        "matched-java-missing-jdk-message"
        if missing_jdk_messages and only_missing_jdk_messages
        else "matched-no-java-lifecycle-messages"
        if messages_ok
        else "java-lifecycle-message-drift"
    )
    return {
        "activationTrace": {
            "status": "matched-java-lifecycle-activation-trace" if activation_ok else "java-lifecycle-activation-incomplete",
            "artifact": artifact_path,
            "activationEvents": activation_events,
            "activeExtensions": active_extensions,
            "referenceStatus": reference_result.get("status", ""),
            "referenceProbeStatus": probe_result.get("status", ""),
            "wizpActivationErrors": wizp_activation_errors,
            "referenceActivationErrors": reference_activation_errors,
        },
        "languageStatus": {
            "status": "matched-java-language-status-surface" if language_ok else "java-language-status-surface-incomplete",
            "artifact": artifact_path,
            "statusBarEventCount": len(status_bar_events),
            "progressEvents": progress_events[-4:],
            "requiredCommands": ["java.show.server.task.status", "java.server.restart", "java.server.mode.switch"],
            "matchedCommands": [
                command
                for command in ("java.show.server.task.status", "java.server.restart", "java.server.mode.switch")
                if command in command_registrations
            ],
        },
        "outputChannels": {
            "status": "matched-java-output-channel-surface" if output_events else "java-output-channel-surface-missing",
            "artifact": artifact_path,
            "channels": sorted({str(item.get("channel") or "") for item in output_events}),
            "sample": output_events[-6:],
            "note": "Output-channel evidence records the Java extension's lifecycle log channels. User-facing message parity is tracked separately by the messages evidence key.",
        },
        "settingsDiff": {
            "status": "matched-java-lifecycle-settings" if settings_ok else "java-lifecycle-settings-incomplete",
            "artifact": artifact_path,
            "requiredSettings": required_settings,
        },
        "cacheState": {
            "status": "matched-java-jdt-cache-state" if cache_ok else "java-jdt-cache-state-incomplete",
            "artifact": artifact_path,
            "jdtProcesses": jdt_processes,
            "cleanCommands": clean_commands,
            "note": "This proves the captured JDT launch/cache path and clean-cache command surface. It does not close H11E budget review for JDT startup time or spawned processes.",
        },
        "messages": {
            "status": message_status,
            "artifact": artifact_path,
            "boundedMissingJdkMessages": missing_jdk_messages,
            "wizpMessages": wizp_messages[-8:],
            "referenceMessages": reference_messages[-8:],
            "wizpActivationErrors": wizp_activation_errors,
            "referenceActivationErrors": reference_activation_errors,
            "note": "The lifecycle scenario declares missing-JDK UX. A WIZP-only JavaSE invalid-runtime prompt with Open Settings action is accepted as bounded user-facing evidence, not as H11E performance-budget proof.",
        },
    }


def generic_composer_payload_scenario(extension_id: str, scenario_id: str) -> bool:
    return extension_id == "devsense.composer-php-vscode" and scenario_id in {
        "composer-valid-commands",
        "composer-missing-tools",
    }


def composer_wizp_events(wizp_result: dict[str, Any]) -> list[dict[str, Any]]:
    events: list[dict[str, Any]] = []
    for key in ("startupUiEvents", "startupUiEventsTail", "uiEvents"):
        rows = wizp_result.get(key)
        if not isinstance(rows, list):
            continue
        events.extend(item for item in rows if isinstance(item, dict))
    return events


def composer_action_labels(message: dict[str, Any]) -> list[str]:
    items = message.get("items") if isinstance(message.get("items"), list) else []
    labels: list[str] = []
    for item in items:
        if isinstance(item, str) and item:
            labels.append(item)
        elif isinstance(item, dict) and str(item.get("label") or ""):
            labels.append(str(item.get("label") or ""))
    return labels


def composer_message_events(events: list[dict[str, Any]]) -> list[dict[str, Any]]:
    messages: list[dict[str, Any]] = []
    for event in events:
        if event.get("type") != "message":
            continue
        text = str(event.get("message") or "")
        if "Composer" not in text and "composer" not in text:
            continue
        messages.append(
            {
                "severity": str(event.get("severity") or ""),
                "message": text,
                "actionLabels": composer_action_labels(event),
            }
        )
    return unique_json_items(messages)


def composer_task_execution_events(events: list[dict[str, Any]]) -> list[dict[str, Any]]:
    tasks: list[dict[str, Any]] = []
    for event in events:
        if event.get("type") != "taskExecute" or not isinstance(event.get("task"), dict):
            continue
        task = event["task"]
        if str(task.get("source") or "") != "composer":
            continue
        definition = task.get("definition") if isinstance(task.get("definition"), dict) else {}
        execution = task.get("execution") if isinstance(task.get("execution"), dict) else {}
        raw_args = execution.get("args") if isinstance(execution.get("args"), list) else []
        args: list[Any] = []
        for arg in raw_args:
            if isinstance(arg, dict):
                args.append(
                    {
                        "value": str(arg.get("value") or ""),
                        "quoting": arg.get("quoting"),
                    }
                )
            else:
                args.append(str(arg))
        tasks.append(
            {
                "name": str(task.get("name") or ""),
                "source": str(task.get("source") or ""),
                "definitionType": str(definition.get("type") or ""),
                "definitionCommand": str(definition.get("command") or ""),
                "commandLine": str(execution.get("commandLine") or ""),
                "args": args,
                "cwd": str((execution.get("options") or {}).get("cwd") or "") if isinstance(execution.get("options"), dict) else "",
            }
        )
    return unique_json_items(tasks)


def composer_output_events(wizp_result: dict[str, Any]) -> list[dict[str, Any]]:
    events = composer_wizp_events(wizp_result)
    side_effects = wizp_result.get("sideEffects") if isinstance(wizp_result.get("sideEffects"), dict) else {}
    outputs = side_effects.get("outputs") if isinstance(side_effects.get("outputs"), list) else []
    rows: list[dict[str, Any]] = []
    for event in [*events, *[item for item in outputs if isinstance(item, dict)]]:
        if event.get("type") not in {"output", "outputTrace"} and "channel" not in event:
            continue
        channel = str(event.get("channel") or "")
        text = str(event.get("text") or "")
        if "Composer" not in channel and "composer" not in channel and "composer" not in text:
            continue
        rows.append({"channel": channel, "action": str(event.get("action") or ""), "text": text[:240]})
    return unique_json_items(rows)


def composer_terminal_events(wizp_result: dict[str, Any]) -> list[dict[str, Any]]:
    side_effects = wizp_result.get("sideEffects") if isinstance(wizp_result.get("sideEffects"), dict) else {}
    terminals = side_effects.get("terminals") if isinstance(side_effects.get("terminals"), list) else []
    rows: list[dict[str, Any]] = []
    for event in composer_wizp_events(wizp_result):
        if str(event.get("type") or "").startswith("terminal"):
            rows.append(event)
    for terminal in terminals:
        if isinstance(terminal, dict):
            rows.append(terminal)
    return unique_json_items(rows)


def composer_configuration_reads(wizp_result: dict[str, Any]) -> list[dict[str, Any]]:
    debug_state = wizp_result.get("debugState") if isinstance(wizp_result.get("debugState"), dict) else {}
    reads = debug_state.get("configurationReads") if isinstance(debug_state.get("configurationReads"), list) else []
    wanted = {"composer.bin", "composer.workingPath", "php.executablePath"}
    result: list[dict[str, Any]] = []
    for read in reads:
        if not isinstance(read, dict):
            continue
        key = str(read.get("key") or "")
        if key not in wanted:
            continue
        result.append(
            {
                "key": key,
                "section": str(read.get("section") or ""),
                "kind": str(read.get("kind") or ""),
                "value": read.get("value"),
                "defaultValue": read.get("defaultValue"),
            }
        )
    return unique_json_items(result)


def composer_configuration_value(reads: list[dict[str, Any]], key: str) -> Any:
    for read in reads:
        if read.get("key") == key:
            return read.get("value")
    return None


def composer_activation_errors(wizp_result: dict[str, Any], reference_result: dict[str, Any]) -> tuple[list[Any], list[Any]]:
    wizp_errors: list[Any] = []
    startup = wizp_result.get("startupActivationErrors") if isinstance(wizp_result.get("startupActivationErrors"), dict) else {}
    if isinstance(startup.get("errors"), list):
        wizp_errors.extend(startup.get("errors") or [])
    side_effects = wizp_result.get("sideEffects") if isinstance(wizp_result.get("sideEffects"), dict) else {}
    if isinstance(side_effects.get("activationErrors"), list):
        wizp_errors.extend(side_effects.get("activationErrors") or [])
    probe_result = reference_result.get("probeResult") if isinstance(reference_result.get("probeResult"), dict) else {}
    reference_side_effects = probe_result.get("sideEffects") if isinstance(probe_result.get("sideEffects"), dict) else {}
    reference_errors = reference_side_effects.get("activationErrors") if isinstance(reference_side_effects.get("activationErrors"), list) else []
    return unique_json_items(wizp_errors), unique_json_items(reference_errors)


def composer_command_results(artifact: dict[str, Any]) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    wizp_result = artifact.get("wizpResult") if isinstance(artifact.get("wizpResult"), dict) else {}
    reference_result = artifact.get("referenceResult") if isinstance(artifact.get("referenceResult"), dict) else {}
    probe_result = reference_result.get("probeResult") if isinstance(reference_result.get("probeResult"), dict) else {}
    wizp_commands = wizp_result.get("activationCommands") if isinstance(wizp_result.get("activationCommands"), list) else []
    reference_commands = (
        probe_result.get("activationCommandResults") if isinstance(probe_result.get("activationCommandResults"), list) else []
    )
    return (
        [item for item in wizp_commands if isinstance(item, dict)],
        [item for item in reference_commands if isinstance(item, dict)],
    )


def composer_commands_executed(
    expected_commands: list[str],
    wizp_commands: list[dict[str, Any]],
    reference_commands: list[dict[str, Any]],
) -> bool:
    for command in expected_commands:
        wizp = next((item for item in wizp_commands if item.get("command") == command), {})
        reference = next((item for item in reference_commands if item.get("command") == command), {})
        if wizp.get("status") != "wizp-command-executed":
            return False
        if reference.get("status") != "reference-command-executed":
            return False
    return True


def composer_task_spawn_processes(
    spawned: list[dict[str, Any]],
    expected_actions: set[str],
) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for item in spawned:
        command = str(item.get("command") or "")
        args = [str(arg) for arg in item.get("args", [])] if isinstance(item.get("args"), list) else []
        if command != "php":
            continue
        if not any(Path(arg).name == "composer" for arg in args):
            continue
        action = next((arg for arg in args if arg in expected_actions), "")
        if not action:
            continue
        rows.append({"command": command, "args": args, "composerAction": action})
    return unique_json_items(sorted(rows, key=json_signature))


def composer_reference_lint_processes(spawned: list[dict[str, Any]]) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for item in spawned:
        command = str(item.get("command") or "")
        args = [str(arg) for arg in item.get("args", [])] if isinstance(item.get("args"), list) else []
        if command != "php":
            continue
        if "-l" not in args or "-f" not in args:
            continue
        if not any(arg.endswith("/src/sample.php") or arg.endswith("${fixtureWorkspace}/src/sample.php") for arg in args):
            continue
        rows.append({"command": command, "args": args})
    return unique_json_items(sorted(rows, key=json_signature))


def composer_empty_diagnostics(events: list[dict[str, Any]]) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for event in events:
        if event.get("type") != "setDiagnostics":
            continue
        uri = str(event.get("uri") or "")
        if not uri.endswith("/composer.json"):
            continue
        diagnostics = event.get("diagnostics") if isinstance(event.get("diagnostics"), list) else []
        rows.append({"uri": uri, "diagnosticCount": len(diagnostics)})
    return unique_json_items(rows)


def composer_network_rows(runtime_processes: dict[str, Any]) -> list[dict[str, Any]]:
    rows = runtime_processes.get("networkAudit") if isinstance(runtime_processes.get("networkAudit"), list) else []
    result: list[dict[str, Any]] = []
    for row in rows:
        if not isinstance(row, dict):
            continue
        result.append(
            {
                "host": str(row.get("host") or ""),
                "module": str(row.get("module") or ""),
                "passthrough": str(row.get("passthrough") or ""),
                "allowlisted": bool(row.get("allowlisted")),
                "requestEnded": bool(row.get("requestEnded")),
                "responseStatus": row.get("responseStatus"),
            }
        )
    return unique_json_items(result)


def composer_payload_evidence(
    extension_id: str,
    scenario_id: str,
    artifact: dict[str, Any],
) -> dict[str, Any]:
    if not generic_composer_payload_scenario(extension_id, scenario_id):
        return {}
    artifact_path = rel(scenario_artifact_path(extension_id, scenario_id))
    wizp_result = artifact.get("wizpResult") if isinstance(artifact.get("wizpResult"), dict) else {}
    reference_result = artifact.get("referenceResult") if isinstance(artifact.get("referenceResult"), dict) else {}
    probe_result = reference_result.get("probeResult") if isinstance(reference_result.get("probeResult"), dict) else {}
    reference_side_effects = probe_result.get("sideEffects") if isinstance(probe_result.get("sideEffects"), dict) else {}
    events = composer_wizp_events(wizp_result)
    messages = composer_message_events(events)
    task_events = composer_task_execution_events(events)
    output_events = composer_output_events(wizp_result)
    terminal_events = composer_terminal_events(wizp_result)
    config_reads = composer_configuration_reads(wizp_result)
    wizp_commands, reference_commands = composer_command_results(artifact)
    wizp_errors, reference_errors = composer_activation_errors(wizp_result, reference_result)
    command_runtime = (
        wizp_result.get("commandScopedRuntimeProcesses")
        if isinstance(wizp_result.get("commandScopedRuntimeProcesses"), dict)
        else {}
    )
    wizp_command_spawned, wizp_command_dropped = normalize_runtime_spawn_processes(command_runtime, drop_workspace_git_probe=True)
    reference_runtime = (
        reference_side_effects.get("runtimeProcesses") if isinstance(reference_side_effects.get("runtimeProcesses"), dict) else {}
    )
    reference_spawned, reference_dropped = normalize_runtime_spawn_processes(reference_runtime, drop_workspace_git_probe=True)

    if scenario_id == "composer-valid-commands":
        expected_commands = ["composer.about", "composer.install", "composer.update"]
        expected_task_actions = {"about", "install", "update"}
        task_commands = sorted({str(item.get("definitionCommand") or "") for item in task_events})
        command_ok = (
            composer_commands_executed(expected_commands, wizp_commands, reference_commands)
            and expected_task_actions <= set(task_commands)
            and not wizp_errors
            and not reference_errors
        )
        diagnostic_rows = composer_empty_diagnostics(events)
        diagnostics_ok = bool(diagnostic_rows) and all(int(row.get("diagnosticCount") or 0) == 0 for row in diagnostic_rows)
        wizp_task_processes = composer_task_spawn_processes(wizp_command_spawned, expected_task_actions)
        reference_lint_processes = composer_reference_lint_processes(reference_spawned)
        task_process_actions = {str(item.get("composerAction") or "") for item in wizp_task_processes}
        process_ok = expected_task_actions <= task_process_actions and bool(reference_lint_processes)
        return {
            "commandInvocations": {
                "status": "matched-composer-command-invocations" if command_ok else "composer-command-invocations-incomplete",
                "artifact": artifact_path,
                "expectedCommands": expected_commands,
                "wizpCommands": wizp_commands,
                "referenceCommands": reference_commands,
                "wizpTasks": task_events,
                "wizpActivationErrors": wizp_errors,
                "referenceActivationErrors": reference_errors,
            },
            "outputChannel": {
                "status": "matched-composer-output-channel" if output_events else "composer-output-channel-missing",
                "artifact": artifact_path,
                "wizpOutputEvents": output_events,
                "note": "The valid command lane requires WIZP to mirror extension task execution into an output channel so command output is reviewable.",
            },
            "terminalOutput": {
                "status": "matched-composer-terminal-output" if terminal_events else "composer-terminal-output-missing",
                "artifact": artifact_path,
                "wizpTerminalEvents": terminal_events,
                "wizpTasks": task_events,
            },
            "errorParsing": {
                "status": "matched-composer-json-error-parsing-clean" if diagnostics_ok else "composer-json-diagnostics-missing",
                "artifact": artifact_path,
                "diagnostics": diagnostic_rows,
            },
            "processAudit": {
                "status": "matched-composer-process-audit" if process_ok else "composer-task-process-gap",
                "artifact": artifact_path,
                "wizpOwnedSpawnedProcesses": wizp_command_spawned,
                "wizpComposerTaskProcesses": wizp_task_processes,
                "referenceOwnedSpawnedProcesses": reference_spawned,
                "referencePhpLintProcesses": reference_lint_processes,
                "droppedWizpBackgroundProcesses": wizp_command_dropped,
                "droppedReferenceBackgroundProcesses": reference_dropped,
                "note": "This row separates WIZP-owned task process launches from the bounded reference-side PHP lint subprocesses captured after Composer command execution.",
            },
        }

    if scenario_id == "composer-missing-tools":
        expected_commands = ["composer.install"]
        command_ok = composer_commands_executed(expected_commands, wizp_commands, reference_commands) and not wizp_errors and not reference_errors
        warning_messages = [
            message
            for message in messages
            if "composer.lock" in str(message.get("message") or "") and "not installed" in str(message.get("message") or "")
        ]
        action_labels = sorted({label for message in warning_messages for label in message.get("actionLabels", [])})
        settings_ok = (
            composer_configuration_value(config_reads, "composer.bin") == "/tmp/wizp-missing-composer"
            and composer_configuration_value(config_reads, "php.executablePath") == "/tmp/wizp-missing-php"
            and any(
                task.get("commandLine") == "/tmp/wizp-missing-php"
                and any(isinstance(arg, dict) and arg.get("value") == "/tmp/wizp-missing-composer" for arg in task.get("args", []))
                for task in task_events
            )
        )
        wizp_runtime = extract_wizp_runtime_processes(artifact)
        reference_runtime_all = extract_reference_runtime_processes(artifact)
        wizp_network = composer_network_rows(wizp_runtime)
        reference_network = composer_network_rows(reference_runtime_all)
        command_network = composer_network_rows(command_runtime)
        telemetry_ok = (
            bool(wizp_network)
            and all(row.get("passthrough") == "blocked" for row in wizp_network)
            and any("dc.services.visualstudio.com" in str(row.get("host") or "") for row in wizp_network)
            and not reference_network
            and not command_network
        )
        process_ok = command_ok and not wizp_command_spawned and not reference_spawned
        return {
            "notifications": {
                "status": "matched-composer-degraded-notification" if warning_messages else "composer-degraded-notification-missing",
                "artifact": artifact_path,
                "messages": warning_messages,
                "allComposerMessages": messages,
            },
            "actionButtons": {
                "status": (
                    "matched-composer-degraded-action-buttons"
                    if {"Install", "Don't show again"} <= set(action_labels)
                    else "composer-degraded-action-buttons-missing"
                ),
                "artifact": artifact_path,
                "actionLabels": action_labels,
            },
            "settingsIntent": {
                "status": "matched-composer-missing-tool-settings-intent" if settings_ok else "composer-missing-tool-settings-incomplete",
                "artifact": artifact_path,
                "configurationReads": config_reads,
                "wizpTasks": task_events,
            },
            "telemetryAudit": {
                "status": "matched-composer-blocked-telemetry-audit" if telemetry_ok else "composer-telemetry-audit-incomplete",
                "artifact": artifact_path,
                "wizpNetworkAudit": wizp_network,
                "referenceNetworkAudit": reference_network,
                "commandScopedNetworkAudit": command_network,
                "note": "The only captured WIZP network attempt is the Composer extension's startup Application Insights request, blocked by the host; the command-scoped missing-tool path performs no network passthrough.",
            },
            "processAudit": {
                "status": "matched-composer-missing-tool-process-audit" if process_ok else "composer-missing-tool-process-audit-incomplete",
                "artifact": artifact_path,
                "wizpOwnedSpawnedProcesses": wizp_command_spawned,
                "referenceOwnedSpawnedProcesses": reference_spawned,
                "droppedWizpBackgroundProcesses": wizp_command_dropped,
                "droppedReferenceBackgroundProcesses": reference_dropped,
                "wizpCommands": wizp_commands,
                "referenceCommands": reference_commands,
            },
        }

    return {}


def apply_generic_payload_validation(
    extension_id: str,
    scenario: dict[str, Any],
    artifact: dict[str, Any],
) -> dict[str, Any]:
    scenario_id = str(scenario.get("id") or "")
    evidence = java_lifecycle_payload_evidence(extension_id, scenario_id, artifact)
    composer_evidence = composer_payload_evidence(extension_id, scenario_id, artifact)
    if composer_evidence:
        evidence = {**evidence, **composer_evidence}
    if not evidence:
        return artifact
    merged_evidence = artifact.get("evidence") if isinstance(artifact.get("evidence"), dict) else {}
    merged_evidence = {**merged_evidence, **evidence}
    pending_expected_evidence = scenario_pending_from_evidence(scenario, merged_evidence)
    blockers = scenario_blocker_tokens(artifact)
    if not blockers and not pending_expected_evidence:
        artifact["status"] = (
            "paired-composer-payload-scenario-verified"
            if composer_evidence
            else "paired-lifecycle-payload-scenario-verified"
        )
        normalized_status = "paired-scenario-evidence-matched"
    elif any(evidence_entry_matched(entry) for entry in merged_evidence.values()):
        artifact["status"] = (
            "paired-composer-payload-scenario-partial"
            if composer_evidence
            else "paired-lifecycle-payload-scenario-partial"
        )
        normalized_status = "paired-scenario-evidence-partial"
    else:
        normalized_status = artifact.get("normalizedDiff", {}).get("status", "not-run")
    artifact["evidence"] = merged_evidence
    artifact["pendingExpectedEvidence"] = pending_expected_evidence
    artifact["genericPayloadEvidence"] = {
        "status": "verified" if not blockers and not pending_expected_evidence else "partial",
        "matchedEvidence": sorted(
            item
            for item in evidence
            if evidence_entry_matched(evidence.get(item))
        ),
        "residualExpectedEvidence": pending_expected_evidence,
    }
    artifact["blockers"] = sorted(set(str(item) for item in blockers if str(item)))
    normalized = artifact.get("normalizedDiff") if isinstance(artifact.get("normalizedDiff"), dict) else {}
    normalized["status"] = normalized_status
    normalized["acceptedDifferences"] = unique_json_items(normalized.get("acceptedDifferences", []))
    existing_notes = str(normalized.get("notes") or "").strip()
    note = (
        "Scenario-specific generic-payload verifier promotes lifecycle or Composer behavior only when every declared evidence key is matched. "
        "Performance-budget blockers remain owned by H11E."
    )
    normalized["notes"] = f"{existing_notes} {note}".strip() if existing_notes and note not in existing_notes else (existing_notes or note)
    if pending_expected_evidence:
        normalized["residualExpectedEvidence"] = pending_expected_evidence
    artifact["normalizedDiff"] = normalized
    return artifact


def evidence_entry_matched(entry: Any) -> bool:
    return isinstance(entry, dict) and str(entry.get("status") or "").startswith("matched-")


def scenario_pending_from_evidence(scenario: dict[str, Any], evidence: dict[str, Any]) -> list[str]:
    pending: list[str] = []
    for item in scenario.get("expectedEvidence", []):
        if not isinstance(item, str) or not item:
            continue
        if evidence_entry_matched(evidence.get(item)):
            continue
        pending.append(item)
    return pending


def tree_view_residual_surface_scenario(extension_id: str, scenario_id: str) -> bool:
    return (extension_id, scenario_id) == (
        "vscjava.vscode-java-dependency",
        "java-dependency-explorer",
    )


def java_pack_child_rollup_scenario(extension_id: str, scenario_id: str) -> bool:
    return (extension_id, scenario_id) == (
        "vscjava.vscode-java-pack",
        "java-pack-child-rollup",
    )


def tree_view_refresh_commands(extension_id: str, scenario_id: str) -> list[str]:
    if tree_view_residual_surface_scenario(extension_id, scenario_id):
        return [
            "java.view.package.refresh",
            "java.project.refreshLibraries",
            "java.project.update",
        ]
    return []


def tree_view_residual_surface_evidence(
    extension_id: str,
    scenario_id: str,
    artifact: dict[str, Any],
    view_artifact: dict[str, Any],
) -> dict[str, Any]:
    if not tree_view_residual_surface_scenario(extension_id, scenario_id):
        return {}
    evidence: dict[str, Any] = {}
    artifact_path = rel(scenario_artifact_path(extension_id, scenario_id))
    view_artifact_path = rel(view_probe_path(extension_id, scenario_id))
    wizp_result = artifact.get("wizpResult") if isinstance(artifact.get("wizpResult"), dict) else {}
    wizp_messages = wizp_debug_config_messages(artifact)
    reference_messages = reference_debug_config_messages(artifact)
    wizp_runtime = extract_wizp_runtime_processes(artifact)
    reference_runtime = extract_reference_runtime_processes(artifact)
    wizp_spawned, wizp_dropped = normalize_runtime_spawn_processes(wizp_runtime, drop_workspace_git_probe=True)
    reference_spawned, reference_dropped = normalize_runtime_spawn_processes(reference_runtime, drop_workspace_git_probe=True)
    wizp_forked = wizp_runtime.get("forkedProcesses") if isinstance(wizp_runtime.get("forkedProcesses"), list) else []
    reference_forked = reference_runtime.get("forkedProcesses") if isinstance(reference_runtime.get("forkedProcesses"), list) else []
    network_ok = runtime_network_audit_count(wizp_runtime) == 0 and runtime_network_audit_count(reference_runtime) == 0
    process_ok = not wizp_spawned and not reference_spawned and not wizp_forked and not reference_forked and network_ok
    messages_ok = not wizp_messages and not reference_messages
    view_points = [
        str(item)
        for item in view_artifact.get("viewProbePoints", [])
        if isinstance(item, str)
    ]
    promotion_ready = view_artifact.get("promotionReady") is True
    refresh_commands = tree_view_refresh_commands(extension_id, scenario_id)
    refresh_entries = command_entries_for_ids(wizp_result.get("commandsAfterOpen"), refresh_commands)
    refresh_ok = (
        promotion_ready
        and {"treeNodes", "commands"}.issubset(set(view_points))
        and len(refresh_entries) == len(refresh_commands)
        and all(entry.get("enabled") is True for entry in refresh_entries)
    )
    evidence["refreshState"] = {
        "status": "matched-tree-refresh-surface" if refresh_ok else "tree-refresh-surface-incomplete",
        "artifact": artifact_path,
        "viewArtifact": view_artifact_path,
        "requiredCommands": refresh_commands,
        "wizpRefreshCommands": refresh_entries,
        "viewProbePromotionReady": promotion_ready,
        "viewProbePoints": view_points,
        "note": "This verifies the bounded tree-view refresh surface: contributed Java dependency refresh/update commands plus promotion-ready H07 tree/view evidence. It does not claim an external JDT project refresh completed.",
    }
    evidence["messages"] = {
        "status": "matched-no-tree-view-messages" if messages_ok else "tree-view-message-drift",
        "artifact": artifact_path,
        "wizpMessages": wizp_messages[-8:],
        "referenceMessages": reference_messages[-8:],
    }
    evidence["processAudit"] = {
        "status": "matched-bounded-tree-view-process-audit" if process_ok else "tree-view-process-audit-drift",
        "artifact": artifact_path,
        "wizpOwnedSpawnedProcesses": wizp_spawned,
        "referenceOwnedSpawnedProcesses": reference_spawned,
        "wizpForkedProcesses": wizp_forked,
        "referenceForkedProcesses": reference_forked,
        "wizpDroppedBackgroundProcesses": wizp_dropped,
        "referenceDroppedBackgroundProcesses": reference_dropped,
        "wizpNetworkAuditCount": runtime_network_audit_count(wizp_runtime),
        "referenceNetworkAuditCount": runtime_network_audit_count(reference_runtime),
    }
    return evidence


def extension_pack_children(package: dict[str, Any]) -> list[str]:
    return sorted(
        {
            str(child)
            for child in [
                *(package.get("extensionPack", []) if isinstance(package.get("extensionPack"), list) else []),
                *(package.get("extensionDependencies", []) if isinstance(package.get("extensionDependencies"), list) else []),
            ]
            if isinstance(child, str) and child
        }
    )


def installed_extension_ids(entries: Any) -> set[str]:
    if not isinstance(entries, list):
        return set()
    ids: set[str] = set()
    for entry in entries:
        if not isinstance(entry, str):
            continue
        extension_id = entry.split("@", 1)[0].strip()
        if extension_id:
            ids.add(extension_id)
    return ids


def active_extension_ids(entries: Any) -> set[str]:
    if not isinstance(entries, list):
        return set()
    return {
        str(entry.get("id") or "")
        for entry in entries
        if isinstance(entry, dict)
        and str(entry.get("id") or "")
        and ("isActive" not in entry or entry.get("isActive") is True)
    }


def activation_error_entries(value: Any) -> list[dict[str, Any]]:
    if not isinstance(value, dict):
        return []
    errors = value.get("errors")
    return [item for item in errors if isinstance(item, dict)] if isinstance(errors, list) else []


def java_pack_child_rollup_evidence(
    extension_id: str,
    scenario_id: str,
    artifact: dict[str, Any],
    view_artifact: dict[str, Any],
    baseline: dict[str, Any],
) -> dict[str, Any]:
    if not java_pack_child_rollup_scenario(extension_id, scenario_id):
        return {}
    evidence: dict[str, Any] = {}
    artifact_path = rel(scenario_artifact_path(extension_id, scenario_id))
    view_artifact_path = rel(view_probe_path(extension_id, scenario_id))
    baseline_row = baseline_extension(baseline, extension_id)
    package_json = read_vsix_package_json((baseline_row.get("vsix") or {}) if isinstance(baseline_row.get("vsix"), dict) else {})
    package = package_summary(package_json)
    manifest_children = extension_pack_children(package)
    unsupported_children = unsupported_dependencies_for(baseline, extension_id)
    unsupported_ids = {
        str(item.get("dependency") or item.get("id") or "")
        for item in unsupported_children
        if isinstance(item, dict) and (item.get("dependency") or item.get("id"))
    }
    supported_children = sorted(child for child in manifest_children if child not in unsupported_ids)

    reference_result = artifact.get("referenceResult") if isinstance(artifact.get("referenceResult"), dict) else {}
    install_evidence = reference_result.get("installEvidence") if isinstance(reference_result.get("installEvidence"), dict) else {}
    reference_probe = reference_result.get("probeResult") if isinstance(reference_result.get("probeResult"), dict) else {}
    installed_ids = installed_extension_ids(install_evidence.get("installedExtensions"))
    reference_active_ids = active_extension_ids(reference_probe.get("activeExtensions"))
    reference_active_children = sorted(reference_active_ids & set(supported_children))
    wizp_result = artifact.get("wizpResult") if isinstance(artifact.get("wizpResult"), dict) else {}
    extra_installs = wizp_result.get("extraExtensionInstalls") if isinstance(wizp_result.get("extraExtensionInstalls"), list) else []
    wizp_installed_ids = {extension_id}
    for install in extra_installs:
        if not isinstance(install, dict):
            continue
        if str(install.get("status") or "").startswith("installed") and str(install.get("extensionId") or ""):
            wizp_installed_ids.add(str(install.get("extensionId") or ""))
    reference_graph_ok = (
        package.get("id") == extension_id
        and bool(manifest_children)
        and install_evidence.get("status") == "installed-and-listed"
        and extension_id in installed_ids
        and set(supported_children).issubset(installed_ids)
    )
    wizp_graph_ok = extension_id in wizp_installed_ids and set(supported_children).issubset(wizp_installed_ids)

    wizp_activation_events = wizp_result.get("activationEvents") if isinstance(wizp_result.get("activationEvents"), list) else []
    wizp_activation_errors = activation_error_entries(wizp_result.get("activationErrorsFinal")) or activation_error_entries(wizp_result.get("activationErrors"))
    wizp_debug_state = wizp_result.get("debugState") if isinstance(wizp_result.get("debugState"), dict) else {}
    wizp_active_ids = active_extension_ids(wizp_debug_state.get("extensions"))
    reference_log_audit = reference_result.get("logAudit") if isinstance(reference_result.get("logAudit"), dict) else {}
    reference_error_lines = reference_log_audit.get("errorLinesTail") if isinstance(reference_log_audit.get("errorLinesTail"), list) else []
    reference_active_ok = extension_id in reference_active_ids and bool(reference_active_children)
    wizp_active_ok = extension_id in wizp_active_ids and set(reference_active_children).issubset(wizp_active_ids)
    activation_ok = reference_active_ok and wizp_active_ok
    wizp_parent_activation_failed = bool(wizp_activation_errors) or any(
        isinstance(event, dict) and str(event.get("status") or "") == "activation-error"
        for event in wizp_activation_events
    )

    evidence["dependencyGraph"] = {
        "status": "matched-extension-pack-dependency-graph" if reference_graph_ok and wizp_graph_ok else "extension-pack-dependency-graph-incomplete",
        "artifact": artifact_path,
        "viewArtifact": view_artifact_path,
        "manifestChildren": manifest_children,
        "supportedChildren": supported_children,
        "referenceInstalledExtensions": sorted(installed_ids),
        "referenceInstallStatus": install_evidence.get("status", ""),
        "wizpInstalledExtensions": sorted(wizp_installed_ids),
        "wizpExtraExtensionInstalls": extra_installs,
        "note": "This matches the pinned Java Pack manifest graph against isolated reference-host install/list evidence and WIZP child-extension install evidence. It does not claim child activation order is complete.",
    }
    evidence["unsupportedChildren"] = {
        "status": "matched-no-unsupported-extension-pack-children" if reference_graph_ok and not unsupported_children else "extension-pack-unsupported-child-classification-incomplete",
        "artifact": artifact_path,
        "unsupportedChildren": unsupported_children,
        "unsupportedChildIds": sorted(unsupported_ids),
        "manifestChildren": manifest_children,
    }
    evidence["activationOrder"] = {
        "status": "matched-extension-pack-activation-surface" if activation_ok else ("extension-pack-activation-order-blocked" if wizp_parent_activation_failed or not wizp_active_ok else "extension-pack-activation-order-incomplete"),
        "artifact": artifact_path,
        "referenceActiveChildren": reference_active_children,
        "referenceActiveParent": extension_id in reference_active_ids,
        "referenceActiveOrderComplete": reference_active_ok,
        "wizpActiveChildren": sorted(wizp_active_ids & set(supported_children)),
        "wizpActiveParent": extension_id in wizp_active_ids,
        "wizpActiveOrderComplete": wizp_active_ok,
        "wizpActivationEvents": wizp_activation_events,
        "wizpActivationErrors": wizp_activation_errors,
        "note": "This compares WIZP's active Java Pack child set with the fixture-relevant child set activated by the reference host. Manifest children that do not activate for the Maven fixture, such as Gradle, remain covered by dependency-graph evidence.",
    }
    evidence["messages"] = {
        "status": "extension-pack-message-drift" if wizp_parent_activation_failed or reference_error_lines else "extension-pack-message-evidence-incomplete",
        "artifact": artifact_path,
        "wizpActivationErrors": wizp_activation_errors,
        "referenceErrorLinesTail": reference_error_lines[-8:],
        "referenceLogErrorLineCount": reference_log_audit.get("errorLineCount"),
        "note": "Message closure stays pending while WIZP has activation errors or the reference run records Java child shutdown/log errors.",
    }
    return evidence


def view_payload_scenario_evidence(
    scenario: dict[str, Any],
    view_artifact: dict[str, Any],
) -> tuple[dict[str, Any], list[str], list[str], dict[str, Any]]:
    expected = [str(item) for item in scenario.get("expectedEvidence", []) if isinstance(item, str)]
    view_points = [
        str(item)
        for item in view_artifact.get("viewProbePoints", [])
        if isinstance(item, str) and item in VIEW_EVIDENCE_KEYS
    ]
    expected_view_points = [item for item in expected if item in VIEW_EVIDENCE_KEYS]
    residual_expected = [item for item in expected if item not in VIEW_EVIDENCE_KEYS]
    promotion_ready = view_artifact.get("promotionReady") is True
    artifact_path = rel(
        view_probe_path(
            str(view_artifact.get("extensionId") or ""),
            str(view_artifact.get("scenarioId") or ""),
        )
    )
    evidence: dict[str, Any] = {}
    matched_expected: list[str] = []
    missing_expected: list[str] = []
    for item in expected_view_points:
        if promotion_ready and item in view_points:
            matched_expected.append(item)
            evidence[item] = {
                "status": "matched-view-payload",
                "artifact": artifact_path,
                "batchId": str(view_artifact.get("batchId") or ""),
                "note": "H07 paired view probe is promotion-ready for this scenario evidence key.",
            }
        else:
            missing_expected.append(item)
            evidence[item] = {
                "status": "view-payload-missing",
                "artifact": artifact_path,
                "batchId": str(view_artifact.get("batchId") or ""),
                "promotionReady": promotion_ready,
            }
    summary = {
        "viewProbePoints": view_points,
        "scenarioRequiredPromotionEvidence": [
            str(item)
            for item in view_artifact.get("requiredPromotionEvidence", [])
            if isinstance(item, str)
        ],
        "matchedViewEvidence": sorted(matched_expected),
        "missingViewEvidence": sorted(missing_expected),
        "residualExpectedEvidence": residual_expected,
        "viewPayloadMatched": bool(expected_view_points) and not missing_expected,
    }
    return evidence, missing_expected + residual_expected, residual_expected, summary


def composite_view_status(artifact: dict[str, Any], suffix: str) -> str:
    if isinstance(artifact.get("debugTaskEvidence"), dict):
        return f"paired-view-debug-task-payload-scenario-{suffix}"
    if isinstance(artifact.get("providerEvidence"), dict):
        return f"paired-view-provider-payload-scenario-{suffix}"
    return f"paired-view-payload-scenario-{suffix}"


def apply_view_payload_validation(
    extension_id: str,
    scenario: dict[str, Any],
    baseline: dict[str, Any],
    artifact: dict[str, Any],
    generated_at: str,
) -> dict[str, Any]:
    scenario_id = str(scenario.get("id") or "")
    batch_id = VIEW_PROBE_SCENARIO_BATCHES.get((extension_id.lower(), scenario_id), "")
    if not batch_id:
        return artifact
    existing_status = str(artifact.get("status") or "")
    existing_pending = artifact.get("pendingExpectedEvidence")
    already_verified = (existing_status == "verified" or existing_status.endswith("-verified")) and not existing_pending
    view_record = write_view_probe_artifact(
        batch_id,
        extension_id,
        scenario,
        baseline,
        artifact,
        generated_at,
    )
    view_artifact = load_json_if_exists(view_probe_path(extension_id, scenario_id))
    view_evidence, _view_pending, residual_expected, summary = view_payload_scenario_evidence(scenario, view_artifact)
    residual_evidence = tree_view_residual_surface_evidence(extension_id, scenario_id, artifact, view_artifact)
    residual_evidence.update(java_pack_child_rollup_evidence(extension_id, scenario_id, artifact, view_artifact, baseline))
    artifact["viewEvidence"] = {
        "artifact": rel(view_probe_path(extension_id, scenario_id)),
        "status": view_record.get("status", ""),
        "promotionReady": view_record.get("promotionReady"),
        "batchId": view_record.get("batchId", ""),
        "summary": summary,
    }
    merged_evidence = artifact.get("evidence") if isinstance(artifact.get("evidence"), dict) else {}
    merged_evidence = {**merged_evidence, **view_evidence, **residual_evidence}
    artifact["evidence"] = merged_evidence
    if already_verified or not summary["viewProbePoints"]:
        return artifact

    pending_expected_evidence = scenario_pending_from_evidence(scenario, merged_evidence)
    residual_expected = [
        item
        for item in residual_expected
        if not evidence_entry_matched(merged_evidence.get(item))
    ]
    summary["matchedResidualEvidence"] = sorted(
        item
        for item in residual_evidence
        if evidence_entry_matched(residual_evidence.get(item))
    )
    summary["residualExpectedEvidence"] = residual_expected
    blockers = scenario_blocker_tokens(artifact)
    if not view_record.get("promotionReady") and summary["viewProbePoints"]:
        blockers.extend(
            str(item)
            for item in view_record.get("missingPromotionEvidence", [])
            if isinstance(item, str)
        )
        blockers.append(str(view_record.get("status") or "view-payload-incomplete"))

    if not blockers and not pending_expected_evidence:
        artifact["status"] = composite_view_status(artifact, "verified")
        normalized_status = "paired-scenario-evidence-matched"
    elif any(evidence_entry_matched(entry) for entry in merged_evidence.values()):
        artifact["status"] = composite_view_status(artifact, "partial")
        normalized_status = "paired-scenario-evidence-partial"
    else:
        normalized_status = artifact.get("normalizedDiff", {}).get("status", "not-run")

    artifact["blockers"] = sorted(set(str(item) for item in blockers if str(item)))
    artifact["pendingExpectedEvidence"] = pending_expected_evidence
    normalized = artifact.get("normalizedDiff") if isinstance(artifact.get("normalizedDiff"), dict) else {}
    normalized["status"] = normalized_status
    normalized["acceptedDifferences"] = unique_json_items(normalized.get("acceptedDifferences", []))
    note = (
        "H07 view-probe promotion satisfies only expected view/tree/status/UI evidence keys with a promotion-ready paired view artifact. "
        "Rows with matched view evidence but residual runtime, message, policy, process, task, or SCM evidence stay partial."
    )
    existing_notes = str(normalized.get("notes") or "").strip()
    normalized["notes"] = f"{existing_notes} {note}".strip() if existing_notes and note not in existing_notes else (existing_notes or note)
    normalized["matchedViewEvidence"] = summary["matchedViewEvidence"]
    normalized["missingViewEvidence"] = summary["missingViewEvidence"]
    normalized["viewProbeStatus"] = view_record.get("status", "")
    normalized["viewProbePromotionReady"] = view_record.get("promotionReady")
    if residual_expected:
        normalized["residualExpectedEvidence"] = pending_expected_evidence
    artifact["normalizedDiff"] = normalized
    return artifact


def build_provider_diff(
    rows: list[dict[str, Any]],
    manifests: dict[str, dict[str, Any]],
    baseline: dict[str, Any],
    generated_at: str,
) -> dict[str, Any]:
    baseline_by_id = {str(item["id"]): item for item in baseline.get("extensions", [])}
    reference = baseline.get("referenceHost", {})
    reference_ready = bool(reference.get("executable") and reference.get("version"))
    results: list[dict[str, Any]] = []
    total_probe_points = 0
    provider_scenarios = 0
    paired_scenarios = 0
    matched_probe_points = 0
    drift_probe_points = 0
    blocked_probe_points = 0
    for row in rows:
        extension_id = str(row["id"])
        baseline_row = baseline_by_id.get(extension_id, {})
        package_json = read_vsix_package_json(baseline_row.get("vsix", {}))
        scenario_manifest = manifests.get(extension_id.lower(), {})
        scenarios: list[dict[str, Any]] = []
        for scenario in scenario_manifest.get("scenarios", []):
            if not isinstance(scenario, dict):
                continue
            expected = [str(item) for item in scenario.get("expectedEvidence", [])]
            provider_points = [item for item in expected if item in PROVIDER_EVIDENCE_KEYS]
            if not provider_points:
                continue
            provider_scenarios += 1
            total_probe_points += len(provider_points)
            artifact_path = provider_probe_artifact_path(extension_id, str(scenario["id"]))
            if reference_ready:
                artifact = run_provider_probe_artifact({"extensionId": extension_id}, scenario, baseline, generated_at)
                artifact_path.parent.mkdir(parents=True, exist_ok=True)
                write_json(artifact_path, artifact)
                normalized = artifact.get("normalizedDiff", {}) if isinstance(artifact.get("normalizedDiff"), dict) else {}
                matched_probe_points += int(normalized.get("matchedPointCount") or 0)
                drift_probe_points += int(normalized.get("driftPointCount") or 0)
                blocked_probe_points += int(normalized.get("blockedPointCount") or 0)
                if str(artifact.get("status") or "").startswith("paired-provider-payload-"):
                    paired_scenarios += 1
                scenarios.append(
                    {
                        "scenarioId": scenario["id"],
                        "backlogIds": scenario.get("backlogIds", []),
                        "fixture": scenario.get("fixture", ""),
                        "fixtureHash": artifact.get("fixtureHash", {}),
                        "activationEvents": scenario.get("activationEvents", []),
                        "providerProbePoints": provider_points,
                        "executionStatus": artifact.get("status", "not-run"),
                        "artifact": rel(artifact_path),
                        "wizpProviderPayload": {
                            "status": provider_bundle_from_wizp(artifact.get("wizp", {}) if isinstance(artifact.get("wizp"), dict) else {}).get("status", "not-run"),
                            "artifact": rel(artifact_path),
                        },
                        "referenceProviderPayload": {
                            "status": provider_bundle_from_reference(artifact.get("reference", {}) if isinstance(artifact.get("reference"), dict) else {}).get("status", "not-run"),
                            "artifact": rel(artifact_path),
                        },
                        "normalizedDiff": normalized,
                    }
                )
            else:
                fixture_hash = fixture_hash_for_scenario(baseline, extension_id, str(scenario["id"]))
                blocked_probe_points += len(provider_points)
                scenarios.append(
                    {
                        "scenarioId": scenario["id"],
                        "backlogIds": scenario.get("backlogIds", []),
                        "fixture": scenario.get("fixture", ""),
                        "fixtureHash": fixture_hash,
                        "activationEvents": scenario.get("activationEvents", []),
                        "providerProbePoints": provider_points,
                        "executionStatus": "blocked-reference-host-executable-unpinned",
                        "artifact": "",
                        "wizpProviderPayload": {"status": "not-run", "artifact": ""},
                        "referenceProviderPayload": {"status": "not-run", "artifact": ""},
                        "normalizedDiff": {"status": "not-run", "unexpectedDrift": False, "blockedPointCount": len(provider_points)},
                    }
                )
        results.append(
            {
                "rank": row["rank"],
                "id": extension_id,
                "version": row.get("version", ""),
                "manifestLanguageSummary": manifest_language_summary(package_json),
                "providerScenarioCount": len(scenarios),
                "providerProbePointCount": sum(len(item["providerProbePoints"]) for item in scenarios),
                "executionGate": "reference-host-executable-unpinned" if not reference_ready else "paired-provider-probes-executed",
                "scenarios": scenarios,
            }
        )
    return {
        "schema": "wizp.top20-behavior-provider-diff.v1",
        "generatedAt": generated_at,
        "sourceBaseline": rel(BASELINE_JSON),
        "totalExtensions": len(results),
        "providerScenarioCount": provider_scenarios,
        "providerProbePointCount": total_probe_points,
        "pairedScenarioCount": paired_scenarios,
        "matchedProbePointCount": matched_probe_points,
        "driftProbePointCount": drift_probe_points,
        "blockedProbePointCount": blocked_probe_points,
        "executionGate": "reference-host-executable-unpinned" if not reference_ready else "paired-provider-probes-executed",
        "results": results,
        "note": (
            "Provider payload probes now execute against WIZP and the pinned MrCode host, write per-scenario artifacts, "
            "and record normalized matched/drift/blocked provider points."
            if reference_ready
            else "Provider payload probes remain blocked until the pinned MrCode executable is available."
        ),
    }


def scenario_provider_probe_points(scenario: dict[str, Any]) -> list[str]:
    return [
        str(item)
        for item in scenario.get("expectedEvidence", [])
        if isinstance(item, str) and item in PROVIDER_EVIDENCE_KEYS
    ]


def provider_diff_scenario_entry(
    extension_id: str,
    scenario: dict[str, Any],
    baseline: dict[str, Any],
    artifact: dict[str, Any] | None,
    *,
    reference_ready: bool,
) -> dict[str, Any]:
    artifact = artifact if isinstance(artifact, dict) else {}
    scenario_id = str(scenario["id"])
    provider_points = scenario_provider_probe_points(scenario)
    artifact_path = provider_probe_artifact_path(extension_id, scenario_id)
    normalized = artifact.get("normalizedDiff") if isinstance(artifact.get("normalizedDiff"), dict) else {}
    fixture_hash = artifact.get("fixtureHash")
    if not isinstance(fixture_hash, dict):
        fixture_hash = fixture_hash_for_scenario(baseline, extension_id, scenario_id)
    if reference_ready and artifact:
        execution_status = str(artifact.get("status") or "not-run")
        wizp_status = provider_bundle_from_wizp(artifact.get("wizp", {}) if isinstance(artifact.get("wizp"), dict) else {}).get("status", "not-run")
        reference_status = provider_bundle_from_reference(artifact.get("reference", {}) if isinstance(artifact.get("reference"), dict) else {}).get("status", "not-run")
        artifact_rel = rel(artifact_path)
    else:
        execution_status = "blocked-reference-host-executable-unpinned"
        wizp_status = "not-run"
        reference_status = "not-run"
        artifact_rel = ""
        if not normalized:
            normalized = {
                "status": "not-run",
                "unexpectedDrift": False,
                "blockedPointCount": len(provider_points),
            }
    return {
        "scenarioId": scenario_id,
        "backlogIds": scenario.get("backlogIds", []),
        "fixture": scenario.get("fixture", ""),
        "fixtureHash": fixture_hash,
        "activationEvents": scenario.get("activationEvents", []),
        "providerProbePoints": provider_points,
        "executionStatus": execution_status,
        "artifact": artifact_rel,
        "wizpProviderPayload": {
            "status": wizp_status,
            "artifact": artifact_rel,
        },
        "referenceProviderPayload": {
            "status": reference_status,
            "artifact": artifact_rel,
        },
        "normalizedDiff": normalized,
    }


def recompute_provider_diff_totals(provider_diff: dict[str, Any], *, reference_ready: bool) -> dict[str, Any]:
    results = provider_diff.get("results") if isinstance(provider_diff.get("results"), list) else []
    provider_scenarios = 0
    total_probe_points = 0
    paired_scenarios = 0
    matched_probe_points = 0
    drift_probe_points = 0
    blocked_probe_points = 0
    for row in results:
        if not isinstance(row, dict):
            continue
        scenarios = row.get("scenarios") if isinstance(row.get("scenarios"), list) else []
        row["providerScenarioCount"] = len(scenarios)
        row["providerProbePointCount"] = sum(
            len(item.get("providerProbePoints", []))
            for item in scenarios
            if isinstance(item, dict)
        )
        row["executionGate"] = "paired-provider-probes-executed" if reference_ready else "reference-host-executable-unpinned"
        provider_scenarios += int(row.get("providerScenarioCount") or 0)
        total_probe_points += int(row.get("providerProbePointCount") or 0)
        for item in scenarios:
            if not isinstance(item, dict):
                continue
            normalized = item.get("normalizedDiff") if isinstance(item.get("normalizedDiff"), dict) else {}
            matched_probe_points += int(normalized.get("matchedPointCount") or 0)
            drift_probe_points += int(normalized.get("driftPointCount") or 0)
            blocked_probe_points += int(normalized.get("blockedPointCount") or 0)
            if str(item.get("executionStatus") or "").startswith("paired-provider-payload-"):
                paired_scenarios += 1
    provider_diff["providerScenarioCount"] = provider_scenarios
    provider_diff["providerProbePointCount"] = total_probe_points
    provider_diff["pairedScenarioCount"] = paired_scenarios
    provider_diff["matchedProbePointCount"] = matched_probe_points
    provider_diff["driftProbePointCount"] = drift_probe_points
    provider_diff["blockedProbePointCount"] = blocked_probe_points
    provider_diff["executionGate"] = "paired-provider-probes-executed" if reference_ready else "reference-host-executable-unpinned"
    provider_diff["note"] = (
        "Provider payload probes now execute against WIZP and the pinned MrCode host, write per-scenario artifacts, "
        "and record normalized matched/drift/blocked provider points."
        if reference_ready
        else "Provider payload probes remain blocked until the pinned MrCode executable is available."
    )
    return provider_diff


def refresh_targeted_provider_lane(
    provider_diff: dict[str, Any],
    manifest: dict[str, Any],
    scenario: dict[str, Any],
    baseline: dict[str, Any],
    generated_at: str,
    *,
    reuse_cached_reference: bool = False,
) -> dict[str, Any]:
    provider_points = scenario_provider_probe_points(scenario)
    if not provider_points:
        return provider_diff
    extension_id = str(manifest["extensionId"])
    scenario_id = str(scenario["id"])
    reference = baseline.get("referenceHost", {}) if isinstance(baseline.get("referenceHost"), dict) else {}
    reference_ready = bool(reference.get("executable") and reference.get("version"))
    artifact_path = provider_probe_artifact_path(extension_id, scenario_id)
    artifact = load_json_if_exists(artifact_path)
    if (
        artifact.get("generatedAt") != generated_at
        or artifact.get("extensionId") != extension_id
        or artifact.get("scenarioId") != scenario_id
    ):
        artifact = run_provider_probe_artifact(
            manifest,
            scenario,
            baseline,
            generated_at,
            reuse_cached_reference=reuse_cached_reference,
        )
        artifact_path.parent.mkdir(parents=True, exist_ok=True)
        write_json(artifact_path, artifact)
    entry = provider_diff_scenario_entry(
        extension_id,
        scenario,
        baseline,
        artifact,
        reference_ready=reference_ready,
    )
    results = provider_diff.get("results") if isinstance(provider_diff.get("results"), list) else []
    row = next((item for item in results if isinstance(item, dict) and str(item.get("id") or "") == extension_id), None)
    if row is None:
        baseline_row = baseline_extension(baseline, extension_id)
        package_json = read_vsix_package_json((baseline_row.get("vsix") or {}) if isinstance(baseline_row.get("vsix"), dict) else {})
        row = {
            "rank": baseline_row.get("rank", 0),
            "id": extension_id,
            "version": baseline_row.get("version", ""),
            "manifestLanguageSummary": manifest_language_summary(package_json),
            "providerScenarioCount": 0,
            "providerProbePointCount": 0,
            "executionGate": "paired-provider-probes-executed" if reference_ready else "reference-host-executable-unpinned",
            "scenarios": [],
        }
        results.append(row)
        provider_diff["results"] = results
    scenarios = row.get("scenarios") if isinstance(row.get("scenarios"), list) else []
    replaced = False
    for index, existing in enumerate(scenarios):
        if isinstance(existing, dict) and str(existing.get("scenarioId") or "") == scenario_id:
            scenarios[index] = entry
            replaced = True
            break
    if not replaced:
        scenarios.append(entry)
    row["scenarios"] = scenarios
    return recompute_provider_diff_totals(provider_diff, reference_ready=reference_ready)


VIEW_EVIDENCE_KEYS = {
    "treeNodes",
    "treeState",
    "timelineState",
    "customEditorDom",
    "webviewMessages",
    "resourcePolicy",
    "views",
    "historyViews",
    "commitDetails",
    "revisionFiles",
    "statusItem",
    "uiState",
    "commands",
}


def manifest_view_summary(manifest: dict[str, Any]) -> dict[str, Any]:
    contributes = manifest.get("contributes")
    if not isinstance(contributes, dict):
        contributes = {}
    views = contributes.get("views") if isinstance(contributes.get("views"), dict) else {}
    containers = contributes.get("viewsContainers") if isinstance(contributes.get("viewsContainers"), dict) else {}
    view_entries: list[dict[str, str]] = []
    for location, entries in views.items():
        if not isinstance(entries, list):
            continue
        for entry in entries:
            if isinstance(entry, dict):
                view_entries.append(
                    {
                        "location": str(location),
                        "id": str(entry.get("id") or ""),
                        "name": str(entry.get("name") or ""),
                        "type": str(entry.get("type") or "tree"),
                    }
                )
    container_entries: list[dict[str, str]] = []
    for location, entries in containers.items():
        if not isinstance(entries, list):
            continue
        for entry in entries:
            if isinstance(entry, dict):
                container_entries.append(
                    {
                        "location": str(location),
                        "id": str(entry.get("id") or ""),
                        "title": str(entry.get("title") or ""),
                    }
                )
    return {
        "views": sorted(view_entries, key=lambda item: (item["location"], item["id"])),
        "viewsContainers": sorted(container_entries, key=lambda item: (item["location"], item["id"])),
        "viewsWelcomeCount": len(contributes.get("viewsWelcome") if isinstance(contributes.get("viewsWelcome"), list) else []),
        "walkthroughCount": len(contributes.get("walkthroughs") if isinstance(contributes.get("walkthroughs"), list) else []),
        "customEditorCount": len(contributes.get("customEditors") if isinstance(contributes.get("customEditors"), list) else []),
    }


def build_view_diff(
    rows: list[dict[str, Any]],
    manifests: dict[str, dict[str, Any]],
    baseline: dict[str, Any],
    generated_at: str,
) -> dict[str, Any]:
    baseline_by_id = {str(item["id"]): item for item in baseline.get("extensions", [])}
    reference = baseline.get("referenceHost", {})
    reference_ready = bool(reference.get("executable") and reference.get("version"))
    results: list[dict[str, Any]] = []
    scenario_count = 0
    view_surface_count = 0
    view_probe_records: list[dict[str, Any]] = []
    for row in rows:
        extension_id = str(row["id"])
        baseline_row = baseline_by_id.get(extension_id, {})
        package_json = read_vsix_package_json(baseline_row.get("vsix", {}))
        summary = manifest_view_summary(package_json)
        view_surface_count += len(summary["views"]) + len(summary["viewsContainers"]) + summary["viewsWelcomeCount"] + summary["walkthroughCount"] + summary["customEditorCount"]
        scenario_manifest = manifests.get(extension_id.lower(), {})
        scenarios: list[dict[str, Any]] = []
        for scenario in scenario_manifest.get("scenarios", []):
            if not isinstance(scenario, dict):
                continue
            expected = [str(item) for item in scenario.get("expectedEvidence", [])]
            view_points = [item for item in expected if item in VIEW_EVIDENCE_KEYS]
            if scenario.get("kind") in {"tree-view", "custom-editor", "scm-view", "ai-offline", "network-auth"}:
                view_points = sorted(set(view_points + [str(scenario.get("kind"))]))
            if not view_points:
                continue
            scenario_count += 1
            payload = read_scenario_artifact_payload(extension_id, str(scenario["id"]))
            artifact_path = scenario_artifact_path(extension_id, str(scenario["id"]))
            surface_summary = scenario_surface_summary(payload)
            view_probe_record: dict[str, Any] = {}
            batch_id = VIEW_PROBE_SCENARIO_BATCHES.get((extension_id.lower(), str(scenario["id"])))
            if batch_id:
                view_probe_record = write_view_probe_artifact(
                    batch_id,
                    extension_id,
                    scenario,
                    baseline,
                    payload,
                    generated_at,
                )
                view_probe_records.append(view_probe_record)
            scenarios.append(
                {
                    "scenarioId": scenario["id"],
                    "backlogIds": scenario.get("backlogIds", []),
                    "fixture": scenario.get("fixture", ""),
                    "fixtureHash": fixture_hash_for_scenario(baseline, extension_id, str(scenario["id"])),
                    "activationEvents": scenario.get("activationEvents", []),
                    "viewProbePoints": view_points,
                    "scenarioArtifact": rel(artifact_path) if artifact_path.exists() else "",
                    "executionStatus": scenario_execution_status(payload, reference_ready),
                    "wizpViewState": {
                        "status": view_surface_status(payload, "wizp"),
                        "artifact": rel(artifact_path) if artifact_path.exists() else "",
                        "viewCounts": surface_summary.get("wizp", {}).get("viewCounts", {}),
                        "messageCounts": surface_summary.get("wizp", {}).get("messageCounts", {}),
                    },
                    "referenceViewState": {
                        "status": view_surface_status(payload, "reference"),
                        "artifact": rel(artifact_path) if artifact_path.exists() else "",
                        "viewCounts": surface_summary.get("reference", {}).get("viewCounts", {}),
                        "messageCounts": surface_summary.get("reference", {}).get("messageCounts", {}),
                    },
                    "viewProbeBatch": view_probe_record.get("batchId", ""),
                    "viewProbeArtifact": view_probe_record.get("artifact", ""),
                    "viewProbeStatus": view_probe_record.get("status", ""),
                    "viewProbePromotionReady": view_probe_record.get("promotionReady"),
                    "viewProbeMissingPromotionEvidence": view_probe_record.get("missingPromotionEvidence", []),
                    "normalizedDiff": scenario_lane_normalized_diff(payload),
                }
            )
        results.append(
            {
                "rank": row["rank"],
                "id": extension_id,
                "version": row.get("version", ""),
                "manifestViewSummary": summary,
                "viewScenarioCount": len(scenarios),
                "executionGate": "reference-host-executable-unpinned" if not reference_ready else "ready-for-paired-view-probes",
                "scenarios": scenarios,
            }
        )
    view_probe_batch_coverage = summarize_view_probe_batch_coverage(view_probe_records)
    view_probe_promotion_gate = build_batch_promotion_gate("T20V-H07", view_probe_batch_coverage, "closed-view-probe-coverage")
    return {
        "schema": "wizp.top20-behavior-view-diff.v1",
        "generatedAt": generated_at,
        "sourceBaseline": rel(BASELINE_JSON),
        "totalExtensions": len(results),
        "manifestViewSurfaceCount": view_surface_count,
        "viewScenarioCount": scenario_count,
        "viewProbeArtifactCount": sum(1 for item in view_probe_records if item.get("artifact")),
        "viewProbePromotionReadyCount": sum(1 for item in view_probe_records if item.get("promotionReady") is True),
        "viewProbeBatchCoverage": view_probe_batch_coverage,
        "viewProbePromotionGate": view_probe_promotion_gate,
        "viewProbePromotionGateStatus": view_probe_promotion_gate.get("status", "unknown"),
        "viewProbeMissingPromotionEvidence": view_probe_promotion_gate.get("missingPromotionEvidence", []),
        "viewProbeMissingPromotionEvidenceKeys": view_probe_promotion_gate.get("missingPromotionEvidenceKeys", []),
        "viewProbeFailingScenarioCount": view_probe_promotion_gate.get("failingScenarioCount", 0),
        "executionGate": "reference-host-executable-unpinned" if not reference_ready else "ready-for-paired-view-probes",
        "results": results,
        "note": "View/webview comparison stays partial, but generic paired WIZP/reference survey execution now lands through T20V-H02 and H07A-C now emit dedicated view-probe ledgers. Promotion still requires DOM/screenshot/state-diff proof per batch.",
    }


