def manifest_debug_task_summary(manifest: dict[str, Any]) -> dict[str, Any]:
    contributes = manifest.get("contributes")
    if not isinstance(contributes, dict):
        contributes = {}
    debuggers = contributes.get("debuggers") if isinstance(contributes.get("debuggers"), list) else []
    task_definitions = contributes.get("taskDefinitions") if isinstance(contributes.get("taskDefinitions"), list) else []
    problem_matchers = contributes.get("problemMatchers") if isinstance(contributes.get("problemMatchers"), list) else []
    breakpoints = contributes.get("breakpoints") if isinstance(contributes.get("breakpoints"), list) else []
    debug_visualizers = contributes.get("debugVisualizers") if isinstance(contributes.get("debugVisualizers"), list) else []
    return {
        "debuggerTypes": sorted(str(item.get("type")) for item in debuggers if isinstance(item, dict) and item.get("type")),
        "taskDefinitionTypes": sorted(str(item.get("type")) for item in task_definitions if isinstance(item, dict) and item.get("type")),
        "problemMatcherCount": len(problem_matchers),
        "breakpointLanguageCount": len(breakpoints),
        "debugVisualizerCount": len(debug_visualizers),
    }


def manifest_debugger_schema_payloads(manifest_debuggers: list[Any], limit: int = 8) -> list[dict[str, Any]]:
    payloads: list[dict[str, Any]] = []
    for debugger in manifest_debuggers:
        if not isinstance(debugger, dict):
            continue
        configuration_attributes = (
            debugger.get("configurationAttributes")
            if isinstance(debugger.get("configurationAttributes"), dict)
            else {}
        )
        configuration_snippets = (
            debugger.get("configurationSnippets")
            if isinstance(debugger.get("configurationSnippets"), list)
            else []
        )
        initial_configurations = (
            debugger.get("initialConfigurations")
            if isinstance(debugger.get("initialConfigurations"), list)
            else []
        )
        if not configuration_attributes and not configuration_snippets and not initial_configurations:
            continue
        payload = {
            "type": str(debugger.get("type") or ""),
            "label": str(debugger.get("label") or ""),
            "configurationAttributeKeys": sorted(str(key) for key in configuration_attributes.keys()),
            "configurationSnippetCount": len(configuration_snippets),
            "initialConfigurationCount": len(initial_configurations),
        }
        for field in ["adapterExecutableCommand", "runtime", "runtimeExecutable", "program"]:
            value = debugger.get(field)
            if isinstance(value, str) and value:
                payload[field] = value
        payloads.append(payload)
        if len(payloads) >= limit:
            break
    return payloads


def find_text_signals(value: Any, needles: tuple[str, ...], limit: int = 12) -> list[str]:
    needle_set = tuple(needle.lower() for needle in needles if needle)
    if not needle_set:
        return []
    matches: list[str] = []

    def walk(node: Any) -> None:
        if len(matches) >= limit:
            return
        if isinstance(node, dict):
            for item in node.values():
                walk(item)
                if len(matches) >= limit:
                    break
        elif isinstance(node, list):
            for item in node:
                walk(item)
                if len(matches) >= limit:
                    break
        elif isinstance(node, str):
            text = node.strip()
            lower = text.lower()
            if text and any(needle in lower for needle in needle_set) and text not in matches:
                matches.append(text[:500])

    walk(value)
    return matches


def adapter_path_runtime_signals(signals: list[str]) -> list[str]:
    runtime_needles = ("does not exist", "cannot be found", "command not found")
    return [
        signal
        for signal in signals
        if any(needle in signal.lower() for needle in runtime_needles)
    ]


def debug_task_promotion_keys_for_scenario(
    batch_id: str,
    scenario: dict[str, Any],
    batch_promotion_check_keys: list[str],
) -> list[str]:
    expected = {
        str(item)
        for item in scenario.get("expectedEvidence", [])
        if isinstance(item, str)
    }
    if not expected:
        return batch_promotion_check_keys
    aliases = {
        "dapTrace": {"dapTrace", "dapEvents", "dapSessionTrace"},
        "breakpointStop": {"breakpointStop", "breakpoints", "stoppedEvent", "stoppedEvents"},
        "stackScopesVariables": {"stackScopesVariables", "stack", "scopes", "variables", "stackFrames", "stackTrace"},
        "evaluate": {"evaluate", "evaluateResult", "evaluateResponse"},
        "continueTerminate": {"continueTerminate", "continue", "terminate", "termination"},
        "debugUiState": {"debugUiState", "debugUiSnapshot", "uiState"},
        "taskTreeState": {"taskTreeState", "taskTree", "taskTreeNodes"},
        "taskOutput": {"taskOutput", "taskOutputLines", "taskRunOutput", "terminalOutput", "output"},
        "problemMatcher": {"problemMatcher", "problemExtraction", "problemMatcherDiagnostics"},
        "cancellation": {"cancellation", "cancellationState", "cancelResult"},
        "terminalMetadata": {"terminalMetadata", "terminalState", "terminalCleanup"},
        "testTree": {"testTree", "testItems", "testTreeState"},
        "testResults": {"testResults", "testRunResults", "resultPayloads"},
        "testOutput": {"testOutput", "testRunOutput"},
        "passFailSkipped": {"passFailSkipped", "testCounts", "testStateCounts"},
        "rerunState": {"rerunState", "rerunResult"},
        "problemMapping": {"problemMapping", "testProblemMapping"},
        "launchSchema": {"launchSchema", "launchConfig"},
        "generatedConfigs": {"generatedConfigs", "generatedConfigurationPayload"},
        "selectorState": {"selectorState", "debugSelectorState"},
        "adapterPath": {"adapterPath", "adapterPathHandling"},
        "schemaDiagnostics": {"schemaDiagnostics", "launchSchemaDiagnostics"},
    }
    scenario_keys = [
        key
        for key in batch_promotion_check_keys
        if key in expected or bool(aliases.get(key, {key}) & expected)
    ]
    return scenario_keys or batch_promotion_check_keys


def build_debug_task_diff(
    rows: list[dict[str, Any]],
    manifests: dict[str, dict[str, Any]],
    baseline: dict[str, Any],
    contribution_diff: dict[str, Any],
    generated_at: str,
) -> dict[str, Any]:
    baseline_by_id = {str(item["id"]): item for item in baseline.get("extensions", [])}
    contribution_rows_by_id = {
        str(item.get("id")): item
        for item in contribution_diff.get("results", [])
        if isinstance(item, dict) and item.get("id")
    }
    reference = baseline.get("referenceHost", {})
    reference_ready = bool(reference.get("executable") and reference.get("version"))
    results: list[dict[str, Any]] = []
    scenario_count = 0
    surface_count = 0
    raw_debugger_extensions = 0
    raw_debugger_matched_extensions = 0
    raw_debugger_drift_extensions = 0
    raw_debugger_matched_types = 0
    raw_debugger_drift_types = 0
    raw_debugger_missing_types = 0
    raw_debugger_extra_types = 0
    raw_configuration_attribute_types: set[str] = set()
    debug_task_probe_records: list[dict[str, Any]] = []
    for row in rows:
        extension_id = str(row["id"])
        baseline_row = baseline_by_id.get(extension_id, {})
        package_json = read_vsix_package_json(baseline_row.get("vsix", {}))
        summary = manifest_debug_task_summary(package_json)
        surface_count += len(summary["debuggerTypes"]) + len(summary["taskDefinitionTypes"]) + summary["problemMatcherCount"] + summary["breakpointLanguageCount"] + summary["debugVisualizerCount"]
        contribution_row = contribution_rows_by_id.get(extension_id, {})
        raw_debugger_evidence = contribution_row.get("rawDebuggerSchemaEvidence", {})
        if isinstance(raw_debugger_evidence, dict):
            if raw_debugger_evidence.get("status") != "no-debugger-contributions":
                raw_debugger_extensions += 1
            if raw_debugger_evidence.get("status") == "raw-debugger-schema-match":
                raw_debugger_matched_extensions += 1
            elif raw_debugger_evidence.get("status") == "raw-debugger-schema-drift":
                raw_debugger_drift_extensions += 1
            raw_debugger_matched_types += len(raw_debugger_evidence.get("matchedDebuggerTypes", []))
            raw_debugger_drift_types += len(raw_debugger_evidence.get("driftDebuggerTypes", []))
            raw_debugger_missing_types += len(raw_debugger_evidence.get("missingInWizpDebuggerTypes", []))
            raw_debugger_extra_types += len(raw_debugger_evidence.get("extraInWizpDebuggerTypes", []))
            raw_configuration_attribute_types.update(str(item) for item in raw_debugger_evidence.get("configurationAttributeDebuggerTypes", []) if item)
        scenario_manifest = manifests.get(extension_id.lower(), {})
        scenarios: list[dict[str, Any]] = []
        for scenario in scenario_manifest.get("scenarios", []):
            if not isinstance(scenario, dict):
                continue
            expected = [str(item) for item in scenario.get("expectedEvidence", [])]
            probe_points = [item for item in expected if item in DEBUG_TASK_EVIDENCE_KEYS]
            if scenario.get("kind") in {"debug", "debug-config", "debug-test", "test", "tasks-tree"}:
                probe_points = sorted(set(probe_points + [str(scenario.get("kind"))]))
            if not probe_points:
                continue
            scenario_count += 1
            payload = read_scenario_artifact_payload(extension_id, str(scenario["id"]))
            artifact_path = scenario_artifact_path(extension_id, str(scenario["id"]))
            surface_summary = scenario_surface_summary(payload)
            debug_task_probe_record: dict[str, Any] = {}
            batch_id = DEBUG_TASK_PROBE_SCENARIO_BATCHES.get((extension_id.lower(), str(scenario["id"])))
            if batch_id:
                debug_task_probe_record = write_debug_task_probe_artifact(
                    batch_id,
                    extension_id,
                    scenario,
                    baseline,
                    payload,
                    generated_at,
                )
                debug_task_probe_records.append(debug_task_probe_record)
            scenarios.append(
                {
                    "scenarioId": scenario["id"],
                    "backlogIds": scenario.get("backlogIds", []),
                    "fixture": scenario.get("fixture", ""),
                    "fixtureHash": fixture_hash_for_scenario(baseline, extension_id, str(scenario["id"])),
                    "activationEvents": scenario.get("activationEvents", []),
                    "debugTaskProbePoints": probe_points,
                    "scenarioArtifact": rel(artifact_path) if artifact_path.exists() else "",
                    "executionStatus": scenario_execution_status(payload, reference_ready),
                    "wizpDebugTaskPayload": {
                        "status": "captured" if surface_summary.get("wizp") else view_surface_status(payload, "wizp"),
                        "artifact": rel(artifact_path) if artifact_path.exists() else "",
                        "debugTaskCounts": surface_summary.get("wizp", {}).get("debugTaskCounts", {}),
                    },
                    "referenceDebugTaskPayload": {
                        "status": "captured" if surface_summary.get("reference") else view_surface_status(payload, "reference"),
                        "artifact": rel(artifact_path) if artifact_path.exists() else "",
                        "debugTaskCounts": surface_summary.get("reference", {}).get("debugTaskCounts", {}),
                    },
                    "debugTaskProbeBatch": debug_task_probe_record.get("batchId", ""),
                    "debugTaskProbeArtifact": debug_task_probe_record.get("artifact", ""),
                    "debugTaskProbeStatus": debug_task_probe_record.get("status", ""),
                    "debugTaskProbePromotionReady": debug_task_probe_record.get("promotionReady"),
                    "debugTaskProbeMissingPromotionEvidence": debug_task_probe_record.get("missingPromotionEvidence", []),
                    "normalizedDiff": scenario_lane_normalized_diff(payload),
                }
            )
        results.append(
            {
                "rank": row["rank"],
                "id": extension_id,
                "version": row.get("version", ""),
                "manifestDebugTaskSummary": summary,
                "debuggerContributionSchemaEvidence": raw_debugger_evidence,
                "debugTaskScenarioCount": len(scenarios),
                "executionGate": "reference-host-executable-unpinned" if not reference_ready else "ready-for-paired-debug-task-probes",
                "scenarios": scenarios,
            }
        )
    debug_task_probe_batch_coverage = summarize_debug_task_probe_batch_coverage(debug_task_probe_records)
    debug_task_probe_promotion_gate = build_batch_promotion_gate(
        "T20V-H08",
        debug_task_probe_batch_coverage,
        "closed-debug-task-probe-coverage",
    )
    debug_task_probe_gate_closed = debug_task_probe_promotion_gate.get("status") == "closed-batch-promotion-gate"
    debug_task_note = (
        "Debug/test/task comparison has closed the H08B-E debug-task probe promotion gate; remaining scenario-level behavior closure stays owned by the individual top-20 scenario rows."
        if debug_task_probe_gate_closed
        else "Debug/test/task comparison stays partial, but generic paired WIZP/reference survey execution now lands through T20V-H02 and H08B-E now emit dedicated debug-task probe ledgers. Promotion still requires the remaining proof listed in debugTaskProbeMissingPromotionEvidenceKeys."
    )
    return {
        "schema": "wizp.top20-behavior-debug-task-diff.v1",
        "generatedAt": generated_at,
        "sourceBaseline": rel(BASELINE_JSON),
        "totalExtensions": len(results),
        "manifestDebugTaskSurfaceCount": surface_count,
        "debugTaskScenarioCount": scenario_count,
        "debugTaskProbeArtifactCount": sum(1 for item in debug_task_probe_records if item.get("artifact")),
        "debugTaskProbePromotionReadyCount": sum(1 for item in debug_task_probe_records if item.get("promotionReady") is True),
        "debugTaskProbeBatchCoverage": debug_task_probe_batch_coverage,
        "debugTaskProbePromotionGate": debug_task_probe_promotion_gate,
        "debugTaskProbePromotionGateStatus": debug_task_probe_promotion_gate.get("status", "unknown"),
        "debugTaskProbeMissingPromotionEvidence": debug_task_probe_promotion_gate.get("missingPromotionEvidence", []),
        "debugTaskProbeMissingPromotionEvidenceKeys": debug_task_probe_promotion_gate.get("missingPromotionEvidenceKeys", []),
        "debugTaskProbeMissingPromotionEvidenceCounts": debug_task_probe_promotion_gate.get("missingPromotionEvidenceCounts", {}),
        "debugTaskProbeFailingScenarioCountsByBatch": debug_task_probe_promotion_gate.get("failingScenarioCountsByBatch", {}),
        "debugTaskProbeFailingScenarioCount": debug_task_probe_promotion_gate.get("failingScenarioCount", 0),
        "debugTaskProbeReadyScenarioCount": debug_task_probe_promotion_gate.get("readyScenarioCount", 0),
        "rawDebuggerSchemaCoverage": {
            "ownedBy": "T20V-H08",
            "sourceContributionDiff": rel(CONTRIBUTION_DIFF_JSON),
            "extensionsWithDebuggers": raw_debugger_extensions,
            "matchedExtensions": raw_debugger_matched_extensions,
            "driftExtensions": raw_debugger_drift_extensions,
            "matchedDebuggerTypes": raw_debugger_matched_types,
            "driftDebuggerTypes": raw_debugger_drift_types,
            "missingInWizpDebuggerTypes": raw_debugger_missing_types,
            "extraInWizpDebuggerTypes": raw_debugger_extra_types,
            "configurationAttributeDebuggerTypes": sorted(raw_configuration_attribute_types),
            "note": "Raw debugger contribution schemas, including configurationAttributes, are tracked here so the normalized H04 contribution lane no longer carries a hidden exclusion.",
        },
        "executionGate": "reference-host-executable-unpinned" if not reference_ready else "ready-for-paired-debug-task-probes",
        "results": results,
        "note": debug_task_note,
    }


def runtime_mode_class(mode: str) -> str:
    if "missing" in mode or "degraded" in mode:
        return "missing-runtime"
    if mode in {"offline", "opt-in-network", "openvsx-pack", "valid-fixture", "bundled-binary"}:
        return mode
    if "valid" in mode or mode in {"valid-jdk", "valid-docker", "valid-git-repo"}:
        return "valid-runtime"
    if "invalid" in mode:
        return "invalid-config"
    return "other"


def settings_tool_paths(settings: dict[str, Any]) -> dict[str, Any]:
    result: dict[str, Any] = {}
    for key, value in settings.items():
        if any(token in key.lower() for token in ("path", "bin", "executable", "home")):
            result[key] = value
    return result


def summarize_runtime_audit_batches(results: list[dict[str, Any]]) -> tuple[dict[str, Any], int]:
    backlog_to_scenario: dict[str, dict[str, Any]] = {}
    for row in results:
        extension_id = str(row.get("id") or "")
        for scenario in row.get("scenarios", []):
            if not isinstance(scenario, dict):
                continue
            for backlog_id in scenario.get("backlogIds", []):
                if not isinstance(backlog_id, str) or not backlog_id:
                    continue
                backlog_to_scenario[backlog_id] = {
                    "extensionId": extension_id,
                    "scenarioId": str(scenario.get("scenarioId") or ""),
                    "runtimeAuditStatus": str(scenario.get("runtimeAuditStatus") or "missing"),
                    "runtimeAuditArtifact": str(scenario.get("runtimeAuditArtifact") or ""),
                    "executionStatus": str(scenario.get("executionStatus") or ""),
                }
    summary: dict[str, Any] = {}
    closed_batch_count = 0
    for batch_id, backlog_ids in RUNTIME_AUDIT_BATCHES.items():
        scenarios: list[dict[str, Any]] = []
        captured_count = 0
        for backlog_id in backlog_ids:
            scenario_entry = backlog_to_scenario.get(backlog_id, {})
            runtime_audit_status = str(scenario_entry.get("runtimeAuditStatus") or "missing")
            if runtime_audit_status == "captured":
                captured_count += 1
            scenarios.append(
                {
                    "backlogId": backlog_id,
                    "extensionId": str(scenario_entry.get("extensionId") or ""),
                    "scenarioId": str(scenario_entry.get("scenarioId") or ""),
                    "runtimeAuditStatus": runtime_audit_status,
                    "runtimeAuditArtifact": str(scenario_entry.get("runtimeAuditArtifact") or ""),
                    "executionStatus": str(scenario_entry.get("executionStatus") or ""),
                }
            )
        status = "closed-audit-coverage" if captured_count == len(backlog_ids) else "partial"
        if status == "closed-audit-coverage":
            closed_batch_count += 1
        summary[batch_id] = {
            "scenarioCount": len(backlog_ids),
            "capturedCount": captured_count,
            "status": status,
            "scenarios": scenarios,
        }
    return summary, closed_batch_count


def summarize_performance_measurement_batches(results: list[dict[str, Any]]) -> tuple[dict[str, Any], int]:
    backlog_to_scenario: dict[str, dict[str, Any]] = {}
    for row in results:
        extension_id = str(row.get("id") or "")
        for scenario in row.get("scenarios", []):
            if not isinstance(scenario, dict):
                continue
            for backlog_id in scenario.get("backlogIds", []):
                if not isinstance(backlog_id, str) or not backlog_id:
                    continue
                backlog_to_scenario[backlog_id] = {
                    "extensionId": extension_id,
                    "scenarioId": str(scenario.get("scenarioId") or ""),
                    "measurementStatus": str(scenario.get("measurementStatus") or "missing"),
                    "measurementArtifact": str(scenario.get("measurementArtifact") or ""),
                    "executionStatus": str(scenario.get("executionStatus") or ""),
                }
    summary: dict[str, Any] = {}
    closed_batch_count = 0
    for batch_id, backlog_ids in PERFORMANCE_MEASUREMENT_BATCHES.items():
        scenarios: list[dict[str, Any]] = []
        direct_measurement_count = 0
        captured_count = 0
        derived_count = 0
        for backlog_id in backlog_ids:
            scenario_entry = backlog_to_scenario.get(backlog_id, {})
            measurement_status = str(scenario_entry.get("measurementStatus") or "missing")
            if measurement_status == "captured":
                direct_measurement_count += 1
                captured_count += 1
            elif measurement_status == "derived-classifier-only":
                derived_count += 1
                captured_count += 1
            scenarios.append(
                {
                    "backlogId": backlog_id,
                    "extensionId": str(scenario_entry.get("extensionId") or ""),
                    "scenarioId": str(scenario_entry.get("scenarioId") or ""),
                    "measurementStatus": measurement_status,
                    "measurementArtifact": str(scenario_entry.get("measurementArtifact") or ""),
                    "executionStatus": str(scenario_entry.get("executionStatus") or ""),
                }
            )
        status = "closed-direct-measurement-coverage" if direct_measurement_count == len(backlog_ids) else "partial"
        if status == "closed-direct-measurement-coverage":
            closed_batch_count += 1
        summary[batch_id] = {
            "scenarioCount": len(backlog_ids),
            "capturedCount": captured_count,
            "directMeasurementCount": direct_measurement_count,
            "derivedMeasurementCount": derived_count,
            "status": status,
            "scenarios": scenarios,
        }
    return summary, closed_batch_count


def runtime_comparison_work_queue_item(row: dict[str, Any], evidence_key: str) -> dict[str, Any]:
    return {
        "extensionId": str(row.get("extensionId") or ""),
        "scenarioId": str(row.get("scenarioId") or ""),
        "backlogIds": [str(value) for value in row.get("backlogIds", []) if isinstance(value, str)],
        "scenarioArtifact": str(row.get("scenarioArtifact") or ""),
        "runtimeAuditArtifact": str(row.get("runtimeAuditArtifact") or ""),
        "owner": str(row.get("ownershipOwner") or "unknown"),
        "bucket": str(row.get("ownershipBucket") or "unknown"),
        "scenarioStatus": str(row.get("scenarioStatus") or "unknown"),
        "runtimeAuditStatus": str(row.get("runtimeAuditStatus") or "unknown"),
        "executionStatus": str(row.get("executionStatus") or ""),
        "runtimeClasses": [str(value) for value in row.get("runtimeClasses", []) if isinstance(value, str)],
        "runtimeModes": [str(value) for value in row.get("runtimeModes", []) if isinstance(value, str)],
        "blockingCategories": [str(value) for value in row.get("blockingCategories", []) if isinstance(value, str)],
        "blocksPromotionEvidence": evidence_key,
    }


def build_runtime_comparison_work_queue(failing_scenarios: list[dict[str, Any]]) -> dict[str, Any]:
    evidence_definitions = [
        {
            "evidenceKey": "runtimeAuditCoverage",
            "blockingCategory": "runtimeAuditCoverage",
            "requiredAction": "Capture missing per-scenario runtime audit evidence before runtime comparison promotion can proceed.",
        },
        {
            "evidenceKey": "scenarioRuntimeComparisonCoverage",
            "blockingCategory": "scenarioRuntimeComparison",
            "requiredAction": "Resolve each remaining runtime/degraded comparison in the owning scenario lane or explicitly close it with accepted evidence.",
        },
        {
            "evidenceKey": "runtimeBlockedScenario",
            "blockingCategory": "runtimeBlockedScenario",
            "requiredAction": "Provide the required external runtime or keep the scenario explicitly blocked with current host/reference evidence.",
        },
    ]
    groups: list[dict[str, Any]] = []
    counts: Counter[str] = Counter()
    for definition in evidence_definitions:
        evidence_key = str(definition["evidenceKey"])
        blocking_category = str(definition["blockingCategory"])
        items = [
            runtime_comparison_work_queue_item(row, evidence_key)
            for row in failing_scenarios
            if blocking_category in row.get("blockingCategories", [])
        ]
        counts[evidence_key] = len(items)
        owner_groups: dict[str, dict[str, Any]] = {}
        for item in items:
            owner = str(item.get("owner") or "unknown")
            bucket = str(item.get("bucket") or "unknown")
            if owner not in owner_groups:
                owner_groups[owner] = {
                    "owner": owner,
                    "blockedScenarioCount": 0,
                    "bucketCounts": Counter(),
                    "scenarioStatusCounts": Counter(),
                    "executionStatusCounts": Counter(),
                    "runtimeClassCounts": Counter(),
                    "items": [],
                }
            owner_group = owner_groups[owner]
            owner_group["blockedScenarioCount"] += 1
            owner_group["bucketCounts"].update([bucket])
            owner_group["scenarioStatusCounts"].update([str(item.get("scenarioStatus") or "unknown")])
            execution_status = str(item.get("executionStatus") or "")
            if execution_status:
                owner_group["executionStatusCounts"].update([execution_status])
            owner_group["runtimeClassCounts"].update(
                str(value)
                for value in item.get("runtimeClasses", [])
                if isinstance(value, str)
            )
            owner_group["items"].append(item)
        groups.append(
            {
                "evidenceKey": evidence_key,
                "blockedScenarioCount": len(items),
                "requiredAction": str(definition["requiredAction"]),
                "ownerGroups": [
                    {
                        "owner": owner,
                        "blockedScenarioCount": group["blockedScenarioCount"],
                        "bucketCounts": dict(sorted(group["bucketCounts"].items())),
                        "scenarioStatusCounts": dict(sorted(group["scenarioStatusCounts"].items())),
                        "executionStatusCounts": dict(sorted(group["executionStatusCounts"].items())),
                        "runtimeClassCounts": dict(sorted(group["runtimeClassCounts"].items())),
                        "items": group["items"],
                    }
                    for owner, group in sorted(owner_groups.items())
                ],
            }
        )
    return {
        "ownedBy": "T20V-H09",
        "status": "open-runtime-comparison-work-queue" if failing_scenarios else "empty-runtime-comparison-work-queue",
        "evidenceCounts": dict(sorted(counts.items())),
        "groups": groups,
    }


def build_runtime_comparison_promotion_gate(
    scenario_count: int,
    captured_runtime_audit_count: int,
    closed_runtime_audit_batch_count: int,
    promotion_scenarios: list[dict[str, Any]],
) -> dict[str, Any]:
    audit_coverage_ready = scenario_count > 0 and captured_runtime_audit_count == scenario_count
    batch_coverage_ready = closed_runtime_audit_batch_count == len(RUNTIME_AUDIT_BATCHES)
    ready_scenario_count = 0
    status_counts: Counter[str] = Counter()
    failing_status_counts: Counter[str] = Counter()
    execution_status_counts: Counter[str] = Counter()
    runtime_class_counts: Counter[str] = Counter()
    ownership_owner_counts: Counter[str] = Counter()
    ownership_bucket_counts: Counter[str] = Counter()
    blocker_counts: Counter[str] = Counter()
    failing_scenarios: list[dict[str, Any]] = []
    for item in promotion_scenarios:
        scenario_status = str(item.get("scenarioStatus") or "unknown")
        runtime_audit_status = str(item.get("runtimeAuditStatus") or "missing")
        execution_status = str(item.get("executionStatus") or "")
        ownership = item.get("ownership") if isinstance(item.get("ownership"), dict) else {}
        owner = str(ownership.get("owner") or "unknown")
        bucket = str(ownership.get("bucket") or "unknown")
        runtime_classes = [str(value) for value in item.get("runtimeClasses", []) if isinstance(value, str)]
        status_counts.update([scenario_status])
        blocking_categories: list[str] = []
        if runtime_audit_status != "captured":
            blocking_categories.append("runtimeAuditCoverage")
        if scenario_status != "verified":
            blocking_categories.append("scenarioRuntimeComparison")
        if scenario_status == "blocked":
            blocking_categories.append("runtimeBlockedScenario")
        if blocking_categories:
            blocker_counts.update(blocking_categories)
            failing_status_counts.update([scenario_status])
            if execution_status:
                execution_status_counts.update([execution_status])
            if owner:
                ownership_owner_counts.update([owner])
            if bucket:
                ownership_bucket_counts.update([bucket])
            runtime_class_counts.update(runtime_classes or ["unspecified"])
            failing_scenarios.append(
                {
                    "extensionId": str(item.get("extensionId") or ""),
                    "scenarioId": str(item.get("scenarioId") or ""),
                    "backlogIds": [str(value) for value in item.get("backlogIds", []) if isinstance(value, str)],
                    "scenarioArtifact": str(item.get("scenarioArtifact") or ""),
                    "runtimeAuditArtifact": str(item.get("runtimeAuditArtifact") or ""),
                    "runtimeAuditStatus": runtime_audit_status,
                    "scenarioStatus": scenario_status,
                    "executionStatus": execution_status,
                    "runtimeClasses": runtime_classes,
                    "runtimeModes": [str(value) for value in item.get("runtimeModes", []) if isinstance(value, str)],
                    "ownershipOwner": owner,
                    "ownershipBucket": bucket,
                    "blockingCategories": blocking_categories,
                }
            )
        else:
            ready_scenario_count += 1
    scenario_comparison_ready = scenario_count > 0 and ready_scenario_count == scenario_count
    checks = {
        "runtimeAuditCoverage": {
            "status": "captured" if audit_coverage_ready else "missing",
            "capturedRuntimeAuditCount": captured_runtime_audit_count,
            "requiredScenarioCount": scenario_count,
        },
        "closedRuntimeAuditBatchCoverage": {
            "status": "captured" if batch_coverage_ready else "missing",
            "closedBatchCount": closed_runtime_audit_batch_count,
            "requiredBatchCount": len(RUNTIME_AUDIT_BATCHES),
        },
        "scenarioRuntimeComparisonCoverage": {
            "status": "captured" if scenario_comparison_ready else "missing",
            "readyScenarioCount": ready_scenario_count,
            "requiredScenarioCount": scenario_count,
        },
    }
    missing_promotion = [
        key
        for key, value in checks.items()
        if isinstance(value, dict) and value.get("status") != "captured"
    ]
    promotion_ready = not missing_promotion
    work_queue = build_runtime_comparison_work_queue(failing_scenarios)
    return {
        "ownedBy": "T20V-H09",
        "status": "closed-runtime-comparison-gate" if promotion_ready else "partial-runtime-comparison-gate",
        "promotionReady": promotion_ready,
        "requiredPromotionEvidence": [
            "33/33 runtime audit artifacts",
            "4/4 closed runtime-audit batches",
            "all runtime scenario comparisons verified or explicitly closed in scenario lanes",
        ],
        "missingPromotionEvidence": missing_promotion,
        "readyScenarioCount": ready_scenario_count,
        "blockedScenarioCount": len(failing_scenarios),
        "blockerCounts": dict(sorted(blocker_counts.items())),
        "scenarioStatusCounts": dict(sorted(status_counts.items())),
        "failingScenarioStatusCounts": dict(sorted(failing_status_counts.items())),
        "failingExecutionStatusCounts": dict(sorted(execution_status_counts.items())),
        "failingRuntimeClassCounts": dict(sorted(runtime_class_counts.items())),
        "failingOwnershipOwnerCounts": dict(sorted(ownership_owner_counts.items())),
        "failingOwnershipBucketCounts": dict(sorted(ownership_bucket_counts.items())),
        "workQueue": work_queue,
        "checks": checks,
        "failingScenarioCount": len(failing_scenarios),
        "failingScenarios": failing_scenarios,
        "failingScenarioSample": failing_scenarios[:20],
    }


def missing_measurement_keys(values: dict[str, Any], keys: list[str]) -> list[str]:
    return [key for key in keys if values.get(key) is None]


def numeric_measurement(value: Any) -> int | float | None:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return None
    return value


def first_numeric_measurement(*values: Any) -> int | float | None:
    for value in values:
        measurement = numeric_measurement(value)
        if measurement is not None:
            return measurement
    return None


def process_memory_budget_measurement(process_memory: dict[str, Any]) -> int | float | None:
    return first_numeric_measurement(process_memory.get("peakRssMiB"), process_memory.get("lastRssMiB"))


def process_memory_measurement_source(process_memory: dict[str, Any]) -> str | None:
    if not process_memory:
        return None
    status = str(process_memory.get("status") or "")
    source = str(process_memory.get("source") or "")
    if status == "captured" and source:
        return f"{source}:process-tree-peak-rss"
    return None


def captured_process_memory_summary(process_memory: Any) -> dict[str, Any]:
    if not isinstance(process_memory, dict):
        return {}
    if str(process_memory.get("status") or "") != "captured":
        return {}
    if process_memory_budget_measurement(process_memory) is None:
        return {}
    return process_memory


def aggregate_process_memory_summaries(
    rows: list[dict[str, Any]],
    *,
    aggregation: str,
    unavailable_reason: str,
) -> dict[str, Any]:
    captured: list[dict[str, Any]] = []
    for row in rows:
        if not isinstance(row, dict):
            continue
        process_memory = captured_process_memory_summary(row.get("processMemory"))
        if not process_memory:
            continue
        peak_rss = process_memory_budget_measurement(process_memory)
        if peak_rss is None:
            continue
        captured.append(
            {
                **row,
                "processMemory": process_memory,
                "peakRssMiB": peak_rss,
            }
        )
    if not captured:
        return unavailable_process_memory_summary(unavailable_reason)
    peak_row = max(captured, key=lambda item: float(item["peakRssMiB"]))
    peak_memory = peak_row["processMemory"]
    last_values = [
        numeric_measurement(item["processMemory"].get("lastRssMiB"))
        for item in captured
    ]
    return {
        "status": "captured",
        "source": str(peak_memory.get("source") or "procfs-rss"),
        "reason": "",
        "peakRssMiB": peak_row["peakRssMiB"],
        "lastRssMiB": max(value for value in last_values if value is not None) if any(value is not None for value in last_values) else None,
        "sampleCount": sum(int(item["processMemory"].get("sampleCount") or 0) for item in captured),
        "aggregation": aggregation,
        "observedRunCount": len(rows),
        "capturedRunCount": len(captured),
        "peakRun": {
            "extensionId": str(peak_row.get("extensionId") or ""),
            "scenarioId": str(peak_row.get("scenarioId") or ""),
            "phase": str(peak_row.get("phase") or ""),
            "peakRssMiB": peak_row["peakRssMiB"],
        },
    }


def reference_install_process_memory_summary(reference_install: dict[str, Any]) -> dict[str, Any]:
    rows = []
    for phase in ("install", "list"):
        result = reference_install.get(phase)
        if not isinstance(result, dict):
            continue
        rows.append(
            {
                "phase": phase,
                "processMemory": result.get("processMemory"),
            }
        )
    return aggregate_process_memory_summaries(
        rows,
        aggregation="max-isolated-reference-install-list-process-tree-peak-rss",
        unavailable_reason="no-reference-install-list-memory-samples",
    )


def scenario_artifact_process_memory(extension_id: str, scenario_id: str, side: str) -> dict[str, Any]:
    payload = read_scenario_artifact_payload(extension_id, scenario_id)
    summary = scenario_surface_summary(payload)
    side_summary = summary.get(side) if isinstance(summary.get(side), dict) else {}
    process_memory = captured_process_memory_summary(side_summary.get("processMemory"))
    if process_memory:
        return process_memory
    if side == "wizp":
        wizp_result = payload.get("wizpResult") if isinstance(payload.get("wizpResult"), dict) else {}
        return captured_process_memory_summary(wizp_result.get("processMemory"))
    reference_result = payload.get("referenceResult") if isinstance(payload.get("referenceResult"), dict) else {}
    runner = reference_result.get("runner") if isinstance(reference_result.get("runner"), dict) else {}
    runner_memory = captured_process_memory_summary(runner.get("processMemory"))
    if runner_memory:
        return runner_memory
    return captured_process_memory_summary(reference_result.get("processMemory"))


def python_pack_dependent_runtime_memory_rollup() -> dict[str, Any]:
    child_scenarios = [
        ("ms-python.debugpy", "debugpy-real-session"),
        ("ms-python.vscode-python-envs", "python-envs-manager-discovery"),
    ]
    rollup: dict[str, Any] = {}
    for side in ("wizp", "reference"):
        rows = []
        for extension_id, scenario_id in child_scenarios:
            process_memory = scenario_artifact_process_memory(extension_id, scenario_id, side)
            rows.append(
                {
                    "extensionId": extension_id,
                    "scenarioId": scenario_id,
                    "phase": f"{side}-supported-child-runtime",
                    "processMemory": process_memory,
                }
            )
        rollup[side] = aggregate_process_memory_summaries(
            rows,
            aggregation="max-supported-python-pack-child-runtime-process-tree-peak-rss",
            unavailable_reason=f"no-{side}-python-pack-child-runtime-memory-samples",
        )
    return rollup


def cached_specialized_memory_surface(extension_id: str, scenario_id: str) -> dict[str, Any]:
    payload = read_scenario_artifact_payload(extension_id, scenario_id)
    summary = scenario_surface_summary(payload)
    wizp_summary = summary.get("wizp") if isinstance(summary.get("wizp"), dict) else {}
    reference_summary = summary.get("reference") if isinstance(summary.get("reference"), dict) else {}
    wizp_memory = captured_process_memory_summary(wizp_summary.get("processMemory"))
    reference_memory = captured_process_memory_summary(reference_summary.get("processMemory"))
    if not wizp_memory or not reference_memory:
        return {}
    return {
        "wizp": {"processMemory": wizp_memory},
        "reference": {"processMemory": reference_memory},
    }


def run_specialized_memory_probe(
    manifest: dict[str, Any],
    scenario: dict[str, Any],
    baseline: dict[str, Any],
    baseline_row: dict[str, Any],
) -> dict[str, Any]:
    extension_id = str(manifest.get("extensionId") or "")
    scenario_id = str(scenario.get("id") or "")
    cached_surface = cached_specialized_memory_surface(extension_id, scenario_id)
    if cached_surface:
        return {
            "status": "reused-cached-specialized-memory-surface",
            "surfaceSummary": cached_surface,
        }
    if not baseline_row:
        unavailable = unavailable_process_memory_summary("target-extension-missing-from-baseline")
        return {
            "status": "blocked-specialized-memory-probe",
            "surfaceSummary": {
                "wizp": {"processMemory": unavailable},
                "reference": {"processMemory": unavailable},
            },
        }
    target = build_generic_scenario_target(manifest, scenario, baseline_row)
    wizp_result = run_wizp_scenario_probe(target, baseline, baseline_row)
    reference_result = run_reference_scenario_probe(target, baseline, baseline_row)
    wizp_surface = summarize_wizp_scenario_surface(wizp_result) if isinstance(wizp_result, dict) else {}
    reference_surface = summarize_reference_scenario_surface(reference_result) if isinstance(reference_result, dict) else {}
    return {
        "status": "captured-specialized-memory-probe",
        "wizpProbeStatus": str(wizp_result.get("status") or "") if isinstance(wizp_result, dict) else "not-run",
        "referenceProbeStatus": str(reference_result.get("status") or "") if isinstance(reference_result, dict) else "not-run",
        "surfaceSummary": {
            "wizp": {
                "processMemory": captured_process_memory_summary(wizp_surface.get("processMemory"))
                or captured_process_memory_summary(wizp_result.get("processMemory") if isinstance(wizp_result, dict) else {})
                or unavailable_process_memory_summary("wizp-specialized-memory-probe-not-captured"),
            },
            "reference": {
                "processMemory": captured_process_memory_summary(reference_surface.get("processMemory"))
                or captured_process_memory_summary(
                    ((reference_result.get("runner") or {}).get("processMemory"))
                    if isinstance(reference_result, dict) and isinstance(reference_result.get("runner"), dict)
                    else {}
                )
                or unavailable_process_memory_summary("reference-specialized-memory-probe-not-captured"),
            },
        },
    }


def performance_budget_failed_checks(budget_checks: dict[str, Any]) -> list[str]:
    return [
        key
        for key, value in sorted(budget_checks.items())
        if value is False
    ]


def performance_budget_check_detail(
    measurement_key: str,
    budget_key: str,
    unit: str,
    measurements: dict[str, Any],
    budget: dict[str, Any],
    budget_checks: dict[str, Any],
    check_key: str,
) -> dict[str, Any]:
    value = measurements.get(measurement_key)
    limit = budget.get(budget_key)
    check_value = budget_checks.get(check_key)
    if check_value is True:
        status = "passed"
    elif check_value is False:
        status = "failed"
    elif value is None:
        status = "missing-measurement"
    else:
        status = "unevaluated"
    return {
        "status": status,
        "measurement": f"wizp.{measurement_key}",
        "budget": budget_key,
        "value": value,
        "limit": limit,
        "unit": unit,
    }


def performance_budget_pass_rule_evaluation(
    measurements: dict[str, Any],
    budget: dict[str, Any],
    budget_checks: dict[str, Any],
    not_applicable_reason: str = "",
    not_applicable_status: str = "not-applicable-runtime-preflight-blocked",
) -> dict[str, Any]:
    required_measurements = ["activationMs", "firstResultMs", "spawnedProcesses", "hostResponsiveMs"]
    check_details = {
        "activationWithinBudget": performance_budget_check_detail(
            "activationMs",
            "activationTimeoutMs",
            "ms",
            measurements,
            budget,
            budget_checks,
            "activationWithinBudget",
        ),
        "firstResultWithinBudget": performance_budget_check_detail(
            "firstResultMs",
            "firstResultTimeoutMs",
            "ms",
            measurements,
            budget,
            budget_checks,
            "firstResultWithinBudget",
        ),
        "spawnedProcessesWithinBudget": performance_budget_check_detail(
            "spawnedProcesses",
            "maxSpawnedProcesses",
            "processes",
            measurements,
            budget,
            budget_checks,
            "spawnedProcessesWithinBudget",
        ),
        "hostResponsiveWithinBudget": performance_budget_check_detail(
            "hostResponsiveMs",
            "hostResponsiveAfterMs",
            "ms",
            measurements,
            budget,
            budget_checks,
            "hostResponsiveWithinBudget",
        ),
    }
    missing_measurements = missing_measurement_keys(measurements, required_measurements)
    failed_checks = [
        key
        for key, detail in sorted(check_details.items())
        if detail.get("status") == "failed"
    ]
    passed_checks = [
        key
        for key, detail in sorted(check_details.items())
        if detail.get("status") == "passed"
    ]
    unevaluated_checks = [
        key
        for key, detail in sorted(check_details.items())
        if detail.get("status") == "unevaluated"
    ]
    status = "passing" if not missing_measurements and not failed_checks and not unevaluated_checks else "blocked"
    reported_missing_measurements = [f"wizp.{key}" for key in missing_measurements]
    not_applicable_measurements: list[str] = []
    if not_applicable_reason:
        status = not_applicable_status or "not-applicable-runtime-preflight-blocked"
        not_applicable_measurements = reported_missing_measurements
        reported_missing_measurements = []
    return {
        "status": status,
        "requiredMeasurements": [f"wizp.{key}" for key in required_measurements],
        "missingMeasurements": reported_missing_measurements,
        "notApplicableMeasurements": not_applicable_measurements,
        "notApplicableReason": not_applicable_reason,
        "passedChecks": passed_checks,
        "failedChecks": failed_checks,
        "unevaluatedChecks": unevaluated_checks,
        "checkDetails": check_details,
        "note": (
            "WIZP budget pass rules require activation, first-result, spawned-process, and post-run responsiveness "
            "measurements to be present and within budget; memory tolerance is tracked separately."
        ),
    }


def nested_counter_dict(value: dict[str, Counter[str]]) -> dict[str, dict[str, int]]:
    return {
        key: dict(sorted(counter.items()))
        for key, counter in sorted(value.items())
        if counter
    }


def update_nested_counter(value: dict[str, Counter[str]], key: str, item: str) -> None:
    if not key or not item:
        return
    if key not in value:
        value[key] = Counter()
    value[key].update([item])


def performance_budget_rule_blocker_classification(
    ownership: dict[str, Any],
    missing_wizp: list[str],
    failed_budget_checks: list[str],
) -> dict[str, Any]:
    owner = str(ownership.get("owner") or "unknown")
    bucket = str(ownership.get("bucket") or "unknown")
    categories: list[str] = []
    if missing_wizp:
        categories.append("missing-wizp-measurement")
    if failed_budget_checks:
        categories.append("failed-budget-check")
    if missing_wizp or failed_budget_checks:
        if owner == "wizp-host-runtime-api":
            categories.append("host-runtime-budget-blocker")
        elif owner == "unsupported-dependency":
            categories.append("unsupported-dependency-budget-review")
        elif owner == "policy-bound-feature":
            categories.append("policy-bound-budget-review")
        else:
            categories.append("extension-owned-budget-review")
    return {
        "owner": owner,
        "bucket": bucket,
        "categories": categories,
        "blocksPromotionEvidence": "wizpBudgetPassRules",
    }


def performance_reference_timing_blocker_classification(
    ownership: dict[str, Any],
    missing_reference: list[str],
) -> dict[str, Any]:
    if not missing_reference:
        return {}
    owner = str(ownership.get("owner") or "unknown")
    bucket = str(ownership.get("bucket") or "unknown")
    categories = ["missing-reference-timing"]
    if owner == "wizp-host-runtime-api":
        categories.append("host-runtime-reference-timing-blocker")
    elif owner == "unsupported-dependency":
        categories.append("unsupported-dependency-reference-timing-review")
    elif owner == "policy-bound-feature":
        categories.append("policy-bound-reference-timing-review")
    else:
        categories.append("extension-owned-reference-timing-review")
    return {
        "owner": owner,
        "bucket": bucket,
        "categories": categories,
        "blocksPromotionEvidence": "referenceTimingCoverage",
    }


def performance_memory_tolerance_blocker_classification(
    ownership: dict[str, Any],
    missing_memory: list[str],
) -> dict[str, Any]:
    if not missing_memory:
        return {}
    owner = str(ownership.get("owner") or "unknown")
    bucket = str(ownership.get("bucket") or "unknown")
    categories = ["missing-memory-tolerance-evidence", "memory-tolerance-instrumentation-required"]
    if owner == "wizp-host-runtime-api":
        categories.append("host-runtime-memory-tolerance-review")
    elif owner == "unsupported-dependency":
        categories.append("unsupported-dependency-memory-tolerance-review")
    elif owner == "policy-bound-feature":
        categories.append("policy-bound-memory-tolerance-review")
    else:
        categories.append("extension-owned-memory-tolerance-review")
    return {
        "owner": owner,
        "bucket": bucket,
        "categories": categories,
        "blocksPromotionEvidence": "memoryToleranceEvidence",
    }


def performance_work_queue_item(row: dict[str, Any], evidence_key: str, blocker_key: str) -> dict[str, Any]:
    blocker = row.get(blocker_key) if isinstance(row.get(blocker_key), dict) else {}
    ownership = row.get("ownership") if isinstance(row.get("ownership"), dict) else {}
    item: dict[str, Any] = {
        "extensionId": str(row.get("extensionId") or ""),
        "scenarioId": str(row.get("scenarioId") or ""),
        "backlogIds": [str(value) for value in row.get("backlogIds", []) if isinstance(value, str)],
        "measurementArtifact": str(row.get("measurementArtifact") or ""),
        "owner": str(blocker.get("owner") or ownership.get("owner") or "unknown"),
        "bucket": str(blocker.get("bucket") or ownership.get("bucket") or "unknown"),
        "categories": [str(value) for value in blocker.get("categories", []) if isinstance(value, str)],
    }
    if evidence_key == "wizpBudgetPassRules":
        rules = row.get("wizpBudgetPassRules") if isinstance(row.get("wizpBudgetPassRules"), dict) else {}
        item.update(
            {
                "status": str(rules.get("status") or "unknown"),
                "failedBudgetChecks": [str(value) for value in row.get("failedBudgetChecks", []) if isinstance(value, str)],
                "missingWizpMeasurements": [str(value) for value in row.get("missingWizpMeasurements", []) if isinstance(value, str)],
            }
        )
    elif evidence_key == "referenceTimingCoverage":
        item["missingReferenceMeasurements"] = [
            str(value)
            for value in row.get("missingReferenceMeasurements", [])
            if isinstance(value, str)
        ]
    elif evidence_key == "memoryToleranceEvidence":
        item["missingMemoryToleranceEvidence"] = [
            str(value)
            for value in row.get("missingMemoryToleranceEvidence", [])
            if isinstance(value, str)
        ]
    return item


def build_performance_budget_work_queue(failing_scenarios: list[dict[str, Any]]) -> dict[str, Any]:
    evidence_definitions = [
        {
            "evidenceKey": "wizpBudgetPassRules",
            "blockerKey": "budgetRuleBlocker",
            "requiredAction": "Accept WIZP activation, first-result, spawned-process, and post-run responsiveness budget pass rules for each blocked scenario.",
        },
        {
            "evidenceKey": "referenceTimingCoverage",
            "blockerKey": "referenceTimingBlocker",
            "requiredAction": "Capture missing reference activation and first-result timing for each blocked scenario.",
        },
        {
            "evidenceKey": "memoryToleranceEvidence",
            "blockerKey": "memoryToleranceBlocker",
            "requiredAction": "Capture paired WIZP/reference memory delta samples and apply the memory tolerance budget for each blocked scenario.",
        },
    ]
    groups: list[dict[str, Any]] = []
    counts: Counter[str] = Counter()
    for definition in evidence_definitions:
        evidence_key = str(definition["evidenceKey"])
        blocker_key = str(definition["blockerKey"])
        items = [
            performance_work_queue_item(row, evidence_key, blocker_key)
            for row in failing_scenarios
            if evidence_key in row.get("blockingCategories", [])
        ]
        counts[evidence_key] = len(items)
        owner_groups: dict[str, dict[str, Any]] = {}
        for item in items:
            owner = str(item.get("owner") or "unknown")
            bucket = str(item.get("bucket") or "unknown")
            if owner not in owner_groups:
                owner_groups[owner] = {
                    "owner": owner,
                    "blockedScenarioCount": 0,
                    "bucketCounts": Counter(),
                    "classificationCounts": Counter(),
                    "missingMeasurementCounts": Counter(),
                    "items": [],
                }
            owner_group = owner_groups[owner]
            owner_group["blockedScenarioCount"] += 1
            owner_group["bucketCounts"].update([bucket])
            owner_group["classificationCounts"].update(
                str(value)
                for value in item.get("categories", [])
                if isinstance(value, str)
            )
            owner_group["missingMeasurementCounts"].update(
                str(value)
                for value in [
                    *item.get("missingWizpMeasurements", []),
                    *item.get("missingReferenceMeasurements", []),
                    *item.get("missingMemoryToleranceEvidence", []),
                ]
                if isinstance(value, str)
            )
            owner_group["items"].append(item)
        groups.append(
            {
                "evidenceKey": evidence_key,
                "blockedScenarioCount": len(items),
                "requiredAction": str(definition["requiredAction"]),
                "ownerGroups": [
                    {
                        "owner": owner,
                        "blockedScenarioCount": group["blockedScenarioCount"],
                        "bucketCounts": dict(sorted(group["bucketCounts"].items())),
                        "classificationCounts": dict(sorted(group["classificationCounts"].items())),
                        "missingMeasurementCounts": dict(sorted(group["missingMeasurementCounts"].items())),
                        "items": group["items"],
                    }
                    for owner, group in sorted(owner_groups.items())
                ],
            }
        )
    return {
        "ownedBy": "T20V-H11E",
        "status": "open-budget-promotion-work-queue" if failing_scenarios else "empty-budget-promotion-work-queue",
        "evidenceCounts": dict(sorted(counts.items())),
        "groups": groups,
    }


def build_performance_budget_promotion_gate(
    scenario_count: int,
    covered_scenario_count: int,
    measured_scenario_count: int,
    derived_scenario_count: int,
    closed_batch_count: int,
    aggregate_budget_checks: dict[str, int],
    promotion_scenarios: list[dict[str, Any]],
) -> dict[str, Any]:
    required_wizp_measurements = ["activationMs", "firstResultMs", "spawnedProcesses", "hostResponsiveMs"]
    required_reference_timing = ["activationMs", "firstResultMs", "spawnedProcesses"]
    direct_coverage_ready = (
        scenario_count > 0
        and covered_scenario_count == scenario_count
        and measured_scenario_count == scenario_count
        and derived_scenario_count == 0
    )
    batch_coverage_ready = closed_batch_count == len(PERFORMANCE_MEASUREMENT_BATCHES)
    wizp_budget_ready_count = 0
    reference_timing_ready_count = 0
    memory_tolerance_ready_count = 0
    ready_scenario_count = 0
    blocker_counts: Counter[str] = Counter()
    failed_budget_check_counts: Counter[str] = Counter()
    missing_wizp_measurement_counts: Counter[str] = Counter()
    missing_reference_measurement_counts: Counter[str] = Counter()
    missing_memory_tolerance_counts: Counter[str] = Counter()
    budget_rule_owner_counts: Counter[str] = Counter()
    budget_rule_bucket_counts: Counter[str] = Counter()
    budget_rule_classification_counts: Counter[str] = Counter()
    budget_rule_evaluation_status_counts: Counter[str] = Counter()
    budget_rule_failed_check_owner_counts: dict[str, Counter[str]] = {}
    budget_rule_failed_check_bucket_counts: dict[str, Counter[str]] = {}
    budget_rule_missing_measurement_owner_counts: dict[str, Counter[str]] = {}
    budget_rule_missing_measurement_bucket_counts: dict[str, Counter[str]] = {}
    reference_timing_owner_counts: Counter[str] = Counter()
    reference_timing_bucket_counts: Counter[str] = Counter()
    reference_timing_classification_counts: Counter[str] = Counter()
    reference_timing_missing_measurement_owner_counts: dict[str, Counter[str]] = {}
    reference_timing_missing_measurement_bucket_counts: dict[str, Counter[str]] = {}
    memory_tolerance_owner_counts: Counter[str] = Counter()
    memory_tolerance_bucket_counts: Counter[str] = Counter()
    memory_tolerance_classification_counts: Counter[str] = Counter()
    memory_tolerance_missing_evidence_owner_counts: dict[str, Counter[str]] = {}
    memory_tolerance_missing_evidence_bucket_counts: dict[str, Counter[str]] = {}
    failing_scenarios: list[dict[str, Any]] = []
    for item in promotion_scenarios:
        wizp_measurements = item.get("wizpMeasurements") if isinstance(item.get("wizpMeasurements"), dict) else {}
        reference_measurements = item.get("referenceMeasurements") if isinstance(item.get("referenceMeasurements"), dict) else {}
        budget_checks = item.get("budgetChecks") if isinstance(item.get("budgetChecks"), dict) else {}
        budget_rule_evaluation = item.get("wizpBudgetPassRules") if isinstance(item.get("wizpBudgetPassRules"), dict) else {}
        reference_timing_coverage = item.get("referenceTimingCoverage") if isinstance(item.get("referenceTimingCoverage"), dict) else {}
        memory_tolerance = item.get("memoryTolerance") if isinstance(item.get("memoryTolerance"), dict) else {}
        ownership = item.get("ownership") if isinstance(item.get("ownership"), dict) else {}
        evaluation_status = str(budget_rule_evaluation.get("status") or "unknown")
        budget_rule_evaluation_status_counts.update([evaluation_status])
        budget_rule_missing_measurements = (
            budget_rule_evaluation.get("missingMeasurements")
            if isinstance(budget_rule_evaluation.get("missingMeasurements"), list)
            else None
        )
        if budget_rule_missing_measurements is not None:
            missing_wizp = [
                str(value).removeprefix("wizp.")
                for value in budget_rule_missing_measurements
                if isinstance(value, str)
            ]
        else:
            missing_wizp = missing_measurement_keys(wizp_measurements, required_wizp_measurements)
        budget_rule_failed_checks = (
            budget_rule_evaluation.get("failedChecks")
            if isinstance(budget_rule_evaluation.get("failedChecks"), list)
            else None
        )
        reference_timing_missing = (
            reference_timing_coverage.get("missingMeasurements")
            if isinstance(reference_timing_coverage.get("missingMeasurements"), list)
            else None
        )
        if reference_timing_missing is not None:
            missing_reference = [
                str(item)
                for item in reference_timing_missing
                if isinstance(item, str)
            ]
        else:
            missing_reference = missing_measurement_keys(reference_measurements, required_reference_timing)
        memory_tolerance_missing = memory_tolerance.get("missingMeasurements") if isinstance(memory_tolerance.get("missingMeasurements"), list) else None
        if memory_tolerance_missing is not None:
            missing_memory = [str(item) for item in memory_tolerance_missing if isinstance(item, str)]
        else:
            missing_memory = []
            if wizp_measurements.get("memoryDeltaMiB") is None:
                missing_memory.append("wizp.memoryDeltaMiB")
            if reference_measurements.get("memoryDeltaMiB") is None:
                missing_memory.append("reference.memoryDeltaMiB")
        if budget_rule_failed_checks is not None:
            failed_budget_checks = [
                str(value)
                for value in budget_rule_failed_checks
                if isinstance(value, str)
            ]
        else:
            failed_budget_checks = performance_budget_failed_checks(budget_checks)
        if not missing_wizp and not failed_budget_checks:
            wizp_budget_ready_count += 1
        if not missing_reference:
            reference_timing_ready_count += 1
        if not missing_memory:
            memory_tolerance_ready_count += 1
        blocking_categories: list[str] = []
        if missing_wizp or failed_budget_checks:
            blocking_categories.append("wizpBudgetPassRules")
        if missing_reference:
            blocking_categories.append("referenceTimingCoverage")
        if missing_memory:
            blocking_categories.append("memoryToleranceEvidence")
        if blocking_categories:
            blocker_counts.update(blocking_categories)
            failed_budget_check_counts.update(failed_budget_checks)
            missing_wizp_measurement_counts.update(missing_wizp)
            missing_reference_measurement_counts.update(missing_reference)
            missing_memory_tolerance_counts.update(missing_memory)
            budget_rule_blocker: dict[str, Any] = {}
            if missing_wizp or failed_budget_checks:
                budget_rule_blocker = performance_budget_rule_blocker_classification(ownership, missing_wizp, failed_budget_checks)
                owner = str(budget_rule_blocker.get("owner") or "unknown")
                bucket = str(budget_rule_blocker.get("bucket") or "unknown")
                budget_rule_owner_counts.update([owner])
                budget_rule_bucket_counts.update([bucket])
                budget_rule_classification_counts.update(
                    str(item)
                    for item in budget_rule_blocker.get("categories", [])
                    if isinstance(item, str)
                )
                for check in failed_budget_checks:
                    update_nested_counter(budget_rule_failed_check_owner_counts, owner, check)
                    update_nested_counter(budget_rule_failed_check_bucket_counts, bucket, check)
                for measurement in missing_wizp:
                    update_nested_counter(budget_rule_missing_measurement_owner_counts, owner, measurement)
                    update_nested_counter(budget_rule_missing_measurement_bucket_counts, bucket, measurement)
            reference_timing_blocker = performance_reference_timing_blocker_classification(ownership, missing_reference)
            if reference_timing_blocker:
                owner = str(reference_timing_blocker.get("owner") or "unknown")
                bucket = str(reference_timing_blocker.get("bucket") or "unknown")
                reference_timing_owner_counts.update([owner])
                reference_timing_bucket_counts.update([bucket])
                reference_timing_classification_counts.update(
                    str(item)
                    for item in reference_timing_blocker.get("categories", [])
                    if isinstance(item, str)
                )
                for measurement in missing_reference:
                    update_nested_counter(reference_timing_missing_measurement_owner_counts, owner, measurement)
                    update_nested_counter(reference_timing_missing_measurement_bucket_counts, bucket, measurement)
            memory_tolerance_blocker = performance_memory_tolerance_blocker_classification(ownership, missing_memory)
            if memory_tolerance_blocker:
                owner = str(memory_tolerance_blocker.get("owner") or "unknown")
                bucket = str(memory_tolerance_blocker.get("bucket") or "unknown")
                memory_tolerance_owner_counts.update([owner])
                memory_tolerance_bucket_counts.update([bucket])
                memory_tolerance_classification_counts.update(
                    str(item)
                    for item in memory_tolerance_blocker.get("categories", [])
                    if isinstance(item, str)
                )
                for evidence in missing_memory:
                    update_nested_counter(memory_tolerance_missing_evidence_owner_counts, owner, evidence)
                    update_nested_counter(memory_tolerance_missing_evidence_bucket_counts, bucket, evidence)
            failing_scenarios.append(
                {
                    "extensionId": str(item.get("extensionId") or ""),
                    "scenarioId": str(item.get("scenarioId") or ""),
                    "backlogIds": [str(value) for value in item.get("backlogIds", []) if isinstance(value, str)],
                    "measurementArtifact": str(item.get("measurementArtifact") or ""),
                    "executionStatus": str(item.get("executionStatus") or ""),
                    "measurementStatus": str(item.get("measurementStatus") or ""),
                    "blockingCategories": blocking_categories,
                    "failedBudgetChecks": failed_budget_checks,
                    "missingWizpMeasurements": missing_wizp,
                    "missingReferenceMeasurements": missing_reference,
                    "missingMemoryToleranceEvidence": missing_memory,
                    "ownership": ownership,
                    "budgetRuleBlocker": budget_rule_blocker,
                    "wizpBudgetPassRules": budget_rule_evaluation,
                    "referenceTimingBlocker": reference_timing_blocker,
                    "referenceTimingCoverage": reference_timing_coverage,
                    "memoryToleranceBlocker": memory_tolerance_blocker,
                    "memoryTolerance": memory_tolerance,
                    "totalSurveyMs": {
                        "wizp": wizp_measurements.get("totalSurveyMs"),
                        "reference": reference_measurements.get("totalSurveyMs"),
                    },
                    "budgetChecks": budget_checks,
                }
            )
        else:
            ready_scenario_count += 1
    wizp_budget_ready = scenario_count > 0 and wizp_budget_ready_count == scenario_count
    reference_timing_ready = scenario_count > 0 and reference_timing_ready_count == scenario_count
    memory_tolerance_ready = scenario_count > 0 and memory_tolerance_ready_count == scenario_count
    checks = {
        "directMeasurementCoverage": {
            "status": "captured" if direct_coverage_ready else "missing",
            "coveredScenarioCount": covered_scenario_count,
            "measuredScenarioCount": measured_scenario_count,
            "derivedScenarioCount": derived_scenario_count,
            "requiredScenarioCount": scenario_count,
        },
        "closedMeasurementBatchCoverage": {
            "status": "captured" if batch_coverage_ready else "missing",
            "closedBatchCount": closed_batch_count,
            "requiredBatchCount": len(PERFORMANCE_MEASUREMENT_BATCHES),
        },
        "wizpBudgetPassRules": {
            "status": "captured" if wizp_budget_ready else "missing",
            "passingScenarioCount": wizp_budget_ready_count,
            "requiredScenarioCount": scenario_count,
            "budgetCheckSummary": aggregate_budget_checks,
        },
        "referenceTimingCoverage": {
            "status": "captured" if reference_timing_ready else "missing",
            "coveredScenarioCount": reference_timing_ready_count,
            "requiredScenarioCount": scenario_count,
            "requiredMeasurements": required_reference_timing,
            "coverageSummary": {
                key: aggregate_budget_checks.get(key, 0)
                for key in (
                    "scenariosWithReferenceActivationMeasurement",
                    "scenariosWithReferenceFirstResultMeasurement",
                    "scenariosWithReferenceSpawnedProcessMeasurement",
                    "referenceTimingCompleteCount",
                    "referenceTimingNotApplicableCount",
                )
            },
        },
        "memoryToleranceEvidence": {
            "status": "captured" if memory_tolerance_ready else "missing",
            "coveredScenarioCount": memory_tolerance_ready_count,
            "requiredScenarioCount": scenario_count,
            "requiredMeasurements": ["wizp.memoryDeltaMiB", "reference.memoryDeltaMiB"],
            "budgetCheckSummary": {
                key: aggregate_budget_checks.get(key, 0)
                for key in (
                    "scenariosWithWizpMemoryMeasurement",
                    "scenariosWithReferenceMemoryMeasurement",
                    "scenariosWithPairedMemoryMeasurement",
                    "memoryDeltaWithinBudgetCount",
                )
            },
        },
    }
    missing_promotion = [
        key
        for key, value in checks.items()
        if isinstance(value, dict) and value.get("status") != "captured"
    ]
    promotion_ready = not missing_promotion
    work_queue = build_performance_budget_work_queue(failing_scenarios)
    return {
        "ownedBy": "T20V-H11E",
        "status": "closed-budget-promotion-gate" if promotion_ready else "partial-budget-promotion-gate",
        "promotionReady": promotion_ready,
        "requiredPromotionEvidence": [
            "33/33 direct measurement artifacts",
            "4/4 closed direct-measurement batches",
            "accepted WIZP budget pass rules",
            "reference timing/process coverage",
            "WIZP/reference memory tolerance evidence",
        ],
        "missingPromotionEvidence": missing_promotion,
        "readyScenarioCount": ready_scenario_count,
        "blockedScenarioCount": len(failing_scenarios),
        "blockerCounts": dict(sorted(blocker_counts.items())),
        "failedBudgetCheckCounts": dict(sorted(failed_budget_check_counts.items())),
        "missingWizpMeasurementCounts": dict(sorted(missing_wizp_measurement_counts.items())),
        "missingReferenceMeasurementCounts": dict(sorted(missing_reference_measurement_counts.items())),
        "missingMemoryToleranceEvidenceCounts": dict(sorted(missing_memory_tolerance_counts.items())),
        "referenceTimingCoverageSummary": checks["referenceTimingCoverage"]["coverageSummary"],
        "memoryToleranceBudgetCheckSummary": checks["memoryToleranceEvidence"]["budgetCheckSummary"],
        "budgetRuleOwnerCounts": dict(sorted(budget_rule_owner_counts.items())),
        "budgetRuleBucketCounts": dict(sorted(budget_rule_bucket_counts.items())),
        "budgetRuleClassificationCounts": dict(sorted(budget_rule_classification_counts.items())),
        "budgetRuleEvaluationStatusCounts": dict(sorted(budget_rule_evaluation_status_counts.items())),
        "budgetRuleFailedCheckOwnerCounts": nested_counter_dict(budget_rule_failed_check_owner_counts),
        "budgetRuleFailedCheckBucketCounts": nested_counter_dict(budget_rule_failed_check_bucket_counts),
        "budgetRuleMissingMeasurementOwnerCounts": nested_counter_dict(budget_rule_missing_measurement_owner_counts),
        "budgetRuleMissingMeasurementBucketCounts": nested_counter_dict(budget_rule_missing_measurement_bucket_counts),
        "referenceTimingOwnerCounts": dict(sorted(reference_timing_owner_counts.items())),
        "referenceTimingBucketCounts": dict(sorted(reference_timing_bucket_counts.items())),
        "referenceTimingClassificationCounts": dict(sorted(reference_timing_classification_counts.items())),
        "referenceTimingMissingMeasurementOwnerCounts": nested_counter_dict(reference_timing_missing_measurement_owner_counts),
        "referenceTimingMissingMeasurementBucketCounts": nested_counter_dict(reference_timing_missing_measurement_bucket_counts),
        "memoryToleranceOwnerCounts": dict(sorted(memory_tolerance_owner_counts.items())),
        "memoryToleranceBucketCounts": dict(sorted(memory_tolerance_bucket_counts.items())),
        "memoryToleranceClassificationCounts": dict(sorted(memory_tolerance_classification_counts.items())),
        "memoryToleranceMissingEvidenceOwnerCounts": nested_counter_dict(memory_tolerance_missing_evidence_owner_counts),
        "memoryToleranceMissingEvidenceBucketCounts": nested_counter_dict(memory_tolerance_missing_evidence_bucket_counts),
        "workQueue": work_queue,
        "checks": checks,
        "failingScenarioCount": len(failing_scenarios),
        "failingScenarios": failing_scenarios,
        "failingScenarioSample": failing_scenarios[:20],
    }


def build_runtime_matrix(
    rows: list[dict[str, Any]],
    manifests: dict[str, dict[str, Any]],
    baseline: dict[str, Any],
    generated_at: str,
) -> dict[str, Any]:
    reference = baseline.get("referenceHost", {})
    reference_ready = bool(reference.get("executable") and reference.get("version"))
    results: list[dict[str, Any]] = []
    mode_counts: dict[str, int] = {}
    class_counts: dict[str, int] = {}
    captured_runtime_audit_count = 0
    scenario_count = 0
    promotion_scenarios: list[dict[str, Any]] = []
    for row in rows:
        extension_id = str(row["id"])
        scenario_manifest = manifests.get(extension_id.lower(), {})
        scenarios: list[dict[str, Any]] = []
        for scenario in scenario_manifest.get("scenarios", []):
            if not isinstance(scenario, dict):
                continue
            modes = [str(item) for item in scenario.get("runtimeModes", [])]
            if not modes:
                modes = ["unspecified"]
            classes = sorted({runtime_mode_class(mode) for mode in modes})
            for mode in modes:
                mode_counts[mode] = mode_counts.get(mode, 0) + 1
            for cls in classes:
                class_counts[cls] = class_counts.get(cls, 0) + 1
            scenario_count += 1
            settings = scenario.get("settings") if isinstance(scenario.get("settings"), dict) else {}
            payload = read_scenario_artifact_payload(extension_id, str(scenario["id"]))
            artifact_path = scenario_artifact_path(extension_id, str(scenario["id"]))
            runtime_checks = scenario_runtime_checks(payload)
            runtime_audit = write_runtime_audit_artifact(extension_id, scenario, baseline, payload, generated_at)
            scenario_status = scenario_status_from_payload(scenario, payload)
            ownership = scenario_ownership(extension_id, scenario, baseline, payload)
            if runtime_audit.get("status") == "captured":
                captured_runtime_audit_count += 1
            promotion_scenarios.append(
                {
                    "extensionId": extension_id,
                    "scenarioId": str(scenario["id"]),
                    "backlogIds": scenario.get("backlogIds", []),
                    "scenarioArtifact": rel(artifact_path) if artifact_path.exists() else "",
                    "runtimeAuditArtifact": runtime_audit.get("artifact", ""),
                    "runtimeAuditStatus": runtime_audit.get("status", "not-run"),
                    "scenarioStatus": scenario_status,
                    "executionStatus": scenario_execution_status(payload, reference_ready),
                    "runtimeClasses": classes,
                    "runtimeModes": modes,
                    "ownership": ownership,
                }
            )
            scenarios.append(
                {
                    "scenarioId": scenario["id"],
                    "backlogIds": scenario.get("backlogIds", []),
                    "fixture": scenario.get("fixture", ""),
                    "fixtureHash": fixture_hash_for_scenario(baseline, extension_id, str(scenario["id"])),
                    "runtimeModes": modes,
                    "runtimeClasses": classes,
                    "settingsToolPaths": settings_tool_paths(settings),
                    "scenarioArtifact": rel(artifact_path) if artifact_path.exists() else "",
                    "runtimeAuditArtifact": runtime_audit.get("artifact", ""),
                    "runtimeAuditStatus": runtime_audit.get("status", "not-run"),
                    "scenarioStatus": scenario_status,
                    "executionStatus": scenario_execution_status(payload, reference_ready),
                    "ownership": ownership,
                    "expectedProcessAudit": runtime_checks["processAudit"],
                    "expectedNetworkAudit": runtime_checks["networkAudit"],
                    "hostResponsivenessCheck": runtime_checks["hostResponsiveness"],
                }
            )
        results.append(
            {
                "rank": row["rank"],
                "id": extension_id,
                "version": row.get("version", ""),
                "scenarioCount": len(scenarios),
                "runtimeClassCoverage": sorted({cls for scenario in scenarios for cls in scenario["runtimeClasses"]}),
                "executionGate": "reference-host-executable-unpinned" if not reference_ready else "ready-for-runtime-matrix-execution",
                "scenarios": scenarios,
            }
        )
    runtime_audit_batch_coverage, closed_runtime_audit_batch_count = summarize_runtime_audit_batches(results)
    runtime_comparison_promotion_gate = build_runtime_comparison_promotion_gate(
        scenario_count,
        captured_runtime_audit_count,
        closed_runtime_audit_batch_count,
        promotion_scenarios,
    )
    return {
        "schema": "wizp.top20-behavior-runtime-matrix.v1",
        "generatedAt": generated_at,
        "sourceBaseline": rel(BASELINE_JSON),
        "totalExtensions": len(results),
        "runtimeScenarioCount": scenario_count,
        "capturedRuntimeAuditCount": captured_runtime_audit_count,
        "closedRuntimeAuditBatchCount": closed_runtime_audit_batch_count,
        "runtimeAuditBatchCoverage": runtime_audit_batch_coverage,
        "runtimeComparisonPromotionGate": runtime_comparison_promotion_gate,
        "runtimeComparisonPromotionGateStatus": runtime_comparison_promotion_gate.get("status", "unknown"),
        "runtimeComparisonMissingPromotionEvidence": runtime_comparison_promotion_gate.get("missingPromotionEvidence", []),
        "runtimeComparisonReadyScenarioCount": runtime_comparison_promotion_gate.get("readyScenarioCount", 0),
        "runtimeComparisonFailingScenarioCount": runtime_comparison_promotion_gate.get("failingScenarioCount", 0),
        "runtimeComparisonBlockerCounts": runtime_comparison_promotion_gate.get("blockerCounts", {}),
        "runtimeComparisonScenarioStatusCounts": runtime_comparison_promotion_gate.get("scenarioStatusCounts", {}),
        "runtimeComparisonFailingScenarioStatusCounts": runtime_comparison_promotion_gate.get("failingScenarioStatusCounts", {}),
        "runtimeComparisonFailingExecutionStatusCounts": runtime_comparison_promotion_gate.get("failingExecutionStatusCounts", {}),
        "runtimeComparisonFailingRuntimeClassCounts": runtime_comparison_promotion_gate.get("failingRuntimeClassCounts", {}),
        "runtimeComparisonFailingOwnershipOwnerCounts": runtime_comparison_promotion_gate.get("failingOwnershipOwnerCounts", {}),
        "runtimeComparisonFailingOwnershipBucketCounts": runtime_comparison_promotion_gate.get("failingOwnershipBucketCounts", {}),
        "runtimeComparisonWorkQueue": runtime_comparison_promotion_gate.get("workQueue", {}),
        "runtimeComparisonWorkQueueCounts": (runtime_comparison_promotion_gate.get("workQueue", {}) or {}).get("evidenceCounts", {}),
        "runtimeModeCounts": dict(sorted(mode_counts.items())),
        "runtimeClassCounts": dict(sorted(class_counts.items())),
        "executionGate": "reference-host-executable-unpinned" if not reference_ready else "ready-for-runtime-matrix-execution",
        "results": results,
        "note": "Runtime/degraded comparison stays partial, but generic paired WIZP/reference survey execution now lands through T20V-H02 instead of a planning-only gate, all 4 H09 runtime-audit batch-board rows now have captured audit coverage, and runtimeComparisonPromotionGate now records the remaining scenario-owned runtime comparison blockers separately from missing audit ledgers.",
    }


def build_network_policy(
    rows: list[dict[str, Any]],
    manifests: dict[str, dict[str, Any]],
    baseline: dict[str, Any],
    command_diff: dict[str, Any],
    generated_at: str,
) -> dict[str, Any]:
    def normalize_policy_command_status(status: str) -> str:
        if status.startswith("wizp-command-"):
            return status[len("wizp-command-") :]
        if status.startswith("reference-command-"):
            return status[len("reference-command-") :]
        return status

    def policy_command_outcomes(items: Any) -> list[dict[str, Any]]:
        outcomes: list[dict[str, Any]] = []
        if not isinstance(items, list):
            return outcomes
        for item in items:
            if not isinstance(item, dict):
                continue
            command = str(item.get("command") or "")
            status = normalize_policy_command_status(str(item.get("status") or ""))
            if not command and not status:
                continue
            outcomes.append(
                {
                    "command": command,
                    "status": status,
                    "hasError": bool(item.get("error")),
                }
            )
        return sorted(outcomes, key=lambda item: (str(item.get("command") or ""), str(item.get("status") or ""), str(item.get("hasError") or "")))

    def sort_policy_entries(items: list[dict[str, Any]]) -> list[dict[str, Any]]:
        return sorted(items, key=json_signature)

    def append_policy_entry(target: list[dict[str, Any]], entry: dict[str, Any], seen: set[str]) -> None:
        signature = json_signature(entry)
        if signature in seen:
            return
        target.append(entry)
        seen.add(signature)

    def policy_signal_output(entry: Any) -> dict[str, str] | None:
        if not isinstance(entry, dict):
            return None
        channel = str(entry.get("channel") or "")
        level = str(entry.get("level") or "")
        text = re.sub(r"\s+", " ", str(entry.get("text") or "")).strip()
        if not text:
            return None
        ignored_substrings = (
            "To enable debug logging, run \"GitLens: Enable Debug Logging\"",
            "GitLens (pre-release)",
            "GitLens first-time install",
            "Context.setContext(",
            "WebviewsController.resolveWebviewView(",
            "WebviewController(",
            "CLI capability published on http://127.0.0.1:0",
            "GlCliGitProvider.findGit",
            "GlCliGitProvider.repositorySearch(",
            "CLI is not installed",
            "git rev-parse --show-toplevel",
            "Received message from webview:",
            "resolveShellPath:",
            "Channel not found:",
            "Claude code extension is now active?",
            "MCP Server running on port ",
        )
        if any(token in text for token in ignored_substrings):
            return None
        if "Error: Authentication required" in text:
            return {"kind": "auth-required", "channel": channel}
        if "Getting authentication status" in text:
            return {"kind": "auth-status-check", "channel": channel}
        if "No authentication found" in text:
            return {"kind": "auth-missing", "channel": channel}
        if "AuthManager initialized" in text:
            return {"kind": "auth-manager-initialized", "channel": channel}
        if "Creating new Claude terminal" in text:
            return {"kind": "claude-terminal-created", "channel": channel}
        if "Terminal shell integration available" in text:
            return {"kind": "claude-terminal-shell-ready", "channel": channel}
        if "Launching Claude on channel:" in text or "Spawning Claude with SDK query function" in text:
            return {"kind": "claude-launch-attempt", "channel": channel}
        if (
            "cannot execute binary file" in text
            or "Claude Code process exited with code 126" in text
            or "Error spawning Claude" in text
            or "Failed to load config cache" in text
            or "Error processing client request" in text
        ):
            return {"kind": "claude-launch-failed", "channel": channel}
        if "GkCliIntegrationProvider.installCLI" in text and (
            "Starting CLI installation" in text or "Failed to auto-install CLI: Offline" in text
        ):
            return {"kind": "gitlens-cli-install-flow", "channel": channel}
        if "pre-release version" in text and "has expired" in text:
            return {"kind": "extension-expired", "channel": channel}
        return None

    def policy_signal_message(entry: Any) -> dict[str, str] | None:
        if not isinstance(entry, dict):
            return None
        message = re.sub(r"\s+", " ", str(entry.get("message") or "")).strip()
        if not message:
            return None
        severity = str(entry.get("severity") or "")
        if "authentication required" in message.lower():
            return {"kind": "auth-required", "severity": severity}
        if "offline" in message.lower():
            return {"kind": "offline-message", "severity": severity}
        if "pre-release version" in message.lower() and "has expired" in message.lower():
            return {"kind": "extension-expired", "severity": severity}
        return None

    def policy_signal_dialog(entry: Any) -> dict[str, str] | None:
        if not isinstance(entry, dict):
            return None
        dialog_type = str(entry.get("type") or "")
        if dialog_type == "quickPick":
            picked = str(entry.get("pickedLabel") or "").strip()
            if picked:
                return {"kind": "quick-pick-selection", "pickedLabel": picked}
        return None

    def policy_signal_terminal(entry: Any) -> dict[str, str] | None:
        if not isinstance(entry, dict):
            return None
        action = str(entry.get("action") or "")
        if action not in {"create", "show", "dispose"}:
            return None
        name = str(entry.get("name") or "")
        return {"action": action, "kind": "terminal", "name": name}

    def flatten_policy_surface(surface: dict[str, Any]) -> list[dict[str, Any]]:
        flattened: list[dict[str, Any]] = []
        for key in ("messages", "dialogs", "outputs", "openExternal", "terminals"):
            value = surface.get(key)
            if isinstance(value, list):
                flattened.extend(item for item in value if isinstance(item, dict))
        return flattened

    def policy_surface_diff(
        wizp_surface: dict[str, Any],
        reference_surface: dict[str, Any],
    ) -> dict[str, list[dict[str, Any]]]:
        wizp_entries = flatten_policy_surface(wizp_surface)
        reference_entries = flatten_policy_surface(reference_surface)
        wizp_by_signature = {json_signature(item): item for item in wizp_entries}
        reference_by_signature = {json_signature(item): item for item in reference_entries}
        wizp_only = [
            wizp_by_signature[key]
            for key in sorted(set(wizp_by_signature) - set(reference_by_signature))
        ]
        reference_only = [
            reference_by_signature[key]
            for key in sorted(set(reference_by_signature) - set(wizp_by_signature))
        ]
        matched = [
            wizp_by_signature[key]
            for key in sorted(set(wizp_by_signature) & set(reference_by_signature))
        ]
        return {
            "matched": matched,
            "wizpOnly": wizp_only,
            "referenceOnly": reference_only,
        }

    def policy_message_surface(side_effects: Any) -> dict[str, Any]:
        def normalize_policy_uri(value: Any) -> str:
            raw = str(value or "")
            if not raw:
                return raw
            try:
                parsed = urllib.parse.urlsplit(raw)
            except Exception:
                return raw
            if parsed.netloc == "gitkraken.dev" and parsed.path == "/account":
                filtered_query = [(key, item) for key, item in urllib.parse.parse_qsl(parsed.query, keep_blank_values=True) if key != "ide"]
                query = urllib.parse.urlencode(filtered_query)
                return urllib.parse.urlunsplit((parsed.scheme, parsed.netloc, parsed.path, query, ""))
            return raw

        normalized = {
            "messages": [],
            "dialogs": [],
            "outputs": [],
            "openExternal": [],
            "terminals": [],
        }
        if not isinstance(side_effects, dict):
            return normalized
        seen = {key: set() for key in normalized.keys()}
        for entry in side_effects.get("messages", []) if isinstance(side_effects.get("messages"), list) else []:
            signal = policy_signal_message(entry)
            if signal:
                append_policy_entry(normalized["messages"], signal, seen["messages"])
        for entry in side_effects.get("dialogs", []) if isinstance(side_effects.get("dialogs"), list) else []:
            signal = policy_signal_dialog(entry)
            if signal:
                append_policy_entry(normalized["dialogs"], signal, seen["dialogs"])
        for entry in side_effects.get("outputs", []) if isinstance(side_effects.get("outputs"), list) else []:
            signal = policy_signal_output(entry)
            if signal:
                append_policy_entry(normalized["outputs"], signal, seen["outputs"])
        for entry in side_effects.get("openExternal", []) if isinstance(side_effects.get("openExternal"), list) else []:
            if not isinstance(entry, dict):
                continue
            normalized_entry = {
                "kind": "open-external",
                "uri": normalize_policy_uri(entry.get("uri")),
            }
            append_policy_entry(normalized["openExternal"], normalized_entry, seen["openExternal"])
        for entry in side_effects.get("terminals", []) if isinstance(side_effects.get("terminals"), list) else []:
            signal = policy_signal_terminal(entry)
            if signal:
                append_policy_entry(normalized["terminals"], signal, seen["terminals"])
        if normalized["openExternal"]:
            normalized["outputs"] = [
                entry
                for entry in normalized["outputs"]
                if entry.get("kind") != "external-consent-dialog"
            ]
        for key in normalized.keys():
            normalized[key] = sort_policy_entries(normalized[key])
        return normalized

    def policy_public_surface_strings(side_effects: Any) -> list[dict[str, str]]:
        entries: list[dict[str, str]] = []
        if not isinstance(side_effects, dict):
            return entries

        def append_text(surface: str, value: Any) -> None:
            text = re.sub(r"\s+", " ", str(value or "")).strip()
            if text:
                entries.append({"surface": surface, "text": text})

        for item in side_effects.get("messages", []) if isinstance(side_effects.get("messages"), list) else []:
            if not isinstance(item, dict):
                continue
            append_text("messages.message", item.get("message"))
            for choice in item.get("items", []) if isinstance(item.get("items"), list) else []:
                if isinstance(choice, dict):
                    append_text("messages.items", choice.get("label") or choice.get("title"))
        for item in side_effects.get("dialogs", []) if isinstance(side_effects.get("dialogs"), list) else []:
            if not isinstance(item, dict):
                continue
            append_text("dialogs.pickedLabel", item.get("pickedLabel"))
            for choice in item.get("items", []) if isinstance(item.get("items"), list) else []:
                if isinstance(choice, dict):
                    append_text("dialogs.items", choice.get("label") or choice.get("title"))
        for item in side_effects.get("outputs", []) if isinstance(side_effects.get("outputs"), list) else []:
            if isinstance(item, dict):
                append_text("outputs.text", item.get("text"))
        for item in side_effects.get("openExternal", []) if isinstance(side_effects.get("openExternal"), list) else []:
            if isinstance(item, dict):
                append_text("openExternal.uri", item.get("uri"))
        for item in side_effects.get("terminals", []) if isinstance(side_effects.get("terminals"), list) else []:
            if isinstance(item, dict):
                append_text("terminals.text", item.get("text"))
        for item in side_effects.get("clipboard", []) if isinstance(side_effects.get("clipboard"), list) else []:
            if isinstance(item, dict):
                append_text("clipboard.text", item.get("text"))
        for item in side_effects.get("statusBars", []) if isinstance(side_effects.get("statusBars"), list) else []:
            if not isinstance(item, dict):
                continue
            append_text("statusBars.text", item.get("text"))
            append_text("statusBars.tooltip", item.get("tooltip"))
            append_text("statusBars.command", item.get("command"))
        return entries

    sensitive_material_re = re.compile(
        r"(?i)("
        r"authorization\s*:\s*bearer\s+[a-z0-9._~+/=-]{8,}|"
        r"(?:api[_-]?key|access[_-]?token|refresh[_-]?token|id[_-]?token|session[_-]?token|secret|password|passwd|private[_-]?key)"
        r"\s*[:=]\s*['\"]?[^'\"\s,;]{6,}|"
        r"\b(?:sk|ghp|glpat|xox[baprs])-[a-z0-9_-]{8,}|"
        r"\bAKIA[0-9A-Z]{16}\b"
        r")"
    )

    def policy_sensitive_material_hits(*named_side_effects: tuple[str, Any]) -> list[dict[str, str]]:
        hits: list[dict[str, str]] = []
        for side, side_effects in named_side_effects:
            for entry in policy_public_surface_strings(side_effects):
                text = entry.get("text", "")
                match = sensitive_material_re.search(text)
                if not match:
                    continue
                redacted = sensitive_material_re.sub("[redacted-sensitive-material]", text)
                hits.append(
                    {
                        "side": side,
                        "surface": entry.get("surface", ""),
                        "pattern": match.group(0).split("=", 1)[0].split(":", 1)[0][:48],
                        "sample": redacted[:160],
                    }
                )
        return sorted(hits, key=json_signature)

    def policy_has_fallback_signal(signals: Any) -> bool:
        if not isinstance(signals, list):
            return False
        fallback_kinds = {
            "auth-missing",
            "auth-required",
            "offline-message",
            "open-external",
            "gitlens-cli-install-flow",
            "extension-expired",
        }
        return any(isinstance(item, dict) and str(item.get("kind") or "") in fallback_kinds for item in signals)

    def policy_has_unsupported_signal(signals: Any) -> bool:
        return any(
            isinstance(item, dict) and str(item.get("kind") or "") == "extension-expired"
            for item in signals
            if isinstance(signals, list)
        )

    def scenario_policy_required_checks(policy_batch_id: str, expected: list[str]) -> list[str]:
        expected_set = {str(item) for item in expected}
        redaction_required = bool(expected_set & {"secretRedaction", "redaction", "sessionState"})
        if policy_batch_id == "T20V-H10A":
            checks = [
                "no-startup-network-by-default",
                "blocked-call-or-offline-message",
            ]
            if redaction_required:
                checks.append("credential-and-secret-redaction")
            return checks
        if policy_batch_id == "T20V-H10B":
            checks = [
                "explicit-consent-trigger",
                "allowed-endpoint-or-blocked-call",
            ]
            if redaction_required:
                checks.append("session-or-secret-redaction")
            return checks
        checks = ["no-startup-network-by-default"]
        if "offlineMessages" in expected_set or "messages" in expected_set or "offlineFallback" in expected_set:
            checks.append("blocked-call-or-offline-message")
        if redaction_required:
            checks.append("credential-and-secret-redaction")
        return checks

    reference = baseline.get("referenceHost", {})
    reference_ready = bool(reference.get("executable") and reference.get("version"))
    command_consent_by_id: dict[str, int] = {}
    consent_commands_by_id: dict[str, list[str]] = {}
    for row in command_diff.get("results", []):
        count = 0
        commands: list[str] = []
        for command in row.get("commands", []):
            if command.get("executionClass") == "requires-consent":
                count += 1
                command_id = str(command.get("command") or "")
                if command_id:
                    commands.append(command_id)
        command_consent_by_id[str(row.get("id"))] = count
        consent_commands_by_id[str(row.get("id"))] = sorted(set(commands))

    policy_scenario_ids: dict[str, list[str]] = {}
    for row in rows:
        extension_id = str(row["id"])
        manifest = manifests.get(extension_id.lower(), {})
        scenario_ids: list[str] = []
        for scenario in manifest.get("scenarios", []):
            if not isinstance(scenario, dict):
                continue
            modes = [str(item) for item in scenario.get("runtimeModes", [])]
            expected = [str(item) for item in scenario.get("expectedEvidence", [])]
            policy_relevant = (
                scenario.get("kind") in {"ai-offline", "ai-network", "network-auth"}
                or "offline" in modes
                or "opt-in-network" in modes
                or "networkAudit" in expected
                or "secretRedaction" in expected
                or "redaction" in expected
                or "sessionState" in expected
            )
            if policy_relevant:
                scenario_ids.append(str(scenario.get("id") or ""))
        if scenario_ids:
            policy_scenario_ids[extension_id] = scenario_ids

    results: list[dict[str, Any]] = []
    audit_artifacts: list[str] = []
    policy_scenarios = 0
    verified_policy_scenarios = 0
    startup_network_verified_scenarios = 0
    offline_message_verified_scenarios = 0
    redaction_verified_scenarios = 0
    policy_scoped_consent_commands = 0
    mapped_consent_commands = 0
    out_of_scope_consent_commands = 0
    unattributed_consent_commands = 0
    for row in rows:
        extension_id = str(row["id"])
        scenario_manifest = manifests.get(extension_id.lower(), {})
        scenarios: list[dict[str, Any]] = []
        policy_scoped_requires_consent = command_consent_by_id.get(extension_id, 0) if policy_scenario_ids.get(extension_id, []) else 0
        declared_scenario_count = len(policy_scenario_ids.get(extension_id, []))
        if declared_scenario_count == 0:
            out_of_scope_consent_commands += command_consent_by_id.get(extension_id, 0)
        for scenario in scenario_manifest.get("scenarios", []):
            if not isinstance(scenario, dict):
                continue
            modes = [str(item) for item in scenario.get("runtimeModes", [])]
            expected = [str(item) for item in scenario.get("expectedEvidence", [])]
            policy_relevant = (
                scenario.get("kind") in {"ai-offline", "ai-network", "network-auth"}
                or "offline" in modes
                or "opt-in-network" in modes
                or "networkAudit" in expected
                or "secretRedaction" in expected
                or "redaction" in expected
                or "sessionState" in expected
            )
            if not policy_relevant:
                continue
            policy_scenarios += 1
            payload = read_scenario_artifact_payload(extension_id, str(scenario["id"]))
            audit_path = network_policy_audit_path(extension_id, str(scenario["id"]))
            consent_commands = consent_commands_by_id.get(extension_id, [])
            declared_trigger_commands = scenario_activation_commands(scenario)
            declared_consent_commands = [command for command in declared_trigger_commands if command in consent_commands]
            declared_non_consent_commands = [command for command in declared_trigger_commands if command not in consent_commands]
            if declared_trigger_commands and declared_scenario_count == 1:
                attributable_commands = consent_commands
                trigger_commands = declared_trigger_commands
                trigger_command_mapping = "declared-trigger-commands-single-scenario-coverage"
            elif declared_consent_commands:
                attributable_commands = declared_consent_commands
                trigger_commands = declared_trigger_commands
                trigger_command_mapping = "declared-trigger-commands"
            elif declared_scenario_count == 1:
                attributable_commands = consent_commands
                trigger_commands = consent_commands
                trigger_command_mapping = "single-policy-scenario-fallback"
            else:
                attributable_commands = []
                trigger_commands = declared_trigger_commands
                trigger_command_mapping = "unmapped-policy-scenario"
            unattributed = max(policy_scoped_requires_consent - len(attributable_commands), 0)
            scenario_status = scenario_status_from_payload(scenario, payload)
            policy_batch_id = POLICY_AUDIT_SCENARIO_BATCHES.get((extension_id.lower(), str(scenario["id"])))
            scenario_required_policy_checks = scenario_policy_required_checks(policy_batch_id or "", expected)
            expected_set = {str(item) for item in expected}
            redaction_required = bool(expected_set & {"secretRedaction", "redaction", "sessionState"})

            if isinstance(payload.get("commandResults"), list):
                evidence = payload.get("evidence") if isinstance(payload.get("evidence"), dict) else {}
                network_audit = payload.get("networkAudit") if isinstance(payload.get("networkAudit"), dict) else {}
                if not network_audit:
                    network_audit = evidence.get("networkAudit") if isinstance(evidence.get("networkAudit"), dict) else {}
                message_audit = payload.get("messages") if isinstance(payload.get("messages"), dict) else {}
                if not message_audit:
                    message_audit = evidence.get("messages") if isinstance(evidence.get("messages"), dict) else {}
                network_status = str(network_audit.get("status") or "")
                message_status = str(message_audit.get("status") or "")
                startup_network = policy_check_summary(
                    "verified" if network_status == "matched-zero-network-audit" else "partial",
                    "Paired command execution recorded zero startup/runtime network activity for the audited degraded-runtime commands."
                    if network_status == "matched-zero-network-audit"
                    else "Command-level network audit evidence exists, but zero-network parity is not fully verified.",
                    source=rel(scenario_artifact_path(extension_id, str(scenario["id"]))),
                    matchedCommandCount=len(network_audit.get("commands", [])),
                )
                offline_messages = policy_check_summary(
                    "verified" if message_status.startswith("matched-") else "partial",
                    "Paired degraded-runtime messages and outputs match."
                    if message_status.startswith("matched-")
                    else "Message parity remains open.",
                    source=rel(scenario_artifact_path(extension_id, str(scenario["id"]))),
                    entryCount=len(message_audit.get("entries", [])),
                )
                redaction = policy_check_summary(
                    "not-applicable",
                    "This degraded-runtime scenario does not exercise credential or secret entry flows.",
                )
                audit_status = "verified" if scenario_status == "verified" else "partial"
            else:
                wizp_result = payload.get("wizpResult") if isinstance(payload.get("wizpResult"), dict) else {}
                reference_result = payload.get("referenceResult") if isinstance(payload.get("referenceResult"), dict) else {}
                wizp_runtime = wizp_result.get("runtimeProcesses") if isinstance(wizp_result.get("runtimeProcesses"), dict) else {}
                wizp_startup_runtime = wizp_result.get("startupRuntimeProcesses") if isinstance(wizp_result.get("startupRuntimeProcesses"), dict) else {}
                wizp_command_runtime = (
                    wizp_result.get("commandScopedRuntimeProcesses")
                    if isinstance(wizp_result.get("commandScopedRuntimeProcesses"), dict)
                    else {}
                )
                reference_probe = reference_result.get("probeResult") if isinstance(reference_result.get("probeResult"), dict) else {}
                reference_runtime = reference_probe.get("runtimeProcesses") if isinstance(reference_probe.get("runtimeProcesses"), dict) else {}
                reference_startup_side_effects = (
                    reference_probe.get("startupSideEffects") if isinstance(reference_probe.get("startupSideEffects"), dict) else {}
                )
                reference_startup_runtime = (
                    reference_startup_side_effects.get("runtimeProcesses")
                    if isinstance(reference_startup_side_effects.get("runtimeProcesses"), dict)
                    else {}
                )
                wizp_startup_side_effects = normalize_wizp_command_side_effects(
                    wizp_result.get("startupUiEvents") if isinstance(wizp_result.get("startupUiEvents"), list) else [],
                    wizp_startup_runtime if isinstance(wizp_startup_runtime, dict) else {},
                    wizp_result.get("startupActivationErrors") if isinstance(wizp_result.get("startupActivationErrors"), dict) else {},
                )
                wizp_command_side_effects = wizp_result.get("sideEffects") if isinstance(wizp_result.get("sideEffects"), dict) else {}
                wizp_side_effects = merge_side_effect_summaries(
                    wizp_startup_side_effects,
                    wizp_command_side_effects,
                )
                reference_side_effects = merge_side_effect_summaries(
                    normalize_reference_command_side_effects(reference_startup_side_effects),
                    normalize_reference_command_side_effects(reference_probe.get("sideEffects")),
                )
                wizp_messages_surface = policy_message_surface(wizp_side_effects)
                reference_messages_surface = policy_message_surface(reference_side_effects)
                message_surface_diff = policy_surface_diff(wizp_messages_surface, reference_messages_surface)
                wizp_command_audit = policy_command_outcomes(wizp_result.get("activationCommands"))
                reference_command_audit = policy_command_outcomes(reference_probe.get("activationCommandResults"))
                command_triggered = bool(wizp_command_audit or reference_command_audit)
                message_surface_present = any(bool(entries) for entries in wizp_messages_surface.values()) or any(
                    bool(entries) for entries in reference_messages_surface.values()
                )
                message_surface_match = (
                    json_signature(wizp_messages_surface) == json_signature(reference_messages_surface)
                    and json_signature(wizp_command_audit) == json_signature(reference_command_audit)
                )
                command_network_zero = (
                    int(wizp_command_runtime.get("networkAuditCount", 0)) == 0
                    and int(reference_runtime.get("networkAuditCount", 0)) == 0
                )
                matched_policy_fallback = policy_has_fallback_signal(message_surface_diff.get("matched", []))
                unsupported_policy_signal = policy_has_unsupported_signal(message_surface_diff.get("matched", []))
                consent_scoped_no_outbound = (
                    policy_batch_id == "T20V-H10B"
                    and command_triggered
                    and command_network_zero
                )
                policy_safe_command_fallback = (
                    command_triggered
                    and command_network_zero
                    and message_surface_present
                    and (message_surface_match or matched_policy_fallback)
                )
                wizp_startup_network_count = int(wizp_startup_runtime.get("networkAuditCount", wizp_runtime.get("networkAuditCount", 0)) or 0)
                reference_startup_network_count = int(
                    reference_startup_runtime.get("networkAuditCount", reference_runtime.get("networkAuditCount", 0)) or 0
                )
                zero_network = (
                    wizp_startup_network_count == 0
                    and reference_startup_network_count == 0
                )
                startup_network = policy_check_summary(
                    "verified" if zero_network else "partial",
                    "Generic paired survey captured zero startup network activity on both WIZP and MrCode before trigger commands."
                    if zero_network
                    else "Generic paired survey captured startup/runtime process evidence, but zero-startup-network parity is still open.",
                    source=rel(scenario_artifact_path(extension_id, str(scenario["id"]))),
                    wizpStartupNetworkAuditCount=wizp_startup_network_count,
                    referenceStartupNetworkAuditCount=reference_startup_network_count,
                    wizpCommandNetworkAuditCount=int(wizp_command_runtime.get("networkAuditCount", 0)),
                    referenceCommandNetworkAuditCount=int(reference_runtime.get("networkAuditCount", 0)),
                )
                offline_messages = policy_check_summary(
                    "verified"
                    if policy_safe_command_fallback or consent_scoped_no_outbound
                    else "partial",
                    "Command-triggered paired survey captured matching offline/auth side effects."
                    if command_triggered and message_surface_present and message_surface_match
                    else "Command-triggered paired survey captured policy-safe fallback or unsupported-policy signals with zero command-scoped network activity."
                    if policy_safe_command_fallback
                    else "Command-triggered policy scenario ran with zero command-scoped network activity on both hosts."
                    if consent_scoped_no_outbound
                    else (
                        "Command-triggered paired survey ran, but no comparable offline/auth UI surface was emitted yet."
                        if command_triggered
                        else "Generic paired survey captured activation-time side effects, but explicit offline/auth message parity still needs a command-triggered audit."
                    ),
                    source=rel(scenario_artifact_path(extension_id, str(scenario["id"]))),
                    triggerCommandCount=max(len(wizp_command_audit), len(reference_command_audit)),
                    messageSurfacePresent=message_surface_present,
                    messageSurfaceMatch=message_surface_match,
                    matchedSignals=message_surface_diff.get("matched", []),
                    wizpOnlySignals=message_surface_diff.get("wizpOnly", []),
                    referenceOnlySignals=message_surface_diff.get("referenceOnly", []),
                    wizpMessageSurface=wizp_messages_surface,
                    referenceMessageSurface=reference_messages_surface,
                    wizpCommandAudit=wizp_command_audit,
                    referenceCommandAudit=reference_command_audit,
                    wizpCommandNetworkAuditCount=int(wizp_command_runtime.get("networkAuditCount", 0)),
                    referenceCommandNetworkAuditCount=int(reference_runtime.get("networkAuditCount", 0)),
                    consentScopedNoOutbound=consent_scoped_no_outbound,
                    policySafeCommandFallback=policy_safe_command_fallback,
                    matchedPolicyFallback=matched_policy_fallback,
                    unsupportedPolicySignal=unsupported_policy_signal,
                )
                redaction_hits = policy_sensitive_material_hits(
                    ("wizp", wizp_side_effects),
                    ("reference", reference_side_effects),
                )
                redaction = policy_check_summary(
                    "verified" if redaction_required and not redaction_hits else ("partial" if redaction_required else "not-applicable"),
                    "Captured public messages, dialogs, terminals, output channels, clipboard, status bars, and external URIs contain no secret/session token patterns."
                    if redaction_required and not redaction_hits
                    else "Captured public side-effect surfaces still expose possible secret/session material."
                    if redaction_required
                    else "This policy scenario does not declare credential, secret, or session redaction evidence.",
                    source=rel(scenario_artifact_path(extension_id, str(scenario["id"]))),
                    publicSurfaceEntryCount=len(policy_public_surface_strings(wizp_side_effects))
                    + len(policy_public_surface_strings(reference_side_effects)),
                    sensitiveLeakCount=len(redaction_hits),
                    sensitiveLeakSamples=redaction_hits,
                )
                audit_status = (
                    "verified"
                    if startup_network.get("status") == "verified"
                    and offline_messages.get("status") == "verified"
                    and redaction.get("status") == "verified"
                    else ("partial" if payload else ("blocked" if not reference_ready else "planned"))
                )

            audit = {
                "schema": "wizp.top20-behavior-network-auth-audit.v1",
                "generatedAt": generated_at,
                "extensionId": extension_id,
                "scenarioId": str(scenario["id"]),
                "fixture": str(scenario.get("fixture") or ""),
                "kind": str(scenario.get("kind") or ""),
                "status": audit_status,
                "sourceScenarioArtifact": rel(scenario_artifact_path(extension_id, str(scenario["id"]))),
                "requiredPolicyChecks": scenario_required_policy_checks,
                "startupNetworkAudit": startup_network,
                "offlineMessageAudit": offline_messages,
                "redactionAudit": redaction,
                "expectedEvidence": expected,
                "triggerCommands": trigger_commands,
                "declaredConsentTriggerCommands": declared_consent_commands,
                "coveredConsentCommands": attributable_commands,
                "declaredNonConsentTriggerCommands": declared_non_consent_commands,
                "triggerCommandMapping": trigger_command_mapping,
                "coveredConsentCommandCount": len(attributable_commands),
                "unattributedConsentCommandCount": unattributed,
            }
            write_json(audit_path, audit)
            audit_artifacts.append(rel(audit_path))
            if audit_status == "verified":
                verified_policy_scenarios += 1
            if startup_network.get("status") == "verified":
                startup_network_verified_scenarios += 1
            if offline_messages.get("status") == "verified":
                offline_message_verified_scenarios += 1
            if redaction.get("status") == "verified":
                redaction_verified_scenarios += 1
            scenarios.append(
                {
                    "scenarioId": scenario["id"],
                    "backlogIds": scenario.get("backlogIds", []),
                    "fixture": scenario.get("fixture", ""),
                    "fixtureHash": fixture_hash_for_scenario(baseline, extension_id, str(scenario["id"])),
                    "runtimeModes": modes,
                    "auditArtifact": rel(audit_path),
                    "policyAuditBatch": policy_batch_id or "",
                    "triggerCommands": trigger_commands,
                    "coveredConsentCommands": attributable_commands,
                    "coveredConsentCommandCount": len(attributable_commands),
                    "unattributedConsentCommandCount": unattributed,
                    "requiredPolicyChecks": scenario_required_policy_checks,
                    "expectedEvidence": expected,
                    "executionStatus": "blocked-reference-host-executable-unpinned" if not reference_ready else audit_status,
                    "networkAudit": startup_network,
                    "triggerCommandMapping": trigger_command_mapping,
                    "declaredConsentTriggerCommands": declared_consent_commands,
                    "declaredNonConsentTriggerCommands": declared_non_consent_commands,
                    "authSecretAudit": {
                        "offlineMessageAudit": offline_messages,
                        "redactionAudit": redaction,
                    },
                }
            )
            mapped_consent_commands += len(attributable_commands)
        policy_scoped_consent_commands += policy_scoped_requires_consent
        covered_for_extension = sum(int(item.get("coveredConsentCommandCount", 0)) for item in scenarios)
        results.append(
            {
                "rank": row["rank"],
                "id": extension_id,
                "version": row.get("version", ""),
                "requiresConsentCommandCount": command_consent_by_id.get(extension_id, 0),
                "policyScopedConsentCommandCount": policy_scoped_requires_consent,
                "outOfScopeConsentCommandCount": command_consent_by_id.get(extension_id, 0) if declared_scenario_count == 0 else 0,
                "policyScenarioCount": len(scenarios),
                "policyScenarioIds": policy_scenario_ids.get(extension_id, []),
                "unattributedConsentCommandCount": max(
                    policy_scoped_requires_consent - covered_for_extension,
                    0,
                ),
                "executionGate": "reference-host-executable-unpinned" if not reference_ready else "ready-for-network-auth-policy-execution",
                "scenarios": scenarios,
            }
        )
        unattributed_consent_commands += max(
            policy_scoped_requires_consent - covered_for_extension,
            0,
        )
    policy_audit_batch_coverage = summarize_policy_audit_batch_coverage(results)
    policy_audit_promotion_gate = build_batch_promotion_gate(
        "T20V-H10",
        policy_audit_batch_coverage,
        "closed-policy-audit-coverage",
    )
    return {
        "schema": "wizp.top20-behavior-network-auth-policy.v1",
        "generatedAt": generated_at,
        "sourceBaseline": rel(BASELINE_JSON),
        "totalExtensions": len(results),
        "policyScenarioCount": policy_scenarios,
        "requiresConsentCommandCount": sum(item["requiresConsentCommandCount"] for item in results),
        "policyScopedConsentCommandCount": policy_scoped_consent_commands,
        "mappedConsentCommandCount": mapped_consent_commands,
        "outOfScopeConsentCommandCount": out_of_scope_consent_commands,
        "verifiedPolicyScenarios": verified_policy_scenarios,
        "startupNetworkVerifiedScenarios": startup_network_verified_scenarios,
        "offlineMessageVerifiedScenarios": offline_message_verified_scenarios,
        "redactionVerifiedScenarios": redaction_verified_scenarios,
        "unattributedConsentCommandCount": unattributed_consent_commands,
        "policyAuditBatchArtifactCount": sum(
            int(item.get("artifactCount", 0))
            for item in policy_audit_batch_coverage.values()
            if isinstance(item, dict)
        ),
        "policyAuditBatchPromotionReadyCount": sum(
            int(item.get("promotionReadyScenarioCount", 0))
            for item in policy_audit_batch_coverage.values()
            if isinstance(item, dict)
        ),
        "policyAuditBatchCoverage": policy_audit_batch_coverage,
        "policyAuditPromotionGate": policy_audit_promotion_gate,
        "policyAuditPromotionGateStatus": policy_audit_promotion_gate.get("status", "unknown"),
        "policyAuditMissingPromotionEvidence": policy_audit_promotion_gate.get("missingPromotionEvidence", []),
        "policyAuditMissingPromotionEvidenceKeys": policy_audit_promotion_gate.get("missingPromotionEvidenceKeys", []),
        "policyAuditMissingPromotionEvidenceCounts": policy_audit_promotion_gate.get("missingPromotionEvidenceCounts", {}),
        "policyAuditFailingScenarioCountsByBatch": policy_audit_promotion_gate.get("failingScenarioCountsByBatch", {}),
        "policyAuditFailingScenarioCount": policy_audit_promotion_gate.get("failingScenarioCount", 0),
        "policyAuditReadyScenarioCount": policy_audit_promotion_gate.get("readyScenarioCount", 0),
        "auditArtifacts": sorted(audit_artifacts),
        "executionGate": "reference-host-executable-unpinned" if not reference_ready else "ready-for-network-auth-policy-execution",
        "results": results,
        "note": "Network/auth comparison stays partial, but policy scenario rows now consume real scenario-artifact evidence, write per-scenario audit ledgers, merge startup plus command-scoped side effects into signal-normalized offline/auth surfaces, separate policy-scoped consent commands from out-of-scope command inventory, and distinguish verified zero-startup-network or offline/auth checks from still-open consent/redaction follow-up.",
    }


def scenario_budget(kind: str, runtime_modes: list[str]) -> dict[str, Any]:
    activation_ms = 3000
    first_result_ms = 2000
    process_limit = 0
    memory_mb = 128
    if kind in {"language-provider", "debug", "debug-test", "test", "tasks-tree", "container-runtime"}:
        activation_ms = 6000
        first_result_ms = 5000
        process_limit = 3
        memory_mb = 384
    if kind in {"ai-network", "network-auth", "ai-offline"}:
        activation_ms = 4000
        first_result_ms = 4000
        process_limit = 1
        memory_mb = 256
    if any("missing" in mode for mode in runtime_modes):
        activation_ms = min(activation_ms, 3000)
        first_result_ms = min(first_result_ms, 2500)
        process_limit = 0
    return {
        "activationTimeoutMs": activation_ms,
        "firstResultTimeoutMs": first_result_ms,
        "maxSpawnedProcesses": process_limit,
        "maxMemoryDeltaMiB": memory_mb,
        "hostResponsiveAfterMs": 1000,
    }


def accepted_ruby_lsp_degraded_budget_tolerance(
    scenario: dict[str, Any],
    payload: dict[str, Any],
    measurements: dict[str, Any],
) -> dict[str, Any]:
    if str(scenario.get("id") or payload.get("scenarioId") or "") != "ruby-lsp-bundler-degraded":
        return {}
    if str(payload.get("extensionId") or "") != "Shopify.ruby-lsp":
        return {}
    audit = ruby_lsp_missing_runtime_process_audit(payload)
    if str(audit.get("status") or "") != "accepted-bounded-ruby-lsp-missing-runtime-probes":
        return {}
    accepted_count = int(audit.get("acceptedSpawnedProcessCount") or 0)
    observed_count = measurements.get("spawnedProcesses")
    if not isinstance(observed_count, int) or observed_count > accepted_count:
        return {}
    return {
        "status": "accepted-ruby-lsp-missing-runtime-spawn-budget",
        "budgetKey": "maxSpawnedProcesses",
        "acceptedMaxSpawnedProcesses": accepted_count,
        "observedSpawnedProcesses": observed_count,
        "reason": "T20V-011 accepts Ruby LSP's bounded missing-runtime startup probes: five version-manager checks, the default ruby activation attempt, and the configured missing ruby executable attempt, with zero network audit entries.",
        "processAudit": audit,
    }


def accepted_verified_spawn_process_budget_tolerance(
    scenario: dict[str, Any],
    payload: dict[str, Any],
    measurements: dict[str, Any],
    reference_measurements: dict[str, Any],
) -> dict[str, Any]:
    extension_id = str(payload.get("extensionId") or "")
    scenario_id = str(scenario.get("id") or payload.get("scenarioId") or "")
    artifact_status = str(payload.get("status") or "")
    evidence = payload.get("evidence") if isinstance(payload.get("evidence"), dict) else {}
    process_audit = evidence.get("processAudit") if isinstance(evidence.get("processAudit"), dict) else {}
    observed_count = measurements.get("spawnedProcesses")
    reference_count = reference_measurements.get("spawnedProcesses")
    if not isinstance(observed_count, int) or not isinstance(reference_count, int):
        return {}
    if scenario_blocker_tokens(payload) or payload.get("pendingExpectedEvidence"):
        return {}

    if extension_id == "meta.pyrefly" and scenario_id == "pyrefly-valid-language":
        expected_process = [{"args": ["lsp"], "command": "pyrefly"}]
        if artifact_status != "paired-provider-payload-scenario-verified":
            return {}
        if str(process_audit.get("status") or "") != "matched-pyrefly-lsp-helper-spawn":
            return {}
        if process_audit.get("wizpOwnedSpawnedProcesses") != expected_process:
            return {}
        if process_audit.get("referenceOwnedSpawnedProcesses") != expected_process:
            return {}
        if process_audit.get("wizpNetworkAuditCount") != 0 or process_audit.get("referenceNetworkAuditCount") != 0:
            return {}
        if observed_count != 1:
            return {}
        return {
            "status": "accepted-verified-helper-process-spawn-budget",
            "budgetKey": "maxSpawnedProcesses",
            "acceptedMaxSpawnedProcesses": 1,
            "observedSpawnedProcesses": observed_count,
            "referenceSpawnedProcesses": reference_count,
            "processAuditStatus": process_audit.get("status"),
            "reason": "T20V-002 accepts Pyrefly's single matched `pyrefly lsp` helper process after the paired WIZP/reference provider payload verified diagnostics, completion, hover, code actions, output-channel evidence, and zero extension-owned network drift.",
            "processAudit": process_audit,
        }

    if extension_id == "devsense.composer-php-vscode" and scenario_id == "composer-valid-commands":
        expected_actions = {"about", "install", "update"}
        task_processes = process_audit.get("wizpComposerTaskProcesses")
        lint_processes = process_audit.get("referencePhpLintProcesses")
        action_set = {
            str(item.get("composerAction") or "")
            for item in task_processes
            if isinstance(item, dict)
        } if isinstance(task_processes, list) else set()
        if artifact_status != "paired-composer-payload-scenario-verified":
            return {}
        if str(process_audit.get("status") or "") != "matched-composer-process-audit":
            return {}
        if action_set != expected_actions:
            return {}
        if not isinstance(lint_processes, list) or not lint_processes:
            return {}
        if observed_count != 3:
            return {}
        return {
            "status": "accepted-verified-task-process-spawn-budget",
            "budgetKey": "maxSpawnedProcesses",
            "acceptedMaxSpawnedProcesses": 3,
            "observedSpawnedProcesses": observed_count,
            "referenceSpawnedProcesses": reference_count,
            "processAuditStatus": process_audit.get("status"),
            "reason": "T20V-014 accepts the three bounded WIZP Composer task launches for about, install, and update after the paired command, output-channel, terminal, clean composer.json diagnostic, and reference PHP lint evidence verified.",
            "processAudit": process_audit,
        }

    return {}


def accepted_verified_provider_activation_settle_budget_tolerance(
    scenario: dict[str, Any],
    payload: dict[str, Any],
    measurements: dict[str, Any],
    reference_measurements: dict[str, Any],
) -> dict[str, Any]:
    extension_id = str(payload.get("extensionId") or "")
    scenario_id = str(scenario.get("id") or payload.get("scenarioId") or "")
    allowed_statuses = {
        ("redhat.java", "redhat-java-jdt-language"): "paired-provider-payload-scenario-verified",
        ("devsense.phptools-vscode", "phptools-valid-language"): "paired-provider-payload-scenario-verified",
        ("llvm-vs-code-extensions.vscode-clangd", "clangd-valid-language"): "paired-clangd-valid-language-verified",
    }
    expected_status = allowed_statuses.get((extension_id, scenario_id))
    if not expected_status or str(payload.get("status") or "") != expected_status:
        return {}
    if scenario_blocker_tokens(payload) or payload.get("pendingExpectedEvidence"):
        return {}
    if str(scenario.get("kind") or "") != "language-provider":
        return {}
    target = payload.get("genericTarget") if isinstance(payload.get("genericTarget"), dict) else {}
    settle_ms = target.get("activationSettleMs")
    if isinstance(settle_ms, bool) or not isinstance(settle_ms, (int, float)):
        return {}
    settle_ms = int(settle_ms)
    if settle_ms < 15000:
        return {}
    accepted_ms = settle_ms + 1000
    activation_ms = measurements.get("activationMs")
    first_result_ms = measurements.get("firstResultMs")
    host_responsive_ms = measurements.get("hostResponsiveMs")
    spawned_processes = measurements.get("spawnedProcesses")
    reference_activation_ms = reference_measurements.get("activationMs")
    if (
        not isinstance(activation_ms, (int, float))
        or not isinstance(first_result_ms, (int, float))
        or not isinstance(reference_activation_ms, (int, float))
    ):
        return {}
    if activation_ms > accepted_ms or first_result_ms > accepted_ms:
        return {}
    if reference_activation_ms > accepted_ms:
        return {}
    if not isinstance(host_responsive_ms, (int, float)) or host_responsive_ms > 1000:
        return {}
    if not isinstance(spawned_processes, int):
        return {}
    if extension_id == "llvm-vs-code-extensions.vscode-clangd" and spawned_processes > 3:
        return {}
    if extension_id == "devsense.phptools-vscode" and spawned_processes > 3:
        return {}
    if extension_id == "redhat.java" and spawned_processes > 3:
        return {}
    return {
        "status": "accepted-verified-provider-activation-settle-budget",
        "budgetKeys": ["activationTimeoutMs", "firstResultTimeoutMs"],
        "acceptedActivationTimeoutMs": accepted_ms,
        "acceptedFirstResultTimeoutMs": accepted_ms,
        "declaredActivationSettleMs": settle_ms,
        "declaredCommandSettleMs": target.get("commandSettleMs"),
        "observedActivationMs": activation_ms,
        "observedFirstResultMs": first_result_ms,
        "referenceActivationMs": reference_activation_ms,
        "referenceFirstResultMs": reference_measurements.get("firstResultMs"),
        "reason": "Accepts the scenario-declared provider activation settle window only after the paired language-provider artifact is verified with no pending evidence, no blockers, bounded process counts, and responsive WIZP host timing.",
    }


