def build_performance_budgets(
    rows: list[dict[str, Any]],
    manifests: dict[str, dict[str, Any]],
    baseline: dict[str, Any],
    generated_at: str,
) -> dict[str, Any]:
    reference = baseline.get("referenceHost", {})
    reference_ready = bool(reference.get("executable") and reference.get("version"))
    results: list[dict[str, Any]] = []
    measured_scenario_count = 0
    derived_scenario_count = 0
    covered_scenario_count = 0
    aggregate_budget_checks = {
        "activationWithinBudgetCount": 0,
        "firstResultWithinBudgetCount": 0,
        "spawnedProcessesWithinBudgetCount": 0,
        "memoryDeltaWithinBudgetCount": 0,
        "hostResponsiveWithinBudgetCount": 0,
        "allApplicableChecksPassingCount": 0,
        "wizpBudgetNotApplicableCount": 0,
        "scenariosWithActivationMeasurement": 0,
        "scenariosWithFirstResultMeasurement": 0,
        "scenariosWithSpawnedProcessMeasurement": 0,
        "scenariosWithReferenceActivationMeasurement": 0,
        "scenariosWithReferenceFirstResultMeasurement": 0,
        "scenariosWithReferenceSpawnedProcessMeasurement": 0,
        "referenceTimingCompleteCount": 0,
        "referenceTimingNotApplicableCount": 0,
        "scenariosWithWizpMemoryMeasurement": 0,
        "scenariosWithReferenceMemoryMeasurement": 0,
        "scenariosWithPairedMemoryMeasurement": 0,
        "scenariosWithHostResponsivenessMeasurement": 0,
    }
    promotion_scenarios: list[dict[str, Any]] = []
    scenario_count = 0
    for row in rows:
        extension_id = str(row["id"])
        scenario_manifest = manifests.get(extension_id.lower(), {})
        scenarios: list[dict[str, Any]] = []
        for scenario in scenario_manifest.get("scenarios", []):
            if not isinstance(scenario, dict):
                continue
            modes = [str(item) for item in scenario.get("runtimeModes", [])]
            budget = scenario_budget(str(scenario.get("kind", "")), modes)
            scenario_count += 1
            payload = read_scenario_artifact_payload(extension_id, str(scenario["id"]))
            artifact_path = scenario_artifact_path(extension_id, str(scenario["id"]))
            ownership = scenario_ownership(extension_id, scenario, baseline, payload)
            measurement_artifact = write_performance_measurement_artifact(extension_id, scenario, baseline, payload, generated_at)
            if measurement_artifact.get("status") == "captured":
                measured_scenario_count += 1
            elif measurement_artifact.get("status") == "derived-classifier-only":
                derived_scenario_count += 1
            if measurement_artifact.get("status") in {"captured", "derived-classifier-only"}:
                covered_scenario_count += 1
            measurement_payload = load_json_if_exists(performance_measurement_path(extension_id, str(scenario["id"])))
            budget_checks = measurement_payload.get("budgetChecks") if isinstance(measurement_payload.get("budgetChecks"), dict) else {}
            budget_rule_evaluation = (
                measurement_payload.get("wizpBudgetPassRules")
                if isinstance(measurement_payload.get("wizpBudgetPassRules"), dict)
                else {}
            )
            if str(budget_rule_evaluation.get("status") or "").startswith("not-applicable"):
                aggregate_budget_checks["wizpBudgetNotApplicableCount"] += 1
            measurement_values = measurement_payload.get("wizpMeasurements") if isinstance(measurement_payload.get("wizpMeasurements"), dict) else {}
            reference_measurement_values = (
                measurement_payload.get("referenceMeasurements")
                if isinstance(measurement_payload.get("referenceMeasurements"), dict)
                else {}
            )
            reference_timing_coverage = (
                measurement_payload.get("referenceTimingCoverage")
                if isinstance(measurement_payload.get("referenceTimingCoverage"), dict)
                else {}
            )
            applicable_flags: list[bool] = []
            if measurement_values.get("activationMs") is not None:
                aggregate_budget_checks["scenariosWithActivationMeasurement"] += 1
                flag = bool(budget_checks.get("activationWithinBudget"))
                applicable_flags.append(flag)
                if flag:
                    aggregate_budget_checks["activationWithinBudgetCount"] += 1
            if measurement_values.get("firstResultMs") is not None:
                aggregate_budget_checks["scenariosWithFirstResultMeasurement"] += 1
                flag = bool(budget_checks.get("firstResultWithinBudget"))
                applicable_flags.append(flag)
                if flag:
                    aggregate_budget_checks["firstResultWithinBudgetCount"] += 1
            if measurement_values.get("spawnedProcesses") is not None:
                aggregate_budget_checks["scenariosWithSpawnedProcessMeasurement"] += 1
                flag = bool(budget_checks.get("spawnedProcessesWithinBudget"))
                applicable_flags.append(flag)
                if flag:
                    aggregate_budget_checks["spawnedProcessesWithinBudgetCount"] += 1
            if reference_measurement_values.get("activationMs") is not None:
                aggregate_budget_checks["scenariosWithReferenceActivationMeasurement"] += 1
            if reference_measurement_values.get("firstResultMs") is not None:
                aggregate_budget_checks["scenariosWithReferenceFirstResultMeasurement"] += 1
            if reference_measurement_values.get("spawnedProcesses") is not None:
                aggregate_budget_checks["scenariosWithReferenceSpawnedProcessMeasurement"] += 1
            if (
                reference_measurement_values.get("activationMs") is not None
                and reference_measurement_values.get("firstResultMs") is not None
                and reference_measurement_values.get("spawnedProcesses") is not None
            ):
                aggregate_budget_checks["referenceTimingCompleteCount"] += 1
            if str(reference_timing_coverage.get("status") or "").startswith("not-applicable"):
                aggregate_budget_checks["referenceTimingNotApplicableCount"] += 1
            if measurement_values.get("hostResponsiveMs") is not None:
                aggregate_budget_checks["scenariosWithHostResponsivenessMeasurement"] += 1
                flag = bool(budget_checks.get("hostResponsiveWithinBudget"))
                applicable_flags.append(flag)
                if flag:
                    aggregate_budget_checks["hostResponsiveWithinBudgetCount"] += 1
            if measurement_values.get("memoryDeltaMiB") is not None:
                aggregate_budget_checks["scenariosWithWizpMemoryMeasurement"] += 1
                flag = bool(budget_checks.get("memoryDeltaWithinBudget"))
                applicable_flags.append(flag)
                if flag:
                    aggregate_budget_checks["memoryDeltaWithinBudgetCount"] += 1
            if reference_measurement_values.get("memoryDeltaMiB") is not None:
                aggregate_budget_checks["scenariosWithReferenceMemoryMeasurement"] += 1
            if measurement_values.get("memoryDeltaMiB") is not None and reference_measurement_values.get("memoryDeltaMiB") is not None:
                aggregate_budget_checks["scenariosWithPairedMemoryMeasurement"] += 1
            if applicable_flags and all(applicable_flags):
                aggregate_budget_checks["allApplicableChecksPassingCount"] += 1
            promotion_scenarios.append(
                {
                    "extensionId": extension_id,
                    "scenarioId": str(scenario["id"]),
                    "backlogIds": scenario.get("backlogIds", []),
                    "measurementStatus": measurement_artifact.get("status", "not-run"),
                    "measurementArtifact": measurement_artifact.get("artifact", ""),
                    "executionStatus": scenario_execution_status(payload, reference_ready),
                    "wizpMeasurements": measurement_values,
                    "referenceMeasurements": reference_measurement_values,
                    "budgetChecks": budget_checks,
                    "wizpBudgetPassRules": budget_rule_evaluation,
                    "referenceTimingCoverage": reference_timing_coverage,
                    "memoryTolerance": (
                        measurement_payload.get("memoryTolerance")
                        if isinstance(measurement_payload.get("memoryTolerance"), dict)
                        else {}
                    ),
                    "ownership": ownership,
                }
            )
            scenarios.append(
                {
                    "scenarioId": scenario["id"],
                    "backlogIds": scenario.get("backlogIds", []),
                    "kind": scenario.get("kind", ""),
                    "fixture": scenario.get("fixture", ""),
                    "fixtureHash": fixture_hash_for_scenario(baseline, extension_id, str(scenario["id"])),
                    "runtimeModes": modes,
                    "budget": budget,
                    "scenarioArtifact": rel(artifact_path) if artifact_path.exists() else "",
                    "measurementArtifact": measurement_artifact.get("artifact", ""),
                    "measurementStatus": measurement_artifact.get("status", "not-run"),
                    "executionStatus": scenario_execution_status(payload, reference_ready),
                    "ownership": ownership,
                    "measurements": scenario_performance_measurements(payload),
                }
            )
        results.append(
            {
                "rank": row["rank"],
                "id": extension_id,
                "version": row.get("version", ""),
                "scenarioBudgetCount": len(scenarios),
                "executionGate": "reference-host-executable-unpinned" if not reference_ready else "ready-for-performance-budget-execution",
                "scenarios": scenarios,
            }
        )
    performance_measurement_batch_coverage, closed_performance_measurement_batch_count = summarize_performance_measurement_batches(results)
    budget_promotion_gate = build_performance_budget_promotion_gate(
        scenario_count,
        covered_scenario_count,
        measured_scenario_count,
        derived_scenario_count,
        closed_performance_measurement_batch_count,
        aggregate_budget_checks,
        promotion_scenarios,
    )
    return {
        "schema": "wizp.top20-behavior-performance-budgets.v1",
        "generatedAt": generated_at,
        "sourceBaseline": rel(BASELINE_JSON),
        "totalExtensions": len(results),
        "scenarioBudgetCount": scenario_count,
        "measuredScenarioCount": measured_scenario_count,
        "derivedScenarioCount": derived_scenario_count,
        "coveredScenarioCount": covered_scenario_count,
        "missingScenarioCount": max(scenario_count - covered_scenario_count, 0),
        "closedPerformanceMeasurementBatchCount": closed_performance_measurement_batch_count,
        "performanceMeasurementBatchCoverage": performance_measurement_batch_coverage,
        "budgetCheckSummary": aggregate_budget_checks,
        "performanceBudgetPromotionGate": budget_promotion_gate,
        "budgetPromotionGateStatus": budget_promotion_gate.get("status", "unknown"),
        "budgetPromotionMissingEvidence": budget_promotion_gate.get("missingPromotionEvidence", []),
        "budgetPromotionFailingScenarioCount": budget_promotion_gate.get("failingScenarioCount", 0),
        "budgetPromotionReadyScenarioCount": budget_promotion_gate.get("readyScenarioCount", 0),
        "budgetPromotionBlockerCounts": budget_promotion_gate.get("blockerCounts", {}),
        "budgetPromotionFailedBudgetCheckCounts": budget_promotion_gate.get("failedBudgetCheckCounts", {}),
        "budgetPromotionMissingWizpMeasurementCounts": budget_promotion_gate.get("missingWizpMeasurementCounts", {}),
        "budgetPromotionMissingReferenceMeasurementCounts": budget_promotion_gate.get("missingReferenceMeasurementCounts", {}),
        "budgetPromotionReferenceTimingCoverageSummary": budget_promotion_gate.get("referenceTimingCoverageSummary", {}),
        "budgetPromotionMissingMemoryToleranceEvidenceCounts": budget_promotion_gate.get("missingMemoryToleranceEvidenceCounts", {}),
        "budgetPromotionMemoryToleranceBudgetCheckSummary": budget_promotion_gate.get("memoryToleranceBudgetCheckSummary", {}),
        "budgetPromotionBudgetRuleOwnerCounts": budget_promotion_gate.get("budgetRuleOwnerCounts", {}),
        "budgetPromotionBudgetRuleBucketCounts": budget_promotion_gate.get("budgetRuleBucketCounts", {}),
        "budgetPromotionBudgetRuleClassificationCounts": budget_promotion_gate.get("budgetRuleClassificationCounts", {}),
        "budgetPromotionBudgetRuleEvaluationStatusCounts": budget_promotion_gate.get("budgetRuleEvaluationStatusCounts", {}),
        "budgetPromotionBudgetRuleFailedCheckOwnerCounts": budget_promotion_gate.get("budgetRuleFailedCheckOwnerCounts", {}),
        "budgetPromotionBudgetRuleFailedCheckBucketCounts": budget_promotion_gate.get("budgetRuleFailedCheckBucketCounts", {}),
        "budgetPromotionBudgetRuleMissingMeasurementOwnerCounts": budget_promotion_gate.get("budgetRuleMissingMeasurementOwnerCounts", {}),
        "budgetPromotionBudgetRuleMissingMeasurementBucketCounts": budget_promotion_gate.get("budgetRuleMissingMeasurementBucketCounts", {}),
        "budgetPromotionReferenceTimingOwnerCounts": budget_promotion_gate.get("referenceTimingOwnerCounts", {}),
        "budgetPromotionReferenceTimingBucketCounts": budget_promotion_gate.get("referenceTimingBucketCounts", {}),
        "budgetPromotionReferenceTimingClassificationCounts": budget_promotion_gate.get("referenceTimingClassificationCounts", {}),
        "budgetPromotionReferenceTimingMissingMeasurementOwnerCounts": budget_promotion_gate.get("referenceTimingMissingMeasurementOwnerCounts", {}),
        "budgetPromotionReferenceTimingMissingMeasurementBucketCounts": budget_promotion_gate.get("referenceTimingMissingMeasurementBucketCounts", {}),
        "budgetPromotionMemoryToleranceOwnerCounts": budget_promotion_gate.get("memoryToleranceOwnerCounts", {}),
        "budgetPromotionMemoryToleranceBucketCounts": budget_promotion_gate.get("memoryToleranceBucketCounts", {}),
        "budgetPromotionMemoryToleranceClassificationCounts": budget_promotion_gate.get("memoryToleranceClassificationCounts", {}),
        "budgetPromotionMemoryToleranceMissingEvidenceOwnerCounts": budget_promotion_gate.get("memoryToleranceMissingEvidenceOwnerCounts", {}),
        "budgetPromotionMemoryToleranceMissingEvidenceBucketCounts": budget_promotion_gate.get("memoryToleranceMissingEvidenceBucketCounts", {}),
        "budgetPromotionWorkQueue": budget_promotion_gate.get("workQueue", {}),
        "budgetPromotionWorkQueueCounts": budget_promotion_gate.get("workQueue", {}).get("evidenceCounts", {}),
        "budgetPromotionReady": budget_promotion_gate.get("promotionReady") is True,
        "executionGate": "reference-host-executable-unpinned" if not reference_ready else "ready-for-performance-budget-execution",
        "results": results,
        "note": "Performance budgets stay partial, but generic paired WIZP/reference survey execution now lands through T20V-H02 instead of a planning-only gate, all 4 H11 performance batch-board rows can now report direct-measurement coverage explicitly, and T20V-H11E now has an aggregate promotion gate that records remaining WIZP budget, reference timing, and memory tolerance evidence.",
    }


