def view_surface_status(payload: dict[str, Any], side: str) -> str:
    summary = scenario_surface_summary(payload)
    side_summary = summary.get(side)
    if isinstance(side_summary, dict) and side_summary:
        return "captured"
    status = str(payload.get("status") or "")
    return status or "not-run"


def compact_nonempty_list(value: Any, limit: int = 20) -> list[Any]:
    if not isinstance(value, list):
        return []
    return value[:limit]


def compact_view_registrations(value: Any) -> dict[str, list[Any]]:
    if not isinstance(value, dict):
        return {}
    return {
        str(key): compact_nonempty_list(items)
        for key, items in sorted(value.items())
        if isinstance(items, list) and items
    }


def debug_launch_configuration_selector_state(value: Any) -> dict[str, Any]:
    if not isinstance(value, dict):
        return {}
    configurations = value.get("configurations") if isinstance(value.get("configurations"), list) else []
    compounds = value.get("compounds") if isinstance(value.get("compounds"), list) else []
    ui = value.get("ui") if isinstance(value.get("ui"), dict) else {}
    labels = [
        str(item.get("name") or "")
        for item in configurations
        if isinstance(item, dict) and str(item.get("name") or "")
    ]
    compound_labels = [
        str(item.get("name") or "")
        for item in compounds
        if isinstance(item, dict) and str(item.get("name") or "")
    ]
    has_selector_surface = bool(labels or compound_labels or ui.get("selector") is True)
    if not has_selector_surface:
        return {}
    selected = str(value.get("selected") or "")
    if not selected and labels:
        selected = labels[0]
    payload: dict[str, Any] = {
        "source": "wizp-debug-launch-configurations-rpc",
        "selected": selected,
        "labels": labels[:12],
        "compoundLabels": compound_labels[:12],
        "configurationCount": len(configurations),
        "compoundCount": len(compounds),
    }
    if ui:
        payload["ui"] = {
            str(key): ui.get(key)
            for key in sorted(ui.keys())
            if isinstance(key, str) and key in {"selector", "editLaunchJson", "schemaDiagnostics", "compoundPicker", "prePostTaskBadges"}
        }
    if configurations:
        payload["configurations"] = compact_nonempty_list(configurations, limit=6)
    if compounds:
        payload["compounds"] = compact_nonempty_list(compounds, limit=6)
    return payload


def debug_launch_configuration_schema_diagnostics(value: Any) -> dict[str, Any]:
    if not isinstance(value, dict):
        return {}
    if "schemaValid" not in value and "errors" not in value:
        return {}
    configurations = value.get("configurations") if isinstance(value.get("configurations"), list) else []
    errors = value.get("errors") if isinstance(value.get("errors"), list) else []
    return {
        "source": "wizp-debug-launch-configurations-rpc",
        "sourcePath": str(value.get("source") or ""),
        "schemaValid": bool(value.get("schemaValid")),
        "errors": compact_nonempty_list(errors, limit=10),
        "configurationCount": len(configurations),
    }


def task_runtime_rpc_payload(value: Any, key: str) -> dict[str, Any]:
    if not isinstance(value, dict):
        return {}
    wrapper = value.get(key)
    if not isinstance(wrapper, dict) or wrapper.get("status") != "ok":
        return {}
    result = wrapper.get("result")
    return result if isinstance(result, dict) else {}


def task_runtime_tree_state(value: Any) -> dict[str, Any]:
    discover = task_runtime_rpc_payload(value, "discover")
    if not discover:
        return {}
    tasks = discover.get("tasks") if isinstance(discover.get("tasks"), list) else []
    if not tasks:
        return {}
    return {
        "source": "wizp-tasks-discover-rpc",
        "taskCount": len(tasks),
        "tasks": compact_nonempty_list(tasks, limit=8),
    }


def task_runtime_output(value: Any) -> dict[str, Any]:
    run = task_runtime_rpc_payload(value, "run")
    selected_task = value.get("selectedTask") if isinstance(value, dict) and isinstance(value.get("selectedTask"), dict) else {}
    if not run or "stdout" not in run:
        return {}
    stdout = str(run.get("stdout") or "")
    stderr = str(run.get("stderr") or "")
    return {
        "source": "wizp-tasks-run-rpc",
        "task": selected_task,
        "state": str(run.get("state") or ""),
        "exitCode": run.get("exitCode"),
        "stdoutTail": stdout[-1000:],
        "stderrTail": stderr[-1000:],
        "problemCount": len(run.get("problems") if isinstance(run.get("problems"), list) else []),
    }


def task_runtime_problem_matcher(value: Any) -> dict[str, Any]:
    if not isinstance(value, dict):
        return {}
    selected_task = value.get("selectedTask") if isinstance(value.get("selectedTask"), dict) else {}
    run = task_runtime_rpc_payload(value, "run")
    problems = run.get("problems") if isinstance(run.get("problems"), list) else []
    matcher = selected_task.get("problemMatcher") if isinstance(selected_task, dict) else None
    if not matcher and not problems:
        return {}
    return {
        "source": "wizp-tasks-discover-run-rpc",
        "problemMatcher": str(matcher or ""),
        "problems": compact_nonempty_list(problems, limit=10),
        "problemCount": len(problems),
    }


def task_runtime_cancellation(value: Any) -> dict[str, Any]:
    cancel = task_runtime_rpc_payload(value, "cancel")
    if not cancel or cancel.get("cancelled") is not True:
        return {}
    return {
        "source": "wizp-tasks-cancel-rpc",
        "id": str(cancel.get("id") or ""),
        "state": str(cancel.get("state") or ""),
        "cancelled": True,
    }


def task_runtime_terminal_metadata(value: Any) -> dict[str, Any]:
    ui = task_runtime_rpc_payload(value, "uiBinding")
